CREATE OR REPLACE FUNCTION sportsbook_private.release_environment_ready() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT EXISTS(SELECT FROM sportsbook_private.application_environment e,sportsbook_private.production_release_control r WHERE e.singleton AND r.singleton
 AND e.environment='production' AND e.project_ref='bmvjcdgxwxqalaohpsnw' AND e.app_origin='https://sportsbook.coopergurrie.com' AND r.release_schema='boff-person-wallets-2026-11')$$;

CREATE OR REPLACE FUNCTION sportsbook_private.release_writes_enabled() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT sportsbook_private.release_environment_ready() AND EXISTS(SELECT FROM sportsbook_private.production_release_control WHERE singleton AND state='active')$$;

REVOKE ALL ON FUNCTION sportsbook_private.release_environment_ready(),sportsbook_private.release_writes_enabled() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.activity_rows(p_league uuid)
 RETURNS TABLE(event_id text, event_at timestamp with time zone, event_type text, label text, member_id uuid, member_name text, actor_id uuid, actor_name text, ticket_id uuid, week integer, details jsonb)
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
 SELECT 'placed:'||t.id,t.placed_at,'TicketPlaced','Ticket Placed',coalesce(w.user_id,t.team_id),
 coalesce(t.bettor_display_name,w.display_name,team.team_name||' · Historical Team'),NULL::uuid,'Member',t.id,t.market_week,
 jsonb_build_object('Stake',t.stake,'Accepted Odds',t.accepted_combined_odds,'Current Status',t.status)
 FROM public.tickets t JOIN public.teams team ON team.id=t.team_id LEFT JOIN public.user_wallets w ON w.id=t.user_wallet_id WHERE t.league_id=p_league
 UNION ALL
 SELECT 'settled:'||t.id,t.settled_at,CASE WHEN t.status='VOIDED' THEN 'TicketVoided' ELSE 'TicketSettled' END,
 CASE WHEN t.status='VOIDED' THEN 'Ticket Voided' ELSE 'Ticket Settled' END,coalesce(w.user_id,t.team_id),
 coalesce(t.bettor_display_name,w.display_name,team.team_name||' · Historical Team'),NULL::uuid,'Settlement',t.id,t.market_week,
 jsonb_build_object('Result',t.status,'Return',t.actual_payout,'Net Profit',t.net_profit)
 FROM public.tickets t JOIN public.teams team ON team.id=t.team_id LEFT JOIN public.user_wallets w ON w.id=t.user_wallet_id
 WHERE t.league_id=p_league AND t.settled_at IS NOT NULL AND t.status<>'OPEN'
 UNION ALL
 SELECT 'credit:'||e.id,e.created_at,'Credits',
 CASE e.kind WHEN 'claim' THEN 'Credits Claimed' WHEN 'opening' THEN 'Starting Credits' WHEN 'adjustment' THEN 'Credits Adjusted'
 WHEN 'payout' THEN 'Payout Credited' WHEN 'refund' THEN 'Credits Returned' ELSE initcap(replace(e.kind,'_',' ')) END,
 w.user_id,w.display_name,NULL::uuid,'Wallet Record',e.ticket_id,t.market_week,
 jsonb_build_object('Amount',e.amount,'Balance Before',e.balance_before,'Balance After',e.balance_after,'Reason',e.reason)
 FROM public.user_wallet_entries e JOIN public.user_wallets w ON w.id=e.wallet_id LEFT JOIN public.tickets t ON t.id=e.ticket_id
 WHERE e.league_id=p_league AND e.kind<>'wager'
 UNION ALL
 SELECT 'admin:'||a.id,a.created_at,
 CASE WHEN a.category~'(correct|settle|void)' THEN 'Correction' WHEN a.category~'(member|invitation)' THEN 'Membership'
 WHEN a.category~'(rule|policy|futures|featured|rival|reward)' THEN 'Rules' ELSE 'Administration' END,
 initcap(replace(a.category,'_',' ')),a.actor_id,coalesce((SELECT min(p.display_name) FROM boff_dev_internal.participant_links p WHERE p.league_id=a.league_id AND p.user_id=a.actor_id),'Administrator'),
 a.actor_id,coalesce((SELECT min(p.display_name) FROM boff_dev_internal.participant_links p WHERE p.league_id=a.league_id AND p.user_id=a.actor_id),'Administrator'),
 CASE WHEN coalesce(a.after_value->>'ticket_id',a.before_value->>'ticket_id')~*'^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' THEN coalesce(a.after_value->>'ticket_id',a.before_value->>'ticket_id')::uuid END,
 CASE WHEN coalesce(a.after_value->>'market_week',a.before_value->>'market_week')~'^[0-9]{1,2}$' THEN coalesce(a.after_value->>'market_week',a.before_value->>'market_week')::integer END,
 jsonb_build_object('Category',a.category,'Reason',a.reason,'Changed Fields',(SELECT string_agg(value,', ') FROM jsonb_array_elements_text(CASE WHEN jsonb_typeof(a.after_value->'changed_fields')='array' THEN a.after_value->'changed_fields' ELSE '[]' END)))
 FROM public.admin_change_log a WHERE a.league_id=p_league
 UNION ALL
 SELECT 'staff:'||a.id,a.created_at,'Membership','Staff Access Changed',a.subject_id,
 coalesce((SELECT min(p.display_name) FROM boff_dev_internal.participant_links p WHERE p.league_id=a.league_id AND p.user_id=a.subject_id),'League Staff'),
 a.actor_id,coalesce((SELECT min(p.display_name) FROM boff_dev_internal.participant_links p WHERE p.league_id=a.league_id AND p.user_id=a.actor_id),'Administrator'),
 NULL::uuid,NULL::integer,jsonb_build_object('Reason',a.reason,'Previous Role',a.before_value->>'role','New Role',a.after_value->>'role')
 FROM public.league_staff_audit a WHERE a.league_id=p_league

 UNION ALL
 SELECT 'reward:'||r.league_id||':'||r.revision,r.changed_at,'Rules',
 CASE WHEN r.revision=1 THEN 'Fantasy Reward Rules Initialized' ELSE 'Fantasy Reward Rules Changed' END,
 r.actor,coalesce((SELECT min(p.display_name) FROM boff_dev_internal.participant_links p WHERE p.league_id=r.league_id AND p.user_id=r.actor),'Commissioner'),
 r.actor,'Commissioner',NULL::uuid,NULL::integer,jsonb_build_object('Revision',r.revision)
 FROM boff_dev_internal.fantasy_reward_rule_changes r WHERE r.league_id=p_league AND r.actor IS NOT NULL
 UNION ALL
 SELECT 'futures:'||r.league_id||':'||r.season||':'||r.revision,r.created_at,'Rules',
 CASE WHEN r.revision=1 THEN 'Season Futures Rules Initialized' ELSE 'Season Futures Rules Changed' END,
 r.actor_id,coalesce((SELECT min(p.display_name) FROM boff_dev_internal.participant_links p WHERE p.league_id=r.league_id AND p.user_id=r.actor_id),'Commissioner'),
 r.actor_id,'Commissioner',NULL::uuid,NULL::integer,jsonb_build_object('Season',r.season,'Revision',r.revision)
 FROM boff_dev_internal.futures_rule_versions r WHERE r.league_id=p_league AND r.actor_id IS NOT NULL
 $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."activity_rows"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.apply_feature_settings(league uuid, season integer, quotes jsonb, teams jsonb, week integer, regular_weeks integer, max_boost integer, playoff_spots integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO ''
AS $function$
WITH config AS (
 SELECT coalesce((SELECT settings FROM boff_dev_internal.feature_settings s WHERE s.league_id=league AND s.season=apply_feature_settings.season),'{}') settings
), team_rows AS (
 SELECT t.*,row_number() OVER (ORDER BY (wins+.5*ties)/greatest(games,1) DESC,"pointsFor" DESC,id) seed
 FROM jsonb_to_recordset(teams) t(id text,roster_id integer,wins numeric,ties numeric,games numeric,"pointsFor" numeric,streak text,matchup_id text,"pregameProjection" numeric)
), facts AS (
 SELECT q->>'matchup_key' matchup,a.id away,h.id home,a.seed away_seed,h.seed home_seed,a."pregameProjection" away_open,h."pregameProjection" home_open,
  a.wins+.5*a.ties away_wins,h.wins+.5*h.ties home_wins,
  (a.wins+h.wins+.5*(a.ties+h.ties))/greatest(1,a.games+h.games) win_rate,a."pointsFor"+h."pointsFor" points,
  (q->>'away_projection')::numeric away_projection,(q->>'home_projection')::numeric home_projection,
  (q->>'line')::numeric total,
  coalesce(substring(a.streak from '^([0-9]+)W$')::integer,substring(a.streak from '^W([0-9]+)$')::integer,0) away_streak,
  coalesce(substring(h.streak from '^([0-9]+)W$')::integer,substring(h.streak from '^W([0-9]+)$')::integer,0) home_streak,
  'sleeper-'||week||'-'||least(a.roster_id,h.roster_id)||'-'||greatest(a.roster_id,h.roster_id) pair_key
 FROM jsonb_array_elements(quotes) q
 JOIN team_rows a ON a.id=q->>'away_team_id' JOIN team_rows h ON h.id=q->>'home_team_id'
 WHERE q->>'kind'='match_total' AND q->>'side'='over' AND (q->'metadata'->>'alternate') IS DISTINCT FROM 'true'
), ranked AS (
 SELECT f.*,abs(away_projection-home_projection) spread,
  count(*) OVER ()/2 cap,
  coalesce((f.win_rate-min(f.win_rate) OVER w)/nullif(max(f.win_rate) OVER w-min(f.win_rate) OVER w,0),.5)*.50
  +coalesce((f.points-min(f.points) OVER w)/nullif(max(f.points) OVER w-min(f.points) OVER w,0),.5)*.25
  +(1-coalesce((abs(away_projection-home_projection)-min(abs(away_projection-home_projection)) OVER w)/nullif(max(abs(away_projection-home_projection)) OVER w-min(abs(away_projection-home_projection)) OVER w,0),.5))*.15
  +coalesce((f.total-min(f.total) OVER w)/nullif(max(f.total) OVER w-min(f.total) OVER w,0),.5)*.10 rating,
  CASE WHEN away_projection<home_projection THEN away WHEN home_projection<away_projection THEN home END underdog,
  settings,settings->'plans'->week::text plan
 FROM facts f CROSS JOIN config WINDOW w AS ()
), contexts AS (
 SELECT r.*,prior.margin,
  (SELECT wins+.5*ties FROM team_rows WHERE seed=playoff_spots) cutoff_wins,
  (SELECT count(*) FROM team_rows) league_size,
  coalesce(plan->'overrides'->pair_key,plan->'overrides'->matchup) override,
  coalesce(plan->'playoffModes'->>pair_key,plan->'playoffModes'->>matchup,'auto') playoff_mode,
  c.payload->'featureFinalists' finalists,
  c.payload->'rewardEvidence' IS NOT NULL playoff_evidence,
  coalesce(c.payload->'rewardEvidence'->'clinchWeeks','{}') clinched,
  coalesce(c.payload->'rewardEvidence'->'eliminationWeeks','{}') eliminated
 FROM ranked r
 LEFT JOIN public.leagues l ON l.id=league
 LEFT JOIN public.dev_live_cache c ON c.key='league:'||l.sleeper_league_id
 LEFT JOIN LATERAL (
  SELECT (w.results->r.away->>'points')::numeric-(w.results->r.home->>'points')::numeric margin
  FROM public.league_result_weeks w WHERE w.league_id=league AND w.nfl_season=season AND w.final AND w.market_week<week
   AND w.results->r.away->>'matchup_id'=w.results->r.home->>'matchup_id'
  ORDER BY w.market_week DESC LIMIT 1
 ) prior ON true
), candidates AS (
 SELECT c.*, rules.*,
  (SELECT roster_id::text FROM team_rows WHERE id=c.away) away_roster,
  (SELECT roster_id::text FROM team_rows WHERE id=c.home) home_roster
 FROM contexts c CROSS JOIN LATERAL (SELECT
  coalesce((settings->'cutoffs'->>'playoffGap')::numeric,1) playoff_gap,
  coalesce((settings->'cutoffs'->>'streakWins')::numeric,5) streak_goal
 ) rules
), choices AS (
 SELECT c.*, choice.kind,choice.priority
 FROM candidates c CROSS JOIN LATERAL (
  SELECT kind,priority FROM (VALUES
   ('championship',1,finalists @> jsonb_build_array(away_roster::integer,home_roster::integer)),
   ('playoff',2,playoff_evidence AND week>=regular_weeks-coalesce((settings->'cutoffs'->>'playoffWeeks')::integer,4)+1 AND
     (NOT (clinched ? away_roster OR eliminated ? away_roster) AND abs(away_wins-cutoff_wins)<=playoff_gap
      OR NOT (clinched ? home_roster OR eliminated ? home_roster) AND abs(home_wins-cutoff_wins)<=playoff_gap)),
   ('rivalry',3,EXISTS(SELECT FROM jsonb_array_elements(coalesce(settings->'rivals','[]')) pair WHERE pair @> jsonb_build_array(away,home))),
   ('revenge',4,margin<>0 AND abs(margin)<=coalesce((settings->'cutoffs'->>'revengeMargin')::numeric,10)),
   ('upset',5,away_open IS NOT NULL AND home_open IS NOT NULL AND away_open<>home_open AND week>=coalesce((settings->'cutoffs'->>'upsetStart')::integer,4)
    AND (CASE WHEN away_open<home_open THEN away_seed ELSE home_seed END)>floor(league_size*coalesce((settings->'cutoffs'->>'upsetOutside')::numeric,50)/100)
    AND (CASE WHEN away_open<home_open THEN home_seed ELSE away_seed END)<=ceil(league_size*coalesce((settings->'cutoffs'->>'upsetTop')::numeric,25)/100)
    AND abs(away_open-home_open)*100/greatest(.1,away_open,home_open)<=coalesce((settings->'cutoffs'->>'upsetGap')::numeric,10)),
   ('streak',6,greatest(away_streak,home_streak)>=streak_goal),
   ('tank',7,week>=coalesce((settings->'cutoffs'->>'tankStart')::integer,regular_weeks/2+1) AND
    round(win_rate*100,1)<=coalesce((settings->'cutoffs'->>'tankPct')::numeric,33.3) AND least(away_seed,home_seed)>playoff_spots),
   ('game',8,true)
  ) kinds(kind,priority,eligible)
  WHERE CASE WHEN override IS NOT NULL THEN override #>> '{}' = kind
    ELSE week<=regular_weeks AND eligible AND coalesce((settings->'enabled'->>kind)::boolean,true) END
  AND (kind<>'revenge' OR margin<>0) AND (kind<>'upset' OR underdog IS NOT NULL)
  ORDER BY priority LIMIT 1
 ) choice
), capped AS (
 SELECT *,count(*) FILTER(WHERE override IS NULL AND kind<>'rivalry') OVER (ORDER BY priority,rating DESC,matchup) slot,
  row_number() OVER (PARTITION BY kind,(override IS NULL) ORDER BY rating DESC,matchup) kind_slot
 FROM choices
), features AS (
 SELECT *,CASE kind WHEN 'game' THEN 'Game of the Week' WHEN 'tank' THEN 'Tank Bowl'
  WHEN 'rivalry' THEN 'Rivalry' WHEN 'upset' THEN 'Upset Watch' WHEN 'revenge' THEN 'Revenge Game'
  WHEN 'streak' THEN 'Streak Breaker' WHEN 'championship' THEN 'Championship Rematch' ELSE 'Playoff Race' END label
 FROM capped WHERE override IS NOT NULL OR kind='rivalry' OR (slot<=cap AND (kind<>'game' OR kind_slot=1))
)
SELECT jsonb_agg(q || jsonb_build_object('featured',CASE WHEN ok THEN f.label ELSE '' END,
 'boost_pct',CASE WHEN ok THEN least(max_boost,CASE f.kind WHEN 'championship' THEN 50 WHEN 'game' THEN 25 WHEN 'tank' THEN 25 WHEN 'streak' THEN 25 ELSE 35 END) ELSE 0 END,
 'metadata',coalesce(q->'metadata','{}') || CASE WHEN ok THEN jsonb_build_object('feature_source',CASE WHEN f.override IS NULL THEN 'Automatic' ELSE 'Commissioner' END) ELSE '{}'::jsonb END) ORDER BY ord)
FROM jsonb_array_elements(quotes) WITH ORDINALITY item(q,ord)
LEFT JOIN features f ON f.matchup=q->>'matchup_key'
CROSS JOIN LATERAL (SELECT max_boost>0 AND f.kind IS NOT NULL AND (q->'metadata'->>'alternate') IS DISTINCT FROM 'true' AND (
 CASE WHEN f.kind='tank' THEN q->>'kind'='match_total' AND q->>'side'='over'
 ELSE q->>'kind'='moneyline' AND CASE f.kind
  WHEN 'upset' THEN q->>'team_id'=coalesce(CASE WHEN f.away_open<f.home_open THEN f.away WHEN f.home_open<f.away_open THEN f.home END,f.underdog)
  WHEN 'revenge' THEN q->>'team_id'=CASE WHEN f.margin<0 THEN f.away ELSE f.home END
  WHEN 'streak' THEN CASE WHEN greatest(f.away_streak,f.home_streak)<f.streak_goal
    THEN q->>'team_id'=CASE WHEN f.away_streak>=f.home_streak THEN f.home ELSE f.away END
    ELSE (f.away_streak>=f.streak_goal AND q->>'team_id'=f.home) OR (f.home_streak>=f.streak_goal AND q->>'team_id'=f.away) END
  WHEN 'playoff' THEN CASE f.playoff_mode WHEN 'away-racing' THEN q->>'team_id'=f.home WHEN 'home-racing' THEN q->>'team_id'=f.away WHEN 'both' THEN true
    ELSE CASE WHEN (NOT (f.clinched ? f.away_roster OR f.eliminated ? f.away_roster) AND abs(f.away_wins-f.cutoff_wins)<=f.playoff_gap)
      AND (NOT (f.clinched ? f.home_roster OR f.eliminated ? f.home_roster) AND abs(f.home_wins-f.cutoff_wins)<=f.playoff_gap) THEN true
      WHEN NOT (f.clinched ? f.away_roster OR f.eliminated ? f.away_roster) AND abs(f.away_wins-f.cutoff_wins)<=f.playoff_gap THEN q->>'team_id'=f.home
      WHEN NOT (f.clinched ? f.home_roster OR f.eliminated ? f.home_roster) AND abs(f.home_wins-f.cutoff_wins)<=f.playoff_gap THEN q->>'team_id'=f.away
      ELSE false END END
  ELSE true END END)) eligible(ok)
$function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."apply_feature_settings"(league uuid, season integer, quotes jsonb, teams jsonb, week integer, regular_weeks integer, max_boost integer, playoff_spots integer) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.apply_futures_season_transition()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 wallet public.user_wallets;
 carry numeric;
 target numeric;
 event text;
BEGIN
 IF NEW.board_type<>'future' THEN
  IF NEW.status='published' AND EXISTS(
    SELECT FROM public.sportsbook_boards b JOIN public.sportsbook_markets m ON m.board_id=b.id
    WHERE b.league_id=NEW.league_id AND b.nfl_season=NEW.nfl_season AND b.board_type='future'
      AND m.kind='future_champion' AND m.metadata->>'dev_futures'='true' AND m.metadata->>'resolved'='true'
  ) THEN
   RAISE EXCEPTION 'Fantasy playoffs have ended. This betting season is paused';
  END IF;
  RETURN NEW;
 END IF;
 IF NEW.status='closed' AND EXISTS(
   SELECT FROM public.sportsbook_markets m WHERE m.board_id=NEW.id AND m.kind='future_champion'
    AND m.metadata->>'dev_futures'='true' AND m.metadata->>'resolved'='true'
 ) THEN
  UPDATE public.sportsbook_boards SET status='closed',quote_valid_until=clock_timestamp()
   WHERE league_id=NEW.league_id AND nfl_season=NEW.nfl_season AND board_type='weekly' AND status='published';
  RETURN NEW;
 END IF;
 IF NEW.status<>'published' OR NOT EXISTS(
  SELECT FROM public.sportsbook_boards WHERE league_id=NEW.league_id AND nfl_season=NEW.nfl_season-1 AND board_type='future'
 ) THEN RETURN NEW; END IF;
 IF EXISTS(SELECT FROM public.tickets WHERE league_id=NEW.league_id AND nfl_season=NEW.nfl_season-1 AND status='OPEN') THEN
  RAISE EXCEPTION 'Resolve prior-season tickets before opening the new season';
 END IF;
 FOR wallet IN SELECT w.* FROM public.user_wallets w WHERE w.league_id=NEW.league_id AND w.status='approved'
  AND w.balance IS NOT NULL AND EXISTS (SELECT FROM boff_dev_internal.participant_links m WHERE m.league_id=w.league_id AND m.user_id=w.user_id)
  ORDER BY w.id FOR UPDATE OF w
 LOOP
  event:='season-opening:'||NEW.nfl_season||':'||wallet.id;
  IF EXISTS(SELECT FROM public.user_wallet_entries e WHERE e.wallet_id=wallet.id AND e.event_key=event) THEN CONTINUE; END IF;
  SELECT COALESCE(sum(actual_payout),0) INTO carry FROM public.tickets
   WHERE league_id=NEW.league_id AND nfl_season=NEW.nfl_season-1 AND user_wallet_id=wallet.id
    AND status='WON' AND ticket_type='future';
  target:=100+carry;
  INSERT INTO public.user_wallet_entries(wallet_id,league_id,team_id,event_key,kind,amount,balance_before,balance_after,reason,metadata)
  VALUES(wallet.id,wallet.league_id,wallet.team_id,event,'adjustment',target-wallet.balance,wallet.balance,target,
   'Season starting balance and futures winnings',jsonb_build_object('season',NEW.nfl_season,'startingBalance',100,'futuresPayout',carry));
  UPDATE public.user_wallets SET balance=target,updated_at=clock_timestamp() WHERE id=wallet.id;
  DELETE FROM boff_dev_internal.credit_claim_state WHERE wallet_id=wallet.id;
 END LOOP;
 RETURN NEW;
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."apply_futures_season_transition"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.audit_commissioner_configuration()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE prior jsonb;current_value jsonb;category text;changed jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT boff_dev_internal.can_manage_members(NEW.league_id) THEN RETURN NEW;END IF;
 IF TG_TABLE_NAME='feature_settings' THEN
  prior:=OLD.settings;current_value:=NEW.settings;category:='featured_matchup_rules';
 ELSE
  prior:=CASE WHEN TG_OP='UPDATE' THEN OLD.choices ELSE NULL END;current_value:=NEW.choices;category:='league_feed_rules';
 END IF;
 IF prior IS NOT DISTINCT FROM current_value THEN RETURN NEW;END IF;
 SELECT jsonb_agg(key ORDER BY key) INTO changed FROM(
 SELECT jsonb_object_keys(coalesce(prior,'{}')) AS key UNION SELECT jsonb_object_keys(current_value))x
 WHERE prior->key IS DISTINCT FROM current_value->key;
 INSERT INTO public.admin_change_log(league_id,actor_id,category,reason,before_value,after_value)
 VALUES(NEW.league_id,auth.uid(),category,CASE category WHEN 'featured_matchup_rules' THEN 'Featured matchup or rivalry settings saved' ELSE 'League feed preferences saved' END,
 jsonb_build_object('settings_md5',md5(prior::text)),jsonb_build_object('settings_md5',md5(current_value::text),'changed_fields',changed));
 RETURN NEW;
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."audit_commissioner_configuration"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.audit_member_invitation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 INSERT INTO public.admin_change_log(league_id,actor_id,category,reason,before_value,after_value)
 VALUES(NEW.league_id,NEW.issuer,'member_invitation',NEW.reason,'{}',jsonb_build_object('invitation_id',NEW.id,'team_id',NEW.team_id,'sleeper_id',NEW.sleeper_id,'expires_at',NEW.expires_at));
 RETURN NULL;
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."audit_member_invitation"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.cached_weekly_offer_options(p_league uuid, p_board uuid, p_version text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE cached boff_dev_internal.weekly_offer_cache;
DECLARE options jsonb;
DECLARE cutoff timestamptz;
BEGIN
 SELECT * INTO cached FROM boff_dev_internal.weekly_offer_cache WHERE league_id=p_league;
 IF cached.input_version=p_version AND cached.next_cutoff>now() THEN RETURN cached.offers; END IF;

 PERFORM pg_advisory_xact_lock(hashtext('dev-weekly-offer-cache'), hashtext(p_league::text));
 SELECT * INTO cached FROM boff_dev_internal.weekly_offer_cache WHERE league_id=p_league;
 IF cached.input_version=p_version AND cached.next_cutoff>now() THEN RETURN cached.offers; END IF;

 options:=boff_dev_internal.weekly_offer_options(p_board);
 SELECT coalesce(min(times.cutoff),'infinity'::timestamptz) INTO cutoff
 FROM (
  SELECT (m.metadata->>'cutoff')::timestamptz AS cutoff
  FROM public.sportsbook_markets m
  WHERE m.board_id=p_board AND m.active AND m.kind IN ('moneyline','spread','match_total','player_h2h','player_milestone')
  UNION ALL
  SELECT (p.value->>'kickoff')::timestamptz
  FROM public.dev_current_book b CROSS JOIN LATERAL jsonb_array_elements(b.payload->'players') p
  WHERE b.league_id=p_league AND b.board_id=p_board
  UNION ALL
  SELECT (o.value->>'deadline')::timestamptz FROM jsonb_array_elements(options) o
 ) times
 WHERE times.cutoff>now();
 INSERT INTO boff_dev_internal.weekly_offer_cache(league_id,input_version,next_cutoff,offers)
 VALUES(p_league,p_version,cutoff,options)
 ON CONFLICT(league_id) DO UPDATE SET
  input_version=excluded.input_version,next_cutoff=excluded.next_cutoff,offers=excluded.offers;
 RETURN options;
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."cached_weekly_offer_options"(p_league uuid, p_board uuid, p_version text) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.can_manage_members(p_league uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT EXISTS(SELECT FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL)
 AND (sportsbook_private.is_platform_owner() OR EXISTS(
  SELECT FROM public.league_memberships WHERE league_id=p_league AND user_id=auth.uid() AND role='admin'))
$function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."can_manage_members"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.changed_board_rows(old_rows jsonb, new_rows jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 WITH old AS (SELECT v->>'id' id,v FROM jsonb_array_elements(coalesce(old_rows,'[]')) v),
 current AS (SELECT v->>'id' id,v FROM jsonb_array_elements(coalesce(new_rows,'[]')) v)
 SELECT jsonb_build_object('upsert',coalesce(jsonb_agg(current.v) FILTER(WHERE current.id IS NOT NULL),'[]'),
  'remove',coalesce(jsonb_agg(old.id) FILTER(WHERE current.id IS NULL),'[]'))
 FROM old FULL JOIN current USING(id) WHERE old.v IS DISTINCT FROM current.v
$function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."changed_board_rows"(old_rows jsonb, new_rows jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.check_player_quote_cutoff()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF NEW.settlement_context->'metadata'->>'cutoff' IS NOT NULL
   AND (NEW.settlement_context->'metadata'->>'cutoff')::timestamptz<=clock_timestamp()
 THEN RAISE EXCEPTION 'A selection has reached its cutoff'; END IF;
 RETURN NEW;
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."check_player_quote_cutoff"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.communication_details(p_choices jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$ SELECT true $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."communication_details"(p_choices jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.credit_email_allowed(p_league uuid, p_user uuid, p_now timestamp with time zone DEFAULT now())
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT NOT EXISTS(SELECT FROM boff_dev_internal.notification_capture WHERE league_id=p_league AND user_id=p_user
   AND kind='opening' AND created_at>=p_now-interval '24 hours')
 AND NOT EXISTS(SELECT FROM public.outbound_emails o JOIN public.user_wallets w ON w.league_id=o.league_id AND w.team_id=o.team_id
   WHERE o.league_id=p_league AND w.user_id=p_user AND o.recipient=(SELECT email FROM auth.users WHERE id=p_user)
    AND o.kind='opening' AND ((o.status IN ('pending','sending') AND o.created_at>=p_now-interval '24 hours') OR coalesce(o.sent_at,o.created_at)>=p_now-interval '24 hours')
    AND o.status NOT IN ('failed','skipped','needs_review'))
 AND NOT EXISTS(SELECT FROM public.dev_current_book c JOIN public.sportsbook_boards b ON b.id=c.board_id
   LEFT JOIN boff_dev_internal.notification_choices choice ON choice.league_id=c.league_id AND choice.user_id=p_user
   WHERE c.league_id=p_league AND b.status='published' AND c.valid_until>p_now AND c.last_error IS NULL
    AND boff_dev_internal.effective_communications(choice.choices)->'opening'->>'email'='true'
    AND NOT EXISTS(SELECT FROM boff_dev_internal.notification_capture seen WHERE seen.league_id=p_league AND seen.user_id=p_user
     AND seen.event_key='opening:'||b.nfl_season||':'||b.market_week))
 AND NOT EXISTS(SELECT FROM public.sportsbook_boards b
   LEFT JOIN boff_dev_internal.notification_choices choice ON choice.league_id=b.league_id AND choice.user_id=p_user
   WHERE b.league_id=p_league AND b.board_type='weekly' AND b.status IN ('draft','published')
    AND b.opens_at BETWEEN p_now-interval '24 hours' AND p_now+interval '24 hours'
    AND boff_dev_internal.effective_communications(choice.choices)->'opening'->>'email'='true'
    AND NOT EXISTS(SELECT FROM boff_dev_internal.notification_capture seen WHERE seen.league_id=p_league AND seen.user_id=p_user
     AND seen.event_key='opening:'||b.nfl_season||':'||b.market_week));
$function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."credit_email_allowed"(p_league uuid, p_user uuid, p_now timestamp with time zone) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.effective_communications(p_choices jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 SELECT jsonb_object_agg(kind,jsonb_strip_nulls(jsonb_build_object(
  'email',coalesce((p_choices->kind->>'email')::boolean,true),
  'push',CASE WHEN push THEN coalesce((p_choices->kind->>'push')::boolean,true) END,
  'details',boff_dev_internal.communication_details(p_choices)
 )))
 FROM (VALUES ('opening',true),('reminder',false),('recap',false),('monday_watch',false),
  ('reopening',false),('settled',true),('leg',true),('offers',true),('reward',true),('credit',true),('featured',true)) kinds(kind,push)
$function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."effective_communications"(p_choices jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.email_edition_for_user(p_league uuid, p_user uuid, p_kind text, p_week integer, p_ticket uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE wallet public.user_wallets; book public.dev_current_book; board public.sportsbook_boards;
 recommendations jsonb:='[]'; tickets jsonb:='[]'; offers jsonb:='[]'; quotes jsonb:='[]'; rewards jsonb:='[]'; result_teams jsonb:='[]';
 performance jsonb:='{}'; crowd jsonb:='{}'; market_bets jsonb:='[]'; league_betting jsonb:='{}'; leader jsonb; recap_stats jsonb:='{}'; metric jsonb; original_quotes jsonb:='[]'; matchup text; eligible numeric; last_claim timestamptz;
BEGIN

 IF NOT EXISTS(SELECT FROM auth.users WHERE id=p_user AND email_confirmed_at IS NOT NULL) THEN RETURN '{}'; END IF;
 SELECT * INTO wallet FROM public.user_wallets WHERE league_id=p_league AND user_id=p_user;
 IF wallet.id IS NULL THEN RETURN '{}'; END IF;
 SELECT * INTO book FROM public.dev_current_book WHERE league_id=p_league;
 SELECT * INTO board FROM public.sportsbook_boards WHERE id=book.board_id;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'status',t.status,'stake',t.stake,'odds',t.accepted_combined_odds,
  'potentialReturn',t.accepted_potential_payout,'actualReturn',t.actual_payout,'legs',
  (SELECT coalesce(jsonb_agg(jsonb_build_object('selection',l.selection,'status',l.status,'odds',l.accepted_odds,
   'market',l.market_type,'evidence',l.result_evidence,'game',boff_dev_internal.email_matchup_context(t.league_id,t.nfl_season,t.market_week,l.settlement_context,l.status='OPEN'),'result',CASE WHEN l.status='OPEN' THEN boff_dev_internal.email_open_leg_result(t.league_id,t.nfl_season,t.market_week,l.settlement_context) ELSE boff_dev_internal.email_leg_result(t.league_id,t.nfl_season,t.market_week,l.settlement_context,l.actual_value) END) ORDER BY l.leg_number),'[]') FROM public.ticket_legs l WHERE l.ticket_id=t.id)
 ) ORDER BY CASE WHEN t.status='OPEN' THEN 0 WHEN t.status='WON' THEN 1 ELSE 2 END,t.placed_at DESC),'[]')
 INTO tickets FROM (
  SELECT * FROM public.tickets WHERE league_id=p_league AND user_wallet_id=wallet.id AND (p_ticket IS NOT NULL OR nfl_season=board.nfl_season)
  AND (CASE WHEN p_ticket IS NOT NULL THEN id=p_ticket
   WHEN p_kind='monday_watch' THEN market_week=p_week AND ticket_type IS DISTINCT FROM 'future'
   WHEN p_kind='recap' THEN market_week=p_week ELSE false END)
  ORDER BY CASE WHEN status='OPEN' THEN 0 WHEN status='WON' THEN 1 ELSE 2 END,placed_at DESC LIMIT 100
 ) t;

 IF p_kind IN ('opening','monday_watch') AND book.valid_until>now() AND book.last_error IS NULL AND board.status='published' AND board.market_week=p_week THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('teamId',m.team_id,'matchup',m.matchup_key,'kind',m.kind,'side',m.side,
    'line',m.line,'odds',m.odds,'boost',m.boost_pct,'featured',nullif(m.featured,''),'label',m.label) ORDER BY m.matchup_key,m.kind,m.side),'[]')
   INTO quotes FROM public.sportsbook_markets m WHERE m.board_id=board.id AND m.active AND m.kind IN ('moneyline','spread','match_total')
    AND m.metadata->>'alternate' IS DISTINCT FROM 'true';
  offers:=boff_dev_internal.cached_weekly_offer_options(p_league,board.id,
   concat_ws(':',board.id,board.revision,board.content_version,book.source_hash,book.offer_schedule_hash));
  IF p_kind='monday_watch' THEN
   SELECT coalesce(jsonb_agg(jsonb_build_object('label',x.label,'odds',x.odds,'matchup',x.matchup_key,'kind',x.kind,'headshot',x.headshot,'projection',x.projection,'kickoff',x.kickoff)),'[]')
    INTO recommendations FROM (
     SELECT DISTINCT ON (m.metadata->>'player_id') m.label,m.odds,m.matchup_key,m.kind,p.value->>'headshot' headshot,(p.value->>'projection')::numeric projection,p.value->>'kickoff' kickoff
     FROM public.sportsbook_markets m
     JOIN LATERAL jsonb_array_elements(book.payload->'players') p ON p.value->>'id'=m.metadata->>'player_id'
     WHERE m.board_id=board.id AND m.active AND m.market_state='open' AND m.suspension_reason IS NULL
      AND m.kind IN ('player_points','player_milestone','player_h2h') AND m.odds>=-1000
      AND (p.value->>'kickoff')::timestamptz>now()
      AND extract(isodow FROM (p.value->>'kickoff')::timestamptz AT TIME ZONE 'America/New_York')=1
     ORDER BY m.metadata->>'player_id',abs(m.odds) LIMIT 3
    ) x;
  END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('label',replace(initcap(achievement),'_',' '),'percent',percent)),'[]')
   INTO rewards FROM boff_dev_internal.fantasy_reward_awards
   WHERE league_id=p_league AND user_id=p_user AND season=board.nfl_season AND revoked_at IS NULL AND ticket_id IS NULL
    AND (expires_at IS NULL OR expires_at>now());
 END IF;
 IF p_kind='recap' THEN
  SELECT jsonb_build_object('Won',count(*) FILTER(WHERE status='WON'),'Lost',count(*) FILTER(WHERE status='LOST'),
   'Pushed Or Voided',count(*) FILTER(WHERE status IN ('PUSH','VOIDED')),'Still Open',count(*) FILTER(WHERE status='OPEN'),
   'Net Profit',coalesce(sum(CASE WHEN status='WON' THEN actual_payout-stake WHEN status='LOST' THEN -stake ELSE 0 END),0)||' credits')
  INTO performance FROM public.tickets WHERE league_id=p_league AND user_wallet_id=wallet.id AND nfl_season=board.nfl_season AND market_week=p_week;
  SELECT results->wallet.team_id::text->>'matchup_id' INTO matchup FROM public.league_result_weeks
   WHERE league_id=p_league AND nfl_season=board.nfl_season AND market_week=p_week AND final;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'name',t.team_name,'avatar',t.avatar_url,
   'matchupId',matchup,'observed',(r.value->>'points')::numeric,'projection',(r.value->>'projection')::numeric)),'[]')
  INTO result_teams FROM public.league_result_weeks w CROSS JOIN LATERAL jsonb_each(w.results) r
   JOIN public.teams t ON t.id::text=r.key AND t.league_id=w.league_id
   WHERE w.league_id=p_league AND w.nfl_season=board.nfl_season AND w.market_week=p_week AND w.final AND r.value->>'matchup_id'=matchup;
  SELECT coalesce(jsonb_agg(jsonb_build_object('teamId',team_id,'matchup',matchup,'kind',kind,'side',side,'line',line,'odds',odds)),'[]')
   INTO original_quotes FROM public.opening_market_benchmarks
   WHERE league_id=p_league AND nfl_season=board.nfl_season AND market_week=p_week AND kind IN ('moneyline','spread','match_total')
    AND (home_team_id::text IN(SELECT value->>'id' FROM jsonb_array_elements(result_teams)) OR away_team_id::text IN(SELECT value->>'id' FROM jsonb_array_elements(result_teams)));
  SELECT jsonb_build_object('Tickets On Your Matchup',count(DISTINCT t.id),
   'Members On Your Matchup',count(DISTINCT coalesce(t.user_wallet_id::text,t.bettor_display_name)),
   'Tickets Backing You',count(DISTINCT t.id) FILTER(WHERE l.settlement_context->>'team_id'=wallet.team_id::text),
   'Tickets Backing Your Opponent',count(DISTINCT t.id) FILTER(WHERE l.settlement_context->>'team_id' IS NOT NULL AND l.settlement_context->>'team_id'<>wallet.team_id::text),
   'Tickets Taking The Under',count(DISTINCT t.id) FILTER(WHERE l.settlement_context->>'side'='under'))
  INTO crowd FROM public.tickets t JOIN public.ticket_legs l ON l.ticket_id=t.id
   WHERE t.league_id=p_league AND t.nfl_season=board.nfl_season AND t.market_week=p_week
    AND (l.settlement_context->>'home_team_id'=wallet.team_id::text OR l.settlement_context->>'away_team_id'=wallet.team_id::text);
  SELECT coalesce(jsonb_agg(jsonb_build_object('market',x.market_type,'selection',x.selection,'tickets',x.tickets) ORDER BY x.market_type,x.selection),'[]')
  INTO market_bets FROM (
   SELECT l.market_type,l.selection,count(DISTINCT t.id) tickets FROM public.tickets t JOIN public.ticket_legs l ON l.ticket_id=t.id
   WHERE t.league_id=p_league AND t.nfl_season=board.nfl_season AND t.market_week=p_week
    AND l.settlement_context->>'kind' IN ('moneyline','spread','winning_margin','match_total','team_total')
    AND (l.settlement_context->>'home_team_id'=wallet.team_id::text OR l.settlement_context->>'away_team_id'=wallet.team_id::text)
   GROUP BY l.market_type,l.selection
  ) x;
  SELECT jsonb_build_object('Bets Placed',count(*),'Winning Tickets',count(*) FILTER(WHERE status='WON'),
   'Credits Wagered',round(coalesce(sum(stake),0),2)||' credits') INTO league_betting
   FROM public.tickets WHERE league_id=p_league AND nfl_season=board.nfl_season AND market_week=p_week;
  WITH counts AS (
   SELECT coalesce(nullif(bettor_display_name,''),'League Member') name,user_wallet_id,count(*) bets
   FROM public.tickets WHERE league_id=p_league AND nfl_season=board.nfl_season AND market_week=p_week
   GROUP BY user_wallet_id,bettor_display_name
  ) SELECT jsonb_build_object('Most Bets Placed',string_agg(name,' / ' ORDER BY name)||' · '||max(bets)||' bets') INTO leader
    FROM counts WHERE bets=(SELECT max(bets) FROM counts);
  IF leader->>'Most Bets Placed' IS NOT NULL THEN league_betting:=league_betting||leader; END IF;
  WITH losses AS (
   SELECT coalesce(nullif(bettor_display_name,''),'League Member') name,user_wallet_id,sum(stake) lost
   FROM public.tickets WHERE league_id=p_league AND nfl_season=board.nfl_season AND market_week=p_week AND status='LOST'
   GROUP BY user_wallet_id,bettor_display_name
  ) SELECT jsonb_build_object('Most Credits Lost',string_agg(name,' / ' ORDER BY name)||' · '||round(max(lost),2)||' credits') INTO leader
    FROM losses WHERE lost=(SELECT max(lost) FROM losses);
  IF leader->>'Most Credits Lost' IS NOT NULL THEN league_betting:=league_betting||leader; END IF;
  SELECT jsonb_build_object('Longest Winning Ticket',coalesce(nullif(t.bettor_display_name,''),'League Member')||' · '||legs.total||'-leg · '||
   CASE WHEN t.accepted_combined_odds>0 THEN '+' ELSE '' END||t.accepted_combined_odds) INTO leader
   FROM public.tickets t CROSS JOIN LATERAL (SELECT count(*) total FROM public.ticket_legs WHERE ticket_id=t.id) legs
   WHERE t.league_id=p_league AND t.nfl_season=board.nfl_season AND t.market_week=p_week AND t.status='WON'
   ORDER BY legs.total DESC,t.actual_payout-t.stake DESC,t.id LIMIT 1;
  IF leader IS NOT NULL THEN league_betting:=league_betting||leader; END IF;
  SELECT jsonb_build_object('teamId',t.id,'name',t.team_name,'score',(r.value->>'points')::numeric,
   'previousRecord',(SELECT max((v.value->>'points')::numeric) FROM public.league_result_weeks prev CROSS JOIN LATERAL jsonb_each(prev.results) v
    WHERE prev.league_id=p_league AND prev.nfl_season=board.nfl_season AND prev.market_week<p_week AND prev.final)) INTO metric
   FROM public.league_result_weeks w CROSS JOIN LATERAL jsonb_each(w.results) r JOIN public.teams t ON t.id::text=r.key AND t.league_id=w.league_id
   WHERE w.league_id=p_league AND w.nfl_season=board.nfl_season AND w.market_week=p_week AND w.final
   ORDER BY (r.value->>'points')::numeric DESC,t.id LIMIT 1;
  IF metric IS NOT NULL THEN recap_stats:=recap_stats||jsonb_build_object('highScorer',metric); END IF;
  WITH pairs AS (
   SELECT a.key id_a,b.key id_b,a.value a,b.value b FROM public.league_result_weeks w
    CROSS JOIN LATERAL jsonb_each(w.results) a JOIN LATERAL jsonb_each(w.results) b ON a.value->>'matchup_id'=b.value->>'matchup_id' AND a.key<b.key
    WHERE w.league_id=p_league AND w.nfl_season=board.nfl_season AND w.market_week=p_week AND w.final
  ) SELECT jsonb_build_object('winner',CASE WHEN (p.a->>'points')::numeric>(p.b->>'points')::numeric THEN ta.team_name ELSE tb.team_name END,
   'loser',CASE WHEN (p.a->>'points')::numeric>(p.b->>'points')::numeric THEN tb.team_name ELSE ta.team_name END,
   'winnerScore',greatest((p.a->>'points')::numeric,(p.b->>'points')::numeric),'loserScore',least((p.a->>'points')::numeric,(p.b->>'points')::numeric),
   'margin',abs((p.a->>'points')::numeric-(p.b->>'points')::numeric)) INTO metric
   FROM pairs p JOIN public.teams ta ON ta.id::text=p.id_a AND ta.league_id=p_league JOIN public.teams tb ON tb.id::text=p.id_b AND tb.league_id=p_league
   WHERE (p.a->>'points')::numeric<>(p.b->>'points')::numeric ORDER BY abs((p.a->>'points')::numeric-(p.b->>'points')::numeric),p.id_a LIMIT 1;
  IF metric IS NOT NULL THEN recap_stats:=recap_stats||jsonb_build_object('closestMatchup',metric); END IF;
  SELECT jsonb_build_object('winner',ta.team_name,'loser',tb.team_name,'winnerScore',(a.value->>'points')::numeric,
   'loserScore',(b.value->>'points')::numeric,'odds',q.odds) INTO metric
   FROM public.league_result_weeks w CROSS JOIN LATERAL jsonb_each(w.results) a
    JOIN LATERAL jsonb_each(w.results) b ON a.value->>'matchup_id'=b.value->>'matchup_id' AND a.key<>b.key
    JOIN public.teams ta ON ta.id::text=a.key AND ta.league_id=w.league_id JOIN public.teams tb ON tb.id::text=b.key AND tb.league_id=w.league_id
    JOIN public.opening_market_benchmarks q ON q.league_id=w.league_id AND q.nfl_season=w.nfl_season AND q.market_week=w.market_week AND q.team_id::text=a.key AND q.kind='moneyline' AND q.odds>0
   WHERE w.league_id=p_league AND w.nfl_season=board.nfl_season AND w.market_week=p_week AND w.final
    AND (a.value->>'points')::numeric>(b.value->>'points')::numeric ORDER BY q.odds DESC,ta.id LIMIT 1;
  IF metric IS NOT NULL THEN recap_stats:=recap_stats||jsonb_build_object('biggestUpset',metric); END IF;
  SELECT recap_stats||jsonb_build_object('tiedMatchups',count(*)) INTO recap_stats FROM public.league_result_weeks w
   CROSS JOIN LATERAL jsonb_each(w.results) a JOIN LATERAL jsonb_each(w.results) b ON a.value->>'matchup_id'=b.value->>'matchup_id' AND a.key<b.key
   WHERE w.league_id=p_league AND w.nfl_season=board.nfl_season AND w.market_week=p_week AND w.final AND (a.value->>'points')::numeric=(b.value->>'points')::numeric;
  SELECT jsonb_build_object('name',coalesce(nullif(t.bettor_display_name,''),'League Member'),'profit',t.actual_payout-t.stake,'legs',legs.total,'odds',t.accepted_combined_odds) INTO metric
   FROM public.tickets t CROSS JOIN LATERAL(SELECT count(*) total FROM public.ticket_legs WHERE ticket_id=t.id) legs
   WHERE t.league_id=p_league AND t.nfl_season=board.nfl_season AND t.market_week=p_week AND t.status='WON'
   ORDER BY t.actual_payout-t.stake DESC,t.id LIMIT 1;
  IF metric IS NOT NULL THEN recap_stats:=recap_stats||jsonb_build_object('largestWin',metric); END IF;
 END IF;
 SELECT last_claim_at INTO last_claim FROM boff_dev_internal.credit_claim_state WHERE wallet_id=wallet.id;
 eligible:=wallet.balance+coalesce((SELECT sum(stake) FROM public.tickets WHERE user_wallet_id=wallet.id AND status='OPEN' AND ticket_type IS DISTINCT FROM 'future'),0);
 RETURN jsonb_build_object('tickets',tickets,'quotes',quotes,'offers',offers,'rewards',rewards,'performance',performance,
  'recommendations',recommendations,'marketBets',market_bets,'leagueBetting',league_betting,'recapStats',recap_stats,'resultTeams',result_teams,'openingQuotes',original_quotes,'crowd',crowd,'balance',wallet.balance,
  'claim',CASE WHEN eligible>=100 THEN 0
   WHEN last_claim IS NULL OR last_claim < ((date_trunc('week',(now() AT TIME ZONE 'America/New_York')-interval '2 days 6 hours')+interval '2 days 6 hours') AT TIME ZONE 'America/New_York')
    OR last_claim<=now()-interval '24 hours' THEN 50
   WHEN last_claim<=now()-interval '2 hours' THEN 10 ELSE 0 END,
  'openStakes',coalesce((SELECT sum(stake) FROM public.tickets WHERE user_wallet_id=wallet.id AND status='OPEN' AND ticket_type IS DISTINCT FROM 'future'),0),
  'futureStakes',coalesce((SELECT sum(stake) FROM public.tickets WHERE user_wallet_id=wallet.id AND status='OPEN' AND ticket_type='future'),0));
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."email_edition_for_user"(p_league uuid, p_user uuid, p_kind text, p_week integer, p_ticket uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.email_league_options(p_user uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',l.id,'name',l.name,'path','/'||l.sleeper_league_id) ORDER BY l.name,l.id),'[]')
 FROM public.leagues l JOIN boff_dev_internal.participant_links m ON m.league_id=l.id AND m.user_id=p_user
 JOIN auth.users u ON u.id=m.user_id AND u.email_confirmed_at IS NOT NULL
 WHERE l.sleeper_league_id ~ '^[0-9]{1,32}$'
 AND EXISTS(SELECT FROM public.dev_current_book b WHERE b.league_id=l.id)
$function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."email_league_options"(p_user uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.email_league_report(p_user uuid, p_league uuid, p_kind text, p_week integer, p_details boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE member record; league public.leagues; payload jsonb; week integer;
BEGIN
 p_details:=true;
 IF p_kind NOT IN ('opening','recap','monday_watch','credit') THEN RAISE EXCEPTION 'Unsupported report'; END IF;
 SELECT * INTO member FROM boff_dev_internal.participant_links WHERE league_id=p_league AND user_id=p_user;
 IF member.team_id IS NULL OR NOT EXISTS(SELECT FROM auth.users WHERE id=p_user AND email_confirmed_at IS NOT NULL)
 THEN RAISE EXCEPTION 'Active verified membership required' USING ERRCODE='42501'; END IF;
 SELECT * INTO league FROM public.leagues WHERE id=p_league;
 SELECT b.payload INTO payload FROM public.dev_current_book b WHERE b.league_id=p_league;
 IF payload IS NULL THEN RAISE EXCEPTION 'League report unavailable'; END IF;
 week:=coalesce(p_week,league.active_week);
 IF week NOT BETWEEN 1 AND 18 THEN RAISE EXCEPTION 'Invalid report week'; END IF;
 RETURN jsonb_build_object('id',league.id,'name',league.name,'path','/'||league.sleeper_league_id,'week',week,
  'teamId',member.team_id,'details',coalesce(p_details,false),'payload',jsonb_build_object('teams',payload->'teams','leagueAvatar',coalesce(payload->'leagueAvatar',to_jsonb(league.avatar_url)),'leagueName',league.name),
  'edition',CASE WHEN p_details THEN boff_dev_internal.email_edition_for_user(p_league,p_user,p_kind,week,NULL) ELSE '{}'::jsonb END);
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."email_league_report"(p_user uuid, p_league uuid, p_kind text, p_week integer, p_details boolean) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.email_leg_result(p_league uuid, p_season integer, p_week integer, p_context jsonb, p_actual numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE kind text:=p_context->>'kind'; teams jsonb:='[]'; label text;
BEGIN
 IF kind IS NULL OR kind LIKE 'future_%' THEN RETURN NULL; END IF;
 IF kind IN ('moneyline','spread','winning_margin','match_total','team_total','team_milestone','weekly_high','weekly_low') THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.team_name,'avatar',t.avatar_url,'score',(r.value->>'points')::numeric) ORDER BY t.id),'[]')
  INTO teams FROM public.league_result_weeks w CROSS JOIN LATERAL jsonb_each(w.results) r
  JOIN public.teams t ON t.id::text=r.key AND t.league_id=w.league_id
  WHERE w.league_id=p_league AND w.nfl_season=p_season AND w.market_week=p_week AND w.final
   AND (CASE WHEN kind IN ('weekly_high','weekly_low') THEN abs((r.value->>'points')::numeric-p_actual)<0.001
    WHEN kind IN ('team_total','team_milestone') THEN t.id::text=p_context->>'team_id'
    ELSE t.id::text IN (p_context->>'home_team_id',p_context->>'away_team_id') OR
     (p_context->>'home_team_id' IS NULL AND r.value->>'matchup_id'=w.results->(p_context->>'team_id')->>'matchup_id') END);
 ELSIF kind IN ('player_points','player_milestone','player_h2h') THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('name',p.value->>'name','avatar',p.value->>'headshot')),'[]') INTO teams
   FROM public.dev_current_book b CROSS JOIN LATERAL jsonb_array_elements(b.payload->'players') p
   WHERE b.league_id=p_league AND (p.value->>'id'=p_context->'metadata'->>'player_id'
     OR (kind='player_h2h' AND p.value->>'id'=p_context->'metadata'->>'opponent_player_id'));
 END IF;
 label:=CASE WHEN kind IN ('moneyline','spread','winning_margin') THEN 'Scores'
  WHEN kind='match_total' THEN 'Match Total' WHEN kind='team_total' THEN 'Team Total'
  WHEN kind IN ('player_points','player_milestone','team_milestone','weekly_high','weekly_low') THEN 'Fantasy Points'
  WHEN kind IN ('player_h2h','position_group') THEN 'Point Difference'
  WHEN kind='weekly_average' THEN 'League Average' WHEN kind IN ('weekly_highest_score','weekly_any_200') THEN 'Highest Score'
  WHEN kind='weekly_any_below_100' THEN 'Lowest Score' WHEN kind='weekly_count_150' THEN 'Teams Scoring 150+'
  WHEN kind='weekly_count_projection' THEN 'Teams Above Projection'
  ELSE 'Result' END;
 IF label='Scores' AND jsonb_array_length(teams)=0 THEN RETURN NULL; END IF;
 IF label<>'Scores' AND p_actual IS NULL THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('label',label,'value',p_actual,'teams',teams);
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."email_leg_result"(p_league uuid, p_season integer, p_week integer, p_context jsonb, p_actual numeric) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.email_matchup_context(p_league uuid, p_season integer, p_week integer, p_context jsonb, p_live boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE teams jsonb:='[]'; current_scores boolean:=false; key text;
BEGIN
 IF p_context->>'home_team_id' IS NULL AND p_context->>'away_team_id' IS NULL AND p_context->>'team_id' IS NULL THEN RETURN NULL; END IF;
 IF p_context->>'kind' LIKE 'future_%' OR p_context->>'kind' LIKE 'weekly_%' THEN RETURN NULL; END IF;
 IF p_live THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.value->>'id','name',t.value->>'name','avatar',t.value->>'avatar','score',t.value->'observed') ORDER BY t.value->>'id'),'[]')
   INTO teams FROM public.dev_current_book c JOIN public.sportsbook_boards b ON b.id=c.board_id
   CROSS JOIN LATERAL jsonb_array_elements(c.payload->'teams') t
   WHERE c.league_id=p_league AND b.nfl_season=p_season AND b.market_week=p_week AND c.valid_until>now() AND c.last_error IS NULL
    AND jsonb_typeof(t.value->'observed')='number'
    AND (t.value->>'id' IN (p_context->>'home_team_id',p_context->>'away_team_id') OR
     (p_context->>'home_team_id' IS NULL AND t.value->>'matchupId'=(SELECT v->>'matchupId' FROM jsonb_array_elements(c.payload->'teams') v WHERE v->>'id'=p_context->>'team_id' LIMIT 1)));
  current_scores:=jsonb_array_length(teams)=2;
 END IF;
 IF NOT current_scores THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',t.id,'name',t.team_name,'avatar',t.avatar_url,'score',r.value->'points') ORDER BY t.id),'[]')
   INTO teams FROM public.league_result_weeks w CROSS JOIN LATERAL jsonb_each(w.results) r
   JOIN public.teams t ON t.id::text=r.key AND t.league_id=w.league_id
   WHERE w.league_id=p_league AND w.nfl_season=p_season AND w.market_week=p_week AND w.final
    AND (t.id::text IN (p_context->>'home_team_id',p_context->>'away_team_id') OR
     (p_context->>'home_team_id' IS NULL AND r.value->>'matchup_id'=w.results->(p_context->>'team_id')->>'matchup_id'));
 END IF;
 IF jsonb_array_length(teams)<>2 THEN RETURN NULL; END IF;
 SELECT p_season||':'||p_week||':'||string_agg(value->>'id',':' ORDER BY value->>'id') INTO key FROM jsonb_array_elements(teams);
 RETURN jsonb_build_object('key',key,'current',current_scores,'teams',teams);
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."email_matchup_context"(p_league uuid, p_season integer, p_week integer, p_context jsonb, p_live boolean) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.email_open_leg_result(p_league uuid, p_season integer, p_week integer, p_context jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE kind text:=p_context->>'kind'; game jsonb; teams jsonb:='[]'; payload jsonb; value numeric; label text; ids jsonb; target text; count_found integer; group_score numeric;
BEGIN
 game:=boff_dev_internal.email_matchup_context(p_league,p_season,p_week,p_context,true);
 IF kind IN ('moneyline','spread','winning_margin') THEN
  IF game IS NULL THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('label','Scores','current',game->'current','teams',game->'teams');
 ELSIF kind='match_total' THEN
  IF game IS NULL THEN RETURN NULL; END IF;
  SELECT sum((v->>'score')::numeric) INTO value FROM jsonb_array_elements(game->'teams') v;
  RETURN jsonb_build_object('label','Match Total','current',game->'current','value',value,'teams',game->'teams');
 END IF;
 SELECT c.payload INTO payload FROM public.dev_current_book c JOIN public.sportsbook_boards b ON b.id=c.board_id
  WHERE c.league_id=p_league AND b.nfl_season=p_season AND b.market_week=p_week AND c.valid_until>now() AND c.last_error IS NULL;
 IF payload IS NULL THEN RETURN NULL; END IF;
 IF kind IN ('team_total','team_milestone') THEN
  SELECT jsonb_build_array(jsonb_build_object('name',v->>'name','avatar',v->>'avatar','score',v->'observed')),(v->>'observed')::numeric INTO teams,value
   FROM jsonb_array_elements(payload->'teams') v WHERE v->>'id'=p_context->>'team_id' AND jsonb_typeof(v->'observed')='number' LIMIT 1;
  label:=CASE WHEN kind='team_total' THEN 'Team Total' ELSE 'Fantasy Points' END;
 ELSIF kind IN ('player_points','player_milestone','player_h2h') THEN
  SELECT coalesce(jsonb_agg(jsonb_build_object('name',v->>'name','avatar',v->>'headshot','score',v->'current') ORDER BY v->>'id'),'[]') INTO teams
   FROM jsonb_array_elements(payload->'players') v WHERE jsonb_typeof(v->'current')='number' AND
    (v->>'id'=p_context->'metadata'->>'player_id' OR (kind='player_h2h' AND v->>'id'=p_context->'metadata'->>'opponent_player_id'));
  IF jsonb_array_length(teams)<>(CASE WHEN kind='player_h2h' THEN 2 ELSE 1 END) THEN RETURN NULL; END IF;
  IF kind='player_h2h' THEN label:='Scores'; ELSE label:='Fantasy Points';value:=(teams->0->>'score')::numeric; END IF;
 ELSIF kind='position_group' THEN
  FOREACH target IN ARRAY ARRAY['home','away'] LOOP
   ids:=p_context->'metadata'->(target||'_player_ids');
   IF jsonb_typeof(ids) IS DISTINCT FROM 'array' OR jsonb_array_length(ids)=0 THEN RETURN NULL; END IF;
   SELECT count(*),sum((v->>'current')::numeric) INTO count_found,group_score FROM jsonb_array_elements(payload->'players') v
    WHERE jsonb_typeof(v->'current')='number' AND v->>'id' IN (SELECT jsonb_array_elements_text(ids));
   IF count_found<>jsonb_array_length(ids) THEN RETURN NULL; END IF;
   SELECT teams||jsonb_build_array(jsonb_build_object('name',v->>'name','avatar',v->>'avatar','score',group_score)) INTO teams
    FROM jsonb_array_elements(payload->'teams') v WHERE v->>'id'=p_context->>(target||'_team_id') LIMIT 1;
  END LOOP;
  label:='Scores';
 ELSIF kind IN ('weekly_average','weekly_highest_score','weekly_high','weekly_low','weekly_any_200','weekly_any_below_100','weekly_count_150','weekly_count_projection') THEN
  IF kind='weekly_count_projection' THEN
   IF p_context->'metadata'->'projection_targets' IS NULL THEN RETURN NULL; END IF;
   SELECT count(*) FILTER(WHERE (v->>'observed')::numeric>(p_context->'metadata'->'projection_targets'->>(v->>'id'))::numeric) INTO value FROM jsonb_array_elements(payload->'teams') v;
   label:='Teams Above Projection';
  ELSE
   SELECT CASE WHEN kind='weekly_average' THEN avg((v->>'observed')::numeric)
    WHEN kind='weekly_count_150' THEN count(*) FILTER(WHERE (v->>'observed')::numeric>=150)
    WHEN kind IN ('weekly_low','weekly_any_below_100') THEN min((v->>'observed')::numeric)
    ELSE max((v->>'observed')::numeric) END INTO value FROM jsonb_array_elements(payload->'teams') v WHERE jsonb_typeof(v->'observed')='number';
   label:=CASE WHEN kind='weekly_average' THEN 'League Average' WHEN kind='weekly_count_150' THEN 'Teams Scoring 150+'
    WHEN kind IN ('weekly_low','weekly_any_below_100') THEN 'Lowest Score' ELSE 'Highest Score' END;
  END IF;
 ELSE RETURN NULL;
 END IF;
 IF teams IS NULL OR (value IS NULL AND label<>'Scores') THEN RETURN NULL; END IF;
 RETURN jsonb_build_object('label',label,'current',true,'value',value,'teams',teams);
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."email_open_leg_result"(p_league uuid, p_season integer, p_week integer, p_context jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.feature_weekly_quotes(p_quotes jsonb, p_teams jsonb, p_week integer, p_regular_weeks integer, p_boost integer, p_playoff_teams integer)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 WITH teams AS (
  SELECT t.*, rank() OVER (
   ORDER BY (wins + 0.5*ties)/greatest(1,games) DESC,
    "pointsFor" DESC, "pointsAgainst" DESC
  ) AS standing
  FROM jsonb_to_recordset(p_teams) AS t(
   id uuid, wins numeric, ties numeric, games numeric, "pointsFor" numeric, "pointsAgainst" numeric
  )
 ), matchups AS (
  SELECT quote->>'matchup_key' AS matchup,
   (a.wins + h.wins + 0.5*(a.ties+h.ties))/greatest(1,a.games+h.games) AS record,
   a."pointsFor"+h."pointsFor" AS points,
   least(a.standing,h.standing) AS best_standing,
   abs((quote->>'away_projection')::numeric-(quote->>'home_projection')::numeric) AS spread,
   (quote->>'line')::numeric AS total
  FROM jsonb_array_elements(p_quotes) AS q(quote)
  JOIN teams a ON a.id=(quote->>'away_team_id')::uuid
  JOIN teams h ON h.id=(quote->>'home_team_id')::uuid
  WHERE quote->>'kind'='match_total' AND quote->>'side'='over'
   AND quote->'metadata'->>'alternate' IS DISTINCT FROM 'true'
 ), ranked AS (
  SELECT *, count(*) OVER () / 2 AS feature_cap,
   0.50*coalesce((record-min(record) OVER w)/nullif(max(record) OVER w-min(record) OVER w,0),0.5)
   +0.25*coalesce((points-min(points) OVER w)/nullif(max(points) OVER w-min(points) OVER w,0),0.5)
   +0.15*(1-coalesce((spread-min(spread) OVER w)/nullif(max(spread) OVER w-min(spread) OVER w,0),0.5))
   +0.10*coalesce((total-min(total) OVER w)/nullif(max(total) OVER w-min(total) OVER w,0),0.5) AS rating
  FROM matchups WINDOW w AS ()
 ), tank AS (
  SELECT matchup, 'Tank Bowl'::text AS featured FROM ranked
  WHERE p_week>p_regular_weeks/2 AND p_week<=p_regular_weeks AND round(record*100,1)<=33.3
   AND p_playoff_teams BETWEEN 1 AND jsonb_array_length(p_teams)
   AND best_standing > p_playoff_teams
  ORDER BY rating DESC, matchup LIMIT (SELECT max(feature_cap) FROM ranked)
 ), game AS (
  SELECT matchup, 'Game of the Week'::text AS featured FROM ranked r
  WHERE p_week<=p_regular_weeks AND r.feature_cap>(SELECT count(*) FROM tank)
   AND NOT EXISTS(SELECT 1 FROM tank t WHERE t.matchup=r.matchup)
  ORDER BY rating DESC, matchup LIMIT 1
 ), features AS (
  SELECT * FROM tank UNION ALL SELECT * FROM game
 )
 SELECT jsonb_agg(
  quote || jsonb_build_object(
   'featured', CASE WHEN eligible THEN f.featured ELSE '' END,
   'boost_pct', CASE WHEN eligible THEN p_boost ELSE 0 END
  ) ORDER BY ordinality
 )
 FROM jsonb_array_elements(p_quotes) WITH ORDINALITY AS q(quote, ordinality)
 LEFT JOIN features f ON f.matchup=quote->>'matchup_key'
 CROSS JOIN LATERAL (
  SELECT p_boost>0 AND quote->'metadata'->>'alternate' IS DISTINCT FROM 'true'
   AND ((f.featured='Game of the Week' AND quote->>'kind'='moneyline')
     OR (f.featured='Tank Bowl' AND quote->>'kind'='match_total' AND quote->>'side'='over')) AS eligible
 ) e;
$function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."feature_weekly_quotes"(p_quotes jsonb, p_teams jsonb, p_week integer, p_regular_weeks integer, p_boost integer, p_playoff_teams integer) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.flag_fantasy_reward_correction()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE digest text;
BEGIN
  digest := CASE WHEN NEW.final THEN md5(NEW.results::text) ELSE 'not-final' END;
  UPDATE boff_dev_internal.fantasy_reward_runs
  SET correction_digest = CASE WHEN source_digest <> digest THEN digest ELSE NULL END
  WHERE league_id = NEW.league_id AND season = NEW.nfl_season AND week = NEW.market_week
    AND correction_digest IS DISTINCT FROM CASE WHEN source_digest <> digest THEN digest ELSE NULL END;
  RETURN NEW;
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."flag_fantasy_reward_correction"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.hash_offer_schedule()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_OP='INSERT' OR NEW.offer_schedule_hash IS NULL OR NEW.payload IS DISTINCT FROM OLD.payload THEN
  NEW.offer_schedule_hash:=md5(jsonb_build_array(
   NEW.payload->'firstGame',
   (SELECT jsonb_agg(jsonb_build_array(t->'matchupId',t->'roster_id') ORDER BY t->>'roster_id') FROM jsonb_array_elements(NEW.payload->'teams') t),
   (SELECT jsonb_agg(jsonb_build_array(p->'roster',p->'kickoff') ORDER BY p->>'roster',p->>'kickoff') FROM jsonb_array_elements(NEW.payload->'players') p)
  )::text);
 END IF;
 RETURN NEW;
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."hash_offer_schedule"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.hash_weekly_payload()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_OP='INSERT' OR NEW.payload IS DISTINCT FROM OLD.payload THEN NEW.payload_hash:=md5(NEW.payload::text); END IF;
 RETURN NEW;
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."hash_weekly_payload"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.keep_weekly_features(p_book jsonb, prior jsonb, p_board uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE assignments jsonb; priced jsonb;
BEGIN
 IF (p_book->'payload'->>'scoringStarted')::boolean IS DISTINCT FROM true THEN
  RETURN p_book;
 END IF;
 IF prior->>'season'=p_book->>'season' AND prior->>'week'=p_book->>'week' THEN
  assignments:=prior->'featureAssignments';
 END IF;
 IF assignments IS NULL THEN
  SELECT coalesce(jsonb_object_agg(m.metadata->>'ui_id',jsonb_build_object(
   'featured',m.featured,'boost_pct',m.boost_pct,'source',m.metadata->>'feature_source')),'{}')
  INTO assignments FROM public.sportsbook_markets m
  WHERE board_id=p_board AND m.active AND m.boost_pct>0 AND m.metadata->>'ui_id' IS NOT NULL;
 END IF;
 SELECT jsonb_agg(q||jsonb_build_object('featured',coalesce(f->>'featured',''),'boost_pct',coalesce((f->>'boost_pct')::integer,0),
  'metadata',(coalesce(q->'metadata','{}')-'feature_source')||
   CASE WHEN f->>'source' IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('feature_source',f->>'source') END) ORDER BY ord)
 INTO priced
 FROM jsonb_array_elements(p_book->'quotes') WITH ORDINALITY items(q,ord)
 CROSS JOIN LATERAL (SELECT assignments->(q->>'ui_id') f) match;
 RETURN jsonb_set(jsonb_set(p_book,'{quotes}',priced),'{payload,featureAssignments}',assignments);
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."keep_weekly_features"(p_book jsonb, prior jsonb, p_board uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.place_reward_ticket(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid, p_reward_percent numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_board public.sportsbook_boards; v_member record; v_wallet public.user_wallets; v_quote public.sportsbook_markets;
 v_ticket public.tickets; v_price numeric:=1; v_legprice numeric; v_price_int integer; v_payout numeric; v_id uuid:=gen_random_uuid(); v_number integer:=0; v_matchup text;
begin
 select * into v_board from public.sportsbook_boards where id=p_board for share;
 if not found then raise exception 'This market board is unavailable.'; end if;
 select * into v_member from sportsbook_private.financial_participant(v_board.league_id);
 if not found then raise exception 'Sign in with your approved league account.'; end if;
 select * into v_wallet from public.user_wallets where league_id=v_board.league_id and user_id=auth.uid() and status='approved' for update;
 select * into v_ticket from public.tickets where request_key=p_request;
 if found then if v_ticket.user_wallet_id is distinct from v_wallet.id then raise exception 'Request belongs to another financial account.';end if;
   if exists(select 1 from public.ticket_promotions where ticket_id=v_ticket.id) then raise exception 'Request identifier already used for a promotion.';end if; if v_ticket.team_id<>v_member.team_id then raise exception 'Request identifier already used.'; end if;
   if v_ticket.stake is distinct from p_stake or (select array_agg(market_quote_id order by market_quote_id) from public.ticket_legs where ticket_id=v_ticket.id) is distinct from (select array_agg(x order by x) from unnest(p_picks) x) then raise exception 'This request was already used for a different ticket.'; end if;
   return jsonb_build_object('ticket_id',v_ticket.id,'balance',v_wallet.balance,'duplicate',true);
 end if;
 if p_request is null or p_stake is null or p_stake<>round(p_stake,2) or p_stake<1 or p_stake>v_wallet.balance or v_wallet.balance is null then raise exception 'Enter a whole-cent wager between $1 and your available balance.'; end if;
 if v_board.status<>'published' or now()<v_board.opens_at or now()>=v_board.closes_at then raise exception 'Betting is closed for this board.'; end if;
 if v_board.reopening_id is not null and not sportsbook_private.valid_reopening(v_board,p_picks) then raise exception 'Reopening prices or game state changed. Refresh your picks.'; end if; 
 if v_board.suspension_reason is not null then raise exception 'Markets suspended: %',v_board.suspension_reason; end if;
 if v_board.quote_valid_until is not null and v_board.quote_valid_until<=now() then raise exception 'Quotes expired; wait for a successful refresh.'; end if;
 if v_board.board_type<>'future' and exists(select 1 from public.line_refresh_runtime r where r.league_id=v_board.league_id and (r.market_week=v_board.market_week or v_board.board_type='future') and (r.observed_at is null or r.observed_at<now()-interval '3 minutes' or (r.week_started and not sportsbook_private.valid_reopening(v_board,p_picks)) or r.last_error is not null)) then raise exception 'Current game state cannot support pregame acceptance.'; end if;
 if exists(select 1 from public.sportsbook_markets where id=any(p_picks) and active and (market_state<>'open' or suspension_reason is not null or metadata->>'resolved'='true')) then raise exception 'A selection is suspended or resolved.'; end if;
 if v_board.revision is distinct from p_revision then raise exception 'Lines have changed. Refresh and review your picks.'; end if;
 if p_picks is null or cardinality(p_picks) not between 1 and 10 or (select count(distinct x) from unnest(p_picks) x)<>cardinality(p_picks) then raise exception 'Select 1–10 distinct picks; singles must be Weekly Specials.'; end if;
 if (select count(*) from public.sportsbook_markets where id=any(p_picks) and board_id=p_board and active)<>cardinality(p_picks) then raise exception 'A selection is no longer available.'; end if;
 if v_board.board_type='future' and cardinality(p_picks)=1 and exists(select 1 from public.sportsbook_markets where id=any(p_picks) and kind='future_playoffs') then raise exception 'Make/Miss Playoffs requires at least two playoff picks.'; end if;
 if v_board.board_type='future' and cardinality(p_picks)>1 and exists(select 1 from public.sportsbook_markets where id=any(p_picks) and kind not in ('future_playoffs','future_win_total')) then raise exception 'League Winner and #1 Pick are standalone bets.'; end if;
 if v_board.board_type='future' and cardinality(p_picks)>1 and (select count(distinct kind) from public.sportsbook_markets where id=any(p_picks))<>1 then raise exception 'Playoff and win-total parlays must remain separate.'; end if;
 if v_board.board_type='weekly' and exists(select 1 from public.sportsbook_markets where id=any(p_picks) and kind like 'future_%') then raise exception 'Futures require a season board.'; end if;
 if v_board.board_type='future' and exists(select 1 from public.sportsbook_markets where id=any(p_picks) and kind not like 'future_%') then raise exception 'Only futures belong on a season board.'; end if;
 
 if exists(select 1 from public.sportsbook_markets a join public.sportsbook_markets b on a.id<b.id where a.id=any(p_picks) and b.id=any(p_picks) and public.sportsbook_special_conflict(a,b)) then raise exception 'These selections have contradictory outcomes.'; end if;
 if exists(select 1 from public.sportsbook_markets where id=any(p_picks) group by market_key having count(*)>1) then raise exception 'Choose only one outcome per market.'; end if;
 if exists(select 1 from public.sportsbook_markets where id=any(p_picks) and matchup_key is not null group by matchup_key having bool_or(kind='spread') and bool_or(kind='moneyline')) then raise exception 'Spread and moneyline picks from one matchup cannot be combined.'; end if;
 for v_quote in select * from public.sportsbook_markets where id=any(p_picks) order by array_position(p_picks,id) loop
   v_legprice:=1+(case when v_quote.odds>0 then v_quote.odds/100.0 else 100.0/abs(v_quote.odds) end)*(1+v_quote.boost_pct/100.0);
   v_price:=v_price*v_legprice;
 end loop;
 v_price:=1+(v_price-1)*(1+p_reward_percent/100); if (v_price-1)*100>2147483647 or round(v_price*p_stake,2)>9999999999.99 then raise exception 'Potential payout exceeds the supported ticket limit.'; end if;
 v_price_int:=round(case when v_price>=2 then (v_price-1)*100 else -100/(v_price-1) end); v_payout:=round(v_price*p_stake,2);
 insert into public.tickets(id,user_wallet_id,bettor_display_name,league_id,team_id,request_key,league_season,nfl_season,placement_week,market_week,placed_at,accepted_combined_odds,stake,accepted_potential_payout,status,actual_payout)
 values(v_id,v_wallet.id,v_member.display_name,v_board.league_id,v_member.team_id,p_request,v_board.league_season,v_board.nfl_season,(select week from public.sportsbook_period(v_board.league_id)),v_board.market_week,now(),v_price_int,p_stake,v_payout,'OPEN',0);
 if v_board.board_type='future' then update public.tickets set ticket_type='future' where id=v_id; end if;
 for v_quote in select * from public.sportsbook_markets where id=any(p_picks) order by array_position(p_picks,id) loop
   v_number:=v_number+1;
   v_legprice:=1+(case when v_quote.odds>0 then v_quote.odds/100.0 else 100.0/abs(v_quote.odds) end)*(1+v_quote.boost_pct/100.0);
   select h.team_name||' vs. '||a.team_name into v_matchup from public.teams h, public.teams a where h.id=v_quote.home_team_id and a.id=v_quote.away_team_id;
   insert into public.ticket_legs(ticket_id,leg_number,market_quote_id,selection,market_type,matchup,accepted_odds,accepted_line,accepted_decimal_odds,status,result_evidence,settlement_context)
   values(v_id,v_number,v_quote.id,v_quote.label,case v_quote.kind when 'moneyline' then 'Moneyline' when 'spread' then 'Spread' when 'match_total' then 'Match Total' when 'team_total' then 'Team Total' when 'player_points' then 'Player Points' when 'weekly_high' then 'Weekly High Scorer' else 'Weekly Low Scorer' end,v_matchup,round(case when v_legprice>=2 then (v_legprice-1)*100 else -100/(v_legprice-1) end),v_quote.line,v_legprice,'OPEN','Accepted board revision '||p_revision,jsonb_build_object('kind',v_quote.kind,'side',v_quote.side,'team_id',v_quote.team_id,'home_team_id',v_quote.home_team_id,'away_team_id',v_quote.away_team_id,'metadata',v_quote.metadata,'boost_pct',v_quote.boost_pct));
 end loop;
 update public.user_wallets set balance=balance-p_stake,updated_at=now() where league_id=v_board.league_id and user_id=auth.uid() and status='approved';
 insert into public.user_wallet_entries(wallet_id,league_id,team_id,ticket_id,event_key,kind,amount,balance_before,balance_after,reason) values(v_wallet.id,v_board.league_id,v_member.team_id,v_id,'ticket:wager:'||v_id,'wager',-p_stake,v_wallet.balance,v_wallet.balance-p_stake,'Ticket placed');
 insert into public.email_deliveries(ticket_id,recipient) values(v_id,v_member.invited_email);
 return jsonb_build_object('ticket_id',v_id,'balance',v_wallet.balance-p_stake,'duplicate',false);
end $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."place_reward_ticket"(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid, p_reward_percent numeric) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.place_ticket(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_board public.sportsbook_boards; v_member record; v_wallet public.user_wallets; v_quote public.sportsbook_markets;
 v_ticket public.tickets; v_price numeric:=1; v_legprice numeric; v_price_int integer; v_payout numeric; v_id uuid:=gen_random_uuid(); v_number integer:=0; v_matchup text;
begin
 select * into v_board from public.sportsbook_boards where id=p_board for share;
 if not found then raise exception 'This market board is unavailable.'; end if;
 select * into v_member from sportsbook_private.financial_participant(v_board.league_id);
 if not found then raise exception 'Sign in with your approved league account.'; end if;
 select * into v_wallet from public.user_wallets where league_id=v_board.league_id and user_id=auth.uid() and status='approved' for update;
 select * into v_ticket from public.tickets where request_key=p_request;
 if found then if v_ticket.user_wallet_id is distinct from v_wallet.id then raise exception 'Request belongs to another financial account.';end if;
   if exists(select 1 from public.ticket_promotions where ticket_id=v_ticket.id) then raise exception 'Request identifier already used for a promotion.';end if; if v_ticket.team_id<>v_member.team_id then raise exception 'Request identifier already used.'; end if;
   if v_ticket.stake is distinct from p_stake or (select array_agg(market_quote_id order by market_quote_id) from public.ticket_legs where ticket_id=v_ticket.id) is distinct from (select array_agg(x order by x) from unnest(p_picks) x) then raise exception 'This request was already used for a different ticket.'; end if;
   return jsonb_build_object('ticket_id',v_ticket.id,'balance',v_wallet.balance,'duplicate',true);
 end if;
 if p_request is null or p_stake is null or p_stake<>round(p_stake,2) or p_stake<1 or p_stake>v_wallet.balance or v_wallet.balance is null then raise exception 'Enter a whole-cent wager between $1 and your available balance.'; end if;
 if v_board.status<>'published' or now()<v_board.opens_at or now()>=v_board.closes_at then raise exception 'Betting is closed for this board.'; end if;
 if v_board.reopening_id is not null and not sportsbook_private.valid_reopening(v_board,p_picks) then raise exception 'Reopening prices or game state changed. Refresh your picks.'; end if; 
 if v_board.suspension_reason is not null then raise exception 'Markets suspended: %',v_board.suspension_reason; end if;
 if v_board.quote_valid_until is not null and v_board.quote_valid_until<=now() then raise exception 'Quotes expired; wait for a successful refresh.'; end if;
 if v_board.board_type<>'future' and exists(select 1 from public.line_refresh_runtime r where r.league_id=v_board.league_id and (r.market_week=v_board.market_week or v_board.board_type='future') and (r.observed_at is null or r.observed_at<now()-interval '3 minutes' or (r.week_started and not sportsbook_private.valid_reopening(v_board,p_picks)) or r.last_error is not null)) then raise exception 'Current game state cannot support pregame acceptance.'; end if;
 if exists(select 1 from public.sportsbook_markets where id=any(p_picks) and active and (market_state<>'open' or suspension_reason is not null or metadata->>'resolved'='true')) then raise exception 'A selection is suspended or resolved.'; end if;
 if v_board.revision is distinct from p_revision then raise exception 'Lines have changed. Refresh and review your picks.'; end if;
 if p_picks is null or cardinality(p_picks) not between 1 and 10 or (select count(distinct x) from unnest(p_picks) x)<>cardinality(p_picks) then raise exception 'Select 1–10 distinct picks; singles must be Weekly Specials.'; end if;
 if (select count(*) from public.sportsbook_markets where id=any(p_picks) and board_id=p_board and active)<>cardinality(p_picks) then raise exception 'A selection is no longer available.'; end if;
 if v_board.board_type='future' and cardinality(p_picks)=1 and exists(select 1 from public.sportsbook_markets where id=any(p_picks) and kind='future_playoffs') then raise exception 'Make/Miss Playoffs requires at least two playoff picks.'; end if;
 if v_board.board_type='future' and cardinality(p_picks)>1 and exists(select 1 from public.sportsbook_markets where id=any(p_picks) and kind not in ('future_playoffs','future_win_total')) then raise exception 'League Winner and #1 Pick are standalone bets.'; end if;
 if v_board.board_type='future' and cardinality(p_picks)>1 and (select count(distinct kind) from public.sportsbook_markets where id=any(p_picks))<>1 then raise exception 'Playoff and win-total parlays must remain separate.'; end if;
 if v_board.board_type='weekly' and exists(select 1 from public.sportsbook_markets where id=any(p_picks) and kind like 'future_%') then raise exception 'Futures require a season board.'; end if;
 if v_board.board_type='future' and exists(select 1 from public.sportsbook_markets where id=any(p_picks) and kind not like 'future_%') then raise exception 'Only futures belong on a season board.'; end if;
 
 if exists(select 1 from public.sportsbook_markets a join public.sportsbook_markets b on a.id<b.id where a.id=any(p_picks) and b.id=any(p_picks) and public.sportsbook_special_conflict(a,b)) then raise exception 'These selections have contradictory outcomes.'; end if;
 if exists(select 1 from public.sportsbook_markets where id=any(p_picks) group by market_key having count(*)>1) then raise exception 'Choose only one outcome per market.'; end if;
 if exists(select 1 from public.sportsbook_markets where id=any(p_picks) and matchup_key is not null group by matchup_key having bool_or(kind='spread') and bool_or(kind='moneyline')) then raise exception 'Spread and moneyline picks from one matchup cannot be combined.'; end if;
 for v_quote in select * from public.sportsbook_markets where id=any(p_picks) order by array_position(p_picks,id) loop
   v_legprice:=1+(case when v_quote.odds>0 then v_quote.odds/100.0 else 100.0/abs(v_quote.odds) end)*(1+v_quote.boost_pct/100.0);
   v_price:=v_price*v_legprice;
 end loop;
 if (v_price-1)*100>2147483647 or round(v_price*p_stake,2)>9999999999.99 then raise exception 'Potential payout exceeds the supported ticket limit.'; end if;
 v_price_int:=round(case when v_price>=2 then (v_price-1)*100 else -100/(v_price-1) end); v_payout:=round(v_price*p_stake,2);
 insert into public.tickets(id,user_wallet_id,bettor_display_name,league_id,team_id,request_key,league_season,nfl_season,placement_week,market_week,placed_at,accepted_combined_odds,stake,accepted_potential_payout,status,actual_payout)
 values(v_id,v_wallet.id,v_member.display_name,v_board.league_id,v_member.team_id,p_request,v_board.league_season,v_board.nfl_season,(select week from public.sportsbook_period(v_board.league_id)),v_board.market_week,now(),v_price_int,p_stake,v_payout,'OPEN',0);
 if v_board.board_type='future' then update public.tickets set ticket_type='future' where id=v_id; end if;
 for v_quote in select * from public.sportsbook_markets where id=any(p_picks) order by array_position(p_picks,id) loop
   v_number:=v_number+1;
   v_legprice:=1+(case when v_quote.odds>0 then v_quote.odds/100.0 else 100.0/abs(v_quote.odds) end)*(1+v_quote.boost_pct/100.0);
   select h.team_name||' vs. '||a.team_name into v_matchup from public.teams h, public.teams a where h.id=v_quote.home_team_id and a.id=v_quote.away_team_id;
   insert into public.ticket_legs(ticket_id,leg_number,market_quote_id,selection,market_type,matchup,accepted_odds,accepted_line,accepted_decimal_odds,status,result_evidence,settlement_context)
   values(v_id,v_number,v_quote.id,v_quote.label,case v_quote.kind when 'moneyline' then 'Moneyline' when 'spread' then 'Spread' when 'match_total' then 'Match Total' when 'team_total' then 'Team Total' when 'player_points' then 'Player Points' when 'weekly_high' then 'Weekly High Scorer' else 'Weekly Low Scorer' end,v_matchup,round(case when v_legprice>=2 then (v_legprice-1)*100 else -100/(v_legprice-1) end),v_quote.line,v_legprice,'OPEN','Accepted board revision '||p_revision,jsonb_build_object('kind',v_quote.kind,'side',v_quote.side,'team_id',v_quote.team_id,'home_team_id',v_quote.home_team_id,'away_team_id',v_quote.away_team_id,'metadata',v_quote.metadata,'boost_pct',v_quote.boost_pct));
 end loop;
 update public.user_wallets set balance=balance-p_stake,updated_at=now() where league_id=v_board.league_id and user_id=auth.uid() and status='approved';
 insert into public.user_wallet_entries(wallet_id,league_id,team_id,ticket_id,event_key,kind,amount,balance_before,balance_after,reason) values(v_wallet.id,v_board.league_id,v_member.team_id,v_id,'ticket:wager:'||v_id,'wager',-p_stake,v_wallet.balance,v_wallet.balance-p_stake,'Ticket placed');
 insert into public.email_deliveries(ticket_id,recipient) values(v_id,v_member.invited_email);
 return jsonb_build_object('ticket_id',v_id,'balance',v_wallet.balance-p_stake,'duplicate',false);
end $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."place_ticket"(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.require_verified_support()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT EXISTS(SELECT FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL) THEN RAISE EXCEPTION 'Verified sign-in required';END IF;
 RETURN auth.uid();
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."require_verified_support"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.revoke_pending_member_invitations()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF TG_TABLE_NAME='league_memberships' THEN
  UPDATE boff_dev_internal.member_invitations SET status='revoked' WHERE league_id=coalesce(NEW.league_id,OLD.league_id) AND team_id=coalesce(NEW.team_id,OLD.team_id) AND NOT co_manager AND status='pending';
 ELSE
  UPDATE boff_dev_internal.member_invitations SET status='revoked' WHERE league_id=coalesce(NEW.league_id,OLD.league_id) AND team_id=coalesce(NEW.team_id,OLD.team_id) AND sleeper_id=coalesce(NEW.sleeper_user_id,OLD.sleeper_user_id) AND status='pending';
 END IF;
 RETURN NULL;
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."revoke_pending_member_invitations"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.save_weekly_delta(old_book dev_current_book, old_board sportsbook_boards, new_book dev_current_book, new_board sportsbook_boards, changed uuid[], removed uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE base text; version text; changes jsonb;
BEGIN
 IF old_book.board_id IS DISTINCT FROM new_book.board_id THEN RETURN; END IF;
 base:=boff_dev_internal.weekly_version(old_board,old_book);
 version:=boff_dev_internal.weekly_version(new_board,new_book);
 IF base=version THEN RETURN; END IF;
 changes:=jsonb_build_object(
  'quotes',jsonb_build_object('upsert',coalesce((SELECT jsonb_agg(to_jsonb(q)) FROM public.sportsbook_markets q
   WHERE q.id=ANY(changed) AND q.active),'[]'),'remove',to_jsonb(removed)),
  'teams',boff_dev_internal.changed_board_rows(old_book.payload->'teams',new_book.payload->'teams'),
  'players',boff_dev_internal.changed_board_rows(old_book.payload->'players',new_book.payload->'players'),
  'payload',coalesce((SELECT jsonb_object_agg(key,value) FROM jsonb_each(new_book.payload - ARRAY['teams','players'])
   WHERE old_book.payload->key IS DISTINCT FROM value),'{}'),
  'payloadRemove',coalesce((SELECT jsonb_agg(key) FROM jsonb_object_keys(old_book.payload - ARRAY['teams','players']) key
   WHERE NOT new_book.payload ? key),'[]'));
 IF octet_length(changes::text)>=280000 THEN RETURN; END IF;
 INSERT INTO boff_dev_internal.weekly_board_delta VALUES(new_book.league_id,base,version,changes)
 ON CONFLICT(league_id) DO UPDATE SET base_version=excluded.base_version,version=excluded.version,changes=excluded.changes;
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."save_weekly_delta"(old_book dev_current_book, old_board sportsbook_boards, new_book dev_current_book, new_board sportsbook_boards, changed uuid[], removed uuid[]) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.schedule_futures_rule_refresh()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 UPDATE public.dev_live_cache c SET payload=c.payload-'futuresAt'
 FROM public.leagues l WHERE l.id=NEW.league_id AND c.key='league:'||l.sleeper_league_id;
 RETURN NEW;
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."schedule_futures_rule_refresh"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.sleeper_manager_status(p_league uuid, p_team uuid, p_co boolean)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT CASE WHEN p_co THEN 'Co-Manager' WHEN coalesce((
  SELECT jsonb_array_length(s.value->'coManagers') FROM public.dev_live_cache c CROSS JOIN LATERAL jsonb_array_elements(c.payload->'metadata'->'teams')s
  WHERE c.key=(SELECT 'league:'||sleeper_league_id FROM public.leagues WHERE id=p_league) AND (s.value->>'rosterId')::integer=t.roster_id
 ),cardinality(t.co_owner_names),0)>0 THEN 'Primary Manager' ELSE 'Manager' END
 FROM public.teams t WHERE t.id=p_team AND t.league_id=p_league
$function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."sleeper_manager_status"(p_league uuid, p_team uuid, p_co boolean) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION boff_dev_internal.storage_maintenance(p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '15s'
 SET lock_timeout TO '500ms'
AS $function$
DECLARE lim integer:=least(100,greatest(1,coalesce(p_limit,25)));q record;fk record;protected boolean;used boolean;
 quotes integer:=0;bundles integer:=0;values_removed integer:=0;progress integer:=0;run_result jsonb;old_role text;
BEGIN
 IF NOT sportsbook_private.release_environment_ready() THEN RAISE EXCEPTION 'Dev project required';END IF;
 IF NOT pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtext('boff.storage.maintenance')) THEN RETURN jsonb_build_object('skipped','busy');END IF;
 -- Existing retention routines preserve event keys, financial rows and pending failures.
 old_role:=current_setting('request.jwt.claim.role',true);
 PERFORM set_config('request.jwt.claim.role','service_role',true);
 run_result:=public.cleanup_routine_payloads(lim)||public.cleanup_terminal_refresh_payloads(least(lim,10))||public.cleanup_evaluated_samples(least(lim,10));
 PERFORM set_config('request.jwt.claim.role',coalesce(old_role,''),true);
 FOR q IN SELECT m.id FROM public.sportsbook_markets m JOIN public.sportsbook_boards b ON b.id=m.board_id
  WHERE NOT m.active AND b.closes_at<now()-interval '7 days'
   AND (b.board_type='weekly' OR (b.status='closed' AND m.metadata->>'resolved'='true' AND NOT EXISTS(SELECT 1 FROM public.tickets t WHERE t.league_id=b.league_id AND t.nfl_season=b.nfl_season AND t.status='OPEN')))
   AND NOT EXISTS(SELECT 1 FROM public.ticket_legs l WHERE l.market_quote_id=m.id)
   AND NOT EXISTS(SELECT 1 FROM public.promo_offers o WHERE to_jsonb(o)::text LIKE '%'||m.id::text||'%')
   AND NOT EXISTS(SELECT 1 FROM public.sportsbook_reopening_reviews r WHERE to_jsonb(r)::text LIKE '%'||m.id::text||'%')
   AND NOT EXISTS(SELECT 1 FROM public.line_refresh_stages s WHERE to_jsonb(s)::text LIKE '%'||m.id::text||'%')
  ORDER BY b.closes_at,m.id LIMIT lim FOR UPDATE OF m SKIP LOCKED LOOP
  protected:=false;
  -- Any FK reference protects a quote, even if its FK would cascade or set null.
  FOR fk IN SELECT c.conrelid::regclass AS rel,a.attname AS col FROM pg_catalog.pg_constraint c
   JOIN pg_catalog.pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=c.conkey[1]
   WHERE c.contype='f' AND c.confrelid='public.sportsbook_markets'::regclass LOOP
   EXECUTE format('select exists(select 1 from %s where %I=$1)',fk.rel,fk.col) INTO used USING q.id;
   IF used THEN protected:=true;EXIT;END IF;
  END LOOP;
  IF protected OR EXISTS(SELECT 1 FROM public.promo_offers o WHERE to_jsonb(o)::text LIKE '%'||q.id::text||'%')
   OR EXISTS(SELECT 1 FROM public.sportsbook_reopening_reviews r WHERE to_jsonb(r)::text LIKE '%'||q.id::text||'%')
   OR EXISTS(SELECT 1 FROM public.line_refresh_stages s WHERE to_jsonb(s)::text LIKE '%'||q.id::text||'%') THEN CONTINUE;END IF;
  DELETE FROM public.sportsbook_markets WHERE id=q.id;quotes:=quotes+1;
 END LOOP;
 FOR q IN SELECT league_id FROM (SELECT league_id FROM public.receipt_context_bundles UNION SELECT league_id FROM public.receipt_context_values) scopes ORDER BY league_id LIMIT lim LOOP
  IF NOT pg_catalog.pg_try_advisory_xact_lock(pg_catalog.hashtext('boff.receipt.storage'),pg_catalog.hashtext(q.league_id::text)) THEN CONTINUE;END IF;
  WITH due AS(SELECT b.id FROM public.receipt_context_bundles b WHERE b.league_id=q.league_id AND b.created_at<now()-interval '7 days'
   AND NOT EXISTS(SELECT 1 FROM public.ticket_legs l WHERE l.context_bundle_id=b.id) ORDER BY b.id LIMIT lim)
  DELETE FROM public.receipt_context_bundles b USING due WHERE b.id=due.id;
  GET DIAGNOSTICS lim=ROW_COUNT;bundles:=bundles+lim;lim:=least(100,greatest(1,coalesce(p_limit,25)));
  WITH due AS(SELECT v.id FROM public.receipt_context_values v WHERE v.league_id=q.league_id AND v.created_at<now()-interval '7 days'
   AND NOT EXISTS(SELECT 1 FROM public.receipt_context_bundles b CROSS JOIN LATERAL jsonb_each(b.refs) r WHERE b.league_id=v.league_id AND (r.value#>>'{}')::bigint=v.id)
   ORDER BY v.id LIMIT lim)
  DELETE FROM public.receipt_context_values v USING due WHERE v.id=due.id;
  GET DIAGNOSTICS lim=ROW_COUNT;values_removed:=values_removed+lim;lim:=least(100,greatest(1,coalesce(p_limit,25)));
 END LOOP;
 WITH due AS(SELECT o.league_id,o.nfl_season,o.market_week FROM public.ticket_score_observations o JOIN public.leagues l ON l.id=o.league_id
  WHERE o.fetched_at<now()-interval '14 days' AND (o.nfl_season<>l.nfl_season OR o.market_week<>l.active_week)
   AND NOT EXISTS(SELECT 1 FROM public.tickets t WHERE t.league_id=o.league_id AND t.nfl_season=o.nfl_season AND t.market_week=o.market_week AND t.status='OPEN')
  ORDER BY o.fetched_at LIMIT lim)
 DELETE FROM public.ticket_score_observations o USING due d WHERE (o.league_id,o.nfl_season,o.market_week)=(d.league_id,d.nfl_season,d.market_week);
 GET DIAGNOSTICS progress=ROW_COUNT;
 run_result:=run_result||jsonb_build_object('obsolete_quotes',quotes,'orphan_context_bundles',bundles,'orphan_context_values',values_removed,'old_progress_rows',progress,'batch_limit',least(100,greatest(1,coalesce(p_limit,25))));
 -- pg_cron is absent in the local test engine. Hosted history is bounded too.
 IF to_regclass('cron.job_run_details') IS NOT NULL THEN
  EXECUTE $history$delete from cron.job_run_details where jobid in (select jobid from cron.job where jobname='boff-storage-maintenance') and end_time<now()-interval '24 hours'$history$;
 END IF;
 UPDATE boff_dev_internal.storage_maintenance_state SET last_run_at=clock_timestamp(),last_result=run_result WHERE singleton;
 RETURN run_result;
END $function$
;

REVOKE ALL ON FUNCTION "boff_dev_internal"."storage_maintenance"(p_limit integer) FROM PUBLIC,anon,authenticated,service_role;

