CREATE OR REPLACE FUNCTION public.approve_member(p_team uuid, p_email text, p_name text, p_sleeper_user text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_team public.teams; v_email text; v_id uuid; v_existing public.league_memberships;
begin
  select * into v_team from public.teams where id = p_team;
  if not found or not sportsbook_private.is_platform_owner() then
    raise exception 'Platform owner access required';
  end if;
  v_email := lower(trim(p_email));
  if v_email is null or v_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception 'Enter a valid email';
  end if;
  if p_name is null or length(trim(p_name)) not between 1 and 80 then
    raise exception 'Enter the owner name';
  end if;
  if p_sleeper_user is null or p_sleeper_user <> v_team.sportsbook_owner_id then
    raise exception 'Use the approved sportsbook owner for this team'; end if;
  -- Serialize changes to one team; never detach an existing linked account silently.
  perform 1 from public.teams where id = p_team for update;
  select * into v_existing from public.league_memberships where team_id = p_team;
  if found then
    if v_existing.invited_email <> v_email or v_existing.sleeper_user_id <> p_sleeper_user then
      raise exception 'This team is already mapped. Account reassignment requires a separate review.';
    end if;
    update public.league_memberships set display_name = trim(p_name) where id = v_existing.id;
    return v_existing.id;
  end if;
  insert into public.league_memberships(league_id, team_id, invited_email, display_name, sleeper_user_id)
    values(v_team.league_id, p_team, v_email, trim(p_name), p_sleeper_user) returning id into v_id;
  return v_id;
end;
$function$
;

REVOKE ALL ON FUNCTION "public"."approve_member"(p_team uuid, p_email text, p_name text, p_sleeper_user text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."approve_member"(p_team uuid, p_email text, p_name text, p_sleeper_user text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.approve_provider_capability(p_league uuid, p_hash text, p_expected integer, p_build text, p_reason text, p_coverage_reviewed boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s sportsbook_private.provider_capability_state;l public.leagues;v jsonb;slots text[];begin
 if not public.league_intake_owner()then raise exception 'Verified platform owner required.';end if;
 if p_reason is null or length(trim(p_reason))not between 8 and 400 or p_coverage_reviewed is distinct from true then raise exception 'Explicit projection/results coverage and supported house-rule review required.';end if;
 perform pg_advisory_xact_lock(hashtextextended('provider-capability:'||p_league,0));
 select * into l from public.leagues where id=p_league for update;select * into s from sportsbook_private.provider_capability_state where league_id=p_league for update;
 if s.approved_hash=p_hash and s.observed_hash=p_hash and exists(select 1 from sportsbook_private.provider_capability_decisions where league_id=p_league and revision=p_expected+1 and review_hash=p_hash and build_sha=p_build and actor=auth.uid()and reason=trim(p_reason))then
  perform sportsbook_private.require_provider_capability(p_league);return jsonb_build_object('revision',p_expected+1,'duplicate',true,'activation',false);
 end if;
 if s.league_id is null or s.observed_hash is distinct from p_hash or s.build_sha is distinct from p_build or s.revision is distinct from p_expected or s.observed_at<clock_timestamp()-interval '15 minutes'then raise exception 'Review changed or expired; prepare a fresh observation.';end if;
 if l.operations_enabled or exists(select 1 from public.weekly_schedule where league_id=p_league and automation_enabled)then raise exception 'Pause operations and automation first.';end if;
 if(s.source->>'season')::integer<>l.nfl_season then raise exception 'Renew the league season before approval.';end if;
 -- Declare support narrowly. Futures/draft compatibility needs separate rule evidence.
 select sportsbook_private.sportsbook_policy(l.id,p.nfl_season,p.week)->'values'into v from public.sportsbook_period(l.id)p;
 if(v->>'futures_enabled')::boolean then raise exception 'Imported capability profile supports reviewed weekly families only; disable season futures before approval.';end if;
 if(s.source->>'total_rosters')::integer not between 8 and 16 or(s.source->>'total_rosters')::integer%2<>0 then raise exception 'Supported even 8-16-team field required.';end if;
 if exists(select 1 from jsonb_array_elements_text(s.source->'positions')x where x not in('QB','RB','WR','TE','K','DEF','FLEX','SUPER_FLEX','REC_FLEX','WRRB_FLEX','BN','IR','TAXI'))or(select count(*)from jsonb_array_elements_text(s.source->'positions')x where x not in('BN','IR','TAXI'))>16 then raise exception 'Unsupported lineup profile.';end if;
 if coalesce((s.source->'settings'->>'divisions')::integer,0)>0 or coalesce((s.source->'settings'->>'league_average_match')::integer,0)>0 or coalesce((s.source->'settings'->>'playoff_round_type')::integer,0)>0 then raise exception 'Unsupported divisions, median wins or multiweek profile.';end if;
 if s.source->>'status' is distinct from 'in_season'then raise exception 'Current in-season provider status required.';end if;
 if s.revision>=64 then raise exception 'Capability decision budget reached.';end if;
 -- Recompute all configuration bindings before accepting the exact review.
 if s.observed_hash<>encode(sha256(convert_to(jsonb_build_object('source',sportsbook_private.capability_source(s.source),'rosters',s.rosters,'configuration',sportsbook_private.provider_configuration_hash(l.id),'build',s.build_sha)::text,'UTF8')),'hex')then raise exception 'Configuration changed; prepare a fresh review.';end if;
 update sportsbook_private.provider_capability_state set approved_hash=observed_hash,approved_by=auth.uid(),approved_at=clock_timestamp(),revision=revision+1 where league_id=p_league;
 insert into sportsbook_private.provider_capability_decisions(league_id,revision,review_hash,build_sha,actor,reason)values(p_league,s.revision+1,p_hash,p_build,auth.uid(),trim(p_reason));
 return jsonb_build_object('revision',s.revision+1,'owner_attested_coverage',true,'activation',false);
end $function$
;

REVOKE ALL ON FUNCTION "public"."approve_provider_capability"(p_league uuid, p_hash text, p_expected integer, p_build text, p_reason text, p_coverage_reviewed boolean) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."approve_provider_capability"(p_league uuid, p_hash text, p_expected integer, p_build text, p_reason text, p_coverage_reviewed boolean) TO "authenticated";

CREATE OR REPLACE FUNCTION public.approve_user_wallet(p_league uuid, p_user uuid, p_team uuid, p_reason text, p_display_name text DEFAULT 'Participant'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w public.user_wallets;begin perform pg_advisory_xact_lock_shared(20261101,17);
 if not sportsbook_private.is_platform_owner() or not exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null)
  then raise exception 'Platform owner approval required.';end if;
 if p_display_name is null or length(trim(p_display_name)) not between 1 and 80 then raise exception 'Reviewed participant display name required.';end if;
 if p_reason is null or length(trim(p_reason)) not between 8 and 500 then raise exception 'Record the reviewed financial-account approval reason.';end if;
 if not exists(select 1 from auth.users where id=p_user and email_confirmed_at is not null)
  or not exists(select 1 from public.teams where id=p_team and league_id=p_league) then raise exception 'Verified user and scoped team required.';end if;
 perform 1 from public.leagues where id=p_league for update;
 select * into w from public.user_wallets where league_id=p_league and user_id=p_user;
 if found then
  if w.team_id<>p_team or w.status<>'approved' then raise exception 'Existing financial identity requires explicit review; it cannot be reassigned.';end if;
  return jsonb_build_object('wallet_id',w.id,'duplicate',true,'funding_pending',w.balance is null);
 end if;
 if (select count(*) from public.user_wallets where league_id=p_league)>=128 then raise exception 'Financial account count budget reached.';end if;
 insert into public.user_wallets(league_id,user_id,team_id,display_name) values(p_league,p_user,p_team,trim(p_display_name)) returning * into w;
 insert into sportsbook_private.user_wallet_approvals(wallet_id,actor,reason) values(w.id,auth.uid(),trim(p_reason));
 return jsonb_build_object('wallet_id',w.id,'duplicate',false,'funding_pending',true);
end $function$
;

REVOKE ALL ON FUNCTION "public"."approve_user_wallet"(p_league uuid, p_user uuid, p_team uuid, p_reason text, p_display_name text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."approve_user_wallet"(p_league uuid, p_user uuid, p_team uuid, p_reason text, p_display_name text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.archive_dev_result_week(p_league uuid, p_season integer, p_week integer, p_results jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.role() IS DISTINCT FROM 'service_role'
    OR NOT sportsbook_private.release_environment_ready() THEN
    RAISE EXCEPTION 'Development result worker required';
  END IF;
  IF NOT EXISTS (SELECT FROM public.leagues WHERE id = p_league AND nfl_season = p_season)
    OR jsonb_typeof(p_results) IS DISTINCT FROM 'object'
    OR p_results = '{}'::jsonb
    OR EXISTS (SELECT FROM jsonb_each(p_results) AS t WHERE jsonb_typeof(t.value->'points') IS DISTINCT FROM 'number') THEN
    RAISE EXCEPTION 'Invalid weekly results';
  END IF;
  INSERT INTO public.league_result_weeks AS w (league_id, nfl_season, market_week, final, source, results)
  VALUES (p_league, p_season, p_week, true, 'Sleeper', p_results)
  ON CONFLICT (league_id, nfl_season, market_week) DO UPDATE SET
    final = true, fetched_at = clock_timestamp(), results = excluded.results
  WHERE NOT w.final;
END $function$
;

REVOKE ALL ON FUNCTION "public"."archive_dev_result_week"(p_league uuid, p_season integer, p_week integer, p_results jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."archive_dev_result_week"(p_league uuid, p_season integer, p_week integer, p_results jsonb) TO "service_role";

