CREATE OR REPLACE FUNCTION public.dev_accept_member_invitation(p_token text, p_accept boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE i boff_dev_internal.member_invitations; account auth.users; original_claims text; result jsonb;
BEGIN
 IF p_token IS NULL OR p_token !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invitation unavailable'; END IF;
 SELECT * INTO account FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL AND deleted_at IS NULL AND coalesce(banned_until,'-infinity')<=now();
 IF account.id IS NULL THEN RAISE EXCEPTION 'Verify your email and sign in first'; END IF;
 SELECT * INTO i FROM boff_dev_internal.member_invitations WHERE token_digest=encode(sha256(convert_to(p_token,'UTF8')),'hex') FOR UPDATE;
 IF i.id IS NULL OR i.email<>lower(account.email) THEN RAISE EXCEPTION 'Sign in with the email address that received this invitation'; END IF;
 IF i.status='revoked' OR i.expires_at<=now() THEN RAISE EXCEPTION 'Invitation expired or revoked. Ask your commissioner to resend'; END IF;
 IF i.status='accepted' AND NOT EXISTS(SELECT FROM boff_dev_internal.participant_links WHERE league_id=i.league_id AND user_id=account.id AND team_id=i.team_id)
 THEN RAISE EXCEPTION 'League access has been revoked'; END IF;
 IF NOT EXISTS(SELECT FROM public.league_memberships m WHERE m.league_id=i.league_id AND m.user_id=i.issuer AND m.role='admin')
  AND NOT EXISTS(SELECT FROM sportsbook_private.platform_owners WHERE user_id=i.issuer) THEN RAISE EXCEPTION 'Commissioner must review this invitation'; END IF;
 IF p_accept AND i.status='pending' THEN
  UPDATE boff_dev_internal.member_invitations SET status='accepted' WHERE id=i.id;
  original_claims:=current_setting('request.jwt.claims',true);
  PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',i.issuer,'role','authenticated')::text,true);
  IF i.co_manager THEN result:=public.dev_change_co_manager(i.league_id,i.team_id,i.sleeper_id,i.expected,i.email,i.reason);
  ELSE result:=public.dev_change_commissioner_member(i.league_id,i.team_id,i.expected,i.email,i.reason);
  END IF;
  PERFORM set_config('request.jwt.claims',coalesce(original_claims,''),true);
 END IF;
 RETURN jsonb_build_object('managerStatus',boff_dev_internal.sleeper_manager_status(i.league_id,i.team_id,i.co_manager),'league',(SELECT name FROM public.leagues WHERE id=i.league_id),'team',(SELECT team_name FROM public.teams WHERE id=i.team_id),
  'leaguePath',(SELECT '/'||sleeper_league_id||'/matchups' FROM public.leagues WHERE id=i.league_id),'accepted',p_accept OR i.status='accepted');
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_accept_member_invitation"(p_token text, p_accept boolean) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_accept_member_invitation"(p_token text, p_accept boolean) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_balance_history_page(p_league uuid, p_cursor jsonb DEFAULT NULL::jsonb, p_size integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb;
BEGIN
 IF NOT EXISTS(SELECT FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL)
 OR NOT sportsbook_private.is_member(p_league) THEN RAISE EXCEPTION 'Verified league membership required'; END IF;
 IF p_size IS NULL OR p_size NOT BETWEEN 1 AND 100 OR
 (p_cursor IS NOT NULL AND (jsonb_typeof(p_cursor)<>'object' OR NOT p_cursor ? 'time' OR NOT p_cursor ? 'id'))
 THEN RAISE EXCEPTION 'Invalid history parameters'; END IF;
 WITH candidates AS MATERIALIZED (
  SELECT e.id,e.reason,e.kind,e.amount,e.balance_after,e.created_at FROM public.user_wallet_entries e
  JOIN public.user_wallets w ON w.id=e.wallet_id WHERE w.league_id=p_league AND w.user_id=auth.uid() AND
  (p_cursor IS NULL OR (e.created_at,e.id)<((p_cursor->>'time')::timestamptz,(p_cursor->>'id')::uuid))
  ORDER BY e.created_at DESC,e.id DESC LIMIT p_size+1
 ), page AS(SELECT * FROM candidates ORDER BY created_at DESC,id DESC LIMIT p_size)
 SELECT jsonb_build_object('entries',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY created_at DESC,id DESC) FROM page p),'[]'),
 'next',CASE WHEN (SELECT count(*) FROM candidates)>p_size THEN
 (SELECT jsonb_build_object('time',created_at,'id',id) FROM page ORDER BY created_at ASC,id ASC LIMIT 1) ELSE NULL END) INTO result;
 RETURN result;
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_balance_history_page"(p_league uuid, p_cursor jsonb, p_size integer) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_balance_history_page"(p_league uuid, p_cursor jsonb, p_size integer) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_capture_member_invitation(p_id uuid, p_digest text, p_account uuid, p_subject text, p_html text, p_text text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE i boff_dev_internal.member_invitations; verified boolean;
BEGIN
 SELECT * INTO i FROM boff_dev_internal.member_invitations WHERE id=p_id AND token_digest=p_digest FOR UPDATE;
 IF i.id IS NULL OR i.status<>'pending' OR i.expires_at<=now() THEN RAISE EXCEPTION 'Invitation expired or revoked'; END IF;
 IF NOT EXISTS(SELECT FROM auth.users WHERE id=p_account AND lower(email)=i.email AND deleted_at IS NULL) THEN RAISE EXCEPTION 'Recipient identity changed'; END IF;
 IF length(p_subject)>300 OR octet_length(p_html)>96000 OR octet_length(p_text)>16000 THEN RAISE EXCEPTION 'Invalid invitation email'; END IF;
 SELECT email_confirmed_at IS NOT NULL INTO verified FROM auth.users WHERE id=p_account;
 INSERT INTO boff_dev_internal.notification_capture(league_id,user_id,event_key,kind,subject,html,plain_text)
 VALUES(i.league_id,p_account,'invitation:'||i.id,CASE WHEN verified THEN 'invite-existing' ELSE 'invite-new' END,p_subject,p_html,p_text)
 ON CONFLICT DO NOTHING;
 UPDATE boff_dev_internal.member_invitations SET captured_at=coalesce(captured_at,now()),account_id=p_account WHERE id=i.id;
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_capture_member_invitation"(p_id uuid, p_digest text, p_account uuid, p_subject text, p_html text, p_text text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_capture_member_invitation"(p_id uuid, p_digest text, p_account uuid, p_subject text, p_html text, p_text text) TO "service_role";

CREATE OR REPLACE FUNCTION public.dev_capture_notification(p_league uuid, p_user uuid, p_key text, p_kind text, p_subject text, p_html text, p_text text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF p_kind='credit' AND NOT boff_dev_internal.credit_email_allowed(p_league,p_user) THEN RETURN; END IF;
 IF NOT EXISTS(SELECT FROM auth.users WHERE id=p_user AND email_confirmed_at IS NOT NULL) THEN RETURN; END IF;
 IF NOT EXISTS(SELECT FROM boff_dev_internal.participant_links m LEFT JOIN boff_dev_internal.notification_choices c
  ON c.league_id=m.league_id AND c.user_id=m.user_id WHERE m.league_id=p_league AND m.user_id=p_user
  AND boff_dev_internal.effective_communications(c.choices)->p_kind->>'email'='true') THEN RETURN; END IF;
 IF length(p_key)>200 OR octet_length(p_html)>96000 OR octet_length(p_text)>16000 THEN RAISE EXCEPTION 'Invalid notification capture'; END IF;
 INSERT INTO boff_dev_internal.notification_capture(league_id,user_id,event_key,kind,subject,html,plain_text)
 VALUES(p_league,p_user,p_key,p_kind,p_subject,p_html,p_text) ON CONFLICT DO NOTHING;

END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_capture_notification"(p_league uuid, p_user uuid, p_key text, p_kind text, p_subject text, p_html text, p_text text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_capture_notification"(p_league uuid, p_user uuid, p_key text, p_kind text, p_subject text, p_html text, p_text text) TO "service_role";

CREATE OR REPLACE FUNCTION public.dev_change_co_manager(p_league uuid, p_team uuid, p_sleeper text, p_expected uuid, p_email text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE prior boff_dev_internal.co_manager_links; account auth.users; manager jsonb; wallet_id uuid;
BEGIN
 IF NOT boff_dev_internal.can_manage_members(p_league) THEN RAISE EXCEPTION 'Commissioner access required'; END IF;
 IF length(trim(coalesce(p_reason,''))) NOT BETWEEN 8 AND 400 THEN RAISE EXCEPTION 'Enter a reason between 8 and 400 characters'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('dev-commissioner-members'),hashtext(p_league::text));
 SELECT person.value INTO manager
 FROM public.teams t JOIN public.leagues l ON l.id=t.league_id
 JOIN public.dev_live_cache c ON c.key='league:'||l.sleeper_league_id AND c.payload->'metadata'->>'season'=l.nfl_season::text
 CROSS JOIN LATERAL jsonb_array_elements(c.payload->'metadata'->'teams') source
 CROSS JOIN LATERAL jsonb_array_elements(source.value->'coManagers') person
 WHERE t.id=p_team AND l.id=p_league AND (source.value->>'rosterId')::integer=t.roster_id AND person.value->>'id'=p_sleeper;
 SELECT * INTO prior FROM boff_dev_internal.co_manager_links WHERE league_id=p_league AND team_id=p_team AND sleeper_user_id=p_sleeper FOR UPDATE;
 IF prior.user_id IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'Mapping changed. Reload before saving'; END IF;
 IF prior.user_id IS NOT NULL AND (
  prior.user_id=auth.uid() OR EXISTS(SELECT FROM sportsbook_private.platform_owners WHERE user_id=prior.user_id)
  OR EXISTS(SELECT FROM public.league_staff_grants WHERE league_id=p_league AND user_id=prior.user_id AND active))
 THEN RAISE EXCEPTION 'Staff access requires platform-owner review'; END IF;
 IF p_email IS NOT NULL THEN
  IF manager IS NULL THEN RAISE EXCEPTION 'This person is not a verified Sleeper co-manager for the selected team'; END IF;
  SELECT * INTO account FROM auth.users WHERE lower(email)=lower(trim(p_email)) AND email_confirmed_at IS NOT NULL;
  IF account.id IS NULL THEN RAISE EXCEPTION 'This person needs an existing verified Boff account'; END IF;
  IF account.id=prior.user_id THEN RETURN public.dev_commissioner_members(p_league); END IF;
  IF EXISTS(SELECT FROM public.league_memberships WHERE league_id=p_league AND (user_id=account.id OR (invited_email=lower(account.email) AND (user_id IS NOT NULL OR team_id<>p_team OR sleeper_user_id IS DISTINCT FROM p_sleeper))))
   OR EXISTS(SELECT FROM boff_dev_internal.co_manager_links WHERE league_id=p_league AND user_id=account.id)
   OR EXISTS(SELECT FROM public.user_wallets WHERE league_id=p_league AND user_id=account.id AND (team_id<>p_team OR status<>'approved'))
  THEN RAISE EXCEPTION 'An existing league or wallet identity requires platform-owner review'; END IF;
 ELSIF prior.user_id IS NULL THEN RAISE EXCEPTION 'No linked co-manager to remove';
 END IF;

 IF prior.user_id IS NOT NULL THEN
  UPDATE public.user_wallets SET status='revoked',revision=revision+1,updated_at=clock_timestamp()
   WHERE league_id=p_league AND user_id=prior.user_id AND status='approved' RETURNING id INTO wallet_id;
  IF wallet_id IS NOT NULL THEN INSERT INTO sportsbook_private.user_wallet_approvals(wallet_id,actor,reason)
   VALUES(wallet_id,auth.uid(),trim(p_reason)); END IF;
  DELETE FROM boff_dev_internal.co_manager_links WHERE league_id=p_league AND team_id=p_team AND sleeper_user_id=p_sleeper;
 END IF;
 IF account.id IS NOT NULL THEN
  INSERT INTO boff_dev_internal.co_manager_links VALUES(p_league,p_team,p_sleeper,account.id,
   left(coalesce(nullif(account.raw_user_meta_data->>'display_name',''),nullif(account.raw_user_meta_data->>'full_name',''),manager->>'name'),80));
 END IF;
 INSERT INTO public.admin_change_log(league_id,actor_id,category,reason,before_value,after_value) VALUES(
  p_league,auth.uid(),'commissioner_membership',trim(p_reason),
  jsonb_build_object('team_id',p_team,'user_id',prior.user_id,'sleeper_id',p_sleeper),
  jsonb_build_object('team_id',p_team,'user_id',account.id,'sleeper_id',p_sleeper));
 RETURN public.dev_commissioner_members(p_league);
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_change_co_manager"(p_league uuid, p_team uuid, p_sleeper text, p_expected uuid, p_email text, p_reason text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_change_co_manager"(p_league uuid, p_team uuid, p_sleeper text, p_expected uuid, p_email text, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_change_commissioner_member(p_league uuid, p_team uuid, p_expected uuid, p_email text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE prior public.league_memberships; account auth.users; target record; wallet public.user_wallets;
BEGIN
 IF NOT boff_dev_internal.can_manage_members(p_league) THEN RAISE EXCEPTION 'Commissioner access required'; END IF;
 IF length(trim(coalesce(p_reason,''))) NOT BETWEEN 8 AND 400 THEN RAISE EXCEPTION 'Enter a reason between 8 and 400 characters'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('dev-commissioner-members'),hashtext(p_league::text));
 SELECT t.id,l.nfl_season,source.value->>'ownerId' sleeper_id,coalesce(source.value->>'ownerName',source.value->'managers'->>0) display_name
 INTO STRICT target FROM public.teams t JOIN public.leagues l ON l.id=t.league_id
 LEFT JOIN public.dev_live_cache c ON c.key='league:'||l.sleeper_league_id AND c.payload->'metadata'->>'season'=l.nfl_season::text
 LEFT JOIN LATERAL (SELECT value FROM jsonb_array_elements(c.payload->'metadata'->'teams') WHERE (value->>'rosterId')::integer=t.roster_id LIMIT 1) source ON true
 WHERE t.id=p_team AND t.league_id=p_league;
 SELECT * INTO prior FROM public.league_memberships WHERE league_id=p_league AND team_id=p_team FOR UPDATE;
 IF prior.id IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'Mapping changed. Reload before saving'; END IF;
 IF prior.id IS NULL AND p_email IS NULL THEN RAISE EXCEPTION 'No mapped member to remove'; END IF;
 IF prior.role='admin' OR prior.user_id=auth.uid()
  OR EXISTS(SELECT FROM sportsbook_private.platform_owners WHERE user_id=prior.user_id)
  OR EXISTS(SELECT FROM public.league_staff_grants WHERE league_id=p_league AND user_id=prior.user_id AND active)
  OR EXISTS(SELECT FROM sportsbook_private.platform_owner WHERE membership_id=prior.id)
 THEN RAISE EXCEPTION 'Commissioner and staff access requires platform-owner review'; END IF;

 IF p_email IS NOT NULL THEN
  IF target.sleeper_id IS NULL THEN RAISE EXCEPTION 'Wait for a verified Sleeper roster sync'; END IF;
  SELECT * INTO account FROM auth.users WHERE lower(email)=lower(trim(p_email)) AND email_confirmed_at IS NOT NULL;
  IF account.id IS NULL THEN RAISE EXCEPTION 'The replacement needs an existing verified Boff account'; END IF;
  IF EXISTS(SELECT FROM boff_dev_internal.co_manager_links WHERE league_id=p_league AND user_id=account.id)
   OR EXISTS(SELECT FROM public.league_memberships WHERE league_id=p_league AND (user_id=account.id OR invited_email=lower(account.email)))
   OR EXISTS(SELECT FROM public.user_wallets WHERE league_id=p_league AND user_id=account.id)
  THEN RAISE EXCEPTION 'An existing league or wallet identity requires platform-owner review'; END IF;
 END IF;

 IF prior.id IS NOT NULL THEN
  UPDATE public.user_wallets SET status='revoked',revision=revision+1,updated_at=clock_timestamp()
   WHERE league_id=p_league AND user_id=prior.user_id AND status='approved' RETURNING * INTO wallet;
  IF wallet.id IS NOT NULL THEN
   INSERT INTO sportsbook_private.user_wallet_approvals(wallet_id,actor,reason) VALUES(wallet.id,auth.uid(),trim(p_reason));
  END IF;
  DELETE FROM public.league_memberships WHERE id=prior.id;
 END IF;
 IF account.id IS NOT NULL THEN
  INSERT INTO public.league_memberships(league_id,team_id,user_id,invited_email,display_name,sleeper_user_id)
  VALUES(p_league,p_team,account.id,lower(account.email),left(coalesce(target.display_name,'Participant'),80),target.sleeper_id);
 END IF;
 INSERT INTO public.admin_change_log(league_id,actor_id,category,reason,before_value,after_value)
 VALUES(p_league,auth.uid(),'commissioner_membership',trim(p_reason),
  jsonb_build_object('team_id',p_team,'user_id',prior.user_id,'sleeper_id',prior.sleeper_user_id),
  jsonb_build_object('team_id',p_team,'user_id',account.id,'sleeper_id',CASE WHEN account.id IS NOT NULL THEN target.sleeper_id END));
 RETURN public.dev_commissioner_members(p_league);
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_change_commissioner_member"(p_league uuid, p_team uuid, p_expected uuid, p_email text, p_reason text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_change_commissioner_member"(p_league uuid, p_team uuid, p_expected uuid, p_email text, p_reason text) TO "authenticated";

