CREATE OR REPLACE FUNCTION public.dev_commissioner_activity(p_league uuid, p_type text DEFAULT 'All'::text, p_member uuid DEFAULT NULL::uuid, p_week integer DEFAULT NULL::integer, p_from date DEFAULT NULL::date, p_until date DEFAULT NULL::date, p_cursor jsonb DEFAULT NULL::jsonb, p_size integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb;
BEGIN
 IF NOT boff_dev_internal.can_manage_members(p_league) THEN RAISE EXCEPTION 'Verified commissioner or platform owner required';END IF;
 IF p_size IS NULL OR p_size NOT BETWEEN 1 AND 100 OR p_type IS NULL OR p_type NOT IN('All','TicketPlaced','TicketSettled','TicketVoided','Credits','Correction','Membership','Rules','Administration')
 OR (p_week IS NOT NULL AND p_week NOT BETWEEN 1 AND 18) OR (p_from IS NOT NULL AND p_until IS NOT NULL AND p_from>p_until)
 OR (p_cursor IS NOT NULL AND (jsonb_typeof(p_cursor)<>'object' OR length(p_cursor::text)>256 OR NOT p_cursor?'time' OR NOT p_cursor?'id'))
 THEN RAISE EXCEPTION 'Invalid activity filters';END IF;
 WITH source AS MATERIALIZED(SELECT * FROM boff_dev_internal.activity_rows(p_league)),filtered AS(
 SELECT * FROM source WHERE (p_type='All' OR event_type=p_type) AND (p_member IS NULL OR member_id=p_member OR actor_id=p_member)
 AND(p_week IS NULL OR week=p_week) AND(p_from IS NULL OR event_at>=p_from::timestamp AT TIME ZONE 'America/New_York')
 AND(p_until IS NULL OR event_at<(p_until+1)::timestamp AT TIME ZONE 'America/New_York')
 ),candidates AS MATERIALIZED(
 SELECT * FROM filtered WHERE p_cursor IS NULL OR(event_at,event_id)<((p_cursor->>'time')::timestamptz,p_cursor->>'id')
 ORDER BY event_at DESC,event_id DESC LIMIT p_size+1
 ),page AS(SELECT * FROM candidates ORDER BY event_at DESC,event_id DESC LIMIT p_size)
 SELECT jsonb_build_object('events',coalesce((SELECT jsonb_agg(to_jsonb(p) ORDER BY event_at DESC,event_id DESC) FROM page p),'[]'),
 'next',CASE WHEN(SELECT count(*) FROM candidates)>p_size THEN(SELECT jsonb_build_object('time',event_at,'id',event_id) FROM page ORDER BY event_at ASC,event_id ASC LIMIT 1) ELSE NULL END,
 'count',(SELECT count(*) FROM filtered),
 'members',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name) ORDER BY name) FROM(
 SELECT member_id AS id,max(member_name) AS name FROM source WHERE member_id IS NOT NULL GROUP BY member_id)x),'[]')) INTO result;
 RETURN result;
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_commissioner_activity"(p_league uuid, p_type text, p_member uuid, p_week integer, p_from date, p_until date, p_cursor jsonb, p_size integer) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_commissioner_activity"(p_league uuid, p_type text, p_member uuid, p_week integer, p_from date, p_until date, p_cursor jsonb, p_size integer) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_commissioner_members(p_league uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT boff_dev_internal.can_manage_members(p_league) THEN RAISE EXCEPTION 'Commissioner access required'; END IF;
 RETURN jsonb_build_object('teams',coalesce((
  SELECT jsonb_agg(jsonb_build_object('teamId',t.id,'team',t.team_name,'rosterId',t.roster_id,
   'memberId',m.id,
 'member',CASE WHEN m.user_id IS NULL AND EXISTS(
  SELECT FROM jsonb_array_elements(source.value->'coManagers') manager WHERE manager->>'id'=m.sleeper_user_id
 ) THEN NULL ELSE m.display_name END,
 'role',m.role,'mappedSleeperId',m.sleeper_user_id,
   'sleeperId',source.value->>'ownerId','sleeperName',coalesce(source.value->>'ownerName',source.value->'managers'->>0),
 'coManagers',(SELECT coalesce(jsonb_agg(jsonb_build_object(
  'id',person.id,'name',person.name,'avatar',person.avatar,'accountId',link.user_id,
 'member',coalesce(link.display_name,CASE WHEN m.sleeper_user_id=person.id AND m.user_id IS NULL THEN m.display_name END),
 
  'walletStatus',wallet.status,'walletInitialized',wallet.balance IS NOT NULL,'departed',person.departed)
 ORDER BY person.departed,person.name),'[]') FROM (
   SELECT j->>'id' id,j->>'name' name,j->>'avatar' avatar,false departed
   FROM jsonb_array_elements(source.value->'coManagers') j
   UNION ALL SELECT x.sleeper_user_id,x.display_name,NULL,true FROM boff_dev_internal.co_manager_links x
   WHERE x.league_id=t.league_id AND x.team_id=t.id
   AND NOT EXISTS(SELECT FROM jsonb_array_elements(source.value->'coManagers') j WHERE j->>'id'=x.sleeper_user_id)
  ) person LEFT JOIN boff_dev_internal.co_manager_links link
   ON link.league_id=t.league_id AND link.team_id=t.id AND link.sleeper_user_id=person.id
  LEFT JOIN public.user_wallets wallet ON wallet.league_id=t.league_id AND wallet.user_id=link.user_id)
 ,'avatar',coalesce(source.value->>'avatar',t.avatar_url),'hasAccount',m.user_id IS NOT NULL,
   'walletStatus',w.status,'walletInitialized',w.balance IS NOT NULL) ORDER BY t.roster_id)
  FROM public.teams t JOIN public.leagues l ON l.id=t.league_id
  LEFT JOIN public.league_memberships m ON m.league_id=t.league_id AND m.team_id=t.id
  LEFT JOIN public.user_wallets w ON w.league_id=t.league_id AND w.user_id=m.user_id
  LEFT JOIN public.dev_live_cache cache ON cache.key='league:'||l.sleeper_league_id
   AND cache.payload->'metadata'->>'season'=l.nfl_season::text
  LEFT JOIN LATERAL (SELECT value FROM jsonb_array_elements(cache.payload->'metadata'->'teams')
   WHERE (value->>'rosterId')::integer=t.roster_id LIMIT 1) source ON true
  WHERE t.league_id=p_league),'[]'));
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_commissioner_members"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_commissioner_members"(p_league uuid) TO "authenticated";

