CREATE OR REPLACE FUNCTION public.dev_email_event_summary(p_league uuid, p_user uuid, p_kind text, p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE ticket_id uuid;
DECLARE summary jsonb;
DECLARE book record;
DECLARE offers jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Mail worker required'; END IF;
 IF p_kind IN ('settled','leg') THEN
  IF split_part(p_key,':',1) IS DISTINCT FROM p_kind OR split_part(p_key,':',2) !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$'
   THEN RETURN '{}'; END IF;
  ticket_id:=split_part(p_key,':',2)::uuid;
  SELECT jsonb_build_object('Ticket',left(t.id::text,8),'Week',t.market_week,'Stake',t.stake||' credits',
   'Ticket Odds',CASE WHEN t.accepted_combined_odds>0 THEN '+' ELSE '' END||t.accepted_combined_odds)
   || coalesce((
    SELECT jsonb_object_agg('Leg '||leg.leg_number,
     left(leg.selection,145)||' · '||initcap(leg.status)||' · '||
      CASE WHEN leg.accepted_odds>0 THEN '+' ELSE '' END||leg.accepted_odds ORDER BY leg.leg_number)
    FROM public.ticket_legs leg WHERE leg.ticket_id=t.id
   ),'{}')
  INTO summary
  FROM public.tickets t JOIN public.user_wallets w ON w.id=t.user_wallet_id
  WHERE t.id=ticket_id AND t.league_id=p_league AND w.league_id=p_league AND w.user_id=p_user
   AND (p_kind<>'settled' OR t.settled_at IS NOT NULL);
  RETURN coalesce(summary,'{}');
 END IF;

 IF p_kind NOT IN ('opening','offers') THEN RETURN '{}'; END IF;
 SELECT b.id,b.market_week,concat_ws(':',b.id,b.revision,b.content_version,d.source_hash,d.offer_schedule_hash) AS version
 INTO book FROM public.dev_current_book d JOIN public.sportsbook_boards b ON b.id=d.board_id
 WHERE d.league_id=p_league AND b.status='published' AND b.opens_at<=now()
  AND b.closes_at>now() AND d.valid_until>now() AND d.last_error IS NULL;
 IF NOT FOUND THEN RETURN '{}'; END IF;
 offers:=boff_dev_internal.cached_weekly_offer_options(p_league,book.id,book.version);
 SELECT coalesce(jsonb_object_agg('Offer '||o.ordinality,
  left(o.value->>'title',100)||' · '||(o.value->>'percent')||'% Profit Boost'||
  coalesce((SELECT ' · '||string_agg(left(leg->>'label',80),', ' ORDER BY n)
   FROM jsonb_array_elements(o.value->'picks') WITH ORDINALITY p(leg,n)),'')),'{}')
 INTO summary FROM jsonb_array_elements(offers) WITH ORDINALITY o(value,ordinality);
 RETURN jsonb_build_object('Week',book.market_week)||summary;
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_email_event_summary"(p_league uuid, p_user uuid, p_kind text, p_key text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_email_event_summary"(p_league uuid, p_user uuid, p_kind text, p_key text) TO "service_role";

CREATE OR REPLACE FUNCTION public.dev_email_reader(p_kind text, p_league uuid DEFAULT NULL::uuid, p_week integer DEFAULT NULL::integer, p_details boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE options jsonb; selected uuid;
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL)
 THEN RAISE EXCEPTION 'Verified sign-in required' USING ERRCODE='42501'; END IF;
 options:=boff_dev_internal.email_league_options(auth.uid());
 selected:=coalesce(p_league,(options->0->>'id')::uuid);
 IF selected IS NULL THEN RETURN jsonb_build_object('leagues',options,'report',NULL); END IF;
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(options) x WHERE x->>'id'=selected::text)
 THEN RAISE EXCEPTION 'League access unavailable' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('leagues',options,'report',boff_dev_internal.email_league_report(auth.uid(),selected,p_kind,p_week,p_details));
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_email_reader"(p_kind text, p_league uuid, p_week integer, p_details boolean) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_email_reader"(p_kind text, p_league uuid, p_week integer, p_details boolean) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_email_standings(p_league uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT coalesce(jsonb_agg(to_jsonb(s) ORDER BY s.tickets>0 DESC,s.profit DESC,s.name),'[]') FROM (
  SELECT p.display_name AS name,w.team_id AS "teamId",w.balance,count(t.id) AS tickets,
   coalesce(sum(CASE WHEN t.status='WON' THEN coalesce(t.actual_payout,t.accepted_potential_payout)-t.stake
    WHEN t.status='LOST' THEN -t.stake ELSE 0 END),0) AS profit
  FROM public.user_wallets w JOIN public.leagues l ON l.id=w.league_id
  JOIN boff_dev_internal.participant_links p ON (p.league_id,p.user_id,p.team_id)=(w.league_id,w.user_id,w.team_id)
  LEFT JOIN public.tickets t ON t.league_id=w.league_id AND t.nfl_season=l.nfl_season AND
   (t.user_wallet_id=w.id OR (t.user_wallet_id IS NULL AND t.team_id=w.team_id AND t.bettor_display_name=p.display_name))
  WHERE w.league_id=p_league AND w.status='approved'
  GROUP BY w.id,p.display_name
  ORDER BY count(t.id)>0 DESC,profit DESC,p.display_name LIMIT 5
 ) s
$function$
;

REVOKE ALL ON FUNCTION "public"."dev_email_standings"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_email_standings"(p_league uuid) TO "service_role";

CREATE OR REPLACE FUNCTION public.dev_email_switcher(p_user uuid, p_kind text, p_week integer, p_primary uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE options jsonb; item jsonb; reports jsonb:='[]'; choice jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Mail worker required'; END IF;
 IF p_kind NOT IN ('opening','recap','monday_watch','credit') THEN RAISE EXCEPTION 'Unsupported report'; END IF;
 options:=boff_dev_internal.email_league_options(p_user);
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(options) x WHERE x->>'id'=p_primary::text)
 THEN RAISE EXCEPTION 'Primary membership unavailable' USING ERRCODE='42501'; END IF;
 FOR item IN SELECT x FROM jsonb_array_elements(options) x ORDER BY x->>'id'=p_primary::text DESC,x->>'name' LIMIT 12 LOOP
  SELECT c.choices->p_kind INTO choice FROM boff_dev_internal.notification_choices c WHERE c.user_id=p_user AND c.league_id=(item->>'id')::uuid;
  IF coalesce((choice->>'email')::boolean,true) THEN
   reports:=reports||jsonb_build_array(boff_dev_internal.email_league_report(p_user,(item->>'id')::uuid,p_kind,p_week,true));
  END IF;
 END LOOP;
 RETURN reports;
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_email_switcher"(p_user uuid, p_kind text, p_week integer, p_primary uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_email_switcher"(p_user uuid, p_kind text, p_week integer, p_primary uuid) TO "service_role";

CREATE OR REPLACE FUNCTION public.dev_email_switcher_scope(p_recipient text, p_kind text, p_leagues jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE account uuid; item jsonb; choice jsonb;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Mail worker required'; END IF;
 IF p_kind NOT IN ('opening','recap','monday_watch','credit') OR jsonb_typeof(p_leagues) IS DISTINCT FROM 'array'
 OR jsonb_array_length(p_leagues) NOT BETWEEN 1 AND 12 THEN RETURN false; END IF;
 SELECT id INTO account FROM auth.users WHERE lower(email)=lower(p_recipient) AND email_confirmed_at IS NOT NULL;
 IF account IS NULL THEN RETURN false; END IF;
 FOR item IN SELECT x FROM jsonb_array_elements(p_leagues) x LOOP
  IF NOT EXISTS(SELECT FROM boff_dev_internal.participant_links WHERE league_id=(item->>'id')::uuid AND user_id=account)
  THEN RETURN false; END IF;
  SELECT c.choices->p_kind INTO choice FROM boff_dev_internal.notification_choices c WHERE c.user_id=account AND c.league_id=(item->>'id')::uuid;
  IF NOT coalesce((choice->>'email')::boolean,true)
  THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_email_switcher_scope"(p_recipient text, p_kind text, p_leagues jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_email_switcher_scope"(p_recipient text, p_kind text, p_leagues jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION public.dev_fantasy_reward_rules(p_league uuid, p_revision integer DEFAULT NULL::integer, p_rules jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE saved boff_dev_internal.fantasy_reward_rules; item record;
BEGIN
  IF auth.uid() IS NULL OR NOT EXISTS (SELECT FROM public.leagues WHERE id = p_league)
    OR NOT (sportsbook_private.is_platform_owner() OR EXISTS (
      SELECT FROM public.league_memberships
      WHERE league_id = p_league AND user_id = auth.uid() AND role = 'admin'
    )) THEN
    RAISE EXCEPTION 'Commissioner access required';
  END IF;
  IF p_rules IS NOT NULL THEN
    IF p_revision IS NULL OR jsonb_typeof(p_rules) <> 'object'
      OR jsonb_typeof(p_rules->'weeklyLimit') IS DISTINCT FROM 'boolean'
      OR jsonb_typeof(p_rules->'boost') IS DISTINCT FROM 'object'
      OR octet_length(p_rules::text) > 2048
      OR (p_rules - ARRAY['weeklyLimit','boost','enabled','maxRecipients','closeMargin','upsetSpread','projectionMargin']) <> '{}'::jsonb THEN
      RAISE EXCEPTION 'Invalid fantasy reward settings';
    END IF;
    FOR item IN SELECT key, value FROM jsonb_each(p_rules->'boost') LOOP
      IF item.key NOT IN ('topScorer','win3','win5','win7','win10','loss3','loss5','loss7','loss10','closeWin','upset','highLoss','beatProjection','seasonRecord','leagueRecord','playoffClinch','champion')
        OR jsonb_typeof(item.value) <> 'number'
        OR (item.value::text)::numeric NOT BETWEEN 0 AND 100 THEN
        RAISE EXCEPTION 'Invalid reward percentage';
      END IF;
    END LOOP;
    
 IF (p_rules ? 'enabled' AND jsonb_typeof(p_rules->'enabled') IS DISTINCT FROM 'object')
 OR (p_rules ? 'maxRecipients' AND jsonb_typeof(p_rules->'maxRecipients') IS DISTINCT FROM 'object')
 OR EXISTS (SELECT FROM jsonb_each(p_rules->'enabled') x WHERE jsonb_typeof(x.value)<>'boolean'
  OR x.key NOT IN ('topScorer','win3','win5','win7','win10','loss3','loss5','loss7','loss10','closeWin','upset','highLoss','beatProjection','seasonRecord','leagueRecord','playoffClinch','champion'))
 OR EXISTS (SELECT FROM jsonb_each(p_rules->'maxRecipients') x WHERE x.value::text !~ '^(0|[1-9][0-9]{0,2})$'
  OR CASE WHEN x.value::text ~ '^[0-9]+$' THEN x.value::text::integer>128 ELSE false END
  OR x.key NOT IN ('topScorer','win3','win5','win7','win10','loss3','loss5','loss7','loss10','closeWin','upset','highLoss','beatProjection','seasonRecord','leagueRecord','playoffClinch','champion'))
 THEN RAISE EXCEPTION 'Invalid award toggles or recipient limits'; END IF;
 FOR item IN SELECT key,value FROM jsonb_each(p_rules - ARRAY['weeklyLimit','boost','enabled','maxRecipients'])
  LOOP
      IF jsonb_typeof(item.value) <> 'number' OR (item.value::text)::numeric NOT BETWEEN 0.01 AND 1000 THEN
        RAISE EXCEPTION 'Invalid reward threshold';
      END IF;
    END LOOP;
    PERFORM pg_advisory_xact_lock(hashtext('boff-dev-fantasy-reward-rules'), hashtext(p_league::text));
    SELECT * INTO saved FROM boff_dev_internal.fantasy_reward_rules WHERE league_id = p_league;
    IF COALESCE(saved.revision, 0) <> p_revision THEN RAISE EXCEPTION 'Reward rules changed. Reload and try again.'; END IF;
    INSERT INTO boff_dev_internal.fantasy_reward_rules AS current_rules (league_id, revision, rules)
    VALUES (p_league, p_revision + 1, p_rules)
    ON CONFLICT (league_id) DO UPDATE SET revision = EXCLUDED.revision, rules = EXCLUDED.rules
    RETURNING current_rules.* INTO saved;
    INSERT INTO boff_dev_internal.fantasy_reward_rule_changes (league_id, revision, actor, rules)
    VALUES (p_league, saved.revision, auth.uid(), saved.rules);
  ELSE
    SELECT * INTO saved FROM boff_dev_internal.fantasy_reward_rules WHERE league_id = p_league;
  END IF;
  RETURN jsonb_build_object('revision', COALESCE(saved.revision, 0), 'rules', COALESCE(saved.rules, '{}'::jsonb));
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_fantasy_reward_rules"(p_league uuid, p_revision integer, p_rules jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_fantasy_reward_rules"(p_league uuid, p_revision integer, p_rules jsonb) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_feature_settings(p_league uuid, p_season integer, p_revision integer DEFAULT NULL::integer, p_settings jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE stored boff_dev_internal.feature_settings; team_count integer; season_now integer;
BEGIN
 IF auth.uid() IS NULL OR NOT (sportsbook_private.is_platform_owner() OR EXISTS(
  SELECT FROM public.league_memberships WHERE league_id=p_league AND user_id=auth.uid() AND role='admin'
 )) THEN RAISE EXCEPTION 'Commissioner access required'; END IF;
 SELECT nfl_season INTO STRICT season_now FROM public.leagues WHERE id=p_league;
 IF season_now IS DISTINCT FROM p_season THEN RAISE EXCEPTION 'Select the current season'; END IF;
 IF p_settings IS NOT NULL THEN
  SELECT count(*) INTO team_count FROM public.teams WHERE league_id=p_league;
  IF jsonb_typeof(p_settings)<>'object' OR octet_length(p_settings::text)>24000
   OR p_settings->>'schema' IS DISTINCT FROM '2'
   OR jsonb_typeof(p_settings->'rivals') IS DISTINCT FROM 'array'
   OR jsonb_typeof(p_settings->'plans') IS DISTINCT FROM 'object'
   OR jsonb_typeof(p_settings->'enabled') IS DISTINCT FROM 'object'
   OR jsonb_typeof(p_settings->'cutoffs') IS DISTINCT FROM 'object'
  THEN RAISE EXCEPTION 'Invalid featured matchup settings'; END IF;
  IF jsonb_array_length(p_settings->'rivals')>team_count*3/2 OR EXISTS(
   SELECT FROM jsonb_array_elements(p_settings->'rivals') pair WHERE
    CASE WHEN jsonb_typeof(pair)<>'array' THEN true WHEN jsonb_array_length(pair)<>2 THEN true ELSE
     pair->>0=pair->>1 OR NOT EXISTS(SELECT FROM public.teams WHERE league_id=p_league AND id::text=pair->>0)
      OR NOT EXISTS(SELECT FROM public.teams WHERE league_id=p_league AND id::text=pair->>1) END
  ) OR EXISTS(
   SELECT FROM jsonb_array_elements(p_settings->'rivals') pair
   GROUP BY least(pair->>0,pair->>1),greatest(pair->>0,pair->>1) HAVING count(*)>1
  ) OR EXISTS(
   SELECT FROM jsonb_array_elements(p_settings->'rivals') pair CROSS JOIN LATERAL jsonb_array_elements_text(pair) team
   GROUP BY team HAVING count(*)>3
  ) THEN RAISE EXCEPTION 'Choose up to three unique rivals per team'; END IF;
  IF EXISTS(SELECT FROM jsonb_each(p_settings->'enabled') e WHERE jsonb_typeof(e.value)<>'boolean')
   OR EXISTS(SELECT FROM jsonb_each(p_settings->'cutoffs') c WHERE jsonb_typeof(c.value)<>'number')
   OR EXISTS(SELECT FROM jsonb_each(p_settings->'plans') w WHERE w.key !~ '^([1-9]|1[0-8])$'
    OR jsonb_typeof(w.value->'overrides') IS DISTINCT FROM 'object'
    OR jsonb_typeof(w.value->'playoffModes') IS DISTINCT FROM 'object')
  THEN RAISE EXCEPTION 'Invalid featured matchup rules'; END IF;
  IF EXISTS(
   SELECT FROM jsonb_each(p_settings->'plans') w CROSS JOIN LATERAL jsonb_each_text(w.value->'overrides') o
   WHERE o.key !~ '^([0-9]+|sleeper-[0-9]+-[0-9]+-[0-9]+)$'
    OR o.value NOT IN ('championship','playoff','rivalry','revenge','upset','streak','tank','game')
  ) OR EXISTS(
   SELECT FROM jsonb_each(p_settings->'plans') w CROSS JOIN LATERAL jsonb_each_text(w.value->'playoffModes') m
   WHERE m.value IS NULL OR m.value NOT IN ('auto','both','away-racing','home-racing')
  ) THEN RAISE EXCEPTION 'Invalid matchup preset'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('dev-feature-settings'),hashtext(p_league::text));
  SELECT * INTO stored FROM boff_dev_internal.feature_settings WHERE league_id=p_league AND season=p_season;
  IF p_revision IS DISTINCT FROM COALESCE(stored.revision,0) THEN RAISE EXCEPTION 'Settings changed. Reopen the tab and try again.'; END IF;
  IF stored.settings IS DISTINCT FROM p_settings THEN
   INSERT INTO boff_dev_internal.feature_settings VALUES(p_league,p_season,coalesce(stored.revision,0)+1,p_settings)
   ON CONFLICT(league_id,season) DO UPDATE SET revision=excluded.revision,settings=excluded.settings RETURNING * INTO stored;
   UPDATE public.dev_live_cache SET next_refresh_at=now() WHERE key='nfl' OR key=(SELECT 'league:'||sleeper_league_id FROM public.leagues WHERE id=p_league);
   PERFORM boff_dev_internal.request_live_refresh();
  END IF;
 ELSE
  SELECT * INTO stored FROM boff_dev_internal.feature_settings WHERE league_id=p_league AND season=p_season;
 END IF;
 RETURN jsonb_build_object('revision',coalesce(stored.revision,0),'settings',stored.settings);
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_feature_settings"(p_league uuid, p_season integer, p_revision integer, p_settings jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_feature_settings"(p_league uuid, p_season integer, p_revision integer, p_settings jsonb) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_futures_rules(p_league uuid, p_revision integer DEFAULT NULL::integer, p_rules jsonb DEFAULT NULL::jsonb, p_confirmed boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  league public.leagues;
  saved boff_dev_internal.futures_rule_versions;
  sleeper jsonb;
BEGIN
  IF NOT sportsbook_private.release_environment_ready()
    OR auth.uid() IS NULL OR NOT (sportsbook_private.is_admin(p_league) OR sportsbook_private.is_platform_owner()) THEN
    RAISE EXCEPTION 'Commissioner access required';
  END IF;
  SELECT * INTO STRICT league FROM public.leagues WHERE id = p_league;
  SELECT payload->'metadata' INTO sleeper FROM public.dev_live_cache
  WHERE key = 'league:' || league.sleeper_league_id AND payload->'metadata'->>'season' = league.nfl_season::text;
  IF p_rules IS NOT NULL THEN
    PERFORM pg_advisory_xact_lock(hashtext('boff-dev-futures-rules'), hashtext(p_league::text));
  END IF;
  SELECT * INTO saved FROM boff_dev_internal.futures_rule_versions
  WHERE league_id = p_league AND season = league.nfl_season ORDER BY revision DESC LIMIT 1;
  IF p_rules IS NOT NULL THEN
    IF p_confirmed IS DISTINCT FROM true OR p_revision IS DISTINCT FROM COALESCE(saved.revision, 0) THEN
      RAISE EXCEPTION 'Confirm the change against the latest saved rules';
    END IF;
    IF jsonb_typeof(p_rules) <> 'object' OR octet_length(p_rules::text) > 1024
      OR (p_rules - ARRAY['qualification','firstPick','rostersReady']) <> '{}'::jsonb
      OR COALESCE(p_rules->>'qualification','') NOT IN ('sleeper','head_to_head','official_bracket')
      OR COALESCE(p_rules->>'firstPick','') NOT IN ('disabled','regular_season','toilet_bowl')
      OR jsonb_typeof(p_rules->'rostersReady') IS DISTINCT FROM 'boolean' THEN
      RAISE EXCEPTION 'Invalid futures rules';
    END IF;
    IF p_rules->>'firstPick' <> 'disabled' AND sleeper->'settings'->>'leagueType' IS DISTINCT FROM '2' THEN
      RAISE EXCEPTION '#1 Pick requires a verified Sleeper dynasty league';
    END IF;
    IF saved.rules IS DISTINCT FROM p_rules THEN
      INSERT INTO boff_dev_internal.futures_rule_versions(league_id, season, revision, rules, actor_id)
      VALUES (p_league, league.nfl_season, p_revision + 1, p_rules, auth.uid())
      RETURNING * INTO saved;
    END IF;
  END IF;
  RETURN jsonb_build_object('revision', COALESCE(saved.revision, 0), 'rules',
    COALESCE(saved.rules, '{"qualification":"sleeper","firstPick":"disabled","rostersReady":false}'::jsonb),
    'season', league.nfl_season, 'leagueSize', jsonb_array_length(sleeper->'teams'), 'sleeper', sleeper->'settings');
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_futures_rules"(p_league uuid, p_revision integer, p_rules jsonb, p_confirmed boolean) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_futures_rules"(p_league uuid, p_revision integer, p_rules jsonb, p_confirmed boolean) TO "authenticated";

