CREATE OR REPLACE FUNCTION public.dev_league_feed_preferences(p_league uuid, p_choices jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NULL OR NOT (sportsbook_private.is_member(p_league) OR sportsbook_private.is_platform_owner()) THEN
  RAISE EXCEPTION 'League membership required';
 END IF;
 IF p_choices IS NOT NULL THEN
  IF NOT (sportsbook_private.is_platform_owner() OR EXISTS (
   SELECT FROM public.league_memberships WHERE league_id=p_league AND user_id=auth.uid() AND role='admin'
  )) THEN RAISE EXCEPTION 'Commissioner access required'; END IF;
  IF jsonb_typeof(p_choices)<>'object' OR octet_length(p_choices::text)>1024 OR EXISTS(
   SELECT FROM jsonb_each(p_choices) x 
 WHERE CASE
  WHEN x.key IN ('tradeHistory','injuryBody','featuredOdds','includeTaxi','injuriesMyMatchup') THEN jsonb_typeof(x.value)<>'boolean'
  WHEN x.key IN ('bigWinProfit','bigWinOdds','underdogLead','parlayProgress','ticketStake','ticketLegs') THEN
    CASE WHEN x.value::text !~ '^[0-9]{1,5}$' THEN true ELSE x.value::text::integer NOT BETWEEN
     CASE x.key WHEN 'bigWinOdds' THEN 100 WHEN 'parlayProgress' THEN 1 WHEN 'ticketLegs' THEN 1 ELSE 0 END AND
     CASE x.key WHEN 'bigWinOdds' THEN 99900 WHEN 'underdogLead' THEN 200 WHEN 'parlayProgress' THEN 10 WHEN 'ticketLegs' THEN 10 ELSE 10000 END
    END
  ELSE jsonb_typeof(x.value)<>'boolean' OR x.key NOT IN (
 
    'Trade','This Week in History','Playoff History','Injury Report','Injury Update','Fantasy Reward',
    'Featured','Big Win','Underdog Watch','Live Score','Parlay Watch','Ticket Placed','Week Recap') END
  ) THEN RAISE EXCEPTION 'Invalid feed categories'; END IF;
  INSERT INTO boff_dev_internal.league_feed_preferences VALUES(p_league,p_choices)
  ON CONFLICT(league_id) DO UPDATE SET choices=excluded.choices;
 END IF;
 RETURN COALESCE((SELECT choices FROM boff_dev_internal.league_feed_preferences WHERE league_id=p_league),'{}'::jsonb);
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_league_feed_preferences"(p_league uuid, p_choices jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_league_feed_preferences"(p_league uuid, p_choices jsonb) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_league_intake_context()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT public.league_intake_owner() THEN RAISE EXCEPTION 'Verified platform owner required'; END IF;
 RETURN jsonb_build_object('season',coalesce((SELECT max(l.nfl_season) FROM public.leagues l JOIN boff_dev_internal.participant_links p ON p.league_id=l.id WHERE p.user_id=auth.uid()),extract(year from now())::integer),
  'sleeperUsers',coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM(SELECT sleeper_user_id AS id,min(display_name) AS name FROM boff_dev_internal.participant_links
    WHERE user_id=auth.uid() AND sleeper_user_id~'^[0-9]{1,32}$' GROUP BY sleeper_user_id ORDER BY sleeper_user_id LIMIT 3)s),'[]'),
  'linked',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'sleeperId',sleeper_league_id,'name',name)) FROM(SELECT id,sleeper_league_id,name FROM public.leagues ORDER BY name LIMIT 1000)l),'[]'));
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_league_intake_context"() FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_league_intake_context"() TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_league_review_members(p_league uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
  IF auth.uid() IS NULL OR NOT sportsbook_private.is_platform_owner() THEN
    RAISE EXCEPTION 'Platform owner access required';
  END IF;
  RETURN COALESCE((
    SELECT jsonb_agg(jsonb_build_object(
      'id', member.id, 'name', member.display_name, 'teamId', member.team_id,
      'teamName', team.team_name, 'lastSignIn', account.last_sign_in_at,
      'balance', wallet.balance, 'hasAccount', member.user_id IS NOT NULL
    ) ORDER BY member.display_name, member.id)
    FROM public.league_memberships member
    JOIN public.teams team ON team.league_id = member.league_id AND team.id = member.team_id
    LEFT JOIN auth.users account ON account.id = member.user_id
    LEFT JOIN public.user_wallets wallet ON wallet.league_id = member.league_id
      AND wallet.user_id = member.user_id AND wallet.status = 'approved'
    WHERE member.league_id = p_league
  ), '[]'::jsonb);
END
$function$
;

REVOKE ALL ON FUNCTION "public"."dev_league_review_members"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_league_review_members"(p_league uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_member_verification_resend(p_league uuid, p_account uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE address text;
BEGIN
 IF NOT boff_dev_internal.can_manage_members(p_league) THEN RAISE EXCEPTION 'Commissioner access required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('verification-resend:'||p_account,0));
 SELECT email INTO address FROM boff_dev_internal.unverified_league_accounts(p_league) WHERE account_id=p_account;
 IF address IS NULL THEN RAISE EXCEPTION 'No pending verification for this league account'; END IF;
 IF EXISTS(SELECT FROM public.admin_change_log WHERE league_id=p_league AND category='verification_resend'
  AND after_value->>'account_id'=p_account::text AND created_at>now()-interval '60 seconds')
  THEN RAISE EXCEPTION 'Wait one minute before resending'; END IF;
 INSERT INTO public.admin_change_log(league_id,actor_id,category,reason,before_value,after_value)
 VALUES(p_league,auth.uid(),'verification_resend','Commissioner verification resend requested','{}',jsonb_build_object('account_id',p_account));
 RETURN address;
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_member_verification_resend"(p_league uuid, p_account uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_member_verification_resend"(p_league uuid, p_account uuid) TO "authenticated";

