CREATE OR REPLACE FUNCTION public.dev_owner_captured_email(p_league uuid, p_source text, p_id text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NULL OR NOT sportsbook_private.is_platform_owner() THEN RAISE EXCEPTION 'Platform owner access required'; END IF;
 IF p_source='event' THEN
  RETURN (SELECT c.html FROM boff_dev_internal.notification_capture c
    WHERE league_id=p_league AND user_id::text=split_part(p_id,':',-1)
    AND event_key=left(p_id,length(p_id)-37));
 ELSIF p_source='outbox' THEN
  RETURN (SELECT c.payload->>'html' FROM public.outbound_emails e
   JOIN sportsbook_private.development_mail_captures c ON c.email_id=e.id
   WHERE e.id::text=p_id AND e.league_id=p_league AND e.kind<>'signin');
 END IF;
 RETURN NULL;
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_owner_captured_email"(p_league uuid, p_source text, p_id text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_owner_captured_email"(p_league uuid, p_source text, p_id text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_owner_email_log(p_league uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NULL OR NOT sportsbook_private.is_platform_owner() THEN RAISE EXCEPTION 'Platform owner access required'; END IF;
 RETURN coalesce((
  SELECT jsonb_agg(to_jsonb(log) ORDER BY log.time DESC,log.id) FROM (
   (SELECT 'event' AS source, c.event_key||':'||c.user_id AS id, c.kind, c.subject,
    u.email AS recipient, 'captured' AS status, 0 AS attempts, NULL::text AS error, c.created_at AS time
    FROM boff_dev_internal.notification_capture c LEFT JOIN auth.users u ON u.id=c.user_id
    WHERE c.league_id=p_league ORDER BY c.created_at DESC LIMIT 50)
   UNION ALL
   (SELECT 'outbox', e.id::text, e.kind, c.payload->>'subject', e.recipient, e.status, e.attempts, e.last_error,
    coalesce(e.sent_at,c.created_at,e.terminal_at,e.created_at)
    FROM public.outbound_emails e LEFT JOIN sportsbook_private.development_mail_captures c ON c.email_id=e.id
    WHERE e.league_id=p_league ORDER BY e.created_at DESC LIMIT 50)
   ORDER BY time DESC LIMIT 50
  ) log
 ),'[]'::jsonb);
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_owner_email_log"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_owner_email_log"(p_league uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_owner_filtered_email_log(p_league uuid, p_member uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NULL OR NOT sportsbook_private.is_platform_owner() THEN RAISE EXCEPTION 'Platform owner access required'; END IF;
 RETURN (
  WITH members AS MATERIALIZED (
   SELECT DISTINCT ON(m.user_id) m.user_id AS id,m.display_name AS name,u.email
   FROM boff_dev_internal.participant_links m JOIN auth.users u ON u.id=m.user_id
   WHERE m.league_id=p_league
   ORDER BY m.user_id,m.display_name
  ), logs AS (
   (SELECT 'event' AS source,c.event_key||':'||c.user_id AS id,c.kind,c.subject,u.email AS recipient,
    'captured' AS status,0 AS attempts,NULL::text AS error,c.created_at AS time,c.kind<>'signin' AND c.html<>'' AS "hasPreview"
    FROM boff_dev_internal.notification_capture c LEFT JOIN auth.users u ON u.id=c.user_id
    WHERE c.league_id=p_league AND (p_member IS NULL OR c.user_id=p_member)
     AND (p_status IS NULL OR p_status='captured')
    ORDER BY c.created_at DESC,c.event_key LIMIT 50)
   UNION ALL
   (SELECT 'outbox',e.id::text,e.kind,c.payload->>'subject',e.recipient,e.status,e.attempts,e.last_error,
    coalesce(e.sent_at,c.created_at,e.terminal_at,e.created_at),
    e.kind<>'signin' AND c.payload->>'html' IS NOT NULL
    FROM public.outbound_emails e LEFT JOIN sportsbook_private.development_mail_captures c ON c.email_id=e.id
    WHERE e.league_id=p_league AND (p_status IS NULL OR e.status=p_status)
     AND (p_member IS NULL OR EXISTS(SELECT FROM members m WHERE m.id=p_member AND (
      coalesce(e.staff_user_id::text,e.routine_context->>'user_id',m.id::text)=m.id::text
      AND (e.staff_user_id=m.id OR e.routine_context->>'user_id'=m.id::text OR lower(e.recipient)=lower(m.email))
     )))
    ORDER BY coalesce(e.sent_at,c.created_at,e.terminal_at,e.created_at) DESC,e.id LIMIT 50)
  ), recent AS (SELECT * FROM logs ORDER BY time DESC,id LIMIT 50)
  SELECT jsonb_build_object(
   'members',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name) ORDER BY name,id) FROM members),'[]'),
   'logs',coalesce((SELECT jsonb_agg(to_jsonb(recent) ORDER BY time DESC,id) FROM recent),'[]'))
 );
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_owner_filtered_email_log"(p_league uuid, p_member uuid, p_status text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_owner_filtered_email_log"(p_league uuid, p_member uuid, p_status text) TO "authenticated";

