CREATE OR REPLACE FUNCTION public.dev_pending_member_invitations(p_league uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF NOT boff_dev_internal.can_manage_members(p_league) THEN RAISE EXCEPTION 'Commissioner access required'; END IF;
 RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',i.id,'managerStatus',boff_dev_internal.sleeper_manager_status(i.league_id,i.team_id,i.co_manager),'teamId',i.team_id,'team',t.team_name,'sleeperId',i.sleeper_id,
 'coManager',i.co_manager,'expected',i.expected,'email',i.email,'expires',i.expires_at,'captured',i.captured_at IS NOT NULL) ORDER BY i.created_at DESC)
 FROM boff_dev_internal.member_invitations i JOIN public.teams t ON t.id=i.team_id WHERE i.league_id=p_league AND i.status='pending' AND i.expires_at>now()),'[]');
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_pending_member_invitations"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_pending_member_invitations"(p_league uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_prepare_member_invitation(p_league uuid, p_team uuid, p_sleeper text, p_co boolean, p_expected uuid, p_email text, p_reason text, p_request uuid, p_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE invitation boff_dev_internal.member_invitations; target jsonb; linked uuid; account auth.users; team public.teams;
BEGIN
 IF NOT boff_dev_internal.can_manage_members(p_league) THEN RAISE EXCEPTION 'Commissioner access required'; END IF;
 IF p_request IS NULL OR p_co IS NULL OR p_digest IS NULL OR p_digest !~ '^[a-f0-9]{64}$'
 OR length(trim(coalesce(p_reason,''))) NOT BETWEEN 8 AND 400 OR length(trim(coalesce(p_email,''))) NOT BETWEEN 3 AND 254
 OR p_email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'Invalid invitation'; END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('member-invite:'||p_league,0));
 DELETE FROM boff_dev_internal.member_invitations WHERE expires_at<now()-interval '30 days';
 SELECT * INTO team FROM public.teams WHERE id=p_team AND league_id=p_league;
 SELECT value INTO target FROM public.dev_live_cache c CROSS JOIN LATERAL jsonb_array_elements(c.payload->'metadata'->'teams')
 WHERE c.key=(SELECT 'league:'||sleeper_league_id FROM public.leagues WHERE id=p_league) AND (value->>'rosterId')::integer=team.roster_id;
 IF target IS NULL OR (NOT p_co AND target->>'ownerId' IS DISTINCT FROM p_sleeper)
 OR (p_co AND NOT EXISTS(SELECT FROM jsonb_array_elements(target->'coManagers') m WHERE m->>'id'=p_sleeper))
 THEN RAISE EXCEPTION 'Sleeper manager changed. Refresh the member list'; END IF;
 IF p_co THEN SELECT user_id INTO linked FROM boff_dev_internal.co_manager_links WHERE league_id=p_league AND team_id=p_team AND sleeper_user_id=p_sleeper;
 ELSE SELECT id INTO linked FROM public.league_memberships WHERE league_id=p_league AND team_id=p_team;
 END IF;
 IF linked IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'Member mapping changed. Refresh before inviting'; END IF;
 IF NOT p_co AND EXISTS(SELECT FROM public.league_memberships WHERE id=linked AND role='admin') THEN RAISE EXCEPTION 'Commissioner replacement needs platform owner review'; END IF;
 SELECT * INTO invitation FROM boff_dev_internal.member_invitations WHERE request_id=p_request;
 IF FOUND THEN
  IF invitation.issuer<>auth.uid() OR invitation.league_id<>p_league OR invitation.team_id<>p_team OR invitation.sleeper_id<>p_sleeper
   OR invitation.co_manager<>p_co OR invitation.email<>lower(trim(p_email)) OR invitation.expected IS DISTINCT FROM p_expected
   OR invitation.token_digest<>p_digest OR invitation.reason<>trim(p_reason) THEN RAISE EXCEPTION 'Invitation request already used'; END IF;
 ELSE
  IF EXISTS(SELECT FROM boff_dev_internal.member_invitations WHERE league_id=p_league AND sleeper_id=p_sleeper AND created_at>now()-interval '60 seconds')
   OR (SELECT count(*) FROM boff_dev_internal.member_invitations WHERE league_id=p_league AND issuer=auth.uid() AND created_at>now()-interval '1 day')>=32
   THEN RAISE EXCEPTION 'Invitation limit reached. Wait before trying again'; END IF;
  UPDATE boff_dev_internal.member_invitations SET status='revoked' WHERE league_id=p_league AND team_id=p_team AND sleeper_id=p_sleeper AND status='pending';
  INSERT INTO boff_dev_internal.member_invitations(request_id,league_id,team_id,sleeper_id,co_manager,expected,email,token_digest,issuer,reason)
  VALUES(p_request,p_league,p_team,p_sleeper,p_co,p_expected,lower(trim(p_email)),p_digest,auth.uid(),trim(p_reason)) RETURNING * INTO invitation;
 END IF;
 SELECT * INTO account FROM auth.users WHERE lower(email)=invitation.email AND deleted_at IS NULL;
 RETURN jsonb_build_object('id',invitation.id,'managerStatus',boff_dev_internal.sleeper_manager_status(p_league,p_team,p_co),'leagueId',p_league,'leagueName',(SELECT name FROM public.leagues WHERE id=p_league),
  'teamName',team.team_name,'coManager',p_co,'email',invitation.email,'accountId',account.id,'verified',account.email_confirmed_at IS NOT NULL,
  'leagueAvatar',(SELECT c.payload->'metadata'->>'avatar' FROM public.dev_live_cache c WHERE c.key=(SELECT 'league:'||sleeper_league_id FROM public.leagues WHERE id=p_league)),
  'teamAvatar',target->>'avatar','expires',invitation.expires_at,'captured',invitation.captured_at IS NOT NULL,'status',invitation.status);
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_prepare_member_invitation"(p_league uuid, p_team uuid, p_sleeper text, p_co boolean, p_expected uuid, p_email text, p_reason text, p_request uuid, p_digest text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_prepare_member_invitation"(p_league uuid, p_team uuid, p_sleeper text, p_co boolean, p_expected uuid, p_email text, p_reason text, p_request uuid, p_digest text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_push_device(p_league uuid, p_endpoint text DEFAULT NULL::text, p_keys jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF auth.uid() IS NULL OR NOT EXISTS(SELECT FROM boff_dev_internal.participant_links WHERE league_id=p_league AND user_id=auth.uid())
 THEN RAISE EXCEPTION 'League membership required'; END IF;
 IF p_endpoint IS NOT NULL AND p_keys IS NULL THEN
  DELETE FROM boff_dev_internal.notification_push_devices WHERE user_id=auth.uid() AND endpoint=p_endpoint;
 ELSIF p_endpoint IS NOT NULL THEN
  IF length(p_endpoint)>2000 OR p_endpoint !~ '^https://(fcm\.googleapis\.com|updates\.push\.services\.mozilla\.com|([a-z0-9-]+\.)*push\.apple\.com|([a-z0-9-]+\.)+notify\.windows\.com)/'
   OR coalesce(p_keys->>'auth','') !~ '^[A-Za-z0-9_-]{22}$' OR coalesce(p_keys->>'p256dh','') !~ '^[A-Za-z0-9_-]{87}$'
  THEN RAISE EXCEPTION 'Unsupported push subscription'; END IF;
  PERFORM pg_advisory_xact_lock(hashtext('dev-notification-device'),hashtext(auth.uid()::text));
  IF NOT EXISTS(SELECT FROM boff_dev_internal.notification_push_devices WHERE user_id=auth.uid() AND endpoint=p_endpoint)
   AND (SELECT count(*) FROM boff_dev_internal.notification_push_devices WHERE user_id=auth.uid())>=5
  THEN RAISE EXCEPTION 'Up to five devices can receive notifications'; END IF;
  DELETE FROM boff_dev_internal.notification_push_devices WHERE endpoint=p_endpoint AND user_id<>auth.uid();
  INSERT INTO boff_dev_internal.notification_push_devices(user_id,endpoint,keys)
  VALUES(auth.uid(),p_endpoint,jsonb_build_object('auth',p_keys->>'auth','p256dh',p_keys->>'p256dh'))
  ON CONFLICT(endpoint) DO UPDATE SET keys=excluded.keys WHERE notification_push_devices.user_id=excluded.user_id;
 END IF;
 RETURN (SELECT jsonb_build_object('publicKey',public_key) FROM boff_dev_internal.notification_push_keys);
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_push_device"(p_league uuid, p_endpoint text, p_keys jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_push_device"(p_league uuid, p_endpoint text, p_keys jsonb) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_push_keys(p_public text DEFAULT NULL::text, p_private text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF p_public IS NOT NULL AND p_private IS NOT NULL THEN
  INSERT INTO boff_dev_internal.notification_push_keys(public_key,private_key)
  VALUES(p_public,p_private) ON CONFLICT DO NOTHING;
 END IF;
 RETURN (SELECT jsonb_build_object('publicKey',public_key,'privateKey',private_key)
  FROM boff_dev_internal.notification_push_keys);
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_push_keys"(p_public text, p_private text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_push_keys"(p_public text, p_private text) TO "service_role";

CREATE OR REPLACE FUNCTION public.dev_record_push(p_league uuid, p_device uuid, p_event text, p_expired boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
BEGIN
 IF p_expired THEN
  DELETE FROM boff_dev_internal.notification_push_devices WHERE id=p_device;
 ELSE
  INSERT INTO boff_dev_internal.notification_push_receipts(league_id,device_id,event_key)
  SELECT p_league,p_device,p_event FROM boff_dev_internal.notification_push_devices WHERE id=p_device ON CONFLICT DO NOTHING;
 END IF;
END $function$
;

