CREATE OR REPLACE FUNCTION public.dev_standings_wallets(p_league uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',w.id,'teamId',w.team_id,'name',m.display_name,'balance',w.balance,
  'sleeperId',m.sleeper_user_id,'tickets',stats.tickets,'WON',stats.won,'LOST',stats.lost,
  'stake',stats.stake,'OPEN',stats.open,'profit',stats.profit)), '[]')
 FROM public.user_wallets w JOIN public.leagues l ON l.id=w.league_id
 JOIN boff_dev_internal.participant_links m ON m.league_id=w.league_id AND m.user_id=w.user_id AND m.team_id=w.team_id
 CROSS JOIN LATERAL (
  SELECT count(*) AS tickets,count(*) FILTER (WHERE t.status='WON') AS won,count(*) FILTER (WHERE t.status='LOST') AS lost,
    coalesce(sum(t.stake) FILTER (WHERE t.status IN ('WON','LOST')),0) AS stake,
    coalesce(sum(t.stake) FILTER (WHERE t.status='OPEN'),0) AS open,
    coalesce(sum(CASE WHEN t.status='WON' THEN coalesce(t.actual_payout,t.accepted_potential_payout)-t.stake
      WHEN t.status='LOST' THEN -t.stake ELSE 0 END),0) AS profit
  FROM public.tickets t
  WHERE t.league_id=w.league_id AND t.nfl_season=l.nfl_season AND
    (t.user_wallet_id=w.id OR (t.user_wallet_id IS NULL AND t.team_id=w.team_id AND t.bettor_display_name=m.display_name))
 ) stats
 WHERE w.league_id=p_league AND w.status='approved' AND sportsbook_private.is_member(p_league)
$function$
;

REVOKE ALL ON FUNCTION "public"."dev_standings_wallets"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_standings_wallets"(p_league uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_submit_support(p_league uuid, p_category text, p_message text, p_page text, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=boff_dev_internal.require_verified_support();r boff_dev_internal.support_requests;fingerprint text;person text;team text;
BEGIN
 IF p_league IS NULL OR NOT EXISTS(SELECT FROM public.leagues WHERE id=p_league) OR NOT sportsbook_private.is_member(p_league) THEN RAISE EXCEPTION 'League access required';END IF;
 IF p_request IS NULL OR p_category IS NULL OR p_category NOT IN('Feedback','Question','Bug Report','Feature Suggestion') OR p_message IS NULL
 OR length(trim(p_message)) NOT BETWEEN 10 AND 2000 OR p_page IS NULL OR length(p_page)>200 OR p_page!~'^/[^?#]*$' OR p_page~'[[:cntrl:]]' OR p_page LIKE '//%'
 THEN RAISE EXCEPTION 'Choose a category and enter a message of 10–2,000 characters';END IF;
 fingerprint:=md5(jsonb_build_object('league',p_league,'category',p_category,'message',trim(p_message),'page',p_page)::text);
 PERFORM pg_advisory_xact_lock(hashtextextended('boff-support:'||actor,0));
 SELECT * INTO r FROM boff_dev_internal.support_requests WHERE user_id=actor AND request_key=p_request;
 IF FOUND THEN
 IF r.payload_md5<>fingerprint THEN RAISE EXCEPTION 'This submission identifier already belongs to a different request';END IF;
 RETURN jsonb_build_object('id',r.id,'status',r.status,'createdAt',r.created_at,'duplicate',true);END IF;
 SELECT * INTO r FROM boff_dev_internal.support_requests WHERE user_id=actor AND payload_md5=fingerprint AND created_at>now()-interval '24 hours' ORDER BY created_at DESC LIMIT 1;
 IF FOUND THEN RETURN jsonb_build_object('id',r.id,'status',r.status,'createdAt',r.created_at,'duplicate',true);END IF;
 IF(SELECT count(*) FROM boff_dev_internal.support_requests WHERE user_id=actor AND created_at>now()-interval '10 minutes')>=5
 OR(SELECT count(*) FROM boff_dev_internal.support_requests WHERE user_id=actor AND created_at>now()-interval '24 hours')>=20
 OR(SELECT count(*) FROM boff_dev_internal.support_requests WHERE user_id=actor AND status IN('New','In Progress'))>=100
 THEN RAISE EXCEPTION 'Submission limit reached. Please wait before sending another request';END IF;
 SELECT p.display_name,t.team_name INTO person,team FROM boff_dev_internal.participant_links p JOIN public.teams t ON t.id=p.team_id
 WHERE p.user_id=actor AND p.league_id=p_league ORDER BY p.team_id LIMIT 1;
 person:=coalesce(person,(SELECT display_name FROM public.league_memberships WHERE league_id=p_league AND user_id=actor),CASE WHEN sportsbook_private.is_platform_owner() THEN 'Platform Owner' ELSE 'League Member' END);team:=coalesce(team,'League Administration');
 INSERT INTO boff_dev_internal.support_requests(league_id,user_id,request_key,payload_md5,category,message,page,requester_name,team_name)
 VALUES(p_league,actor,p_request,fingerprint,p_category,trim(p_message),p_page,person,team) RETURNING * INTO r;
 INSERT INTO boff_dev_internal.support_updates(request_id,actor_id,to_status) VALUES(r.id,actor,'New');
 RETURN jsonb_build_object('id',r.id,'status',r.status,'createdAt',r.created_at,'duplicate',false);
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_submit_support"(p_league uuid, p_category text, p_message text, p_page text, p_request uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_submit_support"(p_league uuid, p_category text, p_message text, p_page text, p_request uuid) TO "authenticated";

