CREATE OR REPLACE FUNCTION public.dev_support_request(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=boff_dev_internal.require_verified_support();r boff_dev_internal.support_requests;owner boolean:=sportsbook_private.is_platform_owner();
BEGIN
 SELECT * INTO r FROM boff_dev_internal.support_requests WHERE id=p_id AND(owner OR user_id=actor);
 IF NOT FOUND THEN RAISE EXCEPTION 'Request unavailable';END IF;
 RETURN jsonb_build_object('id',r.id,'category',r.category,'message',r.message,'status',r.status,'revision',r.revision,'page',r.page,'created',r.created_at,
 'name',r.requester_name,'team',r.team_name,'league',(SELECT name FROM public.leagues WHERE id=r.league_id),'canManage',owner,
 'email',CASE WHEN owner THEN(SELECT email FROM auth.users WHERE id=r.user_id) ELSE NULL END,
 'updates',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'from',from_status,'to',to_status,'note',note,'created',created_at) ORDER BY created_at,id)
 FROM boff_dev_internal.support_updates WHERE request_id=r.id),'[]'));
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_support_request"(p_id uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_support_request"(p_id uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_support_requests(p_owner boolean DEFAULT false, p_league uuid DEFAULT NULL::uuid, p_status text DEFAULT 'All'::text, p_member uuid DEFAULT NULL::uuid, p_cursor jsonb DEFAULT NULL::jsonb, p_size integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=boff_dev_internal.require_verified_support();result jsonb;
BEGIN
 IF p_owner IS NULL OR (p_owner AND NOT sportsbook_private.is_platform_owner()) THEN RAISE EXCEPTION 'Platform owner access required';END IF;
 IF p_status IS NULL OR p_status NOT IN('All','New','In Progress','Resolved','Closed') OR p_size IS NULL OR p_size NOT BETWEEN 1 AND 100
 OR (NOT p_owner AND p_member IS NOT NULL AND p_member<>actor)
 OR(p_cursor IS NOT NULL AND(jsonb_typeof(p_cursor)<>'object' OR length(p_cursor::text)>256 OR NOT p_cursor?'time' OR NOT p_cursor?'id'))
 THEN RAISE EXCEPTION 'Invalid support filters';END IF;
 WITH scope AS MATERIALIZED(SELECT r.*,l.name AS league_name FROM boff_dev_internal.support_requests r JOIN public.leagues l ON l.id=r.league_id WHERE p_owner OR r.user_id=actor),
 filtered AS(SELECT * FROM scope WHERE(p_league IS NULL OR league_id=p_league) AND(p_status='All' OR status=p_status) AND(p_member IS NULL OR user_id=p_member)),
 candidates AS MATERIALIZED(SELECT * FROM filtered WHERE p_cursor IS NULL OR(created_at,id)<((p_cursor->>'time')::timestamptz,(p_cursor->>'id')::uuid)
 ORDER BY created_at DESC,id DESC LIMIT p_size+1),
 page AS(SELECT * FROM candidates ORDER BY created_at DESC,id DESC LIMIT p_size)
 SELECT jsonb_build_object('requests',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'leagueId',league_id,'league',league_name,'name',requester_name,'team',team_name,
 'category',category,'preview',left(message,180),'status',status,'created',created_at,'updated',updated_at,'revision',revision) ORDER BY created_at DESC,id DESC) FROM page),'[]'),
 'next',CASE WHEN(SELECT count(*) FROM candidates)>p_size THEN(SELECT jsonb_build_object('time',created_at,'id',id) FROM page ORDER BY created_at ASC,id ASC LIMIT 1) ELSE NULL END,
 'count',(SELECT count(*) FROM filtered),'newCount',(SELECT count(*) FROM scope WHERE status='New'),
 'leagues',coalesce((SELECT jsonb_agg(jsonb_build_object('id',league_id,'name',name) ORDER BY name) FROM(SELECT league_id,max(league_name) AS name FROM scope GROUP BY league_id)x),'[]'),
 'members',coalesce((SELECT jsonb_agg(jsonb_build_object('id',user_id,'name',name) ORDER BY name) FROM(SELECT user_id,max(requester_name) AS name FROM scope WHERE p_league IS NULL OR league_id=p_league GROUP BY user_id)x),'[]')) INTO result;
 RETURN result;
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_support_requests"(p_owner boolean, p_league uuid, p_status text, p_member uuid, p_cursor jsonb, p_size integer) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_support_requests"(p_owner boolean, p_league uuid, p_status text, p_member uuid, p_cursor jsonb, p_size integer) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_ticket_history_page(p_league uuid, p_mine boolean DEFAULT false, p_status text DEFAULT 'All'::text, p_week integer DEFAULT NULL::integer, p_participant uuid DEFAULT NULL::uuid, p_search text DEFAULT ''::text, p_sort text DEFAULT 'newest'::text, p_cursor jsonb DEFAULT NULL::jsonb, p_size integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE result jsonb; descending_order boolean:=p_sort IN('newest','stake-high'); pattern text;
BEGIN
 IF NOT EXISTS(SELECT FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL)
 OR NOT sportsbook_private.is_member(p_league) THEN RAISE EXCEPTION 'Verified league membership required'; END IF;
 IF p_size IS NULL OR p_size NOT BETWEEN 1 AND 100 OR p_sort NOT IN('newest','oldest','stake-high','stake-low')
 OR p_status NOT IN('All','Open','Won','Lost','Push','Voided') OR length(p_search)>100
 OR (p_week IS NOT NULL AND p_week NOT BETWEEN 1 AND 18)
 OR (p_cursor IS NOT NULL AND (jsonb_typeof(p_cursor)<>'object' OR NOT p_cursor ? 'value' OR NOT p_cursor ? 'id'))
 THEN RAISE EXCEPTION 'Invalid history parameters'; END IF;
 pattern:='%'||replace(replace(replace(p_search,E'\\',E'\\\\'),'%',E'\\%'),'_',E'\\_')||'%';
 WITH scope AS NOT MATERIALIZED (
  SELECT t.* FROM public.tickets t WHERE t.league_id=p_league AND
   (NOT p_mine OR t.user_wallet_id IN(SELECT id FROM public.user_wallets WHERE league_id=p_league AND user_id=auth.uid()))
 ), filtered AS NOT MATERIALIZED (
  SELECT t.*,CASE WHEN p_sort IN('stake-high','stake-low') THEN t.stake ELSE extract(epoch FROM t.placed_at) END AS page_value
  FROM scope t WHERE (p_status='All' OR t.status=upper(p_status)) AND (p_week IS NULL OR t.market_week=p_week)
  AND (p_participant IS NULL OR t.user_wallet_id=p_participant OR (t.user_wallet_id IS NULL AND t.team_id=p_participant))
  AND (p_search='' OR t.id::text ILIKE pattern OR EXISTS(SELECT FROM public.ticket_legs l WHERE l.ticket_id=t.id AND (l.selection ILIKE pattern OR l.matchup ILIKE pattern)))
 ), candidates AS MATERIALIZED (
  SELECT * FROM filtered t WHERE p_cursor IS NULL OR
   (descending_order AND (t.page_value,t.id)<((p_cursor->>'value')::numeric,(p_cursor->>'id')::uuid)) OR
   (NOT descending_order AND (t.page_value,t.id)>((p_cursor->>'value')::numeric,(p_cursor->>'id')::uuid))
  ORDER BY CASE WHEN descending_order THEN page_value END DESC,CASE WHEN NOT descending_order THEN page_value END ASC,
   CASE WHEN descending_order THEN id END DESC,CASE WHEN NOT descending_order THEN id END ASC LIMIT p_size+1
 ), numbered AS (
  SELECT *,row_number() OVER(ORDER BY CASE WHEN descending_order THEN page_value END DESC,CASE WHEN NOT descending_order THEN page_value END ASC,
   CASE WHEN descending_order THEN id END DESC,CASE WHEN NOT descending_order THEN id END ASC) AS n FROM candidates
 ), page AS (
  SELECT n.*,coalesce((SELECT jsonb_agg(to_jsonb(l)-'source_record' ORDER BY l.leg_number) FROM public.ticket_legs l WHERE l.ticket_id=n.id),'[]') AS legs
  FROM numbered n WHERE n.n<=p_size
 )
 SELECT jsonb_build_object(
  'tickets',coalesce((SELECT jsonb_agg((to_jsonb(t)-'page_value'-'n'-'legs'-'source_record'-'policy_snapshot'-'sportsbook_policy_snapshot')||jsonb_build_object('ticket_legs',legs) ORDER BY n) FROM page t),'[]'),
  'next',CASE WHEN (SELECT count(*) FROM candidates)>p_size THEN (SELECT jsonb_build_object('value',page_value::text,'id',id) FROM page ORDER BY n DESC LIMIT 1) ELSE NULL END,
  'summary',(SELECT jsonb_build_object('count',count(*),'openStake',coalesce(sum(stake) FILTER(WHERE status='OPEN'),0)) FROM scope),
  'weeks',coalesce((SELECT jsonb_agg(w ORDER BY w DESC) FROM(SELECT DISTINCT market_week AS w FROM scope)x),'[]'),
  'participants',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'name',name) ORDER BY name) FROM
    (SELECT coalesce(s.user_wallet_id,s.team_id) AS id,max(coalesce(s.bettor_display_name,t.team_name||' · Historical Team')) AS name FROM scope s JOIN public.teams t ON t.id=s.team_id GROUP BY coalesce(s.user_wallet_id,s.team_id))x),'[]')
 ) INTO result;
 RETURN result;
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_ticket_history_page"(p_league uuid, p_mine boolean, p_status text, p_week integer, p_participant uuid, p_search text, p_sort text, p_cursor jsonb, p_size integer) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_ticket_history_page"(p_league uuid, p_mine boolean, p_status text, p_week integer, p_participant uuid, p_search text, p_sort text, p_cursor jsonb, p_size integer) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_update_support(p_id uuid, p_revision integer, p_status text, p_note text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE actor uuid:=boff_dev_internal.require_verified_support();r boff_dev_internal.support_requests;
BEGIN
 IF NOT sportsbook_private.is_platform_owner() THEN RAISE EXCEPTION 'Platform owner access required';END IF;
 IF p_status IS NULL OR p_status NOT IN('New','In Progress','Resolved','Closed') OR p_note IS NULL OR length(p_note)>1000 THEN RAISE EXCEPTION 'Invalid status update';END IF;
 SELECT * INTO r FROM boff_dev_internal.support_requests WHERE id=p_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Request unavailable';END IF;
 IF p_revision IS DISTINCT FROM r.revision THEN RAISE EXCEPTION 'Request changed. Refresh before saving';END IF;
 IF p_status=r.status THEN RETURN public.dev_support_request(p_id);END IF;
 IF(SELECT count(*) FROM boff_dev_internal.support_updates WHERE request_id=p_id)>=100 THEN RAISE EXCEPTION 'Request update limit reached';END IF;
 UPDATE boff_dev_internal.support_requests SET status=p_status,revision=revision+1,updated_at=now() WHERE id=p_id;
 INSERT INTO boff_dev_internal.support_updates(request_id,actor_id,from_status,to_status,note) VALUES(p_id,actor,r.status,p_status,trim(p_note));
 RETURN public.dev_support_request(p_id);
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_update_support"(p_id uuid, p_revision integer, p_status text, p_note text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_update_support"(p_id uuid, p_revision integer, p_status text, p_note text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_weekly_changes(p_league uuid, p_version text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 SELECT jsonb_build_object(
  'board',to_jsonb(b),'book',jsonb_build_object('board_id',c.board_id,'observed_at',c.observed_at,'valid_until',c.valid_until,'last_error',c.last_error),'version',v.version,
  'mode',CASE WHEN p_version=v.version THEN 'unchanged'
    WHEN d.base_version=p_version AND d.version=v.version AND octet_length(d.changes::text)<280000 THEN 'delta'
    ELSE 'snapshot' END,
  'changes',CASE WHEN d.base_version=p_version AND d.version=v.version AND octet_length(d.changes::text)<280000 THEN d.changes END,
  'futures', (SELECT jsonb_build_object('id',f.id,'revision',f.revision,'status',
    CASE WHEN s.rules_revision IS DISTINCT FROM coalesce(r.revision,0) THEN 'draft' ELSE f.status END,'quote_valid_until',f.quote_valid_until)
   FROM public.sportsbook_boards f JOIN boff_dev_internal.futures_board_state s ON s.league_id=f.league_id AND s.season=f.nfl_season
   LEFT JOIN LATERAL (SELECT revision FROM boff_dev_internal.futures_rule_versions WHERE league_id=f.league_id AND season=f.nfl_season ORDER BY revision DESC LIMIT 1) r ON true
   WHERE f.league_id=p_league AND f.nfl_season=b.nfl_season AND f.board_type='future')
 )
 FROM public.dev_current_book c JOIN public.sportsbook_boards b ON b.id=c.board_id
 CROSS JOIN LATERAL (SELECT boff_dev_internal.weekly_version(b,c) version) v
 LEFT JOIN boff_dev_internal.weekly_board_delta d ON d.league_id=c.league_id
 WHERE c.league_id=p_league
$function$
;

REVOKE ALL ON FUNCTION "public"."dev_weekly_changes"(p_league uuid, p_version text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_weekly_changes"(p_league uuid, p_version text) TO "service_role";

CREATE OR REPLACE FUNCTION public.dev_weekly_offer_changes(p_league uuid, p_version text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE b public.sportsbook_boards;
DECLARE input_version text;
DECLARE offers jsonb := '[]';
DECLARE version text;
BEGIN
 IF auth.uid() IS NULL OR NOT sportsbook_private.is_member(p_league) THEN RAISE EXCEPTION 'League membership required'; END IF;
 SELECT sb.* INTO b FROM public.dev_current_book d
 JOIN public.sportsbook_boards sb ON sb.id=d.board_id
 WHERE d.league_id=p_league AND sb.status='published' AND sb.opens_at<=now()
  AND sb.closes_at>now() AND d.valid_until>now() AND d.last_error IS NULL;
 IF b.id IS NOT NULL THEN
  SELECT concat_ws(':',b.id,b.revision,b.content_version,d.source_hash,d.offer_schedule_hash)
  INTO input_version FROM public.dev_current_book d WHERE d.league_id=p_league AND d.board_id=b.id;
  IF input_version IS NOT NULL THEN
   SELECT coalesce(jsonb_agg(o.value || jsonb_build_object('claimed',c.user_id IS NOT NULL,'used',c.ticket_id IS NOT NULL)
     ORDER BY o.position),'[]') INTO offers
   FROM jsonb_array_elements(boff_dev_internal.cached_weekly_offer_options(p_league,b.id,input_version))
    WITH ORDINALITY o(value,position)
   LEFT JOIN boff_dev_internal.weekly_offer_claims c
     ON (c.league_id,c.season,c.week,c.slot,c.user_id)=(p_league,b.nfl_season,b.market_week,o.value->>'slot',auth.uid());
  END IF;
 END IF;
 version:=md5(offers::text);
 RETURN CASE WHEN version=p_version THEN jsonb_build_object('version',version)
  ELSE jsonb_build_object('version',version,'offers',offers) END;
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_weekly_offer_changes"(p_league uuid, p_version text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_weekly_offer_changes"(p_league uuid, p_version text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.dev_weekly_offers(p_league uuid, p_claim text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE b public.sportsbook_boards; options jsonb; promo jsonb;
BEGIN
 IF auth.uid() IS NULL OR NOT sportsbook_private.is_member(p_league) THEN RAISE EXCEPTION 'League membership required'; END IF;
 SELECT sb.* INTO b FROM public.dev_current_book d JOIN public.sportsbook_boards sb ON sb.id=d.board_id WHERE d.league_id=p_league;
 IF b.id IS NULL THEN RETURN '[]'; END IF;
 options:=boff_dev_internal.weekly_offer_options(b.id);
 IF p_claim IS NOT NULL THEN
  SELECT value INTO promo FROM jsonb_array_elements(options) WHERE value->>'slot'=p_claim AND p_claim='duels';
  IF promo IS NULL THEN RAISE EXCEPTION 'Offer unavailable'; END IF;
  INSERT INTO boff_dev_internal.weekly_offer_claims VALUES(p_league,b.nfl_season,b.market_week,p_claim,auth.uid(),NULL,(promo->>'percent')::numeric)
  ON CONFLICT DO NOTHING;
 END IF;
 RETURN COALESCE((SELECT jsonb_agg(value||jsonb_build_object('claimed',c.user_id IS NOT NULL,'used',c.ticket_id IS NOT NULL))
  FROM jsonb_array_elements(options) o
  LEFT JOIN boff_dev_internal.weekly_offer_claims c ON (c.league_id,c.season,c.week,c.slot,c.user_id)=(p_league,b.nfl_season,b.market_week,value->>'slot',auth.uid())),'[]');
END $function$
;

REVOKE ALL ON FUNCTION "public"."dev_weekly_offers"(p_league uuid, p_claim text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."dev_weekly_offers"(p_league uuid, p_claim text) TO "authenticated";

