CREATE OR REPLACE FUNCTION public.financial_email_context(p_league uuid, p_team uuid, p_recipient text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Mail worker only.';end if;
 if not exists(select 1 from sportsbook_private.user_finance_modes where league_id=p_league and enabled) then return null;end if;
 select jsonb_build_object('wallet_id',w.id,'user_id',w.user_id,'league_id',w.league_id,'team_id',w.team_id,
  'recipient',a.email,'display_name',w.display_name,'balance',w.balance) into result
 from public.user_wallets w join auth.users a on a.id=w.user_id where w.league_id=p_league and w.team_id=p_team
  and w.status='approved' and a.email_confirmed_at is not null and a.email=p_recipient;
 if result is null then raise exception 'Financial recipient is pending approval or verification.';end if;
 if (select count(*) from public.user_wallets where league_id=p_league)>128 then raise exception 'Financial email participant budget exceeded.';end if;
 result:=result||coalesce((select jsonb_build_object('rank',r.rank,'participants',r.participants) from (
  select w.id,row_number() over(order by x.profit desc,x.bets desc,w.id) rank,count(*) over() participants
  from public.user_wallets w cross join lateral(select count(*) bets,coalesce(sum(t.net_profit) filter(where t.status<>'OPEN'),0) profit
   from public.tickets t where t.user_wallet_id=w.id and t.status<>'VOIDED') x where w.league_id=p_league
 ) r where r.id=(result->>'wallet_id')::uuid),'{}'::jsonb);
 return result;
end $function$
;

REVOKE ALL ON FUNCTION "public"."financial_email_context"(p_league uuid, p_team uuid, p_recipient text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."financial_email_context"(p_league uuid, p_team uuid, p_recipient text) TO "service_role";

CREATE OR REPLACE FUNCTION public.financial_email_recipient(p_ticket uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Mail worker only.';end if;
 if not exists(select 1 from public.tickets where id=p_ticket and user_wallet_id is not null) then return null;end if;
 select jsonb_build_object('wallet_id',w.id,'user_id',w.user_id,'league_id',t.league_id,'team_id',t.team_id,
  'recipient',a.email,'display_name',w.display_name,'balance',w.balance,
  'accepted_balance',(select balance_after from public.user_wallet_entries where wallet_id=w.id and ticket_id=t.id and kind='wager')) into result
 from public.tickets t join public.user_wallets w on w.id=t.user_wallet_id join auth.users a on a.id=w.user_id
 where t.id=p_ticket and w.status='approved' and a.email_confirmed_at is not null;
 if result is null then raise exception 'Accepted financial recipient is no longer approved or verified.';end if;
 if result->'accepted_balance'='null'::jsonb then raise exception 'Accepted wager receipt is unavailable.';end if;
 return result;
end $function$
;

REVOKE ALL ON FUNCTION "public"."financial_email_recipient"(p_ticket uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."financial_email_recipient"(p_ticket uuid) TO "service_role";

CREATE OR REPLACE FUNCTION public.import_league_intake_draft(p_draft uuid, p_expected integer, p_league_season integer, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.league_intake_drafts;l uuid:=gen_random_uuid();t jsonb;team uuid;options jsonb;begin
 if not public.league_intake_owner() then raise exception 'Verified platform owner required.';end if;
 if p_league_season is null or p_league_season not between 1 and 100 or p_reason is null or length(trim(p_reason)) not between 8 and 400 then raise exception 'Reviewed league season and reason required.';end if;
 perform pg_advisory_xact_lock(20261101,16);
 select * into d from public.league_intake_drafts where id=p_draft and owner_id=auth.uid() for update;
 if not found then raise exception 'Intake draft unavailable.';end if;
 options:=jsonb_build_object('league_season',p_league_season,'reason',trim(p_reason));
 if d.state='imported' then
  if d.import_options is distinct from options then raise exception 'Import already used different reviewed terms.';end if;
  return jsonb_build_object('league_id',d.imported_league_id,'duplicate',true,'operations_enabled',false);
 end if;
 if p_expected is distinct from d.revision or d.state<>'draft' or d.expires_at<=clock_timestamp() then raise exception 'Intake draft changed or expired.';end if;
 if exists(select 1 from public.leagues where sleeper_league_id=d.source_league_id) then raise exception 'This provider league already exists; review renewal separately.';end if;
 if (select count(*) from public.leagues)>=32 then raise exception 'League admission budget reached.';end if;
 perform sportsbook_private.validate_intake_source(d.source,d.capabilities);
 insert into public.leagues(id,name,sleeper_league_id,nfl_season,league_season,active_week,week_anchor,operations_enabled,provider_contract)
 values(l,d.source->>'name',d.source_league_id,(d.source->>'season')::integer,p_league_season,1,clock_timestamp(),false,
  jsonb_build_object('version',1,'source',d.source-'teams','capabilities',d.capabilities,'review_status','pending'));
 for t in select value from jsonb_array_elements(d.source->'teams') loop
  team:=gen_random_uuid();
  insert into public.teams(id,league_id,roster_id,team_name,sleeper_owner_id,owner_name,sportsbook_owner_id,sportsbook_owner_name,co_owner_ids,co_owner_names,wins,losses,ties)
  values(team,l,(t->>'roster_id')::integer,t->>'team_name',t->>'owner_id',t->>'owner_name',t->>'owner_id',t->>'owner_name',
   array(select jsonb_array_elements_text(t->'co_owner_ids')),array(select jsonb_array_elements_text(t->'co_owner_names')),(t->>'wins')::integer,(t->>'losses')::integer,(t->>'ties')::integer);
  insert into public.wallets(team_id,balance) values(team,null) on conflict(team_id) do nothing;
 end loop;
 insert into public.weekly_schedule(league_id,automation_enabled,publication_paused,opening_email,reminder_email,recap_email)
 values(l,false,true,false,false,false) on conflict(league_id) do nothing;
 update public.league_intake_drafts set state='imported',imported_league_id=l,import_options=options,source='{}',capabilities='{}',revision=revision+1 where id=d.id;
 insert into public.admin_change_log(league_id,actor_id,category,reason,before_value,after_value)
 values(l,auth.uid(),'league_intake',trim(p_reason),'{}',jsonb_build_object('draft_id',d.id,'source_md5',d.payload_md5,'provider_contract','sleeper-nfl-intake-v1','operations_enabled',false));
 return jsonb_build_object('league_id',l,'duplicate',false,'operations_enabled',false);
end $function$
;

REVOKE ALL ON FUNCTION "public"."import_league_intake_draft"(p_draft uuid, p_expected integer, p_league_season integer, p_reason text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."import_league_intake_draft"(p_draft uuid, p_expected integer, p_league_season integer, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.initialize_user_wallet(p_league uuid, p_user uuid, p_mode text, p_expected_legacy numeric, p_reason text, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w public.user_wallets;old_balance numeric;entry public.user_wallet_entries;value numeric;begin perform pg_advisory_xact_lock_shared(20261101,17);
 if not sportsbook_private.is_platform_owner() or not exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null)
  then raise exception 'Platform owner approval required.';end if;
 if p_request is null or p_mode is null or p_mode not in ('zero','transfer_legacy') or p_reason is null or length(trim(p_reason)) not between 8 and 500
 then raise exception 'Explicit initialization mode, request identifier and review reason required.';end if;
 select * into w from public.user_wallets where league_id=p_league and user_id=p_user for update;
 if not found or w.status<>'approved' then raise exception 'Approved financial account required.';end if;
 if not exists(select 1 from auth.users where id=p_user and email_confirmed_at is not null) then raise exception 'Verified account required before initialization.';end if;
 select * into entry from public.user_wallet_entries where wallet_id=w.id and event_key='initialize';
 if found then
  if entry.request_key<>p_request or entry.reason<>trim(p_reason) or entry.metadata->>'mode'<>p_mode or entry.metadata->'expected_legacy' is distinct from coalesce(to_jsonb(p_expected_legacy),'null'::jsonb)
  then raise exception 'Financial initialization already used another request or terms.';end if;
  return jsonb_build_object('wallet_id',w.id,'duplicate',true,'balance',w.balance);
 end if;
 if w.balance is not null then raise exception 'Initialized balance lacks its receipt; review required.';end if;
 if not sportsbook_private.user_finance_enabled(p_league) then raise exception 'Financial routing must pass activation before moving opening cash.';end if;
 if p_mode='transfer_legacy' then
  if not exists(select 1 from public.league_memberships where league_id=p_league and team_id=w.team_id and user_id=p_user)
  then raise exception 'Legacy cash requires the existing primary participant and explicit owner approval.';end if;
  select balance into old_balance from public.wallets where team_id=w.team_id for update;
  if not found or old_balance is null or p_expected_legacy is distinct from old_balance then raise exception 'Legacy cash changed or remains pending; review again.';end if;
  if exists(select 1 from public.tickets where team_id=w.team_id and status='OPEN') then raise exception 'Open legacy liabilities require a separately reviewed routing migration.';end if;
  value:=old_balance;
  update public.wallets set balance=0,updated_at=clock_timestamp() where team_id=w.team_id;
  insert into public.wallet_ledger(team_id,event_key,kind,amount,balance_before,balance_after,reason)
   values(w.team_id,'account:transfer:'||w.id,'account_transfer_out',-value,value,0,trim(p_reason));
 else
  if p_expected_legacy is not null then raise exception 'Zero initialization cannot claim a legacy balance.';end if;
  if exists(select 1 from public.league_memberships m where m.league_id=p_league and m.team_id=w.team_id and m.user_id=p_user)
   and (exists(select 1 from public.wallets where team_id=w.team_id and balance>0) or exists(select 1 from public.tickets where team_id=w.team_id and status='OPEN'))
  then raise exception 'Existing primary cash or open liabilities require a reviewed transfer after settlement.';end if;
  value:=0;
 end if;
 update public.user_wallets set balance=value,updated_at=clock_timestamp() where id=w.id;
 insert into public.user_wallet_entries(wallet_id,league_id,team_id,event_key,request_key,kind,amount,balance_before,balance_after,reason,metadata)
 values(w.id,w.league_id,w.team_id,'initialize',p_request,case when p_mode='transfer_legacy' then 'legacy_transfer_in' else 'opening' end,value,null,value,trim(p_reason),
  jsonb_build_object('mode',p_mode,'expected_legacy',p_expected_legacy,'actor_id',auth.uid()));
 return jsonb_build_object('wallet_id',w.id,'duplicate',false,'balance',value);
end $function$
;

REVOKE ALL ON FUNCTION "public"."initialize_user_wallet"(p_league uuid, p_user uuid, p_mode text, p_expected_legacy numeric, p_reason text, p_request uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."initialize_user_wallet"(p_league uuid, p_user uuid, p_mode text, p_expected_legacy numeric, p_reason text, p_request uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION public.issue_team_invitation(p_league uuid, p_team uuid, p_email text, p_digest text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare i sportsbook_private.team_invitations;begin
 if not public.league_intake_owner() then raise exception 'Verified platform owner required.';end if;
 if p_digest is null or p_digest!~'^[0-9a-f]{64}$' or (p_email is not null and (length(trim(p_email)) not between 3 and 254 or position('@' in p_email)<2))
  or p_reason is null or length(trim(p_reason)) not between 8 and 400 then raise exception 'Scoped email, token digest and review reason required.';end if;
 perform pg_advisory_xact_lock(20261102,16);
 select * into i from sportsbook_private.team_invitations where token_digest=p_digest;
 if found then
  if row(i.league_id,i.team_id,i.invited_email,i.reason) is distinct from row(p_league,p_team,lower(trim(p_email)),trim(p_reason)) then raise exception 'Invitation identifier already used with different terms.';end if;
  return jsonb_build_object('id',i.id,'expires_at',i.expires_at,'duplicate',true);
 end if;
 if not exists(select 1 from public.leagues where id=p_league) or (p_team is not null and not exists(select 1 from public.teams where id=p_team and league_id=p_league)) then raise exception 'Scoped team required.';end if;
 if (select count(*) from sportsbook_private.team_invitations where league_id=p_league)>=256
  or (select count(*) from sportsbook_private.team_invitations where league_id=p_league and state='open' and expires_at>clock_timestamp())>=32
 then raise exception 'Invitation admission budget reached; review existing invitations.';end if;
 insert into sportsbook_private.team_invitations(league_id,team_id,token_digest,invited_email,created_by,expires_at,reason)
 values(p_league,p_team,p_digest,lower(trim(p_email)),auth.uid(),clock_timestamp()+interval '7 days',trim(p_reason)) returning * into i;
 insert into public.admin_change_log(league_id,actor_id,category,before_value,after_value,reason)
 values(p_league,auth.uid(),'team_invitation','{}',jsonb_build_object('invitation_id',i.id,'team_id',p_team,'expires_at',i.expires_at),trim(p_reason));
 return jsonb_build_object('id',i.id,'expires_at',i.expires_at,'duplicate',false);
end $function$
;

REVOKE ALL ON FUNCTION "public"."issue_team_invitation"(p_league uuid, p_team uuid, p_email text, p_digest text, p_reason text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."issue_team_invitation"(p_league uuid, p_team uuid, p_email text, p_digest text, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.label_future_leg()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 new.market_type:=case new.settlement_context->>'kind' when 'future_champion' then 'League Winner' when 'future_playoffs' then 'Make / Miss Playoffs' when 'future_first_pick' then '#1 Pick' when 'future_win_total' then 'Regular-season Wins' else new.market_type end;
 return new;
end $function$
;

