CREATE OR REPLACE FUNCTION public.observe_provider_capability(p_league uuid, p_source jsonb, p_report jsonb, p_build text, p_started timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l public.leagues;source jsonb;rosters jsonb;h text;s sportsbook_private.provider_capability_state;begin
 if auth.role()is distinct from 'service_role'then raise exception 'Verified server observation only.';end if;
 if p_build is null or p_build!~'^[a-f0-9]{40}$'then raise exception 'Qualified build identity required.';end if;
 if p_started is null or p_started>clock_timestamp()+interval '30 seconds'or p_started<clock_timestamp()-interval '15 minutes'then raise exception 'Fresh server observation time required.';end if;
 perform sportsbook_private.validate_intake_source(p_source,p_report);
 perform pg_advisory_xact_lock(hashtextextended('provider-capability:'||p_league,0));
 select * into l from public.leagues where id=p_league for share;
 if not found or l.provider_contract is null or(l.sleeper_league_id is distinct from p_source->>'league_id'and not coalesce(p_source->>'previous_league_id'=l.sleeper_league_id and(p_source->>'season')::integer=l.nfl_season+1,false))then raise exception 'Imported provider identity required.';end if;
 if exists(select 1 from sportsbook_private.provider_capability_state where league_id=p_league and observed_at>p_started)then raise exception 'A newer provider observation already exists; retry with current inputs.';end if;
 source:=p_source-'teams';
 select jsonb_agg(jsonb_build_object('roster_id',t->'roster_id','owner_id',t->'owner_id','co_owner_ids',(select coalesce(jsonb_agg(value order by value),'[]')from jsonb_array_elements(t->'co_owner_ids')))order by(t->>'roster_id')::integer)into rosters from jsonb_array_elements(p_source->'teams')t;
 h:=encode(sha256(convert_to(jsonb_build_object('source',sportsbook_private.capability_source(source),'rosters',rosters,'configuration',sportsbook_private.provider_configuration_hash(p_league),'build',p_build)::text,'UTF8')),'hex');
 perform pg_advisory_xact_lock(hashtextextended('provider-capability:'||p_league,0));
 insert into sportsbook_private.provider_capability_state(league_id,source,rosters,observed_hash,observed_at,build_sha)values(p_league,source,rosters,h,p_started,p_build)
 on conflict(league_id)do update set source=excluded.source,rosters=excluded.rosters,observed_hash=excluded.observed_hash,observed_at=excluded.observed_at,build_sha=excluded.build_sha,
 approved_hash=case when sportsbook_private.provider_capability_state.observed_hash=excluded.observed_hash then sportsbook_private.provider_capability_state.approved_hash else null end,
 approved_by=case when sportsbook_private.provider_capability_state.observed_hash=excluded.observed_hash then sportsbook_private.provider_capability_state.approved_by else null end,
 approved_at=case when sportsbook_private.provider_capability_state.observed_hash=excluded.observed_hash then sportsbook_private.provider_capability_state.approved_at else null end;
 return jsonb_build_object('review_hash',h,'build_sha',p_build,'observed_at',p_started,'renewal_required',(p_source->>'season')::integer<>l.nfl_season);
end $function$
;

REVOKE ALL ON FUNCTION "public"."observe_provider_capability"(p_league uuid, p_source jsonb, p_report jsonb, p_build text, p_started timestamp with time zone) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."observe_provider_capability"(p_league uuid, p_source jsonb, p_report jsonb, p_build text, p_started timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION public.opening_editorial_context(p_league uuid, p_season integer, p_week integer, p_window_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c jsonb;e sportsbook_private.opening_editorial_editions;previous jsonb;begin
 if auth.role() is distinct from 'service_role' then raise exception 'Editorial worker only.';end if;
 c:=public.notification_window(p_league,p_season,p_week,'opening');
 if c->>'eligible' is distinct from 'true' or c->>'window_key' is distinct from p_window_key then raise exception 'Current opening window required for editorial evidence.';end if;
 select * into e from sportsbook_private.opening_editorial_editions where league_id=p_league;
 if e.current_document->'facts'->>'window_key'=p_window_key and e.current_document->'facts'->>'nfl_season'=p_season::text and e.current_document->'facts'->>'market_week'=p_week::text then return jsonb_build_object('current',e.current_document,'previous',null);end if;
 if e.current_document->'facts'->>'nfl_season'=p_season::text then
  if e.current_document->'facts'->>'market_week'=p_week::text then previous:=e.previous_document;
  elsif (e.current_document->'facts'->>'market_week')::integer=p_week-1 then previous:=e.current_document;end if;
 end if;
 return jsonb_build_object('current',case when e.current_document->'facts'->>'window_key'=p_window_key and e.current_document->'facts'->>'nfl_season'=p_season::text and e.current_document->'facts'->>'market_week'=p_week::text then e.current_document else null end,'previous',previous);
end $function$
;

REVOKE ALL ON FUNCTION "public"."opening_editorial_context"(p_league uuid, p_season integer, p_week integer, p_window_key text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."opening_editorial_context"(p_league uuid, p_season integer, p_week integer, p_window_key text) TO "service_role";

CREATE OR REPLACE FUNCTION public.patch_future_board(p_board uuid, p_revision integer, p_updates jsonb, p_status text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.sportsbook_boards;
begin
  select * into b from public.sportsbook_boards where id=p_board for update;
  if not found or b.board_type<>'future' or not sportsbook_private.is_admin(b.league_id)
    or b.nfl_season is distinct from (select nfl_season from public.leagues where id=b.league_id) then
    raise exception 'Only the authorized league admin can edit this futures board.';
  end if;
  if p_revision is distinct from b.revision then raise exception 'Futures changed. Reload before saving.'; end if;
  if p_status is null or p_status not in ('draft','published','closed') or p_updates is null
    or jsonb_typeof(p_updates)<>'array' or jsonb_array_length(p_updates)>1000 then
    raise exception 'Invalid futures edit.';
  end if;
  if exists(select 1 from jsonb_array_elements(p_updates) q where jsonb_typeof(q)<>'object'
    or not(q ? 'id' and q ? 'odds') or (q - 'id' - 'odds')<>'{}'::jsonb
    or jsonb_typeof(q->'odds')<>'number' or (q->>'odds')::numeric<>trunc((q->>'odds')::numeric)
    or abs((q->>'odds')::numeric) not between 100 and(public.current_sportsbook_policy(b.league_id)->'values'->>'futures_max_odds')::integer
    or mod((q->>'odds')::numeric,(public.current_sportsbook_policy(b.league_id)->'values'->>'futures_odds_step')::integer)<>0) then raise exception 'Invalid futures price fields.'; end if;
  if (select count(*) from jsonb_array_elements(p_updates))<>
     (select count(distinct (q->>'id')::uuid) from jsonb_array_elements(p_updates) q) then
    raise exception 'Duplicate futures price edits.';
  end if;
  if exists(select 1 from jsonb_array_elements(p_updates) q where not exists(
    select 1 from public.sportsbook_markets m where m.id=(q->>'id')::uuid and m.board_id=b.id
      and m.active and m.kind like 'future_%')) then raise exception 'Futures quote scope mismatch.'; end if;
  if p_status='published' and not exists(select 1 from public.sportsbook_markets where board_id=b.id and active) then
    raise exception 'Generate futures before publishing.';
  end if;
  update public.sportsbook_markets m set odds=(q.value->>'odds')::integer
    from jsonb_array_elements(p_updates) q where m.id=(q.value->>'id')::uuid
      and m.board_id=b.id and m.odds is distinct from (q.value->>'odds')::integer;
  update public.sportsbook_boards set status=p_status,revision=revision+1 where id=b.id;
  return b.id;
end;
$function$
;

REVOKE ALL ON FUNCTION "public"."patch_future_board"(p_board uuid, p_revision integer, p_updates jsonb, p_status text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."patch_future_board"(p_board uuid, p_revision integer, p_updates jsonb, p_status text) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."patch_future_board"(p_board uuid, p_revision integer, p_updates jsonb, p_status text) TO "service_role";

