CREATE OR REPLACE FUNCTION public.place_dev_future(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE board public.sportsbook_boards; rule boff_dev_internal.futures_rule_versions;
BEGIN
 IF NOT sportsbook_private.release_writes_enabled() OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Dev sign-in required'; END IF;
 SELECT * INTO STRICT board FROM public.sportsbook_boards WHERE id=p_board AND board_type='future';
 IF NOT sportsbook_private.is_member(board.league_id) THEN RAISE EXCEPTION 'Approved league mapping required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('boff-dev-futures-rules'), hashtext(board.league_id::text));
 IF EXISTS(SELECT FROM public.tickets t JOIN public.user_wallets w ON w.id=t.user_wallet_id
  WHERE t.request_key=p_request AND t.league_id=board.league_id AND w.user_id=auth.uid()) THEN
  RETURN boff_dev_internal.place_ticket(p_board,p_revision,p_picks,p_stake,p_request);
 END IF;
 SELECT * INTO rule FROM boff_dev_internal.futures_rule_versions WHERE league_id=board.league_id AND season=board.nfl_season ORDER BY revision DESC LIMIT 1;
 IF rule.rules->>'rostersReady' IS DISTINCT FROM 'true' OR NOT EXISTS(
  SELECT FROM boff_dev_internal.futures_board_state WHERE league_id=board.league_id AND season=board.nfl_season AND rules_revision=rule.revision)
 THEN RAISE EXCEPTION 'Futures rules or prices changed. Wait for the refreshed board'; END IF;
 IF EXISTS(SELECT FROM public.sportsbook_markets WHERE board_id=p_board AND id=ANY(p_picks)
   AND ((metadata->>'cutoff')::timestamptz<=clock_timestamp() OR metadata->>'dev_futures' IS DISTINCT FROM 'true'))
 THEN RAISE EXCEPTION 'A futures cutoff has passed'; END IF;
 IF EXISTS(SELECT FROM public.sportsbook_markets WHERE id=ANY(p_picks) GROUP BY metadata->>'ui_group' HAVING count(*)>1)
 THEN RAISE EXCEPTION 'Choose only one outcome per market'; END IF;
 RETURN boff_dev_internal.place_ticket(p_board,p_revision,p_picks,p_stake,p_request);
END $function$
;

REVOKE ALL ON FUNCTION "public"."place_dev_future"(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."place_dev_future"(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION public.place_dev_reward(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid, p_reward uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE b public.sportsbook_boards; a boff_dev_internal.fantasy_reward_awards; placed jsonb; existing uuid;
BEGIN
 IF auth.uid() IS NULL OR NOT sportsbook_private.release_writes_enabled() THEN RAISE EXCEPTION 'Dev sign-in required'; END IF;
 SELECT * INTO STRICT b FROM public.sportsbook_boards WHERE id=p_board;
 IF NOT sportsbook_private.is_member(b.league_id) THEN RAISE EXCEPTION 'League membership required'; END IF;
 IF b.board_type='future' THEN
  PERFORM pg_advisory_xact_lock(hashtext('boff-dev-futures-rules'),hashtext(b.league_id::text));
 END IF;
 SELECT * INTO a FROM boff_dev_internal.fantasy_reward_awards
 WHERE id=p_reward AND league_id=b.league_id AND user_id=auth.uid() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Reward unavailable'; END IF;
 SELECT id INTO existing FROM public.tickets WHERE request_key=p_request;
 IF existing IS NOT NULL THEN
  IF a.ticket_id IS DISTINCT FROM existing THEN RAISE EXCEPTION 'Request already used'; END IF;
  RETURN boff_dev_internal.place_reward_ticket(p_board,p_revision,p_picks,p_stake,p_request,a.percent);
 END IF;
 IF a.ticket_id IS NOT NULL OR a.revoked_at IS NOT NULL OR a.expires_at<=clock_timestamp()
  OR (a.achievement='champion' AND b.nfl_season<>a.season+1)
  OR (a.achievement<>'champion' AND b.nfl_season<>a.season) THEN RAISE EXCEPTION 'Reward unavailable'; END IF;
 IF EXISTS(SELECT FROM public.sportsbook_boards sb JOIN public.sportsbook_markets sm ON sm.board_id=sb.id
  WHERE sb.league_id=b.league_id AND sb.nfl_season=b.nfl_season AND sm.kind='future_champion'
   AND sm.metadata->>'dev_futures'='true' AND sm.metadata->>'resolved'='true') THEN RAISE EXCEPTION 'This season has ended'; END IF;
 IF b.board_type='weekly' AND NOT EXISTS(SELECT FROM public.dev_current_book WHERE board_id=b.id AND valid_until>clock_timestamp() AND last_error IS NULL FOR SHARE)
 THEN RAISE EXCEPTION 'Prices expired'; END IF;
 IF b.board_type='future' AND NOT EXISTS(
  SELECT FROM boff_dev_internal.futures_board_state s
  JOIN LATERAL (SELECT revision,rules FROM boff_dev_internal.futures_rule_versions v WHERE v.league_id=s.league_id AND v.season=s.season ORDER BY revision DESC LIMIT 1) r ON true
  WHERE s.league_id=b.league_id AND s.season=b.nfl_season AND r.revision=s.rules_revision AND r.rules->>'rostersReady'='true'
 ) THEN RAISE EXCEPTION 'Futures prices changed'; END IF;
 IF EXISTS(SELECT FROM public.sportsbook_markets WHERE id=ANY(p_picks)
  AND (boost_pct>0 OR (b.board_type='future' AND ((metadata->>'cutoff')::timestamptz<=clock_timestamp() OR metadata->>'dev_futures' IS DISTINCT FROM 'true'))))
 THEN RAISE EXCEPTION 'Rewards require open selections without an existing boost'; END IF;
 IF EXISTS(SELECT FROM public.sportsbook_markets WHERE id=ANY(p_picks) GROUP BY metadata->>'ui_group' HAVING count(*)>1)
 THEN RAISE EXCEPTION 'Choose only one outcome per market'; END IF;
 placed:=boff_dev_internal.place_reward_ticket(p_board,p_revision,p_picks,p_stake,p_request,a.percent);
 IF (placed->>'duplicate')::boolean THEN RAISE EXCEPTION 'Request already used'; END IF;
 UPDATE boff_dev_internal.fantasy_reward_awards SET ticket_id=(placed->>'ticket_id')::uuid WHERE id=a.id;
 RETURN placed;
END $function$
;

REVOKE ALL ON FUNCTION "public"."place_dev_reward"(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid, p_reward uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."place_dev_reward"(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid, p_reward uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION public.place_dev_ticket(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE l uuid;BEGIN PERFORM pg_advisory_xact_lock_shared(20261101,17);
 IF NOT sportsbook_private.release_writes_enabled() OR auth.uid() IS NULL THEN RAISE EXCEPTION 'Dev sign-in required';END IF;
 SELECT league_id INTO l FROM public.sportsbook_boards WHERE id=p_board;
 IF NOT sportsbook_private.is_member(l) THEN RAISE EXCEPTION 'Approved league mapping required';END IF;
 PERFORM 1 FROM public.dev_current_book WHERE league_id=l AND board_id=p_board AND valid_until>clock_timestamp() AND last_error IS NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Prices expired. Wait for a successful source refresh';END IF;
 IF EXISTS(SELECT 1 FROM public.sportsbook_markets WHERE id=ANY(p_picks) GROUP BY metadata->>'ui_group' HAVING count(*)>1) THEN RAISE EXCEPTION 'Choose only one outcome per market';END IF;
 RETURN boff_dev_internal.place_ticket(p_board,p_revision,p_picks,p_stake,p_request);
END $function$
;

REVOKE ALL ON FUNCTION "public"."place_dev_ticket"(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."place_dev_ticket"(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION public.place_dev_weekly_offer(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid, p_slot text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE b public.sportsbook_boards; promo jsonb; c boff_dev_internal.weekly_offer_claims; placed jsonb; existing uuid;
BEGIN
 SELECT * INTO STRICT b FROM public.sportsbook_boards WHERE id=p_board AND board_type='weekly';
 IF auth.uid() IS NULL OR NOT sportsbook_private.is_member(b.league_id) THEN RAISE EXCEPTION 'League membership required'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('dev-current-book'),hashtext(b.league_id::text));
 PERFORM 1 FROM public.dev_current_book WHERE board_id=b.id FOR SHARE;
 SELECT * INTO b FROM public.sportsbook_boards WHERE id=p_board FOR SHARE;
 SELECT id INTO existing FROM public.tickets WHERE request_key=p_request;
 IF existing IS NOT NULL THEN
  SELECT * INTO c FROM boff_dev_internal.weekly_offer_claims WHERE ticket_id=existing AND user_id=auth.uid() AND slot=p_slot;
  IF NOT FOUND THEN RAISE EXCEPTION 'Request already used'; END IF;
  RETURN boff_dev_internal.place_reward_ticket(p_board,p_revision,p_picks,p_stake,p_request,c.percent);
 END IF;

 IF EXISTS(SELECT FROM public.sportsbook_markets WHERE board_id=b.id AND id=ANY(p_picks) AND odds < -1000)
 THEN RAISE EXCEPTION 'Weekly offers require each pick to have odds of -1000 or longer'; END IF;
 SELECT value INTO promo FROM jsonb_array_elements(boff_dev_internal.weekly_offer_options(b.id))
  WHERE value->>'slot'=p_slot;
 IF promo IS NULL THEN RAISE EXCEPTION 'Offer unavailable or expired'; END IF;
 IF p_slot<>'duels' THEN
  IF ARRAY(SELECT (value->>'id')::uuid FROM jsonb_array_elements(promo->'picks') ORDER BY 1)
   IS DISTINCT FROM ARRAY(SELECT unnest(p_picks) ORDER BY 1) THEN RAISE EXCEPTION 'Offer selections changed. Reload the offer'; END IF;
  INSERT INTO boff_dev_internal.weekly_offer_claims VALUES(b.league_id,b.nfl_season,b.market_week,p_slot,auth.uid(),NULL,(promo->>'percent')::numeric)
  ON CONFLICT DO NOTHING;
 ELSIF cardinality(p_picks)<4 OR EXISTS(SELECT FROM public.sportsbook_markets m WHERE m.id=ANY(p_picks)
  AND (m.kind<>'player_h2h' OR m.boost_pct>0 OR m.metadata->>'lineup_locked'='true' OR m.metadata->>'live' IS DISTINCT FROM 'false'
    OR COALESCE((m.metadata->>'cutoff')::timestamptz,'-infinity')<=clock_timestamp()))
  OR (SELECT count(DISTINCT matchup_key) FROM public.sportsbook_markets WHERE id=ANY(p_picks))<>cardinality(p_picks)
 THEN RAISE EXCEPTION 'Choose at least four unboosted pre-game Player Head-to-Head picks from different matchups'; END IF;
 SELECT * INTO c FROM boff_dev_internal.weekly_offer_claims
 WHERE (league_id,season,week,slot,user_id)=(b.league_id,b.nfl_season,b.market_week,p_slot,auth.uid()) FOR UPDATE;
 IF NOT FOUND OR c.ticket_id IS NOT NULL THEN RAISE EXCEPTION 'Offer must be claimed and unused'; END IF;
 placed:=boff_dev_internal.place_reward_ticket(p_board,p_revision,p_picks,p_stake,p_request,c.percent);
 IF (placed->>'duplicate')::boolean THEN RAISE EXCEPTION 'Request already used'; END IF;
 UPDATE boff_dev_internal.weekly_offer_claims SET ticket_id=(placed->>'ticket_id')::uuid
 WHERE (league_id,season,week,slot,user_id)=(c.league_id,c.season,c.week,c.slot,c.user_id);
 RETURN placed;
END $function$
;

REVOKE ALL ON FUNCTION "public"."place_dev_weekly_offer"(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid, p_slot text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."place_dev_weekly_offer"(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid, p_slot text) TO "authenticated";

