CREATE OR REPLACE FUNCTION public.place_sportsbook_ticket(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin perform pg_advisory_xact_lock_shared(20261101,17);
 if sportsbook_private.user_finance_enabled((select league_id from public.sportsbook_boards where id=p_board)) then return sportsbook_private.user_place_sportsbook_ticket(p_board,p_revision,p_picks,p_stake,p_request);end if;
 return sportsbook_private.legacy_place_sportsbook_ticket(p_board,p_revision,p_picks,p_stake,p_request);
end $function$
;

REVOKE ALL ON FUNCTION "public"."place_sportsbook_ticket"(p_board uuid, p_revision integer, p_picks uuid[], p_stake numeric, p_request uuid) FROM PUBLIC,anon,authenticated,service_role;

