CREATE OR REPLACE FUNCTION public.prepare_user_finance_cutover(p_league uuid, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare review jsonb;v_id uuid:=gen_random_uuid();v_time timestamptz:=clock_timestamp();begin
 perform pg_advisory_xact_lock(20261101,17);
 review:=public.user_finance_cutover_preflight(p_league);
 if p_reason is null or length(trim(p_reason)) not between 8 and 400 then raise exception 'Record the financial review reason (8-400 characters).';end if;
 if (review->>'routing_enabled')::boolean then raise exception 'Independent wallets are already active.';end if;
 if (review->>'ready')::boolean is distinct from true then raise exception 'Resolve the cutover blockers before preparing approval.';end if;
 if (select count(*) from public.admin_change_log where league_id=p_league and category='user_finance_cutover_review')>=64
 then raise exception 'Cutover review admission budget reached; owner maintenance review required.';end if;
 insert into public.admin_change_log(id,league_id,actor_id,category,reason,before_value,after_value,created_at)
 values(v_id,p_league,auth.uid(),'user_finance_cutover_review',trim(p_reason),review,
  jsonb_build_object('expires_at',v_time+interval '5 minutes'),v_time);
 return review||jsonb_build_object('review_id',v_id,'expires_at',v_time+interval '5 minutes');
end $function$
;

REVOKE ALL ON FUNCTION "public"."prepare_user_finance_cutover"(p_league uuid, p_reason text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."prepare_user_finance_cutover"(p_league uuid, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.promo_usage(p_league uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not sportsbook_private.is_admin(p_league) then raise exception 'League admin required.';end if;
 return coalesce((select jsonb_agg(jsonb_build_object('offer_id',o.id,
 'claims',(select count(*) from public.promo_claims c where c.offer_id=o.id),
 'redemptions',(select count(*) from public.ticket_promotions p where p.offer_id=o.id),
 'extra_paid',coalesce((select sum(round((t.actual_payout-t.stake)*p.boost_pct/(100+p.boost_pct),2)) from public.ticket_promotions p join public.tickets t on t.id=p.ticket_id where p.offer_id=o.id and p.kind='boost' and t.status='WON'),0),
 'extra_liability',coalesce((select sum(t.accepted_potential_payout-round(t.stake*p.base_decimal,2)) from public.ticket_promotions p join public.tickets t on t.id=p.ticket_id where p.offer_id=o.id and p.kind='boost' and t.status='OPEN'),0))) from public.promo_offers o where o.league_id=p_league),'[]');
end $function$
;

REVOKE ALL ON FUNCTION "public"."promo_usage"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."promo_usage"(p_league uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION public.provider_capability_review(p_league uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s sportsbook_private.provider_capability_state;valid boolean;begin
 if not public.league_intake_owner()then raise exception 'Verified platform owner required.';end if;
 select * into s from sportsbook_private.provider_capability_state where league_id=p_league;
 if not found then return jsonb_build_object('league_id',p_league,'state','observation_required');end if;
 valid:=s.approved_hash=s.observed_hash and s.observed_at>now()-interval '24 hours'and s.observed_hash=encode(sha256(convert_to(jsonb_build_object('source',sportsbook_private.capability_source(s.source),'rosters',s.rosters,'configuration',sportsbook_private.provider_configuration_hash(p_league),'build',s.build_sha)::text,'UTF8')),'hex')and(s.source->>'season')::integer=(select nfl_season from public.leagues where id=p_league);
 return jsonb_build_object('league_id',p_league,'state',case when coalesce(valid,false)then 'owner_reviewed'else 'review_required'end,'review_hash',s.observed_hash,'build_sha',s.build_sha,'observed_at',s.observed_at,'revision',s.revision,'season',s.source->'season',
 'current_season',(select nfl_season from public.leagues where id=p_league),'approval_current',coalesce(valid,false));
end $function$
;

REVOKE ALL ON FUNCTION "public"."provider_capability_review"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."provider_capability_review"(p_league uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION public.publish_dev_book(p_league uuid, p_book jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE b public.sportsbook_boards;old public.dev_current_book;q jsonb;m public.sportsbook_markets;ident uuid;ids uuid[]:='{}';h text;rev integer;deadline timestamptz; policy_revision text; changed uuid[]:='{}'; removed uuid[]:='{}'; updated_book public.dev_current_book; updated_board public.sportsbook_boards;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR NOT sportsbook_private.release_environment_ready()
 OR NOT EXISTS(SELECT 1 FROM public.leagues WHERE id=p_league AND sleeper_league_id='1312126153980391424') THEN RAISE EXCEPTION 'Dev publisher only';END IF;
 PERFORM pg_advisory_xact_lock(hashtext('dev-current-book'),hashtext(p_league::text));
 IF (p_book->>'observed_at')::timestamptz<clock_timestamp()-interval '3 minutes' OR (p_book->>'observed_at')::timestamptz>clock_timestamp()+interval '30 seconds'
 OR jsonb_array_length(p_book->'quotes') NOT BETWEEN 36 AND 3000 OR octet_length((p_book->'payload')::text)>262144 THEN RAISE EXCEPTION 'Invalid current book';END IF;
 deadline:=(p_book->>'valid_until')::timestamptz;
 IF nullif(p_book->>'closes_at','') IS NULL OR (p_book->>'closes_at')::timestamptz<=clock_timestamp() OR (p_book->>'closes_at')::timestamptz>clock_timestamp()+interval '10 days' THEN RAISE EXCEPTION 'Invalid weekly board window';END IF;
 IF deadline<=clock_timestamp() OR deadline>clock_timestamp()+interval '70 minutes' THEN RAISE EXCEPTION 'Invalid quote freshness';END IF;
 SELECT * INTO old FROM public.dev_current_book WHERE league_id=p_league;
 IF old.observed_at>(p_book->>'observed_at')::timestamptz THEN RETURN jsonb_build_object('skipped','older_observation');END IF;
 SELECT * INTO b FROM public.sportsbook_boards WHERE league_id=p_league AND nfl_season=(p_book->>'season')::integer AND market_week=(p_book->>'week')::integer AND board_type='weekly' FOR UPDATE;
 IF NOT FOUND THEN
  INSERT INTO public.sportsbook_boards(league_id,nfl_season,league_season,market_week,opens_at,closes_at,status)
  SELECT p_league,(p_book->>'season')::integer,league_season,(p_book->>'week')::integer,clock_timestamp(),(p_book->>'closes_at')::timestamptz,'draft' FROM public.leagues WHERE id=p_league RETURNING * INTO b;
 END IF;
 p_book:=jsonb_set(p_book,'{quotes}',boff_dev_internal.apply_feature_settings(p_league,(p_book->>'season')::integer,
  p_book->'quotes', p_book->'payload'->'teams', (p_book->>'week')::integer,
  (p_book->'payload'->>'regularSeasonWeeks')::integer,
  (sportsbook_private.sportsbook_policy(p_league,(p_book->>'season')::integer,(p_book->>'week')::integer)
   ->'values'->>'featured_boost_pct')::integer,
  (SELECT (cache.payload->'metadata'->'settings'->>'playoffTeams')::integer
   FROM public.dev_live_cache cache
   JOIN public.leagues league ON league.id=p_league
   WHERE cache.key='league:'||league.sleeper_league_id
    AND cache.payload->'metadata'->>'season'=p_book->>'season')
 ));
 p_book:=boff_dev_internal.keep_weekly_features(p_book,old.payload,b.id); h:=md5((p_book->'quotes')::text);rev:=b.revision+CASE WHEN old.source_hash IS DISTINCT FROM h THEN 1 ELSE 0 END;
 policy_revision:=sportsbook_private.sportsbook_policy(p_league,(p_book->>'season')::integer,(p_book->>'week')::integer)->>'revision';
 IF old.board_id=b.id AND old.source_hash=h AND b.status='published' AND b.phase=(CASE WHEN (p_book->'payload'->>'gamesActive')::boolean THEN 'live' ELSE 'pregame' END)
 AND NOT EXISTS(SELECT 1 FROM public.sportsbook_markets m0 WHERE m0.board_id=b.id AND m0.active
   AND coalesce(m0.metadata->>'sportsbook_policy_revision','0') IS DISTINCT FROM policy_revision) THEN
  UPDATE public.sportsbook_boards SET source_observed_at=(p_book->>'observed_at')::timestamptz,quote_valid_until=deadline,closes_at=(p_book->>'closes_at')::timestamptz,opens_at=LEAST(opens_at,clock_timestamp()),suspension_reason=NULL WHERE id=b.id;
  UPDATE public.dev_current_book SET payload=CASE WHEN payload=p_book->'payload' THEN payload ELSE p_book->'payload' END, observed_at=(p_book->>'observed_at')::timestamptz,valid_until=deadline,last_error=NULL WHERE league_id=p_league;
 
 SELECT * INTO updated_book FROM public.dev_current_book WHERE league_id=p_league;
 SELECT * INTO updated_board FROM public.sportsbook_boards WHERE id=b.id;
 PERFORM boff_dev_internal.save_weekly_delta(old,b,updated_book,updated_board,changed,removed);
 RETURN jsonb_build_object('board_id'
 ,b.id,'revision',rev,'quotes',jsonb_array_length(p_book->'quotes'));
 END IF;
 UPDATE public.sportsbook_boards SET status='draft',revision=rev,source_observed_at=(p_book->>'observed_at')::timestamptz,quote_valid_until=deadline,closes_at=(p_book->>'closes_at')::timestamptz,opens_at=LEAST(opens_at,clock_timestamp()),suspension_reason=NULL WHERE id=b.id;
 FOR q IN SELECT value FROM jsonb_array_elements(p_book->'quotes') LOOP
  IF NOT(q->>'kind'=ANY(ARRAY['spread','moneyline','match_total','team_total','player_points','player_h2h','position_group','player_milestone','team_milestone','winning_margin','weekly_high','weekly_low','weekly_any_below_100','weekly_any_200','weekly_average','weekly_highest_score','weekly_count_150','weekly_count_projection'])) THEN RAISE EXCEPTION 'Unsupported dev market';END IF;
  IF q->>'kind' IN ('spread','match_total','team_total','player_points') AND abs(mod((q->>'line')::numeric,1))<>.5 THEN RAISE EXCEPTION 'Half-point line required';END IF;
  q:=q||jsonb_build_object('metadata',coalesce(q->'metadata','{}')||jsonb_build_object('ui_id',q->>'ui_id','ui_group',q->>'ui_group','quote_key',coalesce(q->>'variant_key',q->>'ui_group')||':'||(q->>'side'),'sportsbook_policy_revision',policy_revision));
  SELECT * INTO m FROM public.sportsbook_markets WHERE board_id=b.id AND active AND coalesce(metadata->>'quote_key',metadata->>'ui_id')=coalesce(q->'metadata'->>'quote_key',q->>'ui_id') LIMIT 1;
  ident:=m.id;
  IF ident IS NOT NULL AND EXISTS(SELECT 1 FROM public.ticket_legs WHERE market_quote_id=ident)
   AND (m.odds IS DISTINCT FROM (q->>'odds')::integer OR m.line IS DISTINCT FROM (q->>'line')::numeric OR m.metadata IS DISTINCT FROM q->'metadata'
    OR m.boost_pct IS DISTINCT FROM (q->>'boost_pct')::integer
    OR m.featured IS DISTINCT FROM q->>'featured') THEN
   removed:=array_append(removed,ident); UPDATE public.sportsbook_markets SET active=false WHERE id=ident;ident:=NULL;
  END IF;
  IF ident IS NULL THEN
   ident:=gen_random_uuid(); changed:=array_append(changed,ident);
   INSERT INTO public.sportsbook_markets(id,board_id,market_key,matchup_key,kind,label,subject,side,line,odds,boost_pct,featured,team_id,home_team_id,away_team_id,home_projection,away_projection,metadata,active)
   VALUES(ident,b.id,coalesce(q->>'variant_key',q->>'ui_group')||':'||rev,q->>'matchup_key',q->>'kind',q->>'label',q->>'subject',q->>'side',(q->>'line')::numeric,(q->>'odds')::integer,(q->>'boost_pct')::integer,q->>'featured',(q->>'team_id')::uuid,(q->>'home_team_id')::uuid,(q->>'away_team_id')::uuid,(q->>'home_projection')::numeric,(q->>'away_projection')::numeric,q->'metadata',true);
  ELSIF ROW(m.line,m.odds,m.label,m.subject,m.home_projection,m.away_projection,m.metadata,m.boost_pct,m.featured,m.market_state::text) IS DISTINCT FROM ROW((q->>'line')::numeric,(q->>'odds')::integer,q->>'label',q->>'subject',(q->>'home_projection')::numeric,(q->>'away_projection')::numeric,q->'metadata',(q->>'boost_pct')::integer,q->>'featured','open'::text) THEN
   changed:=array_append(changed,ident);
   UPDATE public.sportsbook_markets SET line=(q->>'line')::numeric,odds=(q->>'odds')::integer,boost_pct=(q->>'boost_pct')::integer,featured=q->>'featured',label=q->>'label',subject=q->>'subject',home_projection=(q->>'home_projection')::numeric,away_projection=(q->>'away_projection')::numeric,metadata=q->'metadata',active=true,market_state='open' WHERE id=ident;
  END IF;
  ids:=array_append(ids,ident);
 END LOOP;

 WITH closed AS (UPDATE public.sportsbook_markets SET active=false WHERE board_id=b.id AND active AND NOT(id=ANY(ids)) RETURNING id)
 SELECT removed||coalesce(array_agg(id),'{}') INTO removed FROM closed;
 
 DELETE FROM public.sportsbook_markets obsolete WHERE obsolete.board_id=b.id AND NOT obsolete.active AND NOT EXISTS(SELECT 1 FROM public.ticket_legs WHERE market_quote_id=obsolete.id)
 AND NOT EXISTS(SELECT 1 FROM public.promo_offers o WHERE to_jsonb(o)::text LIKE '%'||obsolete.id::text||'%');
 UPDATE public.sportsbook_boards SET status='published',phase=CASE WHEN (p_book->'payload'->>'gamesActive')::boolean THEN 'live' ELSE 'pregame' END WHERE id=b.id;
 IF nullif(p_book->'payload'->>'firstGame','')::timestamptz > clock_timestamp() THEN
  PERFORM sportsbook_private.capture_forecast(b.id);
 END IF;
 UPDATE public.sportsbook_boards SET status='closed' WHERE league_id=p_league AND board_type='weekly' AND id<>b.id AND closes_at<=clock_timestamp() AND status<>'closed';
 UPDATE public.sportsbook_markets m0 SET active=false FROM public.sportsbook_boards b0 WHERE m0.board_id=b0.id AND b0.league_id=p_league AND b0.board_type='weekly' AND b0.status='closed' AND m0.active;
 INSERT INTO public.dev_current_book(league_id,board_id,payload,source_hash,observed_at,valid_until)
 VALUES(p_league,b.id,p_book->'payload',h,(p_book->>'observed_at')::timestamptz,deadline)
 ON CONFLICT(league_id) DO UPDATE SET board_id=excluded.board_id,payload=excluded.payload,source_hash=excluded.source_hash,observed_at=excluded.observed_at,valid_until=excluded.valid_until,last_error=NULL;

 SELECT * INTO updated_book FROM public.dev_current_book WHERE league_id=p_league;
 SELECT * INTO updated_board FROM public.sportsbook_boards WHERE id=b.id;
 PERFORM boff_dev_internal.save_weekly_delta(old,b,updated_book,updated_board,changed,removed);
 RETURN jsonb_build_object('board_id'
 ,b.id,'revision',rev,'quotes',cardinality(ids));
END $function$
;

REVOKE ALL ON FUNCTION "public"."publish_dev_book"(p_league uuid, p_book jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."publish_dev_book"(p_league uuid, p_book jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION public.publish_dev_futures(p_league uuid, p_season integer, p_revision integer, p_quotes jsonb, p_settlements jsonb, p_complete boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
 league public.leagues;
 board public.sportsbook_boards;
 saved boff_dev_internal.futures_rule_versions;
 prior boff_dev_internal.futures_board_state;
 quote jsonb;
 ticket record;
 owner_id uuid;
 hash text;
 deadline timestamptz;
 board_status text;
 next_revision integer;
BEGIN
 IF auth.role() IS DISTINCT FROM 'service_role' OR NOT sportsbook_private.release_writes_enabled() THEN RAISE EXCEPTION 'Dev worker only'; END IF;
 IF jsonb_typeof(p_quotes) IS DISTINCT FROM 'array' OR jsonb_array_length(p_quotes)>320
   OR jsonb_typeof(p_settlements) IS DISTINCT FROM 'array' OR jsonb_array_length(p_settlements)>200 THEN RAISE EXCEPTION 'Invalid futures update'; END IF;
 PERFORM pg_advisory_xact_lock(hashtext('boff-dev-futures-rules'), hashtext(p_league::text));
 SELECT * INTO STRICT league FROM public.leagues WHERE id=p_league AND nfl_season=p_season;
 SELECT * INTO saved FROM boff_dev_internal.futures_rule_versions WHERE league_id=p_league AND season=p_season ORDER BY revision DESC LIMIT 1;
 IF p_revision IS DISTINCT FROM COALESCE(saved.revision,0) THEN RAISE EXCEPTION 'Futures rules changed'; END IF;
 SELECT * INTO board FROM public.sportsbook_boards WHERE league_id=p_league AND nfl_season=p_season AND board_type='future' FOR UPDATE;
 SELECT * INTO prior FROM boff_dev_internal.futures_board_state WHERE league_id=p_league AND season=p_season;
 IF EXISTS(SELECT FROM jsonb_array_elements(p_quotes) q WHERE q->>'kind' NOT IN ('future_champion','future_playoffs','future_first_pick','future_win_total','future_first_clinch','future_first_elimination')
   OR q->'metadata'->>'quote_key' IS NULL OR q->'metadata'->>'ui_group' IS NULL OR q->'metadata'->>'cutoff' IS NULL
   OR (q->>'kind' NOT IN ('future_first_clinch','future_first_elimination') AND NOT EXISTS(
     SELECT FROM public.teams t WHERE t.league_id=p_league AND t.id=(q->>'team_id')::uuid AND t.roster_id=(q->'metadata'->>'roster_id')::int)))
 THEN RAISE EXCEPTION 'Invalid futures quote'; END IF;
 SELECT max((q->'metadata'->>'cutoff')::timestamptz) INTO deadline FROM jsonb_array_elements(p_quotes) q;
 board_status:=CASE WHEN p_complete THEN 'closed'
  WHEN saved.rules->>'rostersReady'='true' AND deadline>clock_timestamp() THEN 'published' ELSE 'draft' END;
 hash:=md5(p_quotes::text||':'||p_revision||':'||board_status);
 IF board.id IS NULL AND deadline IS NOT NULL THEN
  INSERT INTO public.sportsbook_boards(league_id,nfl_season,league_season,market_week,board_type,opens_at,closes_at)
  VALUES(p_league,p_season,league.league_season,1,'future',LEAST(clock_timestamp(),deadline-interval '1 second'),deadline) RETURNING * INTO board;
 END IF;
 IF board.id IS NOT NULL AND deadline IS NOT NULL THEN
  next_revision:=board.revision+CASE WHEN prior.source_hash IS DISTINCT FROM hash THEN 1 ELSE 0 END;
  IF prior.source_hash IS DISTINCT FROM hash THEN
   UPDATE public.sportsbook_markets SET active=false,market_state='closed' WHERE board_id=board.id AND active;
   DELETE FROM public.sportsbook_markets m WHERE m.board_id=board.id AND m.metadata->>'dev_futures'='true'
    AND NOT EXISTS(SELECT FROM public.ticket_legs WHERE market_quote_id=m.id);
   FOR quote IN SELECT value FROM jsonb_array_elements(p_quotes) LOOP
    INSERT INTO public.sportsbook_markets(id,board_id,market_key,kind,label,subject,side,line,odds,team_id,metadata,active,market_state)
    VALUES(gen_random_uuid(),board.id,(quote->'metadata'->>'ui_group')||':'||next_revision,quote->>'kind',quote->>'label',quote->>'subject',quote->>'side',
     (quote->>'line')::numeric,(quote->>'odds')::integer,(quote->>'team_id')::uuid,
     quote->'metadata'||jsonb_build_object('dev_futures',true,'revision',next_revision,'resolved',quote->'metadata'->>'result' IS NOT NULL,
     'sportsbook_policy_revision',sportsbook_private.sportsbook_policy(p_league,p_season,board.market_week)->>'revision'),
     board_status='published' AND quote->'metadata'->>'result' IS NULL AND quote->'metadata'->>'close_reason' IS NULL AND (quote->'metadata'->>'cutoff')::timestamptz>clock_timestamp(),
     CASE WHEN quote->'metadata'->>'result' IS NOT NULL OR quote->'metadata'->>'close_reason' IS NOT NULL THEN 'closed' ELSE 'open' END);
   END LOOP;
  END IF;
  UPDATE public.sportsbook_boards SET status=board_status,revision=next_revision,
   closes_at=GREATEST(deadline,opens_at+interval '1 second'),source_observed_at=clock_timestamp(),quote_valid_until=clock_timestamp()+interval '75 minutes',suspension_reason=NULL
  WHERE id=board.id;
  INSERT INTO boff_dev_internal.futures_board_state VALUES(p_league,p_season,p_revision,hash)
   ON CONFLICT (league_id,season) DO UPDATE SET source_hash=excluded.source_hash,rules_revision=excluded.rules_revision;
 END IF;
 IF jsonb_array_length(p_settlements)=0 AND saved.rules->>'firstPick' IS DISTINCT FROM 'disabled' THEN RETURN; END IF;
 SELECT m.user_id INTO STRICT owner_id FROM sportsbook_private.platform_owner p JOIN public.league_memberships m ON m.id=p.membership_id;
 PERFORM set_config('request.jwt.claim.sub',owner_id::text,true);
 FOR ticket IN SELECT t.id,work.value->'legs' AS legs,
  saved.rules->>'firstPick'='disabled' AND EXISTS(SELECT FROM public.ticket_legs l
    WHERE l.ticket_id=t.id AND l.settlement_context->>'kind'='future_first_pick') AS removed
  FROM public.tickets t LEFT JOIN LATERAL (SELECT value FROM jsonb_array_elements(p_settlements)
    WHERE value->>'id'=t.id::text) work ON true
  WHERE t.league_id=p_league AND t.nfl_season=p_season AND t.ticket_type='future' AND t.status='OPEN'
    AND (t.user_wallet_id IS NOT NULL OR work.value IS NOT NULL OR prior.rules_revision>0)
    AND (work.value IS NOT NULL OR saved.rules->>'firstPick'='disabled')
  ORDER BY t.id
 LOOP
  IF ticket.removed THEN
   PERFORM public.void_sportsbook_ticket(ticket.id,'Commissioner removed the #1 Pick market');
  ELSIF ticket.legs IS NOT NULL THEN
   PERFORM public.settle_weekly_ticket(ticket.id,ticket.legs);
  END IF;
 END LOOP;
END $function$
;

REVOKE ALL ON FUNCTION "public"."publish_dev_futures"(p_league uuid, p_season integer, p_revision integer, p_quotes jsonb, p_settlements jsonb, p_complete boolean) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."publish_dev_futures"(p_league uuid, p_season integer, p_revision integer, p_quotes jsonb, p_settlements jsonb, p_complete boolean) TO "service_role";

CREATE OR REPLACE FUNCTION public.publish_opening_editorial(p_league uuid, p_document jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare f jsonb:=p_document->'facts';s jsonb;x jsonb;c jsonb;b public.sportsbook_boards;l public.leagues;e sportsbook_private.opening_editorial_editions;
 previous jsonb;scope_ids text[];begin
 if auth.role() is distinct from 'service_role' then raise exception 'Editorial worker only.';end if;
 if p_document->>'contract' is distinct from 'opening-editorial-edition-v1' or f->>'contract' is distinct from 'opening-editorial-facts-v1'
  or jsonb_typeof(f) is distinct from 'object' or jsonb_typeof(f->'prepared_at') is distinct from 'string' or not(f ?& array['contract','league_id','nfl_season','league_season','market_week','board_id','board_revision','window_key','prepared_at','team_ids','teams','matchups','championship']) or f->>'league_id' is distinct from p_league::text or octet_length(p_document::text)>65536
  or exists(select 1 from jsonb_object_keys(p_document)k where k not in('contract','facts','stories'))
  or exists(select 1 from jsonb_object_keys(f)k where k not in('contract','league_id','nfl_season','league_season','market_week','board_id','board_revision','window_key','prepared_at','team_ids','teams','matchups','championship'))
 then raise exception 'Invalid bounded editorial document.';end if;
 if exists(select 1 from unnest(array['team_ids','teams','matchups','championship'])k where jsonb_typeof(f->k) is distinct from 'array')
  or jsonb_array_length(f->'team_ids')>128 or jsonb_array_length(f->'teams')>128 or jsonb_array_length(f->'matchups')>64 or jsonb_array_length(f->'championship')>16
  or jsonb_typeof(p_document->'stories') is distinct from 'array' or jsonb_array_length(p_document->'stories')>3
 then raise exception 'Editorial segment budget exceeded.';end if;
 perform pg_advisory_xact_lock(hashtextextended('opening-editorial:'||p_league,0));
 select * into l from public.leagues where id=p_league;
 select * into b from public.sportsbook_boards where id=(f->>'board_id')::uuid and league_id=p_league for share;
 if not found or f->>'nfl_season' is distinct from l.nfl_season::text or f->>'league_season' is distinct from l.league_season::text
  or f->>'board_revision' is distinct from b.revision::text or (f->>'prepared_at')::timestamptz<now()-interval '5 minutes' or (f->>'prepared_at')::timestamptz>now()+interval '30 seconds'
 then raise exception 'Editorial source revision or preparation time changed.';end if;
 c:=public.notification_window(p_league,l.nfl_season,(f->>'market_week')::integer,'opening');
 if c->>'eligible' is distinct from 'true' or c->>'window_key' is distinct from f->>'window_key' or c->>'board_id' is distinct from b.id::text then raise exception 'Opening window changed before editorial publication.';end if;
 select coalesce(array_agg(id::text order by id),'{}') into scope_ids from public.teams where league_id=p_league;
 if jsonb_array_length(f->'team_ids')<>cardinality(scope_ids) or exists(select 1 from jsonb_array_elements_text(f->'team_ids')t where t<>all(scope_ids))
  or (select count(distinct t) from jsonb_array_elements_text(f->'team_ids')t)<>cardinality(scope_ids) then raise exception 'Editorial team field changed.';end if;
 for x in select value from jsonb_array_elements(f->'teams') loop
  if coalesce(x->>'id','')<>all(scope_ids) or jsonb_typeof(x->'name') is distinct from 'string' or octet_length(x->>'name')>160 or jsonb_typeof(x->'projected') is distinct from 'number' or (x->>'projected')::numeric<=0 or (x->>'projected')::numeric>1000
   or not exists(select 1 from public.sportsbook_markets q where q.board_id=b.id and q.active and q.kind='spread' and ((q.home_team_id::text=x->>'id' and abs(q.home_projection-(x->>'projected')::numeric)<.000001)or(q.away_team_id::text=x->>'id' and abs(q.away_projection-(x->>'projected')::numeric)<.000001)))
   or exists(select 1 from jsonb_object_keys(x)k where k not in('id','name','projected')) then raise exception 'Invalid team forecast evidence.';end if;
 end loop;
 for x in select value from jsonb_array_elements(f->'matchups') loop
  if jsonb_typeof(x->'id') is distinct from 'string' or length(x->>'id')>160 or coalesce(x->>'home','')<>all(scope_ids) or coalesce(x->>'away','')<>all(scope_ids) or x->>'home'=x->>'away'
   or jsonb_typeof(x->'home_projected') is distinct from 'number' or jsonb_typeof(x->'away_projected') is distinct from 'number'
   or (x->>'home_projected')::numeric not between .000001 and 1000 or (x->>'away_projected')::numeric not between .000001 and 1000
   or coalesce(x->>'featured','') not in('','Game of the Week','Tank Bowl')
   or not exists(select 1 from public.sportsbook_markets q where q.board_id=b.id and q.active and q.kind='spread' and q.matchup_key=x->>'id' and q.home_team_id::text=x->>'home' and q.away_team_id::text=x->>'away' and abs(q.home_projection-(x->>'home_projected')::numeric)<.000001 and abs(q.away_projection-(x->>'away_projected')::numeric)<.000001 and (x->>'featured' is null or q.featured=x->>'featured'))
   or exists(select 1 from jsonb_object_keys(x)k where k not in('id','home','away','home_projected','away_projected','featured'))
  then raise exception 'Invalid paired forecast evidence.';end if;
 end loop;
 for x in select value from jsonb_array_elements(f->'championship') loop
  if coalesce(x->>'id','')<>all(scope_ids) or jsonb_typeof(x->'team') is distinct from 'string' or jsonb_typeof(x->'owner') is distinct from 'string'
   or octet_length(x->>'team')>160 or octet_length(x->>'owner')>80 or jsonb_typeof(x->'odds') is distinct from 'number'
   or (x->>'odds')::numeric=0 or abs((x->>'odds')::numeric)>1000000 or (x->>'odds')::numeric<>trunc((x->>'odds')::numeric)
   or not exists(select 1 from public.sportsbook_markets q join public.sportsbook_boards z on z.id=q.board_id where z.league_id=p_league and z.nfl_season=l.nfl_season and z.board_type='future' and z.status='published' and z.opens_at<=now() and z.closes_at>now() and q.active and q.kind='future_champion' and q.team_id::text=x->>'id' and q.odds=(x->>'odds')::integer)
   or exists(select 1 from jsonb_object_keys(x)k where k not in('id','team','owner','odds')) then raise exception 'Invalid saved championship evidence.';end if;
 end loop;
 if (select count(distinct elem.value->>'id') from jsonb_array_elements(f->'teams')as elem(value))<>jsonb_array_length(f->'teams')
  or (select count(distinct elem.value->>'id') from jsonb_array_elements(f->'matchups')as elem(value))<>jsonb_array_length(f->'matchups')
  or (select count(distinct elem.value->>'id') from jsonb_array_elements(f->'championship')as elem(value))<>jsonb_array_length(f->'championship') then raise exception 'Editorial evidence identities must be unique.';end if;
 for s in select value from jsonb_array_elements(p_document->'stories') loop
  if jsonb_typeof(s->'key') is distinct from 'string' or length(s->>'key')>80 or jsonb_typeof(s->'group') is distinct from 'string' or length(s->>'group')>40
   or jsonb_typeof(s->'title') is distinct from 'string' or octet_length(s->>'title')>160 or jsonb_typeof(s->'text') is distinct from 'string' or octet_length(s->>'text')>4096
   or jsonb_typeof(s->'evidence') is distinct from 'array' or jsonb_array_length(s->'evidence')>8
   or exists(select 1 from jsonb_array_elements_text(s->'evidence')t where t<>all(scope_ids))
   or exists(select 1 from jsonb_object_keys(s)k where k not in('key','group','title','text','evidence')) then raise exception 'Invalid bounded editorial story.';end if;
 end loop;
 if (select count(distinct elem.value->>'group') from jsonb_array_elements(p_document->'stories')as elem(value))<>jsonb_array_length(p_document->'stories') then raise exception 'Editorial topics must be diverse.';end if;
 select * into e from sportsbook_private.opening_editorial_editions where league_id=p_league;
 if e.current_document->'facts'->>'nfl_season'=f->>'nfl_season' and e.current_document->'facts'->>'league_season'=f->>'league_season' then
  if (e.current_document->'facts'->>'market_week')::integer>(f->>'market_week')::integer then raise exception 'Editorial history cannot be rewound.';end if;
  if e.current_document->'facts'->>'market_week'=f->>'market_week' then
   if e.current_document->'facts'->>'window_key'=f->>'window_key' then return e.current_document;end if;
   previous:=e.previous_document;
  elsif (e.current_document->'facts'->>'market_week')::integer=(f->>'market_week')::integer-1 then previous:=e.current_document;end if;
 end if;
 insert into sportsbook_private.opening_editorial_editions(league_id,current_document,previous_document)values(p_league,p_document,previous)
 on conflict(league_id)do update set current_document=excluded.current_document,previous_document=excluded.previous_document,revision=opening_editorial_editions.revision+1,updated_at=clock_timestamp();
 return p_document;
end $function$
;

REVOKE ALL ON FUNCTION "public"."publish_opening_editorial"(p_league uuid, p_document jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."publish_opening_editorial"(p_league uuid, p_document jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION public.publish_starter_status(p_scope text, p_key text, p_context text, p_token uuid, p_payload jsonb, p_checked timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_now timestamptz:=clock_timestamp();v_ttl interval;v_size bigint;
begin
 if p_payload is null or p_checked is null or p_checked>v_now+interval '1 second' then raise exception 'Invalid starter cache observation';end if;
 v_ttl:=case p_scope when 'players' then interval '1 day' when 'league' then interval '30 seconds' else interval '15 seconds' end;
 if p_checked+v_ttl<=v_now then return false;end if;
 perform pg_advisory_xact_lock(hashtextextended('starter-status-cache',0));
 if not exists(select 1 from public.starter_status_cache where scope=p_scope and cache_key=p_key and context=p_context
  and lease_token=p_token and lease_until>v_now) then return false;end if;
 select coalesce(sum(octet_length(payload::text)),0) into v_size from public.starter_status_cache where (scope,cache_key)<>(p_scope,p_key);
 if v_size+octet_length(p_payload::text)>8388608 then raise exception 'Starter cache byte budget reached';end if;
 update public.starter_status_cache set payload=p_payload,checked_at=p_checked,expires_at=p_checked+v_ttl,
  lease_token=null,lease_until=null,retry_after=null
  where scope=p_scope and cache_key=p_key and context=p_context and lease_token=p_token;
 return found;
end $function$
;

REVOKE ALL ON FUNCTION "public"."publish_starter_status"(p_scope text, p_key text, p_context text, p_token uuid, p_payload jsonb, p_checked timestamp with time zone) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."publish_starter_status"(p_scope text, p_key text, p_context text, p_token uuid, p_payload jsonb, p_checked timestamp with time zone) TO "service_role";

CREATE OR REPLACE FUNCTION public.queue_relative_reminder(p_league uuid, p_week integer, p_team uuid, p_recipient text, p_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l public.leagues;c jsonb;begin
 if auth.role() is distinct from 'service_role' then raise exception 'Server worker only.';end if;
 perform pg_advisory_xact_lock(hashtextextended('reminder-schedule:'||p_league,0));
 select * into l from public.leagues where id=p_league;
 c:=public.notification_window(p_league,l.nfl_season,p_week,'reminder');
 if c->>'eligible' is distinct from 'true' or c->>'window_key' is distinct from p_key or (c->>'send_after')::timestamptz>now() then return false;end if;
 if exists(select 1 from public.outbound_emails where league_id=p_league and market_week=p_week and kind='reminder'
  and recipient=p_recipient and (notification_context->>'nfl_season'=l.nfl_season::text or event_key like l.nfl_season||':%'
   or event_key like 'relative-reminder-v1:'||p_league||':'||l.nfl_season||':'||p_week||':%')
  and (attempts>0 or status in('sent','captured','needs_review'))) then return false;end if;
 insert into public.outbound_emails(league_id,event_key,kind,recipient,team_id,market_week,notification_context)
 values(p_league,'relative-reminder-v1:'||p_league||':'||l.nfl_season||':'||p_week||':'||md5(p_team||':'||p_recipient)||':'||p_key,'reminder',p_recipient,p_team,p_week,c)
 on conflict(event_key) do update set status='pending',last_error=null,terminal_at=null,lease_until=null
 where public.outbound_emails.status='skipped' and public.outbound_emails.attempts=0 and public.outbound_emails.payload is null
 and public.outbound_emails.provider_id is null and public.outbound_emails.body_retired_at is null
 and public.outbound_emails.notification_context=excluded.notification_context;
 return found;
end $function$
;

REVOKE ALL ON FUNCTION "public"."queue_relative_reminder"(p_league uuid, p_week integer, p_team uuid, p_recipient text, p_key text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."queue_relative_reminder"(p_league uuid, p_week integer, p_team uuid, p_recipient text, p_key text) TO "service_role";

CREATE OR REPLACE FUNCTION public.queue_reopening_announcement(p_review uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w public.sportsbook_reopening_reviews;c jsonb;n integer;begin
 select * into w from public.sportsbook_reopening_reviews where id=p_review;
 if not found or not sportsbook_private.is_admin(w.league_id) then raise exception 'Only this league admin can send this announcement.';end if;
 c:=public.notification_window(w.league_id,w.nfl_season,w.market_week,'reopening');
 if c->>'eligible' is distinct from 'true' or c->>'reopening_id' is distinct from w.id::text then raise exception 'An actionable approved reopening is required.';end if;
 n:=sportsbook_private.base_queue_reopening_announcement(p_review);
 update public.outbound_emails set notification_context=c where reopening_id=w.id and kind='reopening' and status='pending' and attempts=0 and payload is null and notification_context is null;
 return n;
end $function$
;

REVOKE ALL ON FUNCTION "public"."queue_reopening_announcement"(p_review uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."queue_reopening_announcement"(p_review uuid) TO "authenticated";

