CREATE OR REPLACE FUNCTION public.recap_financial_context(p_league uuid, p_team uuid, p_recipient text, p_season integer, p_week integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w public.user_wallets;balance numeric;credit numeric;entry_time timestamptz;u uuid;key text;pending boolean;run boolean;state text;begin
 if auth.role()is distinct from 'service_role'then raise exception 'Mail worker only.';end if;
 if p_week is null or p_week not between 1 and 19 or not exists(select 1 from public.leagues where id=p_league and nfl_season=p_season)or(p_week=19 and not sportsbook_private.final_weekly_recap_ready(p_league,p_season,now()))then raise exception 'Current recap season/period required.';end if;
 if exists(select 1 from sportsbook_private.user_finance_modes where league_id=p_league and enabled)then
  select x.* into w from public.user_wallets x join auth.users a on a.id=x.user_id where x.league_id=p_league and x.team_id=p_team and x.status='approved' and a.email=p_recipient and a.email_confirmed_at is not null;
  if not found then raise exception 'Approved financial recap recipient required.';end if;
  u:=w.user_id;balance:=w.balance;key:='weekly:replenish:'||p_season||':'||p_week||':'||w.id;
  select amount,created_at into credit,entry_time from public.user_wallet_entries where wallet_id=w.id and event_key=key and kind='weekly_replenishment';
  select exists(select 1 from public.tickets t where t.user_wallet_id=w.id and t.nfl_season=p_season and t.ticket_type<>'future' and t.market_week<p_week and t.status='OPEN')into pending;
 else
  select m.user_id into u from public.league_memberships m join auth.users a on a.id=m.user_id where m.league_id=p_league and m.team_id=p_team and m.invited_email=p_recipient and a.email=p_recipient and a.email_confirmed_at is not null;
  if u is null then raise exception 'Approved legacy recap recipient required.';end if;
  select x.balance into balance from public.wallets x where x.team_id=p_team;
  key:='weekly:replenish:'||p_season||':'||p_week||':'||p_team;
  select amount,created_at into credit,entry_time from public.wallet_ledger where team_id=p_team and event_key=key and kind='weekly_replenishment';
  select exists(select 1 from public.tickets t where t.team_id=p_team and t.user_wallet_id is null and t.nfl_season=p_season and t.ticket_type<>'future' and t.market_week<p_week and t.status='OPEN')into pending;
 end if;
 select exists(select 1 from public.weekly_execution_runs where league_id=p_league and nfl_season=p_season and market_week=p_week and operation='replenishment')into run;
 state:=case when p_week=19 then 'weekly_calendar_complete' when credit>0 then 'credited' when credit=0 then 'no_topup_needed' when balance is null then 'funding_pending' when pending then 'results_pending' else 'review_pending'end;
 return jsonb_build_object('league_id',p_league,'team_id',p_team,'recipient',p_recipient,'nfl_season',p_season,'replenishment_week',p_week,'ready',p_week=19 or credit is not null or run,'state',state,'credited',case when p_week=19 then null else credit end,'balance',balance,'recorded_at',entry_time);
end $function$
;

REVOKE ALL ON FUNCTION "public"."recap_financial_context"(p_league uuid, p_team uuid, p_recipient text, p_season integer, p_week integer) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."recap_financial_context"(p_league uuid, p_team uuid, p_recipient text, p_season integer, p_week integer) TO "service_role";

CREATE OR REPLACE FUNCTION public.record_dev_fantasy_rewards(p_league uuid, p_season integer, p_week integer, p_awards jsonb, p_results jsonb, p_expires timestamp with time zone, p_qualified jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  source jsonb;
  digest text;
  prior boff_dev_internal.fantasy_reward_runs;
  issued integer;
BEGIN
  IF NOT sportsbook_private.release_writes_enabled() THEN
    RAISE EXCEPTION 'Development project required';
  END IF;
  IF p_season IS NULL OR p_week IS NULL OR p_week NOT BETWEEN 1 AND 18
    OR jsonb_typeof(p_qualified) IS DISTINCT FROM 'array' OR jsonb_array_length(p_qualified)>400
    OR jsonb_typeof(p_awards) IS DISTINCT FROM 'array' OR jsonb_array_length(p_awards) > 400 THEN
    RAISE EXCEPTION 'Invalid fantasy reward batch';
  END IF;
  SELECT results INTO source FROM public.league_result_weeks
  WHERE league_id = p_league AND nfl_season = p_season AND market_week = p_week AND final
  FOR SHARE;
  IF source IS NULL OR source IS DISTINCT FROM p_results THEN RAISE EXCEPTION 'Final fantasy results required'; END IF;
  digest := md5(source::text);
  PERFORM pg_advisory_xact_lock(hashtext('boff-dev-fantasy-rewards'), hashtext(p_league::text));
  SELECT * INTO prior FROM boff_dev_internal.fantasy_reward_runs
  WHERE league_id = p_league AND season = p_season AND week = p_week;
  IF FOUND THEN
    UPDATE boff_dev_internal.fantasy_reward_runs SET qualified=p_qualified
    WHERE league_id=p_league AND season=p_season AND week=p_week AND qualified IS NULL AND source_digest=digest;
    UPDATE boff_dev_internal.fantasy_reward_runs
    SET correction_digest = CASE WHEN prior.source_digest <> digest THEN digest ELSE NULL END
    WHERE league_id = p_league AND season = p_season AND week = p_week
      AND correction_digest IS DISTINCT FROM CASE WHEN prior.source_digest <> digest THEN digest ELSE NULL END;
    RETURN jsonb_build_object('alreadyIssued', true, 'correctionPending', prior.source_digest <> digest);
  END IF;
  IF EXISTS (
    SELECT 
 FROM (
  SELECT ranked.* FROM (
   SELECT (value->>'team_id')::uuid AS team_id,value->>'achievement' AS achievement,(value->>'percent')::numeric AS percent,
    COALESCE(sum(eligible.users) OVER (PARTITION BY value->>'achievement' ORDER BY entry.ordinality ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) AS already_selected,
    
 COALESCE((settings.rules->'maxRecipients'->>(value->>'achievement'))::integer,
  CASE WHEN value->>'achievement'='highLoss' THEN 3
    WHEN value->>'achievement'~'^(win|loss)' OR value->>'achievement'='playoffClinch' THEN 2 ELSE 1 END)
  AS cap
   FROM jsonb_array_elements(p_awards) WITH ORDINALITY AS entry(value,ordinality)
   LEFT JOIN boff_dev_internal.fantasy_reward_rules settings ON settings.league_id=p_league
   CROSS JOIN LATERAL (
    SELECT count(*) users FROM boff_dev_internal.participant_links m JOIN public.user_wallets w
       ON w.league_id=m.league_id AND w.team_id=m.team_id AND w.user_id=m.user_id AND w.status='approved'
    WHERE m.league_id=p_league AND m.team_id=(value->>'team_id')::uuid
   ) eligible
  ) ranked WHERE ranked.cap=0 OR ranked.already_selected<ranked.cap
 ) award
 
    WHERE award.team_id IS NULL OR award.achievement IS NULL OR award.percent IS NULL
      OR award.percent NOT BETWEEN 0.01 AND 100
      OR award.achievement NOT IN ('topScorer','win3','win5','win7','win10','loss3','loss5','loss7','loss10','closeWin','upset','highLoss','beatProjection','seasonRecord','leagueRecord','playoffClinch','champion')
      OR NOT source ? award.team_id::text
  ) THEN RAISE EXCEPTION 'Invalid fantasy reward'; END IF;

  INSERT INTO boff_dev_internal.fantasy_reward_runs (league_id, season, week, source_digest, qualified)
  VALUES (p_league, p_season, p_week, digest, p_qualified);
  INSERT INTO boff_dev_internal.fantasy_reward_awards (league_id, season, week, team_id, user_id, achievement, percent, expires_at)
  SELECT p_league, p_season, p_week, award.team_id, member.user_id, award.achievement, award.percent, CASE WHEN award.achievement <> 'champion' THEN p_expires END
  
 FROM (
  SELECT ranked.* FROM (
   SELECT (value->>'team_id')::uuid AS team_id,value->>'achievement' AS achievement,(value->>'percent')::numeric AS percent,
    COALESCE(sum(eligible.users) OVER (PARTITION BY value->>'achievement' ORDER BY entry.ordinality ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING),0) AS already_selected,
    
 COALESCE((settings.rules->'maxRecipients'->>(value->>'achievement'))::integer,
  CASE WHEN value->>'achievement'='highLoss' THEN 3
    WHEN value->>'achievement'~'^(win|loss)' OR value->>'achievement'='playoffClinch' THEN 2 ELSE 1 END)
  AS cap
   FROM jsonb_array_elements(p_awards) WITH ORDINALITY AS entry(value,ordinality)
   LEFT JOIN boff_dev_internal.fantasy_reward_rules settings ON settings.league_id=p_league
   CROSS JOIN LATERAL (
    SELECT count(*) users FROM boff_dev_internal.participant_links m JOIN public.user_wallets w
       ON w.league_id=m.league_id AND w.team_id=m.team_id AND w.user_id=m.user_id AND w.status='approved'
    WHERE m.league_id=p_league AND m.team_id=(value->>'team_id')::uuid
   ) eligible
  ) ranked WHERE ranked.cap=0 OR ranked.already_selected<ranked.cap
 ) award
 
  JOIN boff_dev_internal.participant_links member ON member.league_id = p_league AND member.team_id = award.team_id
  JOIN public.user_wallets wallet ON wallet.league_id = member.league_id AND wallet.team_id = member.team_id
    AND wallet.user_id = member.user_id AND wallet.status = 'approved'
  ON CONFLICT (league_id, season, week, user_id, achievement) DO NOTHING;
  GET DIAGNOSTICS issued = ROW_COUNT;
  RETURN jsonb_build_object('alreadyIssued', false, 'awards', issued);
END $function$
;

