CREATE OR REPLACE FUNCTION public.round_future_odds()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.kind like 'future_%' then new.odds:=sign(new.odds)*greatest(100,round(abs(new.odds)/10.0)*10); end if;
 return new;
end $function$
;

