CREATE OR REPLACE FUNCTION public.routine_delivery_permission(p_email uuid, p_commit boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE decision jsonb; context jsonb; include_details boolean; queued public.outbound_emails;
BEGIN
 IF EXISTS(SELECT FROM public.outbound_emails WHERE id=p_email AND kind IN ('reminder','reopening')) THEN
  RETURN jsonb_build_object('allowed',false,'reason','This email type was consolidated into New Weekly Markets.');
 END IF;
 IF auth.role() IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'Mail worker only.'; END IF;
 decision:=sportsbook_private.routine_delivery_permission_at(p_email,false,now());
 context:=decision->'context';
 IF decision->>'allowed' IS DISTINCT FROM 'true' OR context IS NULL THEN RETURN decision; END IF;

 SELECT boff_dev_internal.communication_details(c.choices)
 INTO include_details
 FROM (SELECT 1) lookup LEFT JOIN boff_dev_internal.notification_choices c
 ON c.league_id=(context->>'league_id')::uuid AND c.user_id=(context->>'user_id')::uuid;

 SELECT * INTO STRICT queued FROM public.outbound_emails WHERE id=p_email;
 IF queued.payload IS NOT NULL AND NOT include_details
   AND queued.routine_context->>'include_details' IS DISTINCT FROM 'false' THEN
  RETURN jsonb_build_object('allowed',false,'reason','Email details were disabled before delivery. The saved message was retired.');
 END IF;
 IF p_commit THEN
  decision:=sportsbook_private.routine_delivery_permission_at(p_email,true,now());
  IF decision->>'allowed' IS DISTINCT FROM 'true' THEN RETURN decision; END IF;
 END IF;
 IF queued.payload IS NOT NULL THEN RETURN decision; END IF;
 RETURN jsonb_set(decision,'{context,include_details}',to_jsonb(include_details));
END $function$
;

REVOKE ALL ON FUNCTION "public"."routine_delivery_permission"(p_email uuid, p_commit boolean) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."routine_delivery_permission"(p_email uuid, p_commit boolean) TO "service_role";

CREATE OR REPLACE FUNCTION public.routine_retention_status(p_league uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if not sportsbook_private.is_admin(p_league) then raise exception 'League operator only.';end if;
 return jsonb_build_object('logical_bytes_only',true,'email',(select jsonb_build_object(
  'body_bytes',coalesce(sum(payload_bytes),0),'league_budget',8388608,
  'due',count(*) filter(where retention_version=1 and body_retired_at is null and status in ('sent','captured','skipped') and terminal_at<clock_timestamp()-interval '7 days'),
  'unresolved',count(*) filter(where payload is not null and status in ('pending','sending','failed','needs_review')),
  'last_retirement',max(body_retired_at)) from public.outbound_emails where league_id=p_league),
 'jobs',(select jsonb_build_object('detail_bytes',coalesce(sum(summary_bytes) filter(where diagnostic_retired_at is null),0),'league_budget',4194304,
  'due',count(*) filter(where retention_version=1 and diagnostic_retired_at is null and status='done' and completed_at<clock_timestamp()-interval '30 days'),
  'last_retirement',max(diagnostic_retired_at)) from public.automation_jobs where league_id=p_league),
 'images',(select jsonb_build_object('stored_text_bytes',coalesce(sum(png_bytes),0),'count',count(*),'league_budget',33554432,'league_count_budget',128)
  from public.promo_images where league_id=p_league));
end $function$
;

REVOKE ALL ON FUNCTION "public"."routine_retention_status"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."routine_retention_status"(p_league uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION public.save_communication_identity(p_league uuid, p_expected text, p_url text, p_sender text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare l public.leagues;origin text;begin
 if not public.league_intake_owner()then raise exception 'Verified platform owner required.';end if;
 if p_reason is null or length(trim(p_reason))not between 8 and 400 then raise exception 'Communication review reason required.';end if;
 origin:=public.application_environment_identity()->>'app_origin';
 if p_url is null or length(p_url)>2048 or p_url!~'^https://[a-zA-Z0-9.-]+(:[0-9]+)?(/[^[:space:]]*)?$'or p_url~'[\\]'or substring(p_url from '^(https://[^/]+)')is distinct from origin then raise exception 'Use the exact HTTPS application origin for this environment.';end if;
 if p_sender is null or length(p_sender)>254 or p_sender!~'^[^[:space:]<>@]+@[^[:space:]<>@]+\.[^[:space:]<>@]+$'then raise exception 'Verified sender email address required.';end if;
 select * into l from public.leagues where id=p_league for update;if not found then raise exception 'Selected league unavailable.';end if;
 if l.operations_enabled or exists(select 1 from public.weekly_schedule where league_id=p_league and automation_enabled)then raise exception 'Pause operations and automation before communication identity changes.';end if;
 if l.sportsbook_url=p_url and l.email_sender=p_sender then return public.communication_identity_review(p_league);end if;
 if p_expected is distinct from encode(sha256(convert_to(jsonb_build_array(l.sportsbook_url,l.email_sender)::text,'UTF8')),'hex')then raise exception 'Communication identity changed; reload before saving.';end if;
 update public.leagues set sportsbook_url=p_url,email_sender=p_sender where id=p_league;
 insert into public.admin_change_log(league_id,actor_id,category,reason,before_value,after_value)values(p_league,auth.uid(),'communication_identity',trim(p_reason),jsonb_build_object('sportsbook_url',l.sportsbook_url,'email_sender',l.email_sender),jsonb_build_object('sportsbook_url',p_url,'email_sender',p_sender));
 return public.communication_identity_review(p_league);
end $function$
;

REVOKE ALL ON FUNCTION "public"."save_communication_identity"(p_league uuid, p_expected text, p_url text, p_sender text, p_reason text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_communication_identity"(p_league uuid, p_expected text, p_url text, p_sender text, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.save_evaluation_summary(p_job uuid, p_attempt integer, p_context text, p_hash text, p_started timestamp with time zone, p_summary jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j public.automation_jobs;old public.model_evaluation_summaries;result integer;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Worker only.';end if;
 select * into strict j from public.automation_jobs where id=p_job for update;
 if j.operation<>'model_review' or j.status<>'running' or j.attempts<>p_attempt or j.lease_until<=clock_timestamp() then raise exception 'Summary lease lost.';end if;
 if not exists(select 1 from public.model_weekly_reviews r join public.model_outcome_revisions o on o.id=r.outcome_id and o.league_id=r.league_id
  where r.league_id=j.league_id and r.nfl_season=(select nfl_season from public.leagues where id=j.league_id) and r.market_week=j.market_week
   and r.input_hash=p_hash and r.report->>'summary_context_hash'=p_context and r.report->>'status'='complete'
   and o.outcome->>'final'='true' and o.outcome->>'completed_period'='true' and o.outcome->>'confirmed_games_final'='true') then raise exception 'Confirmed scoped review required for summary.';end if;
 if p_context is null or p_context !~ '^[0-9a-f]{64}$' or p_hash is null or p_hash !~ '^[0-9a-f]{64}$'
  or p_started is null or p_started<clock_timestamp()-interval '20 minutes' or p_started>clock_timestamp()+interval '30 seconds' then raise exception 'Invalid summary identity/time.';end if;
 if jsonb_typeof(p_summary) is distinct from 'object' or jsonb_typeof(p_summary->'coverage') is distinct from 'object'
  or jsonb_typeof(p_summary->'coverage'->'missing_families') is distinct from 'array'
  or p_summary->>'format' is distinct from 'weekly-additive-v1' or octet_length(p_summary::text)>65536 then raise exception 'Invalid summary byte/format budget.';end if;
 if exists(select 1 from unnest(array['scores','players','paired_sleeper','markets']) f(k)
  where jsonb_typeof(p_summary->k) is distinct from 'array' or jsonb_array_length(p_summary->k)>256) then raise exception 'Invalid summary segment budget.';end if;
 -- Defend the compact contract even against a malformed worker: object keys and
 -- all leaves are primitive, with only the declared nested count/bin shapes.
 if exists(select 1 from jsonb_object_keys(p_summary) k where k not in ('format','scores','players','paired_sleeper','markets','coverage','note','diagnostics','futures','future_final','live')) then raise exception 'Unexpected summary field.';end if;
 if jsonb_typeof(p_summary->'diagnostics') is distinct from 'array' or jsonb_array_length(p_summary->'diagnostics')>256
  or jsonb_typeof(p_summary->'futures') is distinct from 'array' or jsonb_array_length(p_summary->'futures')>4
  or jsonb_typeof(p_summary->'live') is distinct from 'array' or jsonb_array_length(p_summary->'live')>4
  or jsonb_typeof(p_summary->'future_final') is distinct from 'boolean' then raise exception 'Invalid diagnostic summary budget.';end if;
 if exists(select 1 from jsonb_array_elements(p_summary->'diagnostics') w,lateral jsonb_each(w) f where
  f.key not in ('kind','horizon','model_version','type','totals','n','ties','probability_n','brier','log_loss','coverage_n','covered80')
  or (f.key in ('n','ties','probability_n','brier','log_loss','coverage_n','covered80') and (jsonb_typeof(f.value)<>'number' or f.value::numeric<0)))
  or exists(select 1 from jsonb_array_elements(p_summary->'diagnostics') w where sportsbook_private.numeric_total_valid(w->'totals') is distinct from true
   or w->>'type' not in ('categorical','distribution')) then raise exception 'Invalid diagnostic totals.';end if;
 if exists(select 1 from jsonb_array_elements(p_summary->'futures') w,lateral jsonb_each(w) f where f.key not in ('kind','generated','pending','totals','wins'))
  or exists(select 1 from jsonb_array_elements(p_summary->'futures') w where sportsbook_private.probability_total_valid(w->'totals') is distinct from true
   or sportsbook_private.numeric_total_valid(w->'wins') is distinct from true or w->>'kind' not in ('future_champion','future_playoffs','future_first_pick','future_win_total')
   or jsonb_typeof(w->'generated') is distinct from 'number' or jsonb_typeof(w->'pending') is distinct from 'number'
   or (w->>'generated')::numeric<0 or (w->>'pending')::numeric<0 or (w->>'pending')::numeric+(w->'totals'->>'n')::numeric<>(w->>'generated')::numeric) then raise exception 'Invalid future totals.';end if;
 if p_summary->>'future_final'='true' and (jsonb_array_length(p_summary->'futures')=0 or exists(select 1 from jsonb_array_elements(p_summary->'futures') w where (w->>'pending')::integer<>0)) then raise exception 'Unresolved future summary cannot be final.';end if;
 if exists(select 1 from jsonb_array_elements(p_summary->'live') w,lateral jsonb_each(w) f where
  f.key not in ('horizon','team_count','matchup_count','mae','rmse','bias','coverage80','brier','log_loss','margin_mae','total_mae')
  or jsonb_typeof(f.value) not in ('number','null')) or exists(select 1 from jsonb_array_elements(p_summary->'live') w where
   (w->>'horizon')::integer not between 0 and 3) then raise exception 'Invalid live totals.';end if;
 if exists(select 1 from jsonb_array_elements((p_summary->'scores')||(p_summary->'players')) row,
  lateral jsonb_object_keys(row) k where k not in ('view','horizon','model_version','missing','totals')) then raise exception 'Unexpected numeric summary field.';end if;
 if exists(select 1 from jsonb_array_elements((p_summary->'scores')||(p_summary->'players')) row
  where sportsbook_private.numeric_total_valid(row->'totals') is distinct from true) then raise exception 'Invalid additive numeric totals.';end if;
 if exists(select 1 from jsonb_array_elements(p_summary->'paired_sleeper') row,lateral jsonb_object_keys(row) k
  where k not in ('view','horizon','model_version','missing','adjusted','sleeper')) or
  exists(select 1 from jsonb_array_elements(p_summary->'paired_sleeper') row where
   sportsbook_private.numeric_total_valid(row->'adjusted') is distinct from true or sportsbook_private.numeric_total_valid(row->'sleeper') is distinct from true)
  then raise exception 'Invalid paired Sleeper totals.';end if;
 if exists(select 1 from jsonb_array_elements(p_summary->'markets') row,
  lateral jsonb_object_keys(row) k where k not in ('kind','horizon','model_version','generated','locked','published','pushes','pending','missing_probability','totals')) then raise exception 'Unexpected probability summary field.';end if;
 if exists(select 1 from jsonb_array_elements(p_summary->'markets') row where jsonb_typeof(row->'totals'->'bands') is distinct from 'array' or jsonb_array_length(row->'totals'->'bands')<>5) then raise exception 'Invalid calibration bin contract.';end if;
 if exists(select 1 from jsonb_array_elements(p_summary->'markets') row,lateral jsonb_each(row->'totals') t
  where t.key not in ('n','brier','log_loss','bands') or (t.key<>'bands' and (jsonb_typeof(t.value)<>'number' or t.value::numeric<0)))
  or exists(select 1 from jsonb_array_elements(p_summary->'markets') row,lateral jsonb_array_elements(row->'totals'->'bands') b,lateral jsonb_each(b) t
   where t.key not in ('n','predicted','observed') or jsonb_typeof(t.value)<>'number' or t.value::numeric<0)
  then raise exception 'Invalid probability totals.';end if;
 if exists(select 1 from jsonb_array_elements(p_summary->'markets') row cross join lateral unnest(array['n','brier','log_loss']) f(k)
  where jsonb_typeof(row->'totals'->k) is distinct from 'number') then raise exception 'Missing probability totals.';end if;
 if exists(select 1 from jsonb_array_elements(p_summary->'markets') row where sportsbook_private.probability_total_valid(row->'totals') is distinct from true)
  then raise exception 'Invalid bounded calibration totals.';end if;
 if exists(select 1 from jsonb_array_elements((p_summary->'scores')||(p_summary->'players')||(p_summary->'markets')||(p_summary->'paired_sleeper')||(p_summary->'diagnostics')) row,
  lateral jsonb_each(row) d where d.key in ('kind','view','horizon','model_version') and (jsonb_typeof(d.value)<>'string' or length(d.value#>>'{}')>80)) then raise exception 'Invalid summary dimensions.';end if;
 if exists(select 1 from jsonb_array_elements((p_summary->'scores')||(p_summary->'players')||(p_summary->'markets')||(p_summary->'paired_sleeper')||(p_summary->'diagnostics')) row
  where row->>'horizon' is null or row->>'horizon' not in ('opening','final_pregame') or not exists
   (select 1 from public.model_config_versions where league_id=j.league_id and id=(row->>'model_version')::uuid)) then raise exception 'Summary context outside league.';end if;
 if exists(select 1 from jsonb_array_elements((p_summary->'scores')||(p_summary->'players')||(p_summary->'paired_sleeper')) row
  where jsonb_typeof(row->'missing') is distinct from 'number' or (row->>'missing')::numeric<0 or (row->>'missing')::numeric<>trunc((row->>'missing')::numeric))
  or exists(select 1 from jsonb_array_elements(p_summary->'paired_sleeper') row where row->'adjusted'->'n'<>row->'sleeper'->'n') then raise exception 'Invalid summary missingness.';end if;
 if exists(select 1 from jsonb_each(p_summary->'coverage') t where t.key not in ('selected_runs','locked_forecasts','missing_starter_forecasts','unknown_source_freshness','missing_families')
  or (t.key<>'missing_families' and (jsonb_typeof(t.value)<>'number' or t.value::numeric<0)))
  or jsonb_array_length(p_summary->'coverage'->'missing_families')>4
  or exists(select 1 from jsonb_array_elements(p_summary->'coverage'->'missing_families') f where f#>>'{}' not in ('Matchups','Player Points','Weekly Specials','Season Futures'))
  or length(p_summary->>'note')>400 then raise exception 'Invalid summary coverage contract.';end if;
 -- This lock is already used by configuration changes; it serializes all
 -- summary revisions for this league and avoids first-insert races.
 perform 1 from public.model_controls where league_id=j.league_id for update;
 select * into old from public.model_evaluation_summaries where league_id=j.league_id
  and nfl_season=(select nfl_season from public.leagues where id=j.league_id) and market_week=j.market_week for update;
 if found then if old.retired_at is not null then raise exception 'Summary correction window closed.';end if;
  if old.input_hash=p_hash then
   if old.summary<>p_summary or old.context_hash<>p_context then raise exception 'Summary identity collision.';end if;
   return old.revision;
  end if;
  if old.read_started_at>=p_started then return old.revision;end if;
  if old.summary=p_summary and old.context_hash=p_context then return old.revision;end if;
 end if;
 insert into public.model_evaluation_summaries(league_id,nfl_season,market_week,context_hash,input_hash,read_started_at,summary)
 values(j.league_id,(select nfl_season from public.leagues where id=j.league_id),j.market_week,p_context,p_hash,p_started,p_summary)
 on conflict(league_id,nfl_season,market_week) do update set context_hash=excluded.context_hash,input_hash=excluded.input_hash,
 read_started_at=excluded.read_started_at,known_at=clock_timestamp(),summary=excluded.summary,revision=model_evaluation_summaries.revision+1
 returning revision into result;
 return result;
end $function$
;

REVOKE ALL ON FUNCTION "public"."save_evaluation_summary"(p_job uuid, p_attempt integer, p_context text, p_hash text, p_started timestamp with time zone, p_summary jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_evaluation_summary"(p_job uuid, p_attempt integer, p_context text, p_hash text, p_started timestamp with time zone, p_summary jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION public.save_future_board(p_board uuid, p_league uuid, p_quotes jsonb, p_status text DEFAULT 'draft'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '45s'
 SET work_mem TO '16MB'
AS $function$
declare l public.leagues; b public.sportsbook_boards; q jsonb;
begin
 if not sportsbook_private.is_admin(p_league) then raise exception 'Only the league admin can manage futures.'; end if;
 if p_status not in ('draft','published','closed') or p_status is null or jsonb_typeof(p_quotes) is distinct from 'array' or jsonb_array_length(p_quotes)>100 then raise exception 'Invalid futures board.'; end if;
 select * into l from public.leagues where id=p_league;
 if not found then raise exception 'League unavailable.'; end if;
 select * into b from public.sportsbook_boards where id=p_board for update;
 if found and (b.league_id<>p_league or b.nfl_season<>l.nfl_season or b.board_type<>'future') then raise exception 'Futures board identity does not match.'; end if;
 if p_status='published' and jsonb_array_length(p_quotes)=0 then raise exception 'Generate futures before publishing.'; end if;
 for q in select value from jsonb_array_elements(p_quotes) loop
  if q->>'kind' is null or q->>'kind' not in ('future_champion','future_playoffs','future_first_pick','future_win_total') or coalesce((q->>'boost_pct')::integer,0)<>0 then raise exception 'Futures board accepts only standalone season markets.'; end if;
  if not exists(select 1 from public.teams where id=(q->>'team_id')::uuid and league_id=p_league) then raise exception 'Future selection must belong to this league.'; end if;
  if not exists(select 1 from public.teams where id=(q->>'team_id')::uuid and roster_id=(q->'metadata'->>'roster_id')::int) then raise exception 'Accepted season roster does not match its team.'; end if;
  if (q->>'kind'='future_playoffs' and q->>'side' not in ('make','miss')) or (q->>'kind' not in ('future_playoffs','future_win_total') and q->>'side' is distinct from q->>'team_id') or (q->>'kind'='future_win_total' and q->>'side' not in ('over','under')) then raise exception 'Invalid futures selection.'; end if;
  if exists(select 1 from public.sportsbook_markets where id=(q->>'id')::uuid and board_id<>p_board) then raise exception 'A quote belongs to a different board.'; end if;
  if q->>'kind'='future_first_pick' and (q->'metadata'->>'last_place_basis' is distinct from 'regular_season' or not exists(select 1 from public.teams where id=(q->'metadata'->>'pick_owner_team_id')::uuid and league_id=p_league)) then raise exception 'First-pick outcome or owner is unavailable.'; end if;
 end loop;
 insert into public.sportsbook_boards(id,league_id,market_week,nfl_season,league_season,board_type,opens_at,closes_at,status)
 values(p_board,p_league,1,l.nfl_season,l.league_season,'future',now()-interval '1 second',make_timestamptz(l.nfl_season+1,3,1,0,0,0,'America/New_York'),p_status)
 on conflict(id) do update set status=excluded.status,revision=public.sportsbook_boards.revision+1;
 update public.sportsbook_markets set active=false where board_id=p_board;
 for q in select value from jsonb_array_elements(p_quotes) loop
  insert into public.sportsbook_markets(id,board_id,market_key,kind,label,subject,side,line,odds,team_id,home_projection,metadata)
  values((q->>'id')::uuid,p_board,q->>'market_key',q->>'kind',q->>'label',q->>'subject',q->>'side',(q->>'line')::numeric,(q->>'odds')::integer,(q->>'team_id')::uuid,(q->>'home_projection')::numeric,q->'metadata')
  on conflict(board_id,market_key,side) do update set label=excluded.label,subject=excluded.subject,line=excluded.line,odds=excluded.odds,home_projection=excluded.home_projection,metadata=excluded.metadata||case when public.sportsbook_markets.metadata->>'resolved'='true' then jsonb_build_object('resolved',true) else '{}'::jsonb end,active=coalesce(public.sportsbook_markets.metadata->>'resolved','false')<>'true';
 end loop;
 perform sportsbook_private.capture_forecast(p_board); return p_board;
end $function$
;

REVOKE ALL ON FUNCTION "public"."save_future_board"(p_board uuid, p_league uuid, p_quotes jsonb, p_status text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_future_board"(p_board uuid, p_league uuid, p_quotes jsonb, p_status text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.save_future_board_revision(p_board uuid, p_league uuid, p_revision integer, p_quotes jsonb, p_status text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare b public.sportsbook_boards;
begin
  if not sportsbook_private.is_admin(p_league) then raise exception 'Only the league admin can manage futures.'; end if;
  perform 1 from public.leagues where id=p_league for update;
  select * into b from public.sportsbook_boards where id=p_board for update;
  if found then
    if b.league_id<>p_league or b.board_type<>'future' then raise exception 'Futures board scope mismatch.'; end if;
    if p_revision is distinct from b.revision then raise exception 'Futures changed. Reload before saving.'; end if;
  elsif p_revision is not null then raise exception 'Futures board is unavailable. Reload before saving.';
  end if;
  return public.save_future_board(p_board,p_league,p_quotes,p_status);
end;
$function$
;

REVOKE ALL ON FUNCTION "public"."save_future_board_revision"(p_board uuid, p_league uuid, p_revision integer, p_quotes jsonb, p_status text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_future_board_revision"(p_board uuid, p_league uuid, p_revision integer, p_quotes jsonb, p_status text) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."save_future_board_revision"(p_board uuid, p_league uuid, p_revision integer, p_quotes jsonb, p_status text) TO "service_role";

CREATE OR REPLACE FUNCTION public.save_league_identity(p_league uuid, p_name text, p_avatar text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare old public.leagues;
begin
 if not sportsbook_private.is_platform_owner() then raise exception 'Only the platform owner can edit settings.'; end if;
 if length(trim(p_name)) not between 3 and 100 or length(trim(p_reason)) not between 5 and 500 or (p_avatar<>'' and p_avatar !~ '^https://') or length(p_avatar)>1000 then raise exception 'Provide a league name, HTTPS image URL, and change reason.'; end if;
 select * into strict old from public.leagues where id=p_league for update;
 update public.leagues set name=trim(p_name),avatar_url=nullif(trim(p_avatar),'') where id=p_league;
 insert into public.admin_change_log(league_id,actor_id,category,reason,before_value,after_value) values(p_league,auth.uid(),'identity',trim(p_reason),jsonb_build_object('name',old.name,'avatar_url',old.avatar_url),jsonb_build_object('name',trim(p_name),'avatar_url',nullif(trim(p_avatar),'')));
end $function$
;

REVOKE ALL ON FUNCTION "public"."save_league_identity"(p_league uuid, p_name text, p_avatar text, p_reason text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_league_identity"(p_league uuid, p_name text, p_avatar text, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.save_league_intake_draft(p_request uuid, p_source jsonb, p_capabilities jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare d public.league_intake_drafts;h text;begin
 if not public.league_intake_owner() then raise exception 'Verified platform owner required.';end if;
 if p_request is null or p_source is null or p_capabilities is null or octet_length(p_source::text)>65536 or octet_length(p_capabilities::text)>16384 then raise exception 'Intake request exceeds its budget.';end if;
 perform sportsbook_private.validate_intake_source(p_source,p_capabilities);
 perform pg_advisory_xact_lock(20261101,16);
 h:=md5(jsonb_build_object('source',p_source,'capabilities',p_capabilities)::text);
 select * into d from public.league_intake_drafts where owner_id=auth.uid() and request_key=p_request;
 if found then
  if d.payload_md5<>h then raise exception 'Intake request already used with different provider data.';end if;
  return jsonb_build_object('id',d.id,'revision',d.revision,'state',d.state,'duplicate',true);
 end if;
 IF EXISTS(SELECT FROM public.leagues WHERE sleeper_league_id=p_source->>'league_id') THEN RAISE EXCEPTION 'This Sleeper league is already connected. Review its existing setup or renewal.'; END IF;
 update public.league_intake_drafts set state='expired',source='{}',capabilities='{}',revision=revision+1 where owner_id=auth.uid() and state='draft' and expires_at<=clock_timestamp();
 SELECT * INTO d FROM public.league_intake_drafts WHERE owner_id=auth.uid() AND source_league_id=p_source->>'league_id' AND state='draft' AND expires_at>clock_timestamp() ORDER BY created_at DESC LIMIT 1;
 IF FOUND THEN
 IF d.payload_md5=h THEN RETURN jsonb_build_object('id',d.id,'revision',d.revision,'state',d.state,'duplicate',true); END IF;
 UPDATE public.league_intake_drafts SET state='expired',source='{}',capabilities='{}',revision=revision+1 WHERE id=d.id;
 END IF;
 if (select count(*) from public.league_intake_drafts where owner_id=auth.uid() and state='draft')>=4
  or (select count(*) from public.league_intake_drafts)>=64 then raise exception 'Intake draft admission budget reached.';end if;
 insert into public.league_intake_drafts(owner_id,request_key,source_league_id,payload_md5,source,capabilities)
 values(auth.uid(),p_request,p_source->>'league_id',h,p_source,p_capabilities) returning * into d;
 return jsonb_build_object('id',d.id,'revision',d.revision,'state',d.state,'duplicate',false);
end $function$
;

REVOKE ALL ON FUNCTION "public"."save_league_intake_draft"(p_request uuid, p_source jsonb, p_capabilities jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_league_intake_draft"(p_request uuid, p_source jsonb, p_capabilities jsonb) TO "authenticated";

CREATE OR REPLACE FUNCTION public.save_league_notification_defaults(p_league uuid, p_revision integer, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare current_revision integer;begin
 if not sportsbook_private.is_platform_owner() then raise exception 'Verified platform owner required.';end if;
 if not sportsbook_private.valid_notification_values(p_values,true) then raise exception 'Every supported notification type requires an enabled/disabled choice.';end if;
 perform pg_advisory_xact_lock(hashtextextended('notification-defaults:'||p_league,0));
 select revision into current_revision from sportsbook_private.notification_defaults where league_id=p_league;
 if p_revision is distinct from coalesce(current_revision,0) then raise exception 'League notification defaults changed; reload before saving.';end if;
 insert into sportsbook_private.notification_defaults(league_id,values,updated_by)values(p_league,p_values,auth.uid())
 on conflict(league_id) do update set values=excluded.values,revision=notification_defaults.revision+1,updated_by=auth.uid(),updated_at=clock_timestamp();
 return public.league_notification_defaults(p_league);
end $function$
;

REVOKE ALL ON FUNCTION "public"."save_league_notification_defaults"(p_league uuid, p_revision integer, p_values jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_league_notification_defaults"(p_league uuid, p_revision integer, p_values jsonb) TO "authenticated";

CREATE OR REPLACE FUNCTION public.save_live_model_review(p_job uuid, p_attempt integer, p_outcome_hash text, p_forecast_hash text, p_outcomes jsonb, p_report jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j public.automation_jobs;result uuid;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Server worker only.';end if;
 select * into strict j from public.automation_jobs where id=p_job for update;
 if j.operation<>'model_review' or j.status<>'running' or j.attempts<>p_attempt or j.lease_until<=now() then raise exception 'Model review lease lost.';end if;
 if ((select week from public.sportsbook_period(j.league_id))<=j.market_week and j.market_week<>18) or p_report->>'status' is distinct from 'complete' then raise exception 'Model review requires a completed week.';end if;
 
 if p_report->>'retention_format' is distinct from 'transient-live-v1' then raise exception 'Temporary live format required.';end if;
 if p_report->>'retention_format'='transient-live-v1' then
  perform 1 from public.model_controls where league_id=j.league_id for update;
  if exists(select 1 from public.model_evaluation_summaries where league_id=j.league_id and nfl_season=(select nfl_season from public.leagues where id=j.league_id)
   and market_week=j.market_week and retired_at is not null) then raise exception 'Row-level correction window closed.';end if;
  select id into result from public.live_model_reviews where league_id=j.league_id and nfl_season=(select nfl_season from public.leagues where id=j.league_id)
   and market_week=j.market_week and outcome_hash=p_outcome_hash and forecast_hash=p_forecast_hash;
  if result is not null then return result;end if;
  if octet_length(p_report::text)>131072 or octet_length(p_outcomes::text)>65536
   or (select count(*) from public.live_model_reviews where league_id=j.league_id and report->>'retention_format'='transient-live-v1')>=64
   or (select coalesce(sum(octet_length(report::text)+octet_length(outcomes::text)),0) from public.live_model_reviews where league_id=j.league_id and report->>'retention_format'='transient-live-v1')+
    octet_length(p_report::text)+octet_length(p_outcomes::text)>8388608 then raise exception 'Live review diagnostic budget exceeded.';end if;
 end if;
 insert into public.live_model_reviews(league_id,nfl_season,market_week,outcome_hash,forecast_hash,outcomes,report)
 values(j.league_id,(select nfl_season from public.leagues where id=j.league_id),j.market_week,p_outcome_hash,p_forecast_hash,p_outcomes,p_report)
 on conflict(league_id,nfl_season,market_week,outcome_hash,forecast_hash) do nothing returning id into result;
 if result is null then select id into result from public.live_model_reviews where league_id=j.league_id and nfl_season=(select nfl_season from public.leagues where id=j.league_id) and market_week=j.market_week and outcome_hash=p_outcome_hash and forecast_hash=p_forecast_hash;end if;
 return result;
end $function$
;

REVOKE ALL ON FUNCTION "public"."save_live_model_review"(p_job uuid, p_attempt integer, p_outcome_hash text, p_forecast_hash text, p_outcomes jsonb, p_report jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_live_model_review"(p_job uuid, p_attempt integer, p_outcome_hash text, p_forecast_hash text, p_outcomes jsonb, p_report jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION public.save_live_shadow(p_job uuid, p_attempt integer, p_snapshot jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j public.automation_jobs;c public.line_refresh_cycles;result uuid;p jsonb;slim jsonb;observed timestamptz;reason text;slots integer;used_bytes bigint;old_bytes integer;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Server worker only.';end if;
 select * into strict j from public.automation_jobs where id=p_job for update;
 if j.operation<>'interval_matchups' or j.status<>'running' or j.attempts<>p_attempt or j.lease_until<=now() then raise exception 'Live shadow lease lost.';end if;
 perform 1 from public.line_refresh_runtime where league_id=j.league_id for update;
 select * into strict c from public.line_refresh_cycles where id=j.refresh_cycle_id for update;
 if c.status<>'staging' or c.market_week<>j.market_week or c.league_id<>j.league_id or c.created_at<now()-interval '20 minutes' then raise exception 'Live shadow cycle expired.';end if;
 if (select week from public.sportsbook_period(j.league_id))<>j.market_week then raise exception 'Live shadow week changed.';end if;
 if p_snapshot->'model_config'->>'mode' is distinct from 'shadow' or coalesce(p_snapshot->'payload'->>'status','') not in ('shadow','blocked') or jsonb_typeof(p_snapshot->'payload'->'teams') is distinct from 'array' or jsonb_typeof(p_snapshot->'payload'->'quotes') is distinct from 'array' then raise exception 'Shadow logging cannot enable acceptance.';end if;

 p:=p_snapshot->'payload';observed:=(p_snapshot->>'observed_at')::timestamptz;
 if observed is null or observed<clock_timestamp()-interval '20 minutes' or observed>clock_timestamp()+interval '30 seconds'
  or jsonb_array_length(p->'teams')>16 or jsonb_array_length(p->'quotes')>8 or length(p_snapshot->>'model_version')>80 then raise exception 'Invalid compact live scope.';end if;
 if exists(select 1 from jsonb_array_elements(p->'teams') t where not exists(select 1 from public.teams m
  where m.id=(t->>'team_id')::uuid and m.league_id=j.league_id and m.roster_id=(t->>'roster_id')::integer)) then raise exception 'Live team outside league.';end if;
 if p->>'status'<>'shadow' or jsonb_typeof(p->'horizon') is distinct from 'number' or (p->>'horizon')::integer not between 0 and 3
  or jsonb_array_length(p->'teams')<2 or jsonb_array_length(p->'quotes')=0
  or jsonb_array_length(p->'teams')<>(select count(*) from public.teams where league_id=j.league_id)
  or (select count(distinct t->>'team_id') from jsonb_array_elements(p->'teams') t)<>jsonb_array_length(p->'teams')
  or exists(select 1 from jsonb_array_elements(p->'teams') t where jsonb_typeof(t->'reasons') is distinct from 'array' or t->'reasons'<>'[]'::jsonb)
  then reason:='incomplete_targets';
 else
  if exists(select 1 from jsonb_array_elements(p->'teams') t where jsonb_typeof(t->'starters') is distinct from 'array'
    or jsonb_array_length(t->'starters')>32 or jsonb_typeof(t->'mean') is distinct from 'number' or jsonb_typeof(t->'sd') is distinct from 'number'
    or jsonb_typeof(t->'observed') is distinct from 'number') then raise exception 'Invalid live prediction targets.';end if;
  if exists(select 1 from jsonb_array_elements(p->'teams') t,lateral jsonb_array_elements(t->'starters') s
    where jsonb_typeof(s)<>'string' or length(s#>>'{}')>80) then raise exception 'Invalid live starter target.';end if;
  if exists(select 1 from jsonb_array_elements(p->'quotes') q,lateral jsonb_each(q) x
    where x.key in ('matchup_id','home_mean','away_mean','spread','total','home_fair_probability','away_fair_probability','home_odds','away_odds')
     and jsonb_typeof(x.value)<>'number') then raise exception 'Invalid live numeric quote.';end if;
  if exists(select 1 from jsonb_array_elements(p->'quotes') q cross join lateral unnest(array['matchup_id','home_mean','away_mean','spread','total','home_fair_probability','away_fair_probability','home_odds','away_odds']) fields(k)
    where jsonb_typeof(q->k) is distinct from 'number') then raise exception 'Missing live numeric quote.';end if;
  if exists(select 1 from jsonb_array_elements(p->'quotes') q where
    not exists(select 1 from jsonb_array_elements(p->'teams') t where t->>'team_id'=q->>'home_team_id')
    or not exists(select 1 from jsonb_array_elements(p->'teams') t where t->>'team_id'=q->>'away_team_id')) then raise exception 'Live quote outside targets.';end if;
  slim:=sportsbook_private.compact_live_payload(p);
  if octet_length(slim::text)>65536 then reason:='sample_too_large';end if;
 end if;
 insert into public.live_forecast_health(league_id,nfl_season,market_week,captured_at,observed_at,status,model_version,payload)
  values(j.league_id,(select nfl_season from public.leagues where id=j.league_id),j.market_week,clock_timestamp(),observed,'blocked',left(p_snapshot->>'model_version',80),'{}') on conflict do nothing;
 perform 1 from public.live_forecast_health where league_id=j.league_id for update;
 if exists(select 1 from public.live_forecast_health where league_id=j.league_id and observed_at>observed) then
  update public.live_forecast_health set skipped_requests=skipped_requests+1,last_gap_reason='old_observation' where league_id=j.league_id;
  return c.id;
 end if;
 if reason is null then
  select count(*),coalesce(sum(octet_length(payload::text)),0) into slots,used_bytes from public.live_forecast_samples where league_id=j.league_id;
  select id,octet_length(payload::text) into result,old_bytes from public.live_forecast_samples where league_id=j.league_id
   and nfl_season=(select nfl_season from public.leagues where id=j.league_id) and market_week=j.market_week and horizon=(p->>'horizon')::integer;
  if exists(select 1 from public.live_forecast_samples where id=result and cycle_id=c.id) then return result;end if;
  if exists(select 1 from public.live_forecast_samples where id=result and observed_at>=observed) then reason:='old_observation';
  elsif result is null and slots>=128 then reason:='row_budget';
  elsif used_bytes-coalesce(old_bytes,0)+octet_length(slim::text)>8388608 then reason:='byte_budget';end if;
 end if;
 if reason is not null then
  update public.live_forecast_health set skipped_requests=skipped_requests+1,last_gap_reason=reason,
   captured_at=clock_timestamp(),observed_at=observed,status='blocked',nfl_season=(select nfl_season from public.leagues where id=j.league_id),market_week=j.market_week,
   payload=jsonb_build_object('teams','[]'::jsonb,'quotes','[]'::jsonb,'reason','Optional evaluation capture unavailable: '||reason)
   where league_id=j.league_id;
  return c.id;
 end if;
 insert into public.live_forecast_samples(league_id,nfl_season,market_week,horizon,cycle_id,captured_at,observed_at,model_version,payload)
 values(j.league_id,(select nfl_season from public.leagues where id=j.league_id),j.market_week,(p->>'horizon')::integer,c.id,clock_timestamp(),observed,left(p_snapshot->>'model_version',80),slim)
 on conflict(league_id,nfl_season,market_week,horizon) do update set cycle_id=excluded.cycle_id,captured_at=excluded.captured_at,
 observed_at=excluded.observed_at,model_version=excluded.model_version,payload=excluded.payload returning id into result;
 update public.live_forecast_health set captured_requests=captured_requests+1,captured_at=clock_timestamp(),observed_at=observed,status='shadow',payload=slim,
  nfl_season=(select nfl_season from public.leagues where id=j.league_id),market_week=j.market_week,model_version=left(p_snapshot->>'model_version',80) where league_id=j.league_id;
 return result;
end; $function$
;

REVOKE ALL ON FUNCTION "public"."save_live_shadow"(p_job uuid, p_attempt integer, p_snapshot jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_live_shadow"(p_job uuid, p_attempt integer, p_snapshot jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION public.save_market_board(p_board uuid, p_league uuid, p_week integer, p_opens timestamp with time zone, p_closes timestamp with time zone, p_quotes jsonb, p_status text DEFAULT 'draft'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET work_mem TO '16MB'
 SET statement_timeout TO '45s'
AS $function$
declare v_league public.leagues; v_board public.sportsbook_boards;
begin
 if not sportsbook_private.is_admin(p_league) then raise exception 'Only the league admin can manage markets.'; end if;
 if p_status is null or p_quotes is null or p_status not in ('draft','published','closed') or jsonb_typeof(p_quotes)<>'array' or jsonb_array_length(p_quotes)>1500 then raise exception 'Invalid market board.'; end if;
 if p_status='published' and (p_closes<=now() or jsonb_array_length(p_quotes)=0) then raise exception 'Add markets and a future cutoff before publishing.'; end if;
 select * into v_league from public.leagues where id=p_league;
 select * into v_board from public.sportsbook_boards where id=p_board for update;
 if found and (v_board.league_id<>p_league or v_board.market_week<>p_week or v_board.board_type<>'weekly') then raise exception 'Board identity does not match this league and week.'; end if;
 -- Validate the complete replacement before any quote changes.
 if exists(select 1 from jsonb_array_elements(p_quotes) q join public.sportsbook_markets m on m.id=(q->>'id')::uuid where m.board_id<>p_board) then raise exception 'A quote belongs to a different board.'; end if;
 if exists(select 1 from jsonb_array_elements(p_quotes) q cross join lateral (values(nullif(q->>'team_id','')::uuid),(nullif(q->>'home_team_id','')::uuid),(nullif(q->>'away_team_id','')::uuid)) x(id) where x.id is not null and not exists(select 1 from public.teams t where t.id=x.id and t.league_id=p_league)) then raise exception 'Market teams must belong to this league.'; end if;
 if exists(select 1 from jsonb_array_elements(p_quotes) q where (q->>'boost_pct')::int=25 and not ((q->>'featured'='Game of the Week' and q->>'kind'='moneyline') or (q->>'featured'='Tank Bowl' and (q->>'kind'='moneyline' or (q->>'kind'='match_total' and q->>'side'='over'))))) then raise exception 'This selection is not eligible for the featured boost.'; end if;
 insert into public.sportsbook_boards(id,league_id,market_week,nfl_season,league_season,opens_at,closes_at,status)
 values(p_board,p_league,p_week,v_league.nfl_season,v_league.league_season,p_opens,p_closes,p_status)
 on conflict(id) do update set opens_at=excluded.opens_at,closes_at=excluded.closes_at,status=excluded.status,revision=public.sportsbook_boards.revision+1;
 update public.sportsbook_markets m set active=false where m.board_id=p_board and m.active and not exists(select 1 from jsonb_array_elements(p_quotes) q where q->>'market_key'=m.market_key and q->>'side'=m.side);
 insert into public.sportsbook_markets(id,board_id,market_key,matchup_key,kind,label,subject,side,line,odds,boost_pct,team_id,home_team_id,away_team_id,home_projection,away_projection,featured,metadata)
 select q.id,p_board,q.market_key,nullif(q.matchup_key,''),q.kind,q.label,q.subject,q.side,q.line,q.odds,coalesce(q.boost_pct,0),q.team_id,q.home_team_id,q.away_team_id,q.home_projection,q.away_projection,coalesce(q.featured,''),coalesce(q.metadata,'{}'::jsonb)
 from jsonb_to_recordset(p_quotes) as q(id uuid,market_key text,matchup_key text,kind text,label text,subject text,side text,line numeric,odds integer,boost_pct integer,team_id uuid,home_team_id uuid,away_team_id uuid,home_projection numeric,away_projection numeric,featured text,metadata jsonb)
 on conflict(board_id,market_key,side) do update set market_key=excluded.market_key,matchup_key=excluded.matchup_key,kind=excluded.kind,label=excluded.label,subject=excluded.subject,side=excluded.side,line=excluded.line,odds=excluded.odds,boost_pct=excluded.boost_pct,team_id=excluded.team_id,home_team_id=excluded.home_team_id,away_team_id=excluded.away_team_id,home_projection=excluded.home_projection,away_projection=excluded.away_projection,featured=excluded.featured,metadata=excluded.metadata,active=true
 where ROW(public.sportsbook_markets.market_key,public.sportsbook_markets.matchup_key,public.sportsbook_markets.kind,public.sportsbook_markets.label,public.sportsbook_markets.subject,public.sportsbook_markets.side,public.sportsbook_markets.line,public.sportsbook_markets.odds,public.sportsbook_markets.boost_pct,public.sportsbook_markets.team_id,public.sportsbook_markets.home_team_id,public.sportsbook_markets.away_team_id,public.sportsbook_markets.home_projection,public.sportsbook_markets.away_projection,public.sportsbook_markets.featured,public.sportsbook_markets.metadata,public.sportsbook_markets.active) IS DISTINCT FROM ROW(excluded.market_key,excluded.matchup_key,excluded.kind,excluded.label,excluded.subject,excluded.side,excluded.line,excluded.odds,excluded.boost_pct,excluded.team_id,excluded.home_team_id,excluded.away_team_id,excluded.home_projection,excluded.away_projection,excluded.featured,excluded.metadata,true);
 perform sportsbook_private.capture_forecast(p_board);
 return p_board;
end $function$
;

REVOKE ALL ON FUNCTION "public"."save_market_board"(p_board uuid, p_league uuid, p_week integer, p_opens timestamp with time zone, p_closes timestamp with time zone, p_quotes jsonb, p_status text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_market_board"(p_board uuid, p_league uuid, p_week integer, p_opens timestamp with time zone, p_closes timestamp with time zone, p_quotes jsonb, p_status text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.save_model_assessment(p_job uuid, p_attempt integer, p_hash text, p_outcome jsonb, p_report jsonb, p_comparison jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j public.automation_jobs;o uuid;r uuid;begin
 if auth.role() is distinct from 'service_role' then raise exception 'Worker only.';end if;
 select * into strict j from public.automation_jobs where id=p_job for update;
 if j.operation<>'model_review' or j.status<>'running' or j.attempts<>p_attempt or j.lease_until<=now() then raise exception 'Assessment lease lost.';end if;
 if p_outcome->>'final' is distinct from 'true' or p_outcome->>'completed_period' is distinct from 'true' or p_outcome->>'confirmed_games_final' is distinct from 'true' or p_report->>'status' is distinct from 'complete' then raise exception 'Confirmed outcomes required.';end if;
 if exists(select 1 from public.tickets where league_id=j.league_id and nfl_season=(select nfl_season from public.leagues where id=j.league_id) and market_week=j.market_week and ticket_type<>'future' and status='OPEN') then raise exception 'Weekly settlement reconciliation pending.';end if;
 
 if p_report->>'retention_format' is distinct from 'transient-evaluation-v1' then raise exception 'Temporary evaluation format required.';end if;
 if p_report->>'retention_format'='transient-evaluation-v1' then
  perform 1 from public.model_controls where league_id=j.league_id for update;
  if exists(select 1 from public.model_evaluation_summaries where league_id=j.league_id and nfl_season=(select nfl_season from public.leagues where id=j.league_id)
   and market_week=j.market_week and retired_at is not null) then raise exception 'Row-level correction window closed.';end if;
  select id into r from public.model_weekly_reviews where league_id=j.league_id and nfl_season=(select nfl_season from public.leagues where id=j.league_id) and market_week=j.market_week and input_hash=p_hash;
  if r is not null then return r;end if;
  if octet_length(p_report::text)>1048576 or octet_length(p_outcome::text)>262144 or octet_length(p_comparison::text)>32768 then raise exception 'Assessment diagnostic row budget exceeded.';end if;
  if (select count(*) from public.model_weekly_reviews where league_id=j.league_id and report->>'retention_format'='transient-evaluation-v1')>=64
   or (select coalesce(sum(octet_length(report::text)),0) from public.model_weekly_reviews where league_id=j.league_id and report->>'retention_format'='transient-evaluation-v1')+
    (select coalesce(sum(octet_length(outcome::text)),0) from public.model_outcome_revisions where league_id=j.league_id and outcome->>'retention_format'='transient-evaluation-v1')+
    octet_length(p_report::text)+octet_length(p_outcome::text)>33554432 then raise exception 'Assessment diagnostic league budget exceeded.';end if;
 end if;
 insert into public.model_outcome_revisions(league_id,nfl_season,market_week,outcome_hash,outcome)
 values(j.league_id,(select nfl_season from public.leagues where id=j.league_id),j.market_week,md5(p_outcome::text),p_outcome)
 on conflict(league_id,nfl_season,market_week,outcome_hash) do nothing returning id into o;
 if o is null then select id into o from public.model_outcome_revisions where league_id=j.league_id and nfl_season=(select nfl_season from public.leagues where id=j.league_id) and market_week=j.market_week and outcome_hash=md5(p_outcome::text);end if;
 insert into public.model_weekly_reviews(league_id,nfl_season,market_week,outcome_id,input_hash,report,comparison)
 values(j.league_id,(select nfl_season from public.leagues where id=j.league_id),j.market_week,o,p_hash,p_report,p_comparison)
 on conflict(league_id,nfl_season,market_week,input_hash) do nothing returning id into r;
 if r is null then select id into r from public.model_weekly_reviews where league_id=j.league_id and nfl_season=(select nfl_season from public.leagues where id=j.league_id) and market_week=j.market_week and input_hash=p_hash;end if;
 return r;
end $function$
;

REVOKE ALL ON FUNCTION "public"."save_model_assessment"(p_job uuid, p_attempt integer, p_hash text, p_outcome jsonb, p_report jsonb, p_comparison jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_model_assessment"(p_job uuid, p_attempt integer, p_hash text, p_outcome jsonb, p_report jsonb, p_comparison jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION public.save_model_forecast(p_run uuid, p_league uuid, p_season integer, p_week integer, p_category text, p_version uuid, p_sources jsonb, p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '20s'
AS $function$
declare c public.model_config_versions;context_id uuid;context_hash text;slim jsonb;deadline timestamptz;
 prediction_time timestamptz;latest_prediction timestamptz;slots integer;used_bytes bigint;required_slots integer;old_bytes bigint;new_bytes integer;h text;
begin
 if auth.role() is distinct from 'service_role' and not sportsbook_private.is_admin(p_league) then raise exception 'League admin only.';end if;
 if not exists(select 1 from public.leagues where id=p_league and nfl_season=p_season) then raise exception 'Season mismatch.';end if;
 if p_run is null or p_week is null or p_week not between 1 and 18 or p_category is null or p_category not in ('Matchups','Player Points','Weekly Specials','Season Futures') then raise exception 'Invalid forecast scope.';end if;
 select * into strict c from public.model_config_versions where league_id=p_league and id=p_version;
 if jsonb_typeof(p_payload->'quotes') is distinct from 'array' then raise exception 'Invalid forecast selections.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'quotes') q where q->'metadata'->>'assessment_run_id' is distinct from p_run::text) then raise exception 'Forecast run context mismatch.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'quotes') q cross join lateral unnest(array[q->>'team_id',q->>'home_team_id',q->>'away_team_id']) t(id) where t.id is not null and not exists(select 1 from public.teams where id=t.id::uuid and league_id=p_league)) then raise exception 'Forecast team outside league.';end if;
 insert into public.model_evaluation_health(league_id) values(p_league) on conflict do nothing;
 -- A stable per-league lock serializes budget admission and opening/final writes.
 perform 1 from public.model_evaluation_health where league_id=p_league for update;
 insert into public.model_evaluation_coverage(league_id,nfl_season,market_week,category,requests)
   values(p_league,p_season,p_week,p_category,1)
   on conflict(league_id,nfl_season,market_week,category) do update set requests=model_evaluation_coverage.requests+1;
 if p_payload->>'retention_format' is distinct from 'compact-forecast-v1' then
   perform sportsbook_private.evaluation_gap(p_league,'unsupported_format',p_season,p_week,p_category);return p_run;
 end if;
 if jsonb_typeof(p_payload->'models') is distinct from 'array' or jsonb_typeof(p_payload->'pool') is distinct from 'array'
   or jsonb_array_length(p_payload->'models')>16 or jsonb_array_length(p_payload->'pool')>512 or jsonb_array_length(p_payload->'quotes')>1500 then raise exception 'Invalid compact evaluation targets.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'models') m where not exists(select 1 from public.teams t where t.id=(m->>'id')::uuid and t.league_id=p_league)) then raise exception 'Forecast model outside league.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'models') m where jsonb_typeof(m->'mean') is distinct from 'number'
   or jsonb_typeof(m->'sd') is distinct from 'number' or jsonb_typeof(m->'lineup') is distinct from 'array'
   or jsonb_array_length(m->'lineup')>32) then raise exception 'Invalid compact team predictions.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'pool') p where jsonb_typeof(p->'expected') is distinct from 'number'
   or jsonb_typeof(p->'id') is distinct from 'string' or length(p->>'id')>80
   or jsonb_typeof(p->'positions') is distinct from 'array' or jsonb_array_length(p->'positions')>8
   or length(coalesce(p->>'injury',''))>24) then raise exception 'Invalid compact player predictions.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'pool') p where
   (p->'assessment_sd' is not null and p->'assessment_sd'<>'null'::jsonb and jsonb_typeof(p->'assessment_sd')<>'number')
   or (p->'injury' is not null and p->'injury'<>'null'::jsonb and jsonb_typeof(p->'injury')<>'string')) then raise exception 'Invalid compact player flags.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'models') m,lateral jsonb_array_elements(m->'lineup') l
   where jsonb_typeof(l->'id') is distinct from 'string' or length(l->>'id')>80) then raise exception 'Invalid compact lineup target IDs.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'pool') p,lateral jsonb_array_elements(p->'positions') x
   where jsonb_typeof(x)<>'string' or length(x::text)>40) then raise exception 'Invalid compact position flags.';end if;
 if p_payload->'algorithm_version' is not null and p_payload->'algorithm_version'<>'null'::jsonb
   and (jsonb_typeof(p_payload->'algorithm_version')<>'string' or length(p_payload->>'algorithm_version')>80) then raise exception 'Invalid algorithm version.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'quotes') q,lateral jsonb_each(q) v
   where v.key in ('line','odds') and v.value<>'null'::jsonb and jsonb_typeof(v.value)<>'number') then raise exception 'Invalid compact price metadata.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'quotes') q,lateral jsonb_each(q) v
   where v.key in ('id','market_key','kind','side','team_id','home_team_id','away_team_id') and v.value<>'null'::jsonb
   and (jsonb_typeof(v.value)<>'string' or length(v.value::text)>200)) then raise exception 'Invalid compact selection identity.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'quotes') q,lateral jsonb_each(q->'metadata') v
   where v.key in ('projection_targets','win_distribution','player_distribution') and v.value<>'null'::jsonb
   and jsonb_typeof(v.value)<>'object') then raise exception 'Invalid compact numeric maps.';end if;
 if exists(select 1 from jsonb_each(case when jsonb_typeof(p_payload->'source_quality')='object' then p_payload->'source_quality' else '{}'::jsonb end) v
   where v.key in ('source_count','unknown_observation_times') and v.value<>'null'::jsonb and jsonb_typeof(v.value)<>'number') then raise exception 'Invalid compact source quality.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'quotes') q,
   lateral jsonb_each(case when jsonb_typeof(q->'metadata'->'projection_targets')='object' then q->'metadata'->'projection_targets' else '{}'::jsonb end) t
   where jsonb_typeof(t.value)<>'number' or not exists(select 1 from public.teams where id=t.key::uuid and league_id=p_league))
   then raise exception 'Invalid compact projection targets.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'quotes') q,
   lateral jsonb_each(case when jsonb_typeof(q->'metadata'->'win_distribution')='object' then q->'metadata'->'win_distribution' else '{}'::jsonb end) t
   where t.key !~ '^([0-9]|1[0-8])$' or jsonb_typeof(t.value)<>'number' or t.value::numeric not between 0 and 1)
   then raise exception 'Invalid compact win distribution.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'quotes') q,
   lateral jsonb_each(case when jsonb_typeof(q->'metadata'->'player_distribution')='object' then q->'metadata'->'player_distribution' else '{}'::jsonb end) t
   where t.key in ('mean','sd') and jsonb_typeof(t.value)<>'number')
   then raise exception 'Invalid compact player distribution.';end if;
 if jsonb_typeof(p_payload->'specials')='object' then
   if exists(select 1 from jsonb_each(p_payload->'specials') s where s.key in ('high','low','counts150','countsProjection')
     and (jsonb_typeof(s.value)<>'array' or jsonb_array_length(s.value)>32)) then raise exception 'Invalid compact special bins.';end if;
   if exists(select 1 from jsonb_each(p_payload->'specials') s,
     lateral jsonb_each(case when s.key in ('average_summary','highest_summary') and jsonb_typeof(s.value)='object' then s.value else '{}'::jsonb end) v
     where s.key in ('average_summary','highest_summary') and v.value<>'null'::jsonb and jsonb_typeof(v.value)<>'number')
     then raise exception 'Invalid compact special summary.';end if;
   if exists(select 1 from jsonb_each(p_payload->'specials') s,
     lateral jsonb_array_elements(case when s.key in ('high','low','counts150','countsProjection') then s.value else '[]'::jsonb end) x
     where jsonb_typeof(x)<>'number' or x::numeric not between 0 and 1) then raise exception 'Invalid compact special probabilities.';end if;
 end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'quotes') q,lateral jsonb_each(q->'metadata') v
   where v.key in ('margin_lower','margin_upper','expected_team_count','roster_id','fair_probability','simulated_probability','expected_points','expected_wins','sleeper_projection')
   and v.value<>'null'::jsonb and jsonb_typeof(v.value)<>'number') then raise exception 'Invalid compact numeric metadata.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'quotes') q,lateral jsonb_each(q->'metadata') v
   where v.key in ('assessment_run_id','player_id','opponent_player_id') and v.value<>'null'::jsonb
   and (jsonb_typeof(v.value)<>'string' or length(v.value::text)>100)) then raise exception 'Invalid compact identity metadata.';end if;
 if exists(select 1 from jsonb_array_elements(p_payload->'quotes') q where q->'metadata'->'lineup_locked' is not null
   and q->'metadata'->'lineup_locked'<>'null'::jsonb and jsonb_typeof(q->'metadata'->'lineup_locked')<>'boolean') then raise exception 'Invalid compact lock metadata.';end if;
 
 if exists(select 1 from jsonb_array_elements(p_payload->'pool') p where p->'sleeper_projection' is not null
   and p->'sleeper_projection'<>'null'::jsonb and jsonb_typeof(p->'sleeper_projection')<>'number') then raise exception 'Invalid Sleeper input benchmark.';end if;
 begin deadline:=(p_payload->>'pregame_cutoff')::timestamptz;
 exception when invalid_datetime_format or datetime_field_overflow then deadline:=null;end;
 if deadline is null then perform sportsbook_private.evaluation_gap(p_league,'unknown_cutoff',p_season,p_week,p_category);return p_run;end if;
 if deadline<=clock_timestamp() then perform sportsbook_private.evaluation_gap(p_league,'post_cutoff',p_season,p_week,p_category);return p_run;end if;
 if jsonb_array_length(p_payload->'quotes')=0 then perform sportsbook_private.evaluation_gap(p_league,'empty_family',p_season,p_week,p_category);return p_run;end if;
 if jsonb_typeof(p_sources->'scoring_settings') is distinct from 'object' or jsonb_typeof(p_sources->'roster_positions') is distinct from 'array'
   or octet_length((p_sources->'scoring_settings')::text)+octet_length((p_sources->'roster_positions')::text)>8192 then
   perform sportsbook_private.evaluation_gap(p_league,'invalid_context',p_season,p_week,p_category);return p_run;
 end if;
 if exists(select 1 from jsonb_each(p_sources->'scoring_settings') s where jsonb_typeof(s.value)<>'number')
   or exists(select 1 from jsonb_array_elements(p_sources->'roster_positions') r where jsonb_typeof(r)<>'string' or length(r::text)>40)
   then perform sportsbook_private.evaluation_gap(p_league,'invalid_context',p_season,p_week,p_category);return p_run;end if;
 
 begin prediction_time:=coalesce((p_payload->>'generated_at')::timestamptz,clock_timestamp());
 exception when invalid_datetime_format or datetime_field_overflow then
   perform sportsbook_private.evaluation_gap(p_league,'unknown_cutoff',p_season,p_week,p_category);return p_run;
 end;
 if prediction_time<clock_timestamp()-interval '5 minutes' or prediction_time>clock_timestamp()+interval '30 seconds' then
   perform sportsbook_private.evaluation_gap(p_league,'unknown_cutoff',p_season,p_week,p_category);return p_run;
 end if;
 slim:=sportsbook_private.compact_evaluation_payload(p_payload)||jsonb_build_object('prediction_at',prediction_time);
 new_bytes:=octet_length(slim::text);
 
 if new_bytes>262144 then perform sportsbook_private.evaluation_gap(p_league,'sample_too_large',p_season,p_week,p_category);return p_run;end if;
 context_hash:=md5((p_sources->'scoring_settings')::text || ':' || (p_sources->'roster_positions')::text);
 
 if exists(select 1 from public.model_evaluation_samples s join public.model_prediction_contexts v on v.id=s.context_version and v.league_id=s.league_id
   where s.league_id=p_league and s.run_id=p_run and
   ((s.payload-'prediction_at')<>(slim-'prediction_at') or s.model_version<>p_version or v.fingerprint<>context_hash)) then
   raise exception 'Retained forecast run collision.';
 end if;
 -- A retained run retry is idempotent even after a newer final slot was saved.
 if exists(select 1 from public.model_evaluation_samples where league_id=p_league and run_id=p_run) then return p_run;end if;
 select max(coalesce((payload->>'prediction_at')::timestamptz,captured_at)) into latest_prediction
   from public.model_evaluation_samples where league_id=p_league and nfl_season=p_season and market_week=p_week and category=p_category;
 -- An overwritten intermediate run has no permanent tombstone. Its generation
 -- time still prevents a late delivery from replacing newer retained evidence.
 if latest_prediction is not null and prediction_time<=latest_prediction then return p_run;end if;
 select id into context_id from public.model_prediction_contexts where league_id=p_league and fingerprint=context_hash;
 
 if context_id is not null and exists(select 1 from public.model_prediction_contexts where id=context_id
   and (scoring_settings<>p_sources->'scoring_settings' or roster_positions<>p_sources->'roster_positions')) then raise exception 'Prediction context fingerprint collision.';end if;
 if context_id is null and (select count(*) from public.model_prediction_contexts where league_id=p_league)>=64 then
   perform sportsbook_private.evaluation_gap(p_league,'context_budget',p_season,p_week,p_category);return p_run;
 end if;
 select count(*)::integer,coalesce(sum(payload_bytes),0) into slots,used_bytes from public.model_evaluation_samples where league_id=p_league;
 required_slots:=case when p_category='Season Futures' then 1 else 2 end;
 select required_slots-count(*)::integer,coalesce(sum(payload_bytes),0) into required_slots,old_bytes
   from public.model_evaluation_samples where league_id=p_league and nfl_season=p_season and market_week=p_week and category=p_category;
 if slots+required_slots>256 then perform sportsbook_private.evaluation_gap(p_league,'row_budget',p_season,p_week,p_category);return p_run;end if;
 -- Opening remains fixed; only the provisional final slot is replaceable.
 select coalesce(sum(payload_bytes),0) into old_bytes from public.model_evaluation_samples
   where league_id=p_league and nfl_season=p_season and market_week=p_week and category=p_category and horizon='final_pregame';
 if used_bytes-old_bytes+new_bytes*(required_slots+case when old_bytes>0 then 1 else 0 end)>8388608 then
   perform sportsbook_private.evaluation_gap(p_league,'byte_budget',p_season,p_week,p_category);return p_run;
 end if;
 if context_id is null then
   insert into public.model_prediction_contexts(league_id,fingerprint,scoring_settings,roster_positions)
     values(p_league,context_hash,p_sources->'scoring_settings',p_sources->'roster_positions') returning id into context_id;
 end if;
 if exists(select 1 from public.model_evaluation_samples where league_id=p_league and run_id=p_run
   and (payload<>slim or model_version<>p_version or context_version<>context_id)) then raise exception 'Retained forecast run collision.';end if;
 foreach h in array case when p_category='Season Futures' then array['opening'] else array['opening','final_pregame'] end loop
   insert into public.model_evaluation_samples(run_id,league_id,nfl_season,market_week,category,horizon,captured_at,cutoff,model_version,context_version,payload)
   values(p_run,p_league,p_season,p_week,p_category,h,clock_timestamp(),deadline,p_version,context_id,slim)
   on conflict(league_id,nfl_season,market_week,category,horizon) do update
     set run_id=excluded.run_id,captured_at=excluded.captured_at,cutoff=excluded.cutoff,
         model_version=excluded.model_version,context_version=excluded.context_version,payload=excluded.payload
     where model_evaluation_samples.horizon='final_pregame' and model_evaluation_samples.run_id<>excluded.run_id;
 end loop;
 update public.model_evaluation_health set last_capture_at=now(),captured_requests=captured_requests+1 where league_id=p_league;
 update public.model_evaluation_coverage set stored_requests=stored_requests+1,last_capture_at=now()
   where league_id=p_league and nfl_season=p_season and market_week=p_week and category=p_category;
 return p_run;
end $function$
;

REVOKE ALL ON FUNCTION "public"."save_model_forecast"(p_run uuid, p_league uuid, p_season integer, p_week integer, p_category text, p_version uuid, p_sources jsonb, p_payload jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_model_forecast"(p_run uuid, p_league uuid, p_season integer, p_week integer, p_category text, p_version uuid, p_sources jsonb, p_payload jsonb) TO "authenticated";

GRANT EXECUTE ON FUNCTION "public"."save_model_forecast"(p_run uuid, p_league uuid, p_season integer, p_week integer, p_category text, p_version uuid, p_sources jsonb, p_payload jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION public.save_my_notification_preferences(p_league uuid, p_revision integer, p_values jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare current_revision integer;begin
 if not sportsbook_private.notification_participant(p_league,auth.uid()) then raise exception 'Approved league participant required.';end if;
 if not sportsbook_private.valid_notification_values(p_values,false) then raise exception 'Use only supported notification choices.';end if;
 perform pg_advisory_xact_lock(hashtextextended('notification-defaults:'||p_league,0));
 perform pg_advisory_xact_lock(hashtextextended('notification-user:'||p_league||':'||auth.uid(),0));
 select revision into current_revision from sportsbook_private.notification_preferences where league_id=p_league and user_id=auth.uid();
 if p_revision is distinct from coalesce(current_revision,0) then raise exception 'Notification preferences changed; reload before saving.';end if;
 if current_revision is null and (select count(*) from sportsbook_private.notification_preferences where league_id=p_league)>=128 then raise exception 'Notification preference capacity reached.';end if;
 insert into sportsbook_private.notification_preferences(league_id,user_id,values)values(p_league,auth.uid(),p_values)
 on conflict(league_id,user_id) do update set values=excluded.values,revision=notification_preferences.revision+1,updated_at=clock_timestamp();
 return public.my_notification_preferences(p_league);
end $function$
;

REVOKE ALL ON FUNCTION "public"."save_my_notification_preferences"(p_league uuid, p_revision integer, p_values jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_my_notification_preferences"(p_league uuid, p_revision integer, p_values jsonb) TO "authenticated";

CREATE OR REPLACE FUNCTION public.save_promo(p_league uuid, p_id uuid, p_version integer, p_offer jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare o public.promo_offers;l public.leagues;t jsonb:=p_offer->'terms';q public.sportsbook_markets; leg jsonb; frozen jsonb:='[]'; st text:=p_offer->>'status'; at timestamptz;
begin
 if not sportsbook_private.is_admin(p_league) then raise exception 'League admin required.';end if;
 select * into strict l from public.leagues where id=p_league;
 if p_offer->>'kind' not in ('boost','fixed') or st not in ('draft','scheduled') or st is null or p_offer->>'kind' is null then raise exception 'Invalid offer type or state.';end if;
 if (p_offer->>'expires_at')::timestamptz<=now() then raise exception 'Choose a future expiry.';end if;
 if p_id is not null then
  select * into o from public.promo_offers where id=p_id and league_id=p_league for update;
  if not found or o.version is distinct from p_version then raise exception 'Offer changed. Reload before saving.';end if;
  if o.status<>'draft' then raise exception 'Advertised terms are locked. Create a new draft version.';end if;
 end if;
 if p_offer->>'kind'='boost' then
  if t->>'criterion' not in ('points_min','points_exact','spreads_min','parlay_min','category','featured') or t->>'criterion' is null or
   (t->>'count')::int not between 1 and 10 or (t->>'count') is null or (t->>'percent')::numeric not between 1 and 1000 or t->>'percent' is null or
   (t->>'max_stake')::numeric<1 or t->>'max_stake' is null then raise exception 'Choose valid eligibility, percentage and maximum wager.';end if;
  if t->>'criterion'='category' and (t->>'category' is null or t->>'category' not in ('player_points','spread','moneyline','match_total','team_total','weekly')) then raise exception 'Choose an approved category.';end if;
  if length(coalesce(t->>'code',''))>40 or (t->>'max_stake')::numeric<>round((t->>'max_stake')::numeric,2) or (t->>'max_stake')::numeric>9999999999.99 then raise exception 'Use a code up to 40 characters and a whole-cent maximum wager.';end if;
  if t->>'criterion'='featured' and not exists(select 1 from public.sportsbook_markets m join public.sportsbook_boards b on b.id=m.board_id where b.league_id=p_league and b.nfl_season=l.nfl_season and b.market_week=(p_offer->>'week')::int and m.matchup_key=t->>'matchup') then raise exception 'Choose a matchup from this league and week.';end if;
  t:=jsonb_build_object('criterion',t->>'criterion','count',(t->>'count')::int,'percent',(t->>'percent')::numeric,'max_stake',(t->>'max_stake')::numeric,'category',t->>'category','matchup',t->>'matchup','code',upper(trim(coalesce(t->>'code',''))));
 else
  if jsonb_typeof(t->'legs') is distinct from 'array' or jsonb_array_length(t->'legs') not between 2 and 10 then raise exception 'Choose 2–10 fixed selections.';end if;
  for leg in select value from jsonb_array_elements(t->'legs') loop
   select m.* into q from public.sportsbook_markets m join public.sportsbook_boards b on b.id=m.board_id where m.id=(leg->>'id')::uuid and b.league_id=p_league and b.market_week=(p_offer->>'week')::int and b.nfl_season=l.nfl_season and b.board_type='weekly';
   if not found then raise exception 'Fixed selections must belong to this league and week.';end if;
   if q.boost_pct>0 or q.kind like 'future_%' then raise exception 'Fixed offers cannot stack featured boosts or futures.';end if;
   q.line:=coalesce((leg->>'line')::numeric,q.line);q.odds:=(leg->>'odds')::int;q.label:=leg->>'label';q.active:=true;q.market_state:='open';q.suspension_reason:=null;
   if abs(q.odds::bigint) not between 100 and 100000 or q.odds is null or length(q.label) not between 1 and 160 or q.label is null then raise exception 'Enter valid saved labels and odds.';end if;
   if exists(select 1 from jsonb_populate_recordset(null::public.sportsbook_markets,frozen) f where f.id=q.id or f.market_key=q.market_key or public.sportsbook_special_conflict(f,q) or (f.matchup_key=q.matchup_key and ((f.kind='spread' and q.kind='moneyline') or (f.kind='moneyline' and q.kind='spread')))) then raise exception 'Fixed selections are incompatible.';end if;
   frozen:=frozen||jsonb_build_array(to_jsonb(q));
  end loop;
  if t->>'fixed_stake' is not null and ((t->>'fixed_stake')::numeric<1 or (t->>'fixed_stake')::numeric<>round((t->>'fixed_stake')::numeric,2)) then raise exception 'Fixed wager must be whole cents and at least $1.';end if;
  t:=jsonb_build_object('legs',frozen,'fixed_stake',(t->>'fixed_stake')::numeric);
 end if;
 if st='scheduled' then select greatest(now(),b.opens_at) into at from public.sportsbook_boards b where b.league_id=p_league and b.nfl_season=l.nfl_season and b.market_week=(p_offer->>'week')::int and b.board_type='weekly' and b.status='published';end if;
 if p_id is null then
  insert into public.promo_offers(league_id,nfl_season,market_week,slot,kind,title,description,image_id,expires_at,status,terms,activated_at)
  values(p_league,l.nfl_season,(p_offer->>'week')::int,(p_offer->>'slot')::int,p_offer->>'kind',trim(p_offer->>'title'),trim(p_offer->>'description'),(p_offer->>'image_id')::uuid,(p_offer->>'expires_at')::timestamptz,st,t,at) returning id into p_id;
 else
  update public.promo_offers set market_week=(p_offer->>'week')::int,slot=(p_offer->>'slot')::int,kind=p_offer->>'kind',title=trim(p_offer->>'title'),description=trim(p_offer->>'description'),image_id=(p_offer->>'image_id')::uuid,expires_at=(p_offer->>'expires_at')::timestamptz,status=st,terms=t,activated_at=at,version=version+1 where id=p_id;
 end if;
 insert into public.promo_events(league_id,offer_id,user_id,event,details) values(p_league,p_id,auth.uid(),st,jsonb_build_object('title',p_offer->>'title'));
 return p_id;
end $function$
;

REVOKE ALL ON FUNCTION "public"."save_promo"(p_league uuid, p_id uuid, p_version integer, p_offer jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_promo"(p_league uuid, p_id uuid, p_version integer, p_offer jsonb) TO "authenticated";

CREATE OR REPLACE FUNCTION public.save_prospective_state(p_job uuid, p_attempt integer, p_active uuid, p_revision integer, p_context text, p_hash text, p_state jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare j public.automation_jobs;ctl public.model_controls;old public.model_prospective_state;next_state jsonb;renew boolean;frozen jsonb;period integer;rev integer;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Worker only.';end if;
 select * into strict j from public.automation_jobs where id=p_job for update;
 if j.operation<>'model_review' or j.status<>'running' or j.attempts<>p_attempt or j.lease_until<=clock_timestamp() then raise exception 'Prospective lease lost.';end if;
 if exists(select 1 from public.tickets where league_id=j.league_id and market_week=j.market_week and nfl_season=(select nfl_season from public.leagues where id=j.league_id)
  and ticket_type<>'future' and status='OPEN') then raise exception 'Settlement reconciliation pending.';end if;
 select * into strict ctl from public.model_controls where league_id=j.league_id for update;
 if ctl.active_id<>p_active then raise exception 'Active model changed.';end if;
 select * into old from public.model_prospective_state where league_id=j.league_id for update;
 if old.last_hash=p_hash and old.active_id=p_active and old.context_hash=p_context then return old.state||jsonb_build_object('revision',old.revision);end if;
 if coalesce(old.revision,0)<>p_revision then raise exception 'Prospective revision changed.';end if;
 if p_context is null or p_context !~ '^[0-9a-f]{64}$' or p_hash is null or p_hash !~ '^[0-9a-f]{64}$' or octet_length(p_state::text)>32768 then raise exception 'Invalid prospective identity/budget.';end if;
 if exists(select 1 from jsonb_object_keys(p_state) k where k not in ('active_id','context_hash','revision','training','fit_training','evidence','monitor','candidate','frozen_at','trained_period','training_weeks','last_period','finished','skipped_weeks'))
  or p_state->>'active_id' is distinct from p_active::text or p_state->>'context_hash' is distinct from p_context then raise exception 'Invalid prospective scope.';end if;
 if jsonb_typeof(p_state->'training') is distinct from 'array' or jsonb_array_length(p_state->'training')>8
  or jsonb_typeof(p_state->'fit_training') is distinct from 'array' or jsonb_array_length(p_state->'fit_training')>8
  or jsonb_typeof(p_state->'evidence') is distinct from 'array' or jsonb_array_length(p_state->'evidence')>32
  or jsonb_typeof(p_state->'monitor') is distinct from 'array' or jsonb_array_length(p_state->'monitor')>4 then raise exception 'Prospective segment budget exceeded.';end if;
 if exists(select 1 from jsonb_array_elements((p_state->'training')||(p_state->'fit_training')) w,lateral jsonb_each(w) f
  where f.key not in ('period','n','prediction','actual','z2','z_n') or jsonb_typeof(f.value)<>'number')
  or exists(select 1 from jsonb_array_elements(p_state->'monitor') w,lateral jsonb_each(w) f where f.key not in ('period','delta') or jsonb_typeof(f.value)<>'number') then raise exception 'Invalid prospective training totals.';end if;
 if exists(select 1 from jsonb_array_elements(p_state->'evidence') w,lateral jsonb_each(w) f where f.key not in
   ('period','prediction_at','phase','n','current','candidate','baseline','sleeper','market_ok') or
   (f.key in ('period','n','current','candidate','baseline','sleeper') and jsonb_typeof(f.value)<>'number'))
  or exists(select 1 from jsonb_array_elements(p_state->'evidence') w where w->>'phase' not in ('validation','holdout')
   or jsonb_typeof(w->'market_ok') is distinct from 'boolean' or (w->>'n')::integer<8) then raise exception 'Invalid prospective evidence.';end if;
 period:=(select nfl_season from public.leagues where id=j.league_id)*100+j.market_week;
 if (select count(distinct w->>'period') from jsonb_array_elements(p_state->'evidence') w)<>jsonb_array_length(p_state->'evidence')
  or (select count(distinct w->>'period') from jsonb_array_elements(p_state->'training') w)<>jsonb_array_length(p_state->'training') then raise exception 'Duplicate prospective periods.';end if;
 if exists(select 1 from jsonb_array_elements(p_state->'evidence') w where w->>'phase'='holdout') and
  ((select count(*) from jsonb_array_elements(p_state->'evidence') w where w->>'phase'='validation')<12 or
   (select coalesce(sum((w->>'n')::integer),0) from jsonb_array_elements(p_state->'evidence') w where w->>'phase'='validation')<120 or
   (select min((w->>'period')::integer) from jsonb_array_elements(p_state->'evidence') w where w->>'phase'='holdout')<=
   (select max((w->>'period')::integer) from jsonb_array_elements(p_state->'evidence') w where w->>'phase'='validation')) then raise exception 'Holdout phase is not untouched.';end if;
 if p_state->>'finished'='true' and jsonb_array_length(p_state->'evidence')<32 and
  ((select count(*) from jsonb_array_elements(p_state->'evidence') w where w->>'phase'='holdout')<4 or
   (select coalesce(sum((w->>'n')::integer),0) from jsonb_array_elements(p_state->'evidence') w where w->>'phase'='holdout')<40) then raise exception 'Prospective cycle is not complete.';end if;
 if (p_state->>'last_period')::integer<>greatest(period,coalesce((old.state->>'last_period')::integer,0)) then raise exception 'Prospective period mismatch.';end if;
 renew:=old.league_id is null or old.active_id<>p_active or old.context_hash<>p_context or
  (old.state->>'finished'='true' and (p_state->>'trained_period')::integer>(old.state->>'last_period')::integer);
 next_state:=p_state-'revision';
 if not renew and old.state->'candidate'<>'null'::jsonb and p_state->'candidate'='null'::jsonb then raise exception 'Frozen candidate cannot be abandoned before the cycle completes.';end if;
 if p_state->'candidate'<>'null'::jsonb then
  if (select count(*) from jsonb_object_keys(p_state->'candidate'))<>2 or exists(select 1 from jsonb_each(p_state->'candidate') x
    where x.key not in ('score_scale','variance_scale') or jsonb_typeof(x.value)<>'number' or x.value::numeric not between .9 and 1.1)
    or exists(select 1 from jsonb_each(p_state->'candidate') x join public.model_config_versions v on v.id=p_active
     where abs(x.value::numeric/(v.config->>x.key)::numeric-1)>.020000001) then raise exception 'Candidate parameter bounds failed.';end if;
  if renew or old.state->'candidate'='null'::jsonb then
   if (p_state->>'trained_period')::integer<>period or jsonb_array_length(p_state->'training')<>8 or jsonb_array_length(p_state->'evidence')<>0
    or p_state->'fit_training'<>p_state->'training' or (p_state->>'training_weeks')::integer<>8 then raise exception 'New candidate requires eight prior completed weeks.';end if;
   frozen:=to_jsonb(clock_timestamp());
  else
   if p_state->'candidate'<>old.state->'candidate' or p_state->'trained_period'<>old.state->'trained_period'
    or p_state->'fit_training'<>old.state->'fit_training' or p_state->'training_weeks'<>old.state->'training_weeks' then raise exception 'Frozen candidate cannot change.';end if;
   frozen:=old.state->'frozen_at';
  end if;
  next_state:=jsonb_set(next_state,'{frozen_at}',frozen);
  if exists(select 1 from jsonb_array_elements(next_state->'evidence') w where (w->>'prediction_at')::timestamptz<=(frozen#>>'{}')::timestamptz
   or (w->>'period')::integer<=(next_state->>'trained_period')::integer) then raise exception 'Evidence predates frozen candidate.';end if;
 end if;
 rev:=coalesce(old.revision,0)+1;
 insert into public.model_prospective_state(league_id,active_id,context_hash,revision,last_hash,state)
 values(j.league_id,p_active,p_context,rev,p_hash,next_state)
 on conflict(league_id) do update set active_id=excluded.active_id,context_hash=excluded.context_hash,revision=excluded.revision,
 last_hash=excluded.last_hash,state=excluded.state,updated_at=clock_timestamp();
 return next_state||jsonb_build_object('revision',rev);
end $function$
;

REVOKE ALL ON FUNCTION "public"."save_prospective_state"(p_job uuid, p_attempt integer, p_active uuid, p_revision integer, p_context text, p_hash text, p_state jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_prospective_state"(p_job uuid, p_attempt integer, p_active uuid, p_revision integer, p_context text, p_hash text, p_state jsonb) TO "service_role";

