CREATE OR REPLACE FUNCTION public.save_sportsbook_policy(p_league uuid, p_expected integer, p_season integer, p_week integer, p_overrides jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare p record;r integer;prior jsonb;begin
 if not public.league_intake_owner()then raise exception 'Verified platform owner required.';end if;
 perform sportsbook_private.validate_sportsbook_policy(p_overrides);
 if p_reason is null or length(trim(p_reason))not between 8 and 400 then raise exception 'Policy review reason required.';end if;
 perform pg_advisory_xact_lock(hashtextextended('sportsbook-policy:'||p_league,0));perform 1 from public.leagues where id=p_league for update;
 if not found then raise exception 'Selected league unavailable.';end if;
 select * into p from public.sportsbook_period(p_league);
 if p_season is null or p_week is null or p_season not between p.nfl_season and p.nfl_season+1 or p_week not between 1 and 18 or(p_season,p_week)<(p.nfl_season,p.week)then raise exception 'Current or future supported period required.';end if;
 if exists(select 1 from public.leagues where id=p_league and operations_enabled)or exists(select 1 from public.weekly_schedule where league_id=p_league and automation_enabled)then raise exception 'Pause operations and automation before policy changes.';end if;
 select coalesce(max(revision),0)into r from sportsbook_private.sportsbook_policy_versions where league_id=p_league;
 if exists(select 1 from sportsbook_private.sportsbook_policy_versions where league_id=p_league and revision=p_expected+1 and nfl_season=p_season and market_week=p_week and overrides=p_overrides and reason=trim(p_reason)and actor=auth.uid())then return jsonb_build_object('revision',p_expected+1,'duplicate',true);end if;
 if p_expected is distinct from r then raise exception 'Policy changed; reload before saving.';end if;
 if r>=64 then raise exception 'Policy history budget reached.';end if;
 if exists(select 1 from sportsbook_private.sportsbook_policy_versions where league_id=p_league and(nfl_season,market_week)>=(p_season,p_week))then raise exception 'Effective policy periods must increase.';end if;
 if exists(select 1 from public.tickets where league_id=p_league and status<>'VOIDED'and(nfl_season,placement_week)>=(p_season,p_week))or exists(select 1 from public.sportsbook_boards where league_id=p_league and status='published'and(nfl_season,market_week)>=(p_season,p_week))then raise exception 'Published boards or accepted tickets exist; choose a later period.';end if;
 prior:=sportsbook_private.sportsbook_policy(p_league,p_season,p_week);
 insert into sportsbook_private.sportsbook_policy_versions(league_id,revision,nfl_season,market_week,overrides,actor,reason)values(p_league,r+1,p_season,p_week,p_overrides,auth.uid(),trim(p_reason));
 insert into public.admin_change_log(league_id,actor_id,category,reason,before_value,after_value)values(p_league,auth.uid(),'sportsbook_policy',trim(p_reason),prior,sportsbook_private.sportsbook_policy(p_league,p_season,p_week));
 return jsonb_build_object('revision',r+1,'duplicate',false);
end $function$
;

REVOKE ALL ON FUNCTION "public"."save_sportsbook_policy"(p_league uuid, p_expected integer, p_season integer, p_week integer, p_overrides jsonb, p_reason text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_sportsbook_policy"(p_league uuid, p_expected integer, p_season integer, p_week integer, p_overrides jsonb, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.save_wallet_policy(p_league uuid, p_expected integer, p_season integer, p_week integer, p_overrides jsonb, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare period record;last_revision integer;prior jsonb;begin
 if not public.league_intake_owner() then raise exception 'Verified platform owner required.';end if;
 if p_reason is null or length(trim(p_reason)) not between 8 and 400 then raise exception 'Policy review reason required.';end if;
 perform sportsbook_private.validate_wallet_policy(p_overrides);
 perform pg_advisory_xact_lock(20261101,17);
 perform 1 from public.leagues where id=p_league for update;
 if not found then raise exception 'Selected league unavailable.';end if;
 select * into period from public.sportsbook_period(p_league);
 if p_season is null or p_week is null or p_season not between period.nfl_season and period.nfl_season+1 or p_week not between 1 and 18
  or (p_season,p_week)<(period.nfl_season,period.week) then raise exception 'Policy must take effect in a current or future supported period.';end if;
 if exists(select 1 from public.leagues where id=p_league and operations_enabled) or exists(select 1 from public.weekly_schedule where league_id=p_league and automation_enabled)
 then raise exception 'Pause operations and automation before reviewing policy.';end if;
 select coalesce(max(revision),0) into last_revision from sportsbook_private.league_policy_versions where league_id=p_league;
 -- Lost-response retries return the original receipt; changed terms never reuse it.
 if exists(select 1 from sportsbook_private.league_policy_versions where league_id=p_league and revision=p_expected+1 and nfl_season=p_season and market_week=p_week and overrides=p_overrides and reason=trim(p_reason) and actor=auth.uid())
 then return jsonb_build_object('revision',p_expected+1,'duplicate',true);end if;
 if p_expected is distinct from last_revision then raise exception 'Policy changed; reload before saving.';end if;
 if last_revision>=64 then raise exception 'Policy history admission budget reached.';end if;
 if exists(select 1 from sportsbook_private.league_policy_versions where league_id=p_league and (nfl_season,market_week)>=(p_season,p_week)) then raise exception 'Policy effective periods must increase; review the scheduled version.';end if;
 if exists(select 1 from public.tickets where league_id=p_league and ticket_type<>'future' and status<>'VOIDED' and (nfl_season,market_week)>=(p_season,p_week))
 then raise exception 'Accepted tickets already exist in the requested policy period; choose a later period.';end if;
 prior:=sportsbook_private.wallet_policy(p_league,p_season,p_week);
 insert into sportsbook_private.league_policy_versions(league_id,revision,nfl_season,market_week,overrides,actor,reason)
 values(p_league,last_revision+1,p_season,p_week,p_overrides,auth.uid(),trim(p_reason));
 insert into public.admin_change_log(league_id,actor_id,category,reason,before_value,after_value)
 values(p_league,auth.uid(),'wallet_policy',trim(p_reason),prior,sportsbook_private.wallet_policy(p_league,p_season,p_week));
 return jsonb_build_object('revision',last_revision+1,'duplicate',false);
end $function$
;

REVOKE ALL ON FUNCTION "public"."save_wallet_policy"(p_league uuid, p_expected integer, p_season integer, p_week integer, p_overrides jsonb, p_reason text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."save_wallet_policy"(p_league uuid, p_expected integer, p_season integer, p_week integer, p_overrides jsonb, p_reason text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.set_league_staff(p_league uuid, p_user uuid, p_role text, p_active boolean, p_reason text, p_expected integer DEFAULT NULL::integer)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare r public.league_staff_grants;v_revision integer;
begin
 if not sportsbook_private.is_platform_owner() then raise exception 'Platform owner required';end if;
 perform pg_advisory_xact_lock(hashtextextended('staff-grants:'||p_league::text,0));
 select * into r from public.league_staff_grants where league_id=p_league and user_id=p_user for update;
 if (r.revision is null and p_expected is not null) or (r.revision is not null and p_expected is distinct from r.revision)
  then raise exception 'Staff access changed; refresh before saving';end if;
 insert into public.league_staff_grants(league_id,user_id,role,active,reason,created_by,updated_by)
 values(p_league,p_user,p_role,p_active,p_reason,auth.uid(),auth.uid())
 on conflict(league_id,user_id) do update set role=excluded.role,active=excluded.active,reason=excluded.reason
 returning revision into v_revision;
 return v_revision;
end $function$
;

REVOKE ALL ON FUNCTION "public"."set_league_staff"(p_league uuid, p_user uuid, p_role text, p_active boolean, p_reason text, p_expected integer) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."set_league_staff"(p_league uuid, p_user uuid, p_role text, p_active boolean, p_reason text, p_expected integer) TO "authenticated";

CREATE OR REPLACE FUNCTION public.set_team_balance(p_team uuid, p_balance numeric, p_reason text, p_request uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_league uuid; v_previous numeric; v_event public.balance_events; v_id uuid;
begin perform pg_advisory_xact_lock_shared(20261101,17);
 if exists(select 1 from public.teams t join sportsbook_private.user_finance_modes f on f.league_id=t.league_id where t.id=p_team and f.enabled)
 then raise exception 'This league uses per-user financial accounts; legacy team cash cannot be edited through this action.';end if;
 
  select league_id into v_league from public.teams where id = p_team;
  if v_league is null or not sportsbook_private.is_admin(v_league) then raise exception 'Admin access required'; end if;
  if p_balance is null or p_balance < 0 or p_balance > 9999999999.99 or p_balance <> round(p_balance, 2) then
    raise exception 'Enter a nonnegative balance with at most two decimal places'; end if;
  if p_reason is null or length(trim(p_reason)) not between 3 and 500 or p_request is null then
    raise exception 'A reason and request reference are required'; end if;
  select balance into v_previous from public.wallets where team_id = p_team for update;
  if not found then raise exception 'Wallet not found'; end if;
  select * into v_event from public.balance_events where team_id = p_team and request_id = p_request;
  if found then
    if v_event.new_balance <> p_balance or v_event.reason <> trim(p_reason) or v_event.actor_id <> auth.uid() then
      raise exception 'Request already used for a different adjustment'; end if;
    return v_event.id;
  end if;
  update public.wallets set balance = p_balance, updated_at = now() where team_id = p_team;
  insert into public.balance_events(team_id, actor_id, request_id, previous_balance, new_balance, reason, kind)
    values(p_team, auth.uid(), p_request, v_previous, p_balance, trim(p_reason),
      case when v_previous is null then 'opening_balance' else 'admin_adjustment' end) returning id into v_id;
  return v_id;
end;
$function$
;

REVOKE ALL ON FUNCTION "public"."set_team_balance"(p_team uuid, p_balance numeric, p_reason text, p_request uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."set_team_balance"(p_team uuid, p_balance numeric, p_reason text, p_request uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION public.set_user_wallet_balance(p_wallet uuid, p_expected numeric, p_balance numeric, p_reason text, p_request uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w public.user_wallets;e public.user_wallet_entries;
begin perform pg_advisory_xact_lock_shared(20261101,17);
 select * into w from public.user_wallets where id=p_wallet for update;
 if not found or not sportsbook_private.is_admin(w.league_id) or not exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null) then raise exception 'League operator required.';end if;
 if p_request is null or p_reason is null or length(trim(p_reason)) not between 8 and 500 or p_balance is null or p_balance::text in ('NaN','Infinity','-Infinity')
  or p_balance<0 or p_balance>9999999999.99 or p_balance<>round(p_balance,2) then raise exception 'Valid whole-cent balance, review reason and request required.';end if;
 select * into e from public.user_wallet_entries where wallet_id=w.id and request_key=p_request;
 if found then
  if e.kind<>'adjustment' or e.balance_after<>p_balance or e.metadata->'expected' is distinct from coalesce(to_jsonb(p_expected),'null'::jsonb)
   or e.reason<>trim(p_reason) then raise exception 'Request already used for another financial change.';end if;
  return jsonb_build_object('wallet_id',w.id,'balance',w.balance,'duplicate',true);
 end if;
 if w.balance is null or w.status<>'approved' then raise exception 'Owner-initialized approved wallet required.';end if;
 if w.balance is distinct from p_expected then raise exception 'Balance changed; review again.';end if;
 insert into public.user_wallet_entries(wallet_id,league_id,team_id,event_key,request_key,kind,amount,balance_before,balance_after,reason,metadata)
  values(w.id,w.league_id,w.team_id,'adjustment:'||p_request,p_request,'adjustment',p_balance-w.balance,w.balance,p_balance,trim(p_reason),jsonb_build_object('expected',p_expected,'actor_id',auth.uid()));
 update public.user_wallets set balance=p_balance,updated_at=clock_timestamp() where id=w.id;
 return jsonb_build_object('wallet_id',w.id,'balance',p_balance,'duplicate',false);
end $function$
;

REVOKE ALL ON FUNCTION "public"."set_user_wallet_balance"(p_wallet uuid, p_expected numeric, p_balance numeric, p_reason text, p_request uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."set_user_wallet_balance"(p_wallet uuid, p_expected numeric, p_balance numeric, p_reason text, p_request uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION public.set_user_wallet_status(p_wallet uuid, p_expected integer, p_status text, p_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare w public.user_wallets;
begin perform pg_advisory_xact_lock_shared(20261101,17);
 if not sportsbook_private.is_platform_owner() or not exists(select 1 from auth.users where id=auth.uid() and email_confirmed_at is not null)
  then raise exception 'Platform owner required.';end if;
 if p_status is null or p_status not in ('approved','revoked') or p_reason is null or length(trim(p_reason)) not between 8 and 400 then raise exception 'Reviewed status and reason required.';end if;
 select * into w from public.user_wallets where id=p_wallet for update;
 if not found or p_expected is distinct from w.revision then raise exception 'Financial approval changed; refresh.';end if;
 if p_status='approved' and not exists(select 1 from auth.users where id=w.user_id and email_confirmed_at is not null) then raise exception 'Verified user required.';end if;
 update public.user_wallets set status=p_status,revision=revision+1,updated_at=clock_timestamp() where id=w.id;
 insert into sportsbook_private.user_wallet_approvals(wallet_id,actor,reason) values(w.id,auth.uid(),'Status '||w.status||' to '||p_status||': '||trim(p_reason));
 return w.revision+1;
end $function$
;

REVOKE ALL ON FUNCTION "public"."set_user_wallet_status"(p_wallet uuid, p_expected integer, p_status text, p_reason text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."set_user_wallet_status"(p_wallet uuid, p_expected integer, p_status text, p_reason text) TO "authenticated";

