CREATE OR REPLACE FUNCTION public.sportsbook_category_snapshot(p_league uuid, p_board uuid, p_category text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare period record;b public.sportsbook_boards;v_markets jsonb;v_result jsonb;
begin
 if p_category not in ('Matchups','Player Points','Head to Head','Weekly Specials','Season Futures') or p_category is null
  then raise exception 'Unknown market category';end if;
 if not sportsbook_private.is_member(p_league) then return null;end if;
 select * into period from public.sportsbook_period(p_league);
 select * into b from public.sportsbook_boards where id=p_board and league_id=p_league and nfl_season=period.nfl_season
  and board_type=case when p_category='Season Futures' then 'future' else 'weekly' end
  and (p_category='Season Futures' or market_week=period.week);
 if b.id is null then return null;end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',m.id,'board_id',m.board_id,'market_key',m.market_key,'matchup_key',m.matchup_key,
  'kind',m.kind,'label',m.label,'subject',m.subject,'side',m.side,'line',m.line,'odds',m.odds,'boost_pct',m.boost_pct,
  'team_id',m.team_id,'home_team_id',m.home_team_id,'away_team_id',m.away_team_id,'home_projection',m.home_projection,
  'away_projection',m.away_projection,'featured',m.featured,'metadata',sportsbook_private.member_quote_metadata(m.metadata),
  'active',m.active,'market_state',m.market_state,'suspension_reason',m.suspension_reason) order by m.market_key,m.side,m.id),'[]'::jsonb)
  into v_markets from public.sportsbook_markets m where m.board_id=b.id and m.active and
   m.kind=any(case p_category
    when 'Player Points' then array['player_points','player_milestone']
    when 'Head to Head' then array['player_h2h']
    when 'Weekly Specials' then array['weekly_high','weekly_low','weekly_count_150','weekly_count_projection','weekly_average','weekly_highest_score','weekly_any_below_100','weekly_any_200']
    when 'Season Futures' then array['future_champion','future_playoffs','future_first_pick','future_win_total']
    else array['spread','moneyline','match_total','team_total','team_milestone','winning_margin'] end);
 v_result:=jsonb_build_object('week',period.week,'board',to_jsonb(b),'markets',v_markets);
 if octet_length(v_result::text)>1048576 then raise exception 'Market category exceeds its read budget';end if;
 return v_result;
end $function$
;

REVOKE ALL ON FUNCTION "public"."sportsbook_category_snapshot"(p_league uuid, p_board uuid, p_category text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."sportsbook_category_snapshot"(p_league uuid, p_board uuid, p_category text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.sportsbook_current_snapshot(p_league uuid, p_type text DEFAULT 'weekly'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare period record; board_id uuid; snapshot jsonb; member_markets jsonb;
begin
 if p_type not in ('weekly','future') then raise exception 'Unknown board type.'; end if;
 if not sportsbook_private.is_member(p_league) then return null; end if;
 select * into period from public.sportsbook_period(p_league);
 select b.id into board_id from public.sportsbook_boards b
  where b.league_id=p_league and b.nfl_season=period.nfl_season and b.board_type=p_type
   and (p_type='future' or b.market_week=period.week)
  order by b.market_week desc,b.id limit 1;
 snapshot:=case when board_id is null then null else public.sportsbook_quote_snapshot(board_id) end;
 select coalesce(jsonb_agg(q||jsonb_build_object('metadata',sportsbook_private.member_quote_metadata(q->'metadata'))),'[]'::jsonb)
  into member_markets from jsonb_array_elements(coalesce(snapshot->'markets','[]'::jsonb))q;
 return jsonb_build_object('week',period.week,'board',snapshot->'board','markets',member_markets);
end $function$
;

REVOKE ALL ON FUNCTION "public"."sportsbook_current_snapshot"(p_league uuid, p_type text) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."sportsbook_current_snapshot"(p_league uuid, p_type text) TO "authenticated";

CREATE OR REPLACE FUNCTION public.sportsbook_period(p_league uuid)
 RETURNS TABLE(league_season integer, nfl_season integer, week integer)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select l.league_season,l.nfl_season,
 least(18,l.active_week+greatest(0,floor(extract(epoch from ((now() at time zone 'America/New_York')-(l.week_anchor at time zone 'America/New_York')))/604800)::integer))
 from public.leagues l where l.id=p_league;
$function$
;

