GRANT EXECUTE ON FUNCTION "public"."update_dev_reward_scores"(p_league uuid, p_season integer, p_week integer, p_before jsonb, p_results jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION public.user_finance_cutover_preflight(p_league uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb;state jsonb;begin
 result:=sportsbook_private.legacy_user_finance_cutover_preflight(p_league);
 if (select count(*) from public.teams where league_id=p_league)>128
  or (select count(*) from public.league_memberships where league_id=p_league)>128
  or (select count(*) from public.user_wallets where league_id=p_league)>128
  or (select count(*) from public.tickets where league_id=p_league and user_wallet_id is null and status='OPEN')>1024
 then return result||jsonb_build_object('ready',false,'blockers',(result->'blockers')||'"Cutover review exceeds its admission budget"'::jsonb);end if;
 state:=jsonb_build_object('review',result,'actor',auth.uid(),
  'wallets',(select coalesce(jsonb_agg(to_jsonb(w) order by w.id),'[]') from public.user_wallets w where w.league_id=p_league),
  'identities',(select coalesce(jsonb_agg(jsonb_build_array(a.id,a.email,a.email_confirmed_at) order by a.id),'[]')
   from auth.users a where exists(select 1 from public.user_wallets w where w.league_id=p_league and w.user_id=a.id)),
  'memberships',(select coalesce(jsonb_agg(to_jsonb(m) order by m.id),'[]') from public.league_memberships m where m.league_id=p_league),
  'legacy_cash',(select coalesce(jsonb_agg(to_jsonb(w) order by w.team_id),'[]') from public.wallets w join public.teams t on t.id=w.team_id where t.league_id=p_league),
  'legacy_open',(select coalesce(jsonb_agg(to_jsonb(t) order by t.id),'[]') from public.tickets t where t.league_id=p_league and t.user_wallet_id is null and t.status='OPEN'));
 return result||jsonb_build_object('state_fingerprint',md5(state::text));
end $function$
;

REVOKE ALL ON FUNCTION "public"."user_finance_cutover_preflight"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."user_finance_cutover_preflight"(p_league uuid) TO "authenticated";

CREATE OR REPLACE FUNCTION public.user_leaderboard(p_league uuid)
 RETURNS TABLE(wallet_id uuid, team_id uuid, display_name text, bets_placed bigint, bets_won bigint, bets_lost bigint, bets_push bigint, total_wagered numeric, total_payout numeric, net_profit numeric, roi numeric, win_percentage numeric, biggest_parlay_legs bigint, biggest_parlay_odds integer, biggest_payout numeric, current_balance numeric, open_stakes numeric, settled_stakes numeric, balance_visible boolean)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if not sportsbook_private.is_member(p_league) or not sportsbook_private.user_finance_enabled(p_league) then raise exception 'Approved user-finance league access required.';end if;
 if (select count(*) from public.user_wallets w where w.league_id=p_league)>128 then raise exception 'Standings account budget reached.';end if;
 return query
 select w.id,w.team_id,w.display_name,count(b.id),count(b.id) filter(where b.status='WON'),count(b.id) filter(where b.status='LOST'),count(b.id) filter(where b.status='PUSH'),
  coalesce(sum(b.stake),0),coalesce(sum(b.actual_payout),0),coalesce(sum(b.net_profit) filter(where b.status<>'OPEN'),0),
  coalesce(100*sum(b.net_profit) filter(where b.status<>'OPEN')/nullif(sum(b.stake) filter(where b.status<>'OPEN'),0),0),
  coalesce(100.0*count(b.id) filter(where b.status='WON')/nullif(count(b.id) filter(where b.status in ('WON','LOST')),0),0),
  coalesce(max((select count(*) from public.ticket_legs l where l.ticket_id=b.id)) filter(where b.status='WON'),0),
  max(b.accepted_combined_odds) filter(where b.status='WON'),coalesce(max(b.actual_payout),0),
  case when w.user_id=auth.uid() or sportsbook_private.is_admin(p_league) then w.balance else null end,
  coalesce(sum(b.stake) filter(where b.status='OPEN'),0),coalesce(sum(b.stake) filter(where b.status in ('WON','LOST','PUSH')),0),
  (w.user_id=auth.uid() or sportsbook_private.is_admin(p_league))
 from public.user_wallets w left join public.tickets b on b.user_wallet_id=w.id and b.status<>'VOIDED'
 where w.league_id=p_league group by w.id,w.team_id,w.display_name,w.user_id,w.balance
 order by 10 desc,4 desc,w.id;
end $function$
;

REVOKE ALL ON FUNCTION "public"."user_leaderboard"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."user_leaderboard"(p_league uuid) TO "authenticated";

