CREATE OR REPLACE FUNCTION public.worker_operation(p_league uuid, p_operation text, p_args jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET statement_timeout TO '45s'
AS $function$
declare v_admin uuid; v_result jsonb; v_board uuid;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Server worker only.'; end if;
 select user_id into v_admin from public.league_memberships where league_id=p_league and role='admin' and user_id is not null limit 1;
 if v_admin is null then
  select a.id into v_admin from auth.users a where a.email_confirmed_at is not null and
   (exists(select 1 from sportsbook_private.platform_owners where user_id=a.id)
    or exists(select 1 from public.league_staff_grants where league_id=p_league and user_id=a.id and active and role='operator'))
   order by case when exists(select 1 from sportsbook_private.platform_owners where user_id=a.id) then 0 else 1 end,a.id limit 1;
 end if;
 if v_admin is null then raise exception 'A verified owner or league operator is required before automation is enabled.';end if;
 perform set_config('request.jwt.claim.sub',v_admin::text,true);
 if p_operation='settle' then
  if not exists(select 1 from public.tickets where id=(p_args->>'ticket')::uuid and league_id=p_league) then raise exception 'Ticket league mismatch.'; end if;
  return public.settle_weekly_ticket((p_args->>'ticket')::uuid,p_args->'results');
 elsif p_operation='replenish' then return public.replenish_weekly_balances(p_league,(p_args->>'season')::int,(p_args->>'week')::int);
 elsif p_operation='save_board' then
  v_board:=public.save_market_board((p_args->>'board')::uuid,p_league,(p_args->>'week')::int,(p_args->>'opens')::timestamptz,(p_args->>'closes')::timestamptz,p_args->'quotes',p_args->>'status');
  return to_jsonb(v_board);
 elsif p_operation='save_future_board' then
  return to_jsonb(public.save_future_board((p_args->>'board')::uuid,p_league,p_args->'quotes',p_args->>'status'));
 elsif p_operation='resolve_futures' then
  return to_jsonb(public.resolve_future_markets(p_league,array(select jsonb_array_elements_text(p_args->'kinds'))));
 else raise exception 'Unknown worker operation.'; end if;
end $function$
;

REVOKE ALL ON FUNCTION "public"."worker_operation"(p_league uuid, p_operation text, p_args jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "public"."worker_operation"(p_league uuid, p_operation text, p_args jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION sportsbook_private.accept_enabled_family()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare t public.tickets;q public.sportsbook_markets;begin
 select * into t from public.tickets where id=new.ticket_id;if t.source_batch is not null or new.market_quote_id is null then return new;end if;
 select * into q from public.sportsbook_markets where id=new.market_quote_id;perform sportsbook_private.check_policy_quote(q);
 if t.sportsbook_policy_snapshot is not null and not(t.sportsbook_policy_snapshot->'values'->>(sportsbook_private.quote_family(q.kind)||'_enabled'))::boolean then raise exception 'Market family disabled by accepted placement policy.';end if;return new;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."accept_enabled_family"() FROM PUBLIC,anon,authenticated,service_role;

