CREATE OR REPLACE FUNCTION sportsbook_private.capture_forecast(p_board uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE b public.sportsbook_boards;
BEGIN
 SELECT * INTO b FROM public.sportsbook_boards WHERE id=p_board;
 IF NOT FOUND OR b.status<>'published' OR b.phase<>'pregame' OR b.board_type<>'weekly' OR b.closes_at<=clock_timestamp() THEN RETURN;END IF;
 INSERT INTO public.opening_market_benchmarks(league_id,nfl_season,market_week,market_key,kind,source_quote_id,home_team_id,away_team_id,team_id,side,line,odds)
 SELECT b.league_id,b.nfl_season,b.market_week,coalesce(m.metadata->>'ui_group',m.market_key)||':'||m.side,m.kind,m.id,m.home_team_id,m.away_team_id,m.team_id,m.side,m.line,m.odds
 FROM public.sportsbook_markets m WHERE m.board_id=b.id AND m.active AND m.kind IN ('spread','moneyline','match_total') AND m.metadata->>'alternate' IS DISTINCT FROM 'true'
 ON CONFLICT(league_id,nfl_season,market_week,market_key) DO NOTHING;
END $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."capture_forecast"(p_board uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.capture_sportsbook_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare p record;begin
 if tg_op='UPDATE'then if new.sportsbook_policy_snapshot is distinct from old.sportsbook_policy_snapshot then raise exception 'Accepted sportsbook policy is immutable.';end if;return new;end if;
 if new.source_batch is not null then new.sportsbook_policy_snapshot:=null;return new;end if;
 perform pg_advisory_xact_lock_shared(hashtextextended('sportsbook-policy:'||new.league_id,0));select * into p from public.sportsbook_period(new.league_id);
 new.sportsbook_policy_snapshot:=sportsbook_private.sportsbook_policy(new.league_id,new.nfl_season,p.week);return new;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."capture_sportsbook_policy"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.capture_ticket_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if tg_op='UPDATE' then
  if new.policy_snapshot is distinct from old.policy_snapshot then raise exception 'Accepted policy snapshot is immutable.';end if;
  return new;
 end if;
 if new.source_batch is not null then new.policy_snapshot:=null;return new;end if;
 perform pg_advisory_xact_lock_shared(20261101,17);
 new.policy_snapshot:=sportsbook_private.wallet_policy(new.league_id,new.nfl_season,new.placement_week);
 if new.stake<(new.policy_snapshot->'values'->>'minimum_stake')::numeric then raise exception 'Wager is below the effective league minimum.';end if;
 return new;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."capture_ticket_policy"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.check_policy_quote(q sportsbook_markets)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare b public.sportsbook_boards;v jsonb;expected integer:=0;period record;begin
 select * into b from public.sportsbook_boards where id=q.board_id;perform pg_advisory_xact_lock_shared(hashtextextended('sportsbook-policy:'||b.league_id,0));select * into period from public.sportsbook_period(b.league_id);v:=sportsbook_private.sportsbook_policy(b.league_id,b.nfl_season,case when b.board_type='future'then case when b.nfl_season<period.nfl_season then 18 else period.week end else b.market_week end)->'values';
 if not(v->>(sportsbook_private.quote_family(q.kind)||'_enabled'))::boolean then raise exception 'Market family disabled by effective policy.';end if;
 if(q.featured='Game of the Week'and q.kind='moneyline')or(q.featured='Tank Bowl'and(q.kind='moneyline'or(q.kind='match_total'and q.side='over')))then expected:=(v->>'featured_boost_pct')::integer;end if;

 IF b.board_type='weekly' AND q.featured IN ('Championship Rematch','Playoff Race','Rivalry','Revenge Game','Upset Watch','Streak Breaker')
 AND q.kind='moneyline' THEN expected:=least((v->>'featured_boost_pct')::integer,
  CASE q.featured WHEN 'Championship Rematch' THEN 50 WHEN 'Streak Breaker' THEN 25 ELSE 35 END); END IF;
 IF b.board_type='weekly' AND q.featured IN ('Game of the Week','Tank Bowl') THEN expected:=least(expected,25); END IF;
  if coalesce(q.metadata->>'sportsbook_policy_revision','0')<>(sportsbook_private.sportsbook_policy(b.league_id,b.nfl_season,case when b.board_type='future'then case when b.nfl_season<period.nfl_season then 18 else period.week end else b.market_week end)->>'revision')then raise exception 'Quote policy changed; regenerate before publication.';end if;
 if b.board_type='future'and abs(q.odds)>(v->>'futures_max_odds')::integer then raise exception 'Futures price exceeds effective policy cap.';end if;
 if q.boost_pct<>0 and q.boost_pct<>expected then raise exception 'Featured boost does not match effective policy.';end if;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."check_policy_quote"(q sportsbook_markets) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.check_ticket_policy_picks()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare t public.tickets;begin
 if tg_table_name='tickets' then select * into t from public.tickets where id=new.id;else select * into t from public.tickets where id=new.ticket_id;end if;
 if t.policy_snapshot is not null and (select count(*) from public.ticket_legs where ticket_id=t.id)>(t.policy_snapshot->'values'->>'maximum_picks')::integer then raise exception 'Ticket exceeds the effective league pick limit.';end if;
 return null;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."check_ticket_policy_picks"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.cleanup_evaluated_samples(p_limit integer DEFAULT 2)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET row_security TO 'on'
 SET statement_timeout TO '5s'
 SET lock_timeout TO '500ms'
AS $function$
declare s public.model_evaluation_summaries;latest uuid;latest_hash text;removed integer:=0;before_removed integer;n integer;periods integer:=0;l record;begin
 -- Authentication is enforced by the sole postgres-owned public wrapper.
 if p_limit is null or p_limit not between 1 and 10 then raise exception 'Invalid retirement batch.';end if;
 for s in select * from public.model_evaluation_summaries where retired_at is null and known_at<clock_timestamp()-interval '7 days'
  order by known_at,league_id,nfl_season,market_week limit p_limit for update skip locked loop
  if exists(select 1 from public.automation_jobs j where j.league_id=s.league_id and j.market_week=s.market_week and j.operation='model_review'
   and j.status='running' and j.lease_until>clock_timestamp()) then continue;end if;
  select id,input_hash into latest,latest_hash from public.model_weekly_reviews where league_id=s.league_id and nfl_season=s.nfl_season and market_week=s.market_week
   order by created_at desc,id desc limit 1;
  if latest_hash is distinct from s.input_hash then continue;end if;
  before_removed:=removed;
  delete from public.model_evaluation_samples where league_id=s.league_id and nfl_season=s.nfl_season and market_week=s.market_week and category<>'Season Futures';
  get diagnostics n=row_count;removed:=removed+n;
  delete from public.published_forecast_samples where league_id=s.league_id and nfl_season=s.nfl_season and market_week=s.market_week and board_type='weekly';
  get diagnostics n=row_count;removed:=removed+n;
  delete from public.live_forecast_samples where league_id=s.league_id and nfl_season=s.nfl_season and market_week=s.market_week;
  get diagnostics n=row_count;removed:=removed+n;
  if s.summary->>'future_final'='true' then
   delete from public.model_evaluation_samples where league_id=s.league_id and nfl_season=s.nfl_season and category='Season Futures';
   get diagnostics n=row_count;removed:=removed+n;
   delete from public.published_forecast_samples where league_id=s.league_id and nfl_season=s.nfl_season and board_type='future';
   get diagnostics n=row_count;removed:=removed+n;
  end if;
  delete from public.model_weekly_reviews r where r.league_id=s.league_id and r.nfl_season=s.nfl_season and r.market_week=s.market_week
   and r.id<>latest and r.report->>'retention_format'='transient-evaluation-v1' and not exists(select 1 from public.model_change_events e where e.review_id=r.id);
  update public.model_weekly_reviews r set report=case when r.id=latest then
   jsonb_build_object('status','complete','retention_format','retired-evaluation-v1','assessment_version',r.report->'assessment_version','summary',s.summary)
   else jsonb_build_object('status','complete','retention_format','retired-evaluation-v1','assessment_version',r.report->'assessment_version',
    'score_views',r.report->'score_views','coverage',r.report->'coverage','row_level_retired',true) end
   where r.league_id=s.league_id and r.nfl_season=s.nfl_season and r.market_week=s.market_week and r.report->>'retention_format'='transient-evaluation-v1';
  update public.model_outcome_revisions o set outcome=jsonb_build_object('final',true,'completed_period',true,'confirmed_games_final',true,'retention_format','retired-evaluation-v1')
   where o.league_id=s.league_id and o.nfl_season=s.nfl_season and o.market_week=s.market_week and o.outcome->>'retention_format'='transient-evaluation-v1'
    and not exists(select 1 from public.model_weekly_reviews r where r.outcome_id=o.id and r.report->>'retention_format'<>'retired-evaluation-v1');
  delete from public.model_outcome_revisions o where o.league_id=s.league_id and o.nfl_season=s.nfl_season and o.market_week=s.market_week
   and o.outcome->>'retention_format'='retired-evaluation-v1' and not exists(select 1 from public.model_weekly_reviews r where r.outcome_id=o.id);
  update public.live_model_reviews set report=(report-array['observations','matches','excluded'])||'{"retention_format":"retired-live-v1","row_level_retired":true}'::jsonb,outcomes='[]'
   where league_id=s.league_id and nfl_season=s.nfl_season and market_week=s.market_week and report->>'retention_format'='transient-live-v1';
  update public.model_evaluation_summaries set retired_at=clock_timestamp() where league_id=s.league_id and nfl_season=s.nfl_season and market_week=s.market_week;
  delete from public.model_prediction_contexts c where c.league_id=s.league_id and c.created_at<clock_timestamp()-interval '7 days'
   and not exists(select 1 from public.model_evaluation_samples x where x.league_id=c.league_id and x.context_version=c.id);
  periods:=periods+1;
  insert into public.evaluation_retention_health(league_id,retired_periods,removed_samples,last_retired_at)
   values(s.league_id,1,removed-before_removed,clock_timestamp()) on conflict(league_id) do update set heartbeat_at=clock_timestamp(),
    retired_periods=evaluation_retention_health.retired_periods+1,removed_samples=evaluation_retention_health.removed_samples+removed-before_removed,last_retired_at=clock_timestamp();
 end loop;
 -- Fourteen-day unresolved periods remain capped by writer admission budgets;
 -- record the backlog rather than deleting pending evidence on a timer.
 for l in select id from public.leagues loop
  insert into public.evaluation_retention_health(league_id) values(l.id) on conflict(league_id) do update set heartbeat_at=clock_timestamp();
  update public.evaluation_retention_health h set (unresolved_periods,oldest_unresolved_period)=(
   select count(*),min(period) from (select distinct nfl_season*100+market_week period from public.model_evaluation_samples x
    where x.league_id=l.id and x.category<>'Season Futures' and captured_at<clock_timestamp()-interval '14 days'
    and not exists(select 1 from public.model_evaluation_summaries checkpoint where checkpoint.league_id=x.league_id and checkpoint.nfl_season=x.nfl_season and checkpoint.market_week=x.market_week)
    union select nfl_season*100+market_week from public.published_forecast_samples x where x.league_id=l.id and board_type='weekly' and captured_at<clock_timestamp()-interval '14 days'
     and not exists(select 1 from public.model_evaluation_summaries checkpoint where checkpoint.league_id=x.league_id and checkpoint.nfl_season=x.nfl_season and checkpoint.market_week=x.market_week)
    union select nfl_season*100+market_week from public.live_forecast_samples x where x.league_id=l.id and captured_at<clock_timestamp()-interval '14 days'
     and not exists(select 1 from public.model_evaluation_summaries checkpoint where checkpoint.league_id=x.league_id and checkpoint.nfl_season=x.nfl_season and checkpoint.market_week=x.market_week)
    
 union select x.nfl_season*100+x.market_week from public.model_evaluation_samples x
  where x.league_id=l.id and x.category='Season Futures' and exists(select 1 from public.sportsbook_boards b where b.league_id=x.league_id
   and b.nfl_season=x.nfl_season and b.board_type='future' and b.closes_at<clock_timestamp()-interval '14 days')
  and not exists(select 1 from public.model_evaluation_summaries done where done.league_id=x.league_id and done.nfl_season=x.nfl_season and done.summary->>'future_final'='true')
 union select x.nfl_season*100+x.market_week from public.published_forecast_samples x join public.sportsbook_boards b on b.id=x.board_id and b.league_id=x.league_id
  where x.league_id=l.id and x.board_type='future' and b.closes_at<clock_timestamp()-interval '14 days'
  and not exists(select 1 from public.model_evaluation_summaries done where done.league_id=x.league_id and done.nfl_season=x.nfl_season and done.summary->>'future_final'='true')
 union select nfl_season*100+market_week from public.model_evaluation_summaries where league_id=l.id and retired_at is null and known_at<clock_timestamp()-interval '14 days') pending)
   where h.league_id=l.id;
 end loop;
 return jsonb_build_object('retired_periods',periods,'removed_samples',removed);
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."cleanup_evaluated_samples"(p_limit integer) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "sportsbook_private"."cleanup_evaluated_samples"(p_limit integer) TO "boff_evaluation_retention";

CREATE OR REPLACE FUNCTION sportsbook_private.cleanup_intake_drafts(p_limit integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET row_security TO 'on'
 SET statement_timeout TO '2s'
 SET lock_timeout TO '200ms'
AS $function$
declare retired integer;begin
 with due as(select id from public.league_intake_drafts where state='draft' and expires_at<=clock_timestamp()
  order by expires_at,id limit least(25,greatest(1,coalesce(p_limit,10))) for update skip locked)
 update public.league_intake_drafts d set source='{}',capabilities='{}',state='expired',revision=revision+1 from due where d.id=due.id;
 get diagnostics retired=row_count;return retired;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."cleanup_intake_drafts"(p_limit integer) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "sportsbook_private"."cleanup_intake_drafts"(p_limit integer) TO "boff_routine_retention";

CREATE OR REPLACE FUNCTION sportsbook_private.cleanup_routine_payloads(p_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
 SET row_security TO 'on'
 SET statement_timeout TO '2s'
 SET lock_timeout TO '200ms'
AS $function$
declare emails integer;jobs integer;images integer;lim integer:=least(25,greatest(1,coalesce(p_limit,10)));begin
 with due as (select id from public.outbound_emails where retention_version=1 and body_retired_at is null
  and status in ('sent','captured','skipped') and terminal_at<clock_timestamp()-interval '7 days'
  and (lease_until is null or lease_until<clock_timestamp()) order by terminal_at,id limit lim for update skip locked)
 update public.outbound_emails e set payload=null,body_retired_at=clock_timestamp(),last_error=null from due where e.id=due.id;
 get diagnostics emails=row_count;
 with due as (select id from public.automation_jobs where retention_version=1 and diagnostic_retired_at is null
  and status='done' and completed_at<clock_timestamp()-interval '30 days'
  and (lease_until is null or lease_until<clock_timestamp()) order by completed_at,id limit lim for update skip locked)
 update public.automation_jobs j set summary=jsonb_build_object('detail_unavailable',true,'reason','Completed diagnostic expired',
  'original_bytes',j.summary_bytes,'digest',md5(j.summary::text)),diagnostic_retired_at=clock_timestamp(),last_error=null from due where j.id=due.id;
 get diagnostics jobs=row_count;
 with due as (select i.id from public.promo_images i where retention_version=1 and created_at<clock_timestamp()-interval '7 days'
  and not exists(select 1 from public.promo_offers o where o.image_id=i.id and o.league_id=i.league_id)
  order by created_at,id limit lim for update skip locked)
 delete from public.promo_images i using due where i.id=due.id;
 get diagnostics images=row_count;
 return jsonb_build_object('retired_email_bodies',emails,'retired_job_diagnostics',jobs,'removed_orphan_images',images,'batch_limit',lim);
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."cleanup_routine_payloads"(p_limit integer) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "sportsbook_private"."cleanup_routine_payloads"(p_limit integer) TO "boff_routine_retention";

CREATE OR REPLACE FUNCTION sportsbook_private.compact_evaluation_payload(p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select jsonb_build_object('retention_format','compact-forecast-v1','algorithm_version',p->'algorithm_version',
  'source_quality',sportsbook_private.evaluation_pick(p->'source_quality',array['source_count','unknown_observation_times']),
  'models',coalesce((select jsonb_agg(sportsbook_private.evaluation_pick(m,array['id','roster_id','mean','sd']) ||
    jsonb_build_object('lineup',coalesce((select jsonb_agg(jsonb_build_object('id',l->'id')) from jsonb_array_elements(m->'lineup') l),'[]'::jsonb)))
    from jsonb_array_elements(p->'models') m),'[]'::jsonb),
  'pool',coalesce((select jsonb_agg(sportsbook_private.evaluation_pick(m,array['id','expected','assessment_sd','injury','positions','sleeper_projection']))
    from jsonb_array_elements(p->'pool') m),'[]'::jsonb),
  'quotes',coalesce((select jsonb_agg(sportsbook_private.evaluation_pick(q,array['id','market_key','kind','side','line','odds','team_id','home_team_id','away_team_id']) ||
    jsonb_build_object('metadata',sportsbook_private.evaluation_pick(q->'metadata',array['assessment_run_id','player_id','opponent_player_id','margin_lower','margin_upper',
      'expected_team_count','projection_targets','roster_id','fair_probability','simulated_probability','expected_points','expected_wins','sleeper_projection','win_distribution','lineup_locked']) ||
      case when jsonb_typeof(q->'metadata'->'player_distribution')='object' then jsonb_build_object('player_distribution',
        sportsbook_private.evaluation_pick(q->'metadata'->'player_distribution',array['mean','sd'])) else '{}'::jsonb end))
    from jsonb_array_elements(p->'quotes') q),'[]'::jsonb),
  'specials',case when jsonb_typeof(p->'specials')='object' then
    sportsbook_private.evaluation_pick(p->'specials',array['anyBelow100','anyAtLeast200','high','low','counts150','countsProjection']) ||
    jsonb_build_object('average_summary',sportsbook_private.evaluation_pick(p->'specials'->'average_summary',
      array['n','mean','median','p05','p10','p25','p75','p90','p95','sd']),
      'highest_summary',sportsbook_private.evaluation_pick(p->'specials'->'highest_summary',
      array['n','mean','median','p05','p10','p25','p75','p90','p95','sd'])) else 'null'::jsonb end);
$function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."compact_evaluation_payload"(p jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.compact_live_payload(p jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
select jsonb_build_object('horizon',p->'horizon','status',p->'status','reason',left(p->>'reason',240),'source_quality','{"live_freshness_verified":false}'::jsonb,
 'teams',coalesce((select jsonb_agg(jsonb_build_object('team_id',t->'team_id','roster_id',t->'roster_id',
 'name',left(t->>'name',160),'matchup_id',t->'matchup_id','starters',t->'starters',
 'mean',t->'mean','sd',t->'sd','observed',t->'observed','reasons',t->'reasons'))
 from jsonb_array_elements(p->'teams') t),'[]'::jsonb),
 'quotes',coalesce((select jsonb_agg((select jsonb_object_agg(key,value) from jsonb_each(q) where key=any(array[
 'matchup_id','home_team_id','away_team_id','home_mean','away_mean','spread','total','home_fair_probability',
 'away_fair_probability','home_odds','away_odds'])) || '{"shadow":true,"acceptance_enabled":false,"promotion_pct":0}'::jsonb)
 from jsonb_array_elements(p->'quotes') q),'[]'::jsonb));
$function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."compact_live_payload"(p jsonb) FROM PUBLIC,anon,authenticated,service_role;

