CREATE OR REPLACE FUNCTION sportsbook_private.enqueue_calendar_jobs(p_now timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s record; local_now timestamp:=p_now at time zone 'America/New_York';
 cycle date; op text; due time; offset_days integer; event_day date;
 scheduled timestamptz; deadline timestamptz; target_week integer; event text;
begin
 if auth.role() is distinct from 'service_role' then raise exception 'Server worker only.'; end if;
 cycle:=local_now::date-((extract(isodow from local_now)::integer+5)%7);
 for s in select cfg.*,l.active_week,l.week_anchor,l.nfl_season
   from public.weekly_schedule cfg join public.leagues l on l.id=cfg.league_id
   where cfg.automation_enabled and l.operations_enabled order by cfg.league_id loop
  for op,due,offset_days in select * from (values
   ('settlement',(s.job_times->>'settlement')::time,0),
   ('recheck',(s.job_times->>'recheck')::time,0),
   ('replenishment',(s.job_times->>'replenishment')::time,0),
   ('generate_matchups',(s.job_times->>'generation')::time,0),
   ('generate_players',(s.job_times->>'generation')::time,0),
   ('generate_specials',(s.job_times->>'generation')::time,0),
   ('generate_futures',(s.job_times->>'generation')::time,0),
   ('refresh_matchups',(s.job_times->>'refresh')::time,1),
   ('refresh_players',(s.job_times->>'refresh')::time,1),
   ('refresh_specials',(s.job_times->>'refresh')::time,1),
   ('refresh_futures',(s.job_times->>'refresh')::time,1),
   ('publish',s.opening_time,1),('recap',s.recap_time,0),
   ('cutoff',(s.job_times->>'cutoff')::time,2),
   ('monday_watch','17:00'::time,6)
  ) x(op,due,offset_days) loop
   event_day:=cycle+offset_days;
   scheduled:=(event_day+due) at time zone 'America/New_York';
   deadline:=case
    when op in ('settlement','recheck','replenishment','recap','cutoff') then (cycle+7+'08:00'::time) at time zone 'America/New_York'
    when op='monday_watch' then (cycle+7+'00:00'::time) at time zone 'America/New_York'
    else (cycle+2+(s.job_times->>'cutoff')::time) at time zone 'America/New_York' end;
   if scheduled>p_now or deadline<=p_now then continue; end if;
   target_week:=least(18,s.active_week+greatest(0,floor(extract(epoch from
     ((scheduled at time zone 'America/New_York')-(s.week_anchor at time zone 'America/New_York')))/604800)::integer));
   event:=s.league_id||':'||event_day||':'||op;
   insert into public.automation_jobs(league_id,event_key,operation,market_week,scheduled_for,expires_at)
    values(s.league_id,event,op,target_week,scheduled,deadline)
    on conflict(event_key) do update set
      scheduled_for=coalesce(public.automation_jobs.scheduled_for,excluded.scheduled_for),
      expires_at=coalesce(public.automation_jobs.expires_at,excluded.expires_at)
    where public.automation_jobs.scheduled_for is null or public.automation_jobs.expires_at is null;
   -- A late opening must recalculate stale categories, not publish yesterday's prices.
   if op like 'refresh_%' and not exists(select 1 from public.automation_jobs published
     where published.league_id=s.league_id and published.event_key=s.league_id||':'||(cycle+1)||':publish' and published.status='done') then
    update public.automation_jobs set status='pending',lease_until=null,attempts=0,
      summary=jsonb_build_object('retry_reason','Refresh stale before opening')
     where event_key=event and status='done' and coalesce(completed_at,created_at)<p_now-interval '120 minutes';
   end if;
  end loop;
 end loop;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."enqueue_calendar_jobs"(p_now timestamp with time zone) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.enqueue_relative_notification_jobs(p_now timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s record;b record;c jsonb;k text;due timestamptz;deadline timestamptz;begin
 if auth.role() is distinct from 'service_role' then raise exception 'Server worker only.';end if;
 perform sportsbook_private.enqueue_calendar_jobs(p_now);
 for s in select cfg.*,l.nfl_season from public.weekly_schedule cfg join public.leagues l on l.id=cfg.league_id
  where cfg.automation_enabled and l.operations_enabled order by cfg.league_id loop
  perform pg_advisory_xact_lock(hashtextextended('reminder-schedule:'||s.league_id,0));
  -- Legacy reminder jobs are never executed under the new relative schedule.
  update public.automation_jobs set status='done',completed_at=p_now,
   summary=jsonb_build_object('skipped',true,'reason','Reminder schedule superseded')
   where id in(select id from public.automation_jobs where league_id=s.league_id and operation='reminder'
    and event_key not like 'relative-reminder-v1:%' and status in('pending','failed','running')
    and coalesce(lease_until,'-infinity')<p_now order by created_at limit 500);
  for b in select market_week from public.sportsbook_boards where league_id=s.league_id and nfl_season=s.nfl_season and board_type='weekly' order by market_week loop
   c:=public.notification_window(s.league_id,s.nfl_season,b.market_week,'reminder');
   k:=case when c->>'eligible'='true' then 'relative-reminder-v1:'||s.league_id||':'||s.nfl_season||':'||b.market_week||':'||(c->>'window_key') else null end;
   update public.automation_jobs set status='done',completed_at=p_now,
    summary=jsonb_build_object('skipped',true,'reason','Reminder window changed or became unavailable')
    where id in(select id from public.automation_jobs where league_id=s.league_id and operation='reminder' and market_week=b.market_week
     and event_key is distinct from k and status in('pending','failed','running') and coalesce(lease_until,'-infinity')<p_now order by created_at limit 500);
   update public.outbound_emails set status=case when attempts>0 then 'needs_review' else 'skipped' end,
    last_error='Reminder window changed or became unavailable.'
    where id in(select id from public.outbound_emails where league_id=s.league_id and kind='reminder' and market_week=b.market_week
     and status in('pending','failed') and coalesce(lease_until,'-infinity')<p_now
     and (c->>'eligible' is distinct from 'true' or notification_context->>'window_key' is distinct from c->>'window_key') order by created_at limit 500);
   if k is null then continue;end if;
   due:=(c->>'send_after')::timestamptz;deadline:=(c->>'deadline')::timestamptz;
   if due>p_now or deadline<=p_now then continue;end if;
   insert into public.automation_jobs(league_id,event_key,operation,market_week,scheduled_for,expires_at)
   values(s.league_id,k,'reminder',b.market_week,due,deadline) on conflict(event_key) do update set status='pending',scheduled_for=excluded.scheduled_for,
 expires_at=excluded.expires_at,lease_until=null,completed_at=null,summary=null
 where public.automation_jobs.status='done' and public.automation_jobs.summary->>'skipped'='true'
 and public.automation_jobs.summary->>'reason'='Reminder window changed or became unavailable';
  end loop;
 end loop;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."enqueue_relative_notification_jobs"(p_now timestamp with time zone) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.enqueue_weekly_jobs(p_now timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s record;cycle date;due timestamptz;deadline timestamptz;begin
 if auth.role()is distinct from 'service_role'then raise exception 'Server worker only.';end if;
 perform sportsbook_private.enqueue_relative_notification_jobs(p_now);
 for s in select cfg.*,l.nfl_season from public.weekly_schedule cfg join public.leagues l on l.id=cfg.league_id
  where cfg.automation_enabled and l.operations_enabled order by cfg.league_id loop
  if sportsbook_private.notification_calendar_week(s.league_id,p_now)>18 then
   update public.automation_jobs set status='done',completed_at=p_now,summary=jsonb_build_object('skipped',true,'reason','Weekly notification calendar complete')
    where league_id=s.league_id and operation in('recap','reminder','monday_watch')and status in('pending','failed','running')and coalesce(lease_until,'-infinity')<p_now;
  end if;
  if not s.recap_email or not sportsbook_private.final_weekly_recap_ready(s.league_id,s.nfl_season,p_now)then continue;end if;
  cycle:=sportsbook_private.notification_week(p_now);
  due:=(cycle+s.recap_time)at time zone 'America/New_York';
  deadline:=(cycle+7+'00:00'::time)at time zone 'America/New_York';
  if due>p_now or deadline<=p_now then continue;end if;
  insert into public.automation_jobs(league_id,event_key,operation,market_week,scheduled_for,expires_at)
   values(s.league_id,'final-recap-v1:'||s.league_id||':'||s.nfl_season,'final_recap',18,due,deadline)on conflict(event_key)do nothing;
 end loop;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."enqueue_weekly_jobs"(p_now timestamp with time zone) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.evaluation_gap(p_league uuid, p_reason text, p_season integer, p_week integer, p_category text)
 RETURNS void
 LANGUAGE sql
 SET search_path TO ''
AS $function$
 update public.model_evaluation_health set skipped_requests=skipped_requests+1,last_gap_at=now(),last_gap_reason=p_reason where league_id=p_league;
 update public.model_evaluation_coverage set skipped_requests=skipped_requests+1,
   eligible_gaps=eligible_gaps+case when p_reason='post_cutoff' then 0 else 1 end,
   last_gap_at=case when p_reason='post_cutoff' then last_gap_at else now() end,
   last_gap_reason=case when p_reason='post_cutoff' then last_gap_reason else p_reason end
   where league_id=p_league and nfl_season=p_season and market_week=p_week and category=p_category;
$function$
;

