CREATE OR REPLACE FUNCTION sportsbook_private.guard_live_league_activation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.operations_enabled then
  if tg_op='UPDATE' then
   if old.operations_enabled then return new; end if;
  end if;
  if not exists(select 1 from sportsbook_private.league_launch_approvals a
   join sportsbook_private.platform_owner o on o.membership_id=a.owner_membership_id
   where a.league_id=new.id) then
   raise exception 'Platform owner approval is required before a league goes live.';
  end if;
 end if;
 return new;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."guard_live_league_activation"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.guard_market_league()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_league uuid;
begin
 select league_id into v_league from public.sportsbook_boards where id=new.board_id;
 if exists(select 1 from (values(new.team_id),(new.home_team_id),(new.away_team_id)) x(id)
   where x.id is not null and not exists(select 1 from public.teams where id=x.id and league_id=v_league)) then
  raise exception 'Market teams must belong to this league.';
 end if;
 return new;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."guard_market_league"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.guard_outbox_recipient()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if new.kind='attention' and new.staff_user_id is not null then
  if tg_op='INSERT' then
   perform 1 from public.leagues where id=new.league_id for share;
   new.wallet_model:=case when exists(select 1 from sportsbook_private.user_finance_modes where league_id=new.league_id and enabled)then 'user' else 'legacy'end;
  elsif new.wallet_model is distinct from old.wallet_model then raise exception 'Queued financial model is immutable.';end if;
  if tg_op='UPDATE' and new.payload is null and old.payload is not null and row(new.league_id,new.team_id,new.ticket_id,new.recipient,new.kind,new.staff_user_id)is not distinct from row(old.league_id,old.team_id,old.ticket_id,old.recipient,old.kind,old.staff_user_id)then return new;end if;
  if not sportsbook_private.is_alert_staff(new.league_id,new.staff_user_id) or not exists(select 1 from auth.users where id=new.staff_user_id and email=new.recipient and email_confirmed_at is not null)then raise exception 'Verified current league staff recipient required.';end if;
  if new.team_id is not null or new.ticket_id is not null then raise exception 'Operational staff alerts cannot borrow a participant account.';end if;
  if new.payload is not null and (new.payload->'to' is distinct from jsonb_build_array(new.recipient) or new.payload?'cc' or new.payload?'bcc')then raise exception 'Email payload recipients must match the outbox recipient.';end if;
  return new;
 end if;
 if tg_op='INSERT' and new.kind='attention' then raise exception 'New attention messages require a verified staff binding.';end if;

 if tg_op='INSERT' then
  perform 1 from public.leagues where id=new.league_id for share;
  new.wallet_model:=case when exists(select 1 from sportsbook_private.user_finance_modes where league_id=new.league_id and enabled) then 'user' else 'legacy' end;
 elsif new.wallet_model is distinct from old.wallet_model then raise exception 'Queued financial model is immutable.';end if;
 if tg_op='UPDATE' and new.payload is null and old.payload is not null
  and row(new.league_id,new.team_id,new.ticket_id,new.recipient,new.kind) is not distinct from
      row(old.league_id,old.team_id,old.ticket_id,old.recipient,old.kind) then return new;end if;
 if exists(select 1 from public.tickets where id=new.ticket_id and user_wallet_id is not null) then
  if new.kind<>'confirmation' or not exists(select 1 from public.tickets t join public.user_wallets w on w.id=t.user_wallet_id
   join auth.users a on a.id=w.user_id where t.id=new.ticket_id and t.league_id=new.league_id and t.team_id=new.team_id
    and w.status='approved' and a.email_confirmed_at is not null and a.email=new.recipient)
  then raise exception 'Confirmation must target the accepted financial account owner.';end if;
 elsif new.wallet_model='user' and new.ticket_id is null and new.kind<>'attention' then
  if not exists(select 1 from public.user_wallets w join auth.users a on a.id=w.user_id
    where w.league_id=new.league_id and w.team_id=new.team_id and w.status='approved'
     and a.email_confirmed_at is not null and a.email=new.recipient)
   then raise exception 'Email must target an approved financial account owner.';end if;
 elsif new.team_id is null or not exists(select 1 from public.league_memberships m where m.league_id=new.league_id
  and m.team_id=new.team_id and m.invited_email=new.recipient and (new.kind<>'attention' or m.role='admin'))
 then raise exception 'Email recipient must match the approved league membership.';end if;
 if new.payload is not null and (new.payload->'to' is distinct from jsonb_build_array(new.recipient) or new.payload ? 'cc' or new.payload ? 'bcc')
 then raise exception 'Email payload recipients must match the outbox recipient.';end if;
 return new;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."guard_outbox_recipient"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.guard_platform_owner_identity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if exists(select 1 from sportsbook_private.platform_owner where membership_id=old.id) then
  if row(new.invited_email,new.role,new.league_id,new.team_id) is distinct from
     row(old.invited_email,old.role,old.league_id,old.team_id)
   or (old.user_id is not null and new.user_id is distinct from old.user_id) then
   raise exception 'Platform owner identity cannot be reassigned by league administration.';
  end if;
  if old.user_id is null and new.user_id is not null and not exists(
   select 1 from auth.users where id=new.user_id and lower(email)=old.invited_email and email_confirmed_at is not null) then
   raise exception 'Platform owner requires a verified matching email account.';
  end if;
 end if;
 return new;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."guard_platform_owner_identity"() FROM PUBLIC,anon,authenticated,service_role;

