CREATE OR REPLACE FUNCTION sportsbook_private.invalidate_board_content()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op='INSERT' then
    update public.sportsbook_boards set content_version=content_version+1
      where id in(select distinct board_id from new_rows);
  elsif tg_op='DELETE' then
    update public.sportsbook_boards set content_version=content_version+1
      where id in(select distinct board_id from old_rows);
  else
    update public.sportsbook_boards set content_version=content_version+1 where id in(
      select board_id from (select * from new_rows except select * from old_rows) changed
      union select board_id from (select * from old_rows except select * from new_rows) removed);
  end if;
  return null;
end;
$function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."invalidate_board_content"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.is_admin(p_league uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
 select sportsbook_private.is_platform_owner()
 or exists(select 1 from public.league_staff_grants where league_id=p_league and user_id=(select auth.uid()) and active and role='operator')
 or exists(select 1 from public.league_memberships where league_id=p_league and user_id=(select auth.uid()) and role='admin')
$function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."is_admin"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

