CREATE OR REPLACE FUNCTION sportsbook_private.numeric_total_valid(t jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare k text;v numeric;n numeric;begin
 if jsonb_typeof(t) is distinct from 'object' or (select count(*) from jsonb_object_keys(t))<>6 then return false;end if;
 foreach k in array array['n','absolute_error','squared_error','error','interval_n','covered80'] loop
  if jsonb_typeof(t->k) is distinct from 'number' then return false;end if;
  v:=(t->>k)::numeric;
  if (k<>'error' and v<0) or (k in ('n','interval_n','covered80') and v<>trunc(v)) then return false;end if;
 end loop;
 n:=(t->>'n')::numeric;
 return (t->>'interval_n')::numeric<=n and (t->>'covered80')::numeric<=(t->>'interval_n')::numeric
  and abs((t->>'error')::numeric)<=(t->>'absolute_error')::numeric+.000001
  and power((t->>'absolute_error')::numeric,2)<=n*(t->>'squared_error')::numeric+.000001;
end;
$function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."numeric_total_valid"(t jsonb) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.platform_owner_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if tg_op='DELETE' then
  if (select count(*) from sportsbook_private.platform_owners)<=1 then raise exception 'The last platform owner cannot be removed';end if;
  return old;
 end if;
 if tg_op='UPDATE' and new.user_id<>old.user_id then raise exception 'Insert the verified successor before removing an owner';end if;
 if not exists(select 1 from auth.users where id=new.user_id and email_confirmed_at is not null)
  then raise exception 'A verified independent Auth identity is required';end if;
 return new;
end $function$
;

