CREATE OR REPLACE FUNCTION sportsbook_private.policy_base_board_manifest(p_league uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare period record; weekly jsonb; future jsonb;
begin
  if not sportsbook_private.is_member(p_league) then return null; end if;
  select * into period from public.sportsbook_period(p_league);
  select to_jsonb(b) into weekly from public.sportsbook_boards b
    where b.league_id=p_league and b.nfl_season=period.nfl_season
      and b.board_type='weekly' and b.market_week=period.week
      and (b.status<>'draft' or sportsbook_private.is_admin(p_league))
    order by b.id limit 1;
  select to_jsonb(b) into future from public.sportsbook_boards b
    where b.league_id=p_league and b.nfl_season=period.nfl_season
      and b.board_type='future' and (b.status<>'draft' or sportsbook_private.is_admin(p_league))
    order by b.id limit 1;
  -- Deliberately no quote/snapshot calls or market-table reads here.
  return jsonb_build_object('week',period.week,'weekly',weekly,'future',future);
end;
$function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."policy_base_board_manifest"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.policy_base_finance_wallets(p_league uuid, p_season integer, p_week integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare enabled boolean;rows jsonb;result jsonb;
begin
 if auth.role() is distinct from 'service_role' and not sportsbook_private.is_admin(p_league) then raise exception 'League operator required.';end if;
 if p_season is null or p_season not between 2020 and 2100 or p_week is null or p_week not between 1 and 18 then raise exception 'Invalid financial preview period.';end if;
 select exists(select 1 from sportsbook_private.user_finance_modes where league_id=p_league and user_finance_modes.enabled) into enabled;
 if enabled then
  if (select count(*) from public.user_wallets where league_id=p_league)>128 then raise exception 'Financial preview account budget reached.';end if;
  select coalesce(jsonb_agg(jsonb_build_object('wallet_id',w.id,'team_id',w.team_id,'user_id',w.user_id,'balance',w.balance,'display_name',w.display_name,
   'legacy_primary',exists(select 1 from public.league_memberships m where m.league_id=p_league and m.team_id=w.team_id and m.user_id=w.user_id),
   'processed',exists(select 1 from public.user_wallet_entries e where e.wallet_id=w.id and e.event_key='weekly:replenish:'||p_season||':'||p_week||':'||w.id)) order by w.id),'[]'::jsonb) into rows
  from public.user_wallets w join auth.users a on a.id=w.user_id where w.league_id=p_league and w.status='approved' and a.email_confirmed_at is not null;
 else
  if (select count(*) from public.teams where league_id=p_league)>128 then raise exception 'Financial preview team budget reached.';end if;
  select coalesce(jsonb_agg(jsonb_build_object('wallet_id',null,'team_id',w.team_id,'balance',w.balance,'legacy_primary',true,
   'processed',exists(select 1 from public.wallet_ledger e where e.team_id=w.team_id and e.event_key='weekly:replenish:'||p_season||':'||p_week||':'||w.team_id)) order by w.team_id),'[]'::jsonb) into rows
  from public.wallets w join public.teams t on t.id=w.team_id where t.league_id=p_league;
 end if;
 result:=jsonb_build_object('wallet_model',case when enabled then 'user' else 'legacy' end,'wallets',rows);
 if octet_length(result::text)>65536 then raise exception 'Financial preview byte budget reached.';end if;
 return result;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."policy_base_finance_wallets"(p_league uuid, p_season integer, p_week integer) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.policy_publication_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare q public.sportsbook_markets;begin
 IF NEW.board_type = 'weekly' AND NEW.status <> 'published' THEN RETURN NULL; END IF;
 IF NEW.board_type = 'weekly' AND TG_OP = 'UPDATE' AND OLD.status = NEW.status AND OLD.content_version = NEW.content_version AND OLD.revision = NEW.revision AND OLD.league_id = NEW.league_id AND OLD.nfl_season = NEW.nfl_season AND OLD.market_week = NEW.market_week THEN RETURN NULL; END IF;
 if exists(select 1 from public.sportsbook_boards where id=new.id and status='published')then for q in select * from public.sportsbook_markets where board_id=new.id and active loop perform sportsbook_private.check_policy_quote(q);end loop;end if;return null;
end $function$
;

