CREATE OR REPLACE FUNCTION sportsbook_private.preserve_accepted_terms()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE old_terms jsonb;new_terms jsonb;
BEGIN
 IF TG_TABLE_NAME='ticket_legs' THEN
  old_terms:=to_jsonb(OLD)-ARRAY['status','actual_value','result_evidence','context_bundle_id','settlement_context'];
  new_terms:=to_jsonb(NEW)-ARRAY['status','actual_value','result_evidence','context_bundle_id','settlement_context'];
  IF old_terms IS DISTINCT FROM new_terms OR
   sportsbook_private.expand_receipt_context(OLD.settlement_context,OLD.context_bundle_id) IS DISTINCT FROM sportsbook_private.expand_receipt_context(NEW.settlement_context,NEW.context_bundle_id)
   THEN RAISE EXCEPTION 'Accepted leg terms are immutable.';END IF;
 ELSE
  IF (to_jsonb(NEW)-ARRAY['status','actual_payout','settled_at','ticket_type','net_profit']) IS DISTINCT FROM
   (to_jsonb(OLD)-ARRAY['status','actual_payout','settled_at','ticket_type','net_profit']) THEN RAISE EXCEPTION 'Accepted ticket terms are immutable.';END IF;
 END IF;
 RETURN NEW;
END $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."preserve_accepted_terms"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.probability_total_valid(t jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare k text;b jsonb;n numeric;bins numeric:=0;v numeric;begin
 if jsonb_typeof(t) is distinct from 'object' or (select count(*) from jsonb_object_keys(t))<>4
  or jsonb_typeof(t->'bands') is distinct from 'array' or jsonb_array_length(t->'bands')<>5 then return false;end if;
 foreach k in array array['n','brier','log_loss'] loop
  if jsonb_typeof(t->k) is distinct from 'number' or (t->>k)::numeric<0 then return false;end if;
 end loop;
 n:=(t->>'n')::numeric;
 if n<>trunc(n) or (t->>'brier')::numeric>n+.000001 then return false;end if;
 for b in select value from jsonb_array_elements(t->'bands') loop
  if jsonb_typeof(b) is distinct from 'object' or (select count(*) from jsonb_object_keys(b))<>3 then return false;end if;
  foreach k in array array['n','predicted','observed'] loop
   if jsonb_typeof(b->k) is distinct from 'number' or (b->>k)::numeric<0 then return false;end if;
   v:=(b->>k)::numeric;
   if k in ('n','observed') and v<>trunc(v) then return false;end if;
  end loop;
  if (b->>'predicted')::numeric>(b->>'n')::numeric+.000001 or (b->>'observed')::numeric>(b->>'n')::numeric then return false;end if;
  bins:=bins+(b->>'n')::numeric;
 end loop;
 return bins=n;
end;
$function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."probability_total_valid"(t jsonb) FROM PUBLIC,anon,authenticated,service_role;

