CREATE OR REPLACE FUNCTION sportsbook_private.promo_snapshot_immutable()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin raise exception 'Promotion snapshots and events are immutable.';end $function$
;

