CREATE OR REPLACE FUNCTION sportsbook_private.report_quote(q jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 select (select coalesce(jsonb_object_agg(key,value),'{}'::jsonb) from jsonb_each(q) where key=any(array['id','market_key','matchup_key','kind','label','subject','side','line','odds',
  'boost_pct','team_id','home_team_id','away_team_id','home_projection','away_projection','featured'])) ||
 jsonb_build_object('metadata',
  coalesce((select jsonb_object_agg(key,value) from jsonb_each(coalesce(q->'metadata','{}'::jsonb)) where
   (key=any(array['assessment_run_id','player_id','opponent_player_id','model_version','pick_owner_name'])
     and jsonb_typeof(value)='string' and length(value#>>'{}')<=160)
   or (key=any(array['margin_lower','margin_upper','expected_team_count','roster_id','simulated_probability','fair_probability',
     'expected_wins','trials','playoff_week_start','playoff_teams']) and jsonb_typeof(value) in ('number','null'))
   or (key='lineup_locked' and jsonb_typeof(value)='boolean')),'{}'::jsonb) ||
  coalesce((select jsonb_object_agg(key,value) from jsonb_each(coalesce(q->'metadata','{}'::jsonb)) where
    key in ('projection_targets','win_distribution') and jsonb_typeof(value)='object'
    and (select count(*) from jsonb_each(case when jsonb_typeof(value)='object' then value else '{}'::jsonb end))<=32
    and not exists(select 1 from jsonb_each(case when jsonb_typeof(value)='object' then value else '{}'::jsonb end) x where jsonb_typeof(x.value)<>'number' or length(x.key)>80)), '{}'::jsonb));
$function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."report_quote"(q jsonb) FROM PUBLIC,anon,authenticated,service_role;

GRANT EXECUTE ON FUNCTION "sportsbook_private"."report_quote"(q jsonb) TO "authenticated";

GRANT EXECUTE ON FUNCTION "sportsbook_private"."report_quote"(q jsonb) TO "service_role";

CREATE OR REPLACE FUNCTION sportsbook_private.require_provider_capability(p_league uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare l public.leagues;s sportsbook_private.provider_capability_state;h text;begin
 select * into l from public.leagues where id=p_league;if l.provider_contract is null then return;end if;
 if not pg_try_advisory_xact_lock_shared(hashtextextended('provider-capability:'||p_league,0))then raise exception 'Provider review changed or is in progress; retry after review.';end if;
 select * into s from sportsbook_private.provider_capability_state where league_id=p_league;
 if not found then raise exception 'Provider capability review required.';end if;
 h:=encode(sha256(convert_to(jsonb_build_object('source',sportsbook_private.capability_source(s.source),'rosters',s.rosters,'configuration',sportsbook_private.provider_configuration_hash(p_league),'build',s.build_sha)::text,'UTF8')),'hex');
 if s.approved_hash is null or s.approved_hash<>s.observed_hash or s.observed_hash<>h or(s.source->>'season')::integer<>l.nfl_season or s.observed_at<clock_timestamp()-interval '24 hours'then raise exception 'Provider rules, settings, season or review freshness changed; owner review required.';end if;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."require_provider_capability"(p_league uuid) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.round_market_odds()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare increment integer;
begin
 increment:=case when new.kind like 'future_%' then 50 when new.kind like 'weekly_%' then 25 else 10 end;
 new.odds:=sign(new.odds)*greatest(100,round(abs(new.odds)/increment::numeric)*increment);
 if new.kind like 'future_%' then new.odds:=greatest(-10000,least(10000,new.odds)); end if;
 return new;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."round_market_odds"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.round_special_odds()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if new.kind like 'weekly_%' then
  new.odds:=sign(new.odds)*greatest(100,round(abs(new.odds)/10.0)*10);
 end if;
 return new;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."round_special_odds"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.routine_context_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 if tg_op='UPDATE' and current_user='boff_routine_retention' and old.body_retired_at is null and new.body_retired_at is not null and new.payload is null then new.routine_context:=null;return new;end if;
 if tg_op='UPDATE' and old.routine_context is not null and new.routine_context is distinct from old.routine_context then raise exception 'Routine composition context is immutable.';end if;
 if tg_op='UPDATE' and old.routine_context is null and new.routine_context is not null and old.payload is not null then raise exception 'Frozen mail cannot adopt new routine composition.';end if;
 if new.routine_context is not null and (new.kind not in('opening','reminder','recap','monday_watch','reopening')
  or new.routine_context->>'contract' is distinct from 'routine-composition-v1' or new.routine_context->>'league_id' is distinct from new.league_id::text or new.routine_context->>'kind' is distinct from new.kind
  or coalesce(new.routine_context->>'user_id','')!~'^[0-9a-f-]{36}$' or jsonb_typeof(new.routine_context->'merge_watch') is distinct from 'boolean') then raise exception 'Invalid routine composition scope.';end if;
 return new;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."routine_context_guard"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.routine_delivery_permission_at(p_email uuid, p_commit boolean, p_now timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare r public.outbound_emails;l public.leagues;s public.weekly_schedule;u uuid;wallet uuid;choices jsonb;period record;
 cycle date:=sportsbook_private.notification_week(p_now);local_now timestamp:=p_now at time zone 'America/New_York';
 prior sportsbook_private.routine_dispatches;recap jsonb;used integer;open_count integer;merge_watch boolean:=false;c jsonb;context jsonb;begin
 if auth.role() is distinct from 'service_role' then raise exception 'Mail worker only.';end if;
 if p_commit is null or p_now is null then raise exception 'Delivery phase and time required.';end if;
 select * into r from public.outbound_emails where id=p_email;
 if not found then raise exception 'Queued message unavailable.';end if;
 if r.kind not in('opening','reminder','recap','monday_watch','reopening') then return jsonb_build_object('allowed',true,'essential',true);end if;
 if exists(select 1 from sportsbook_private.user_finance_modes where league_id=r.league_id and enabled) then
  select w.user_id,w.id into u,wallet from public.user_wallets w join auth.users a on a.id=w.user_id where w.league_id=r.league_id and w.team_id=r.team_id and w.status='approved' and a.email_confirmed_at is not null and a.email=r.recipient;
 else
  select m.user_id into u from public.league_memberships m join auth.users a on a.id=m.user_id where m.league_id=r.league_id and m.team_id=r.team_id and m.invited_email=r.recipient and a.email=r.recipient and a.email_confirmed_at is not null;
 end if;
 if u is null then return jsonb_build_object('allowed',false,'reason','Approved routine recipient unavailable.');end if;
 perform pg_advisory_xact_lock(hashtextextended('notification-defaults:'||r.league_id,0));
 perform pg_advisory_xact_lock(hashtextextended('notification-user:'||r.league_id||':'||u,0));
 select * into l from public.leagues where id=r.league_id;
 select * into s from public.weekly_schedule where league_id=r.league_id;
 choices:=sportsbook_private.notification_choices(r.league_id,u)->'effective';
 if choices->>r.kind is distinct from 'true' or not l.operations_enabled or (r.kind<>'reopening' and not coalesce(s.automation_enabled,false)) then return jsonb_build_object('allowed',false,'reason','Routine notification is disabled for this recipient or league.');end if;
 select * into period from public.sportsbook_period(r.league_id);
 if r.market_week not between 1 and 18 or(sportsbook_private.notification_calendar_week(r.league_id,p_now)>18 and r.kind not in('recap','reopening'))
  or(r.kind='recap' and not((sportsbook_private.notification_calendar_week(r.league_id,p_now)<=18 and r.market_week=period.week-1)
   or(r.market_week=18 and sportsbook_private.final_weekly_recap_ready(r.league_id,l.nfl_season,p_now))))
  or(r.kind not in('recap')and r.market_week<>period.week)then return jsonb_build_object('allowed',false,'reason','Routine notification belongs to an obsolete week.');end if;
 if r.kind='monday_watch' and (extract(isodow from local_now)<>1 or local_now::time<'17:00'::time) then return jsonb_build_object('allowed',false,'reason','Monday ticket watch is outside its useful window.');end if;
 open_count:=0;
 if r.kind='monday_watch' or (r.kind='reminder' and choices->>'monday_watch'='true' and extract(isodow from local_now)=1 and local_now::time>='15:00'::time) then
  select count(*)::integer into open_count from public.tickets t where t.league_id=r.league_id and t.market_week=period.week and t.nfl_season=l.nfl_season and t.status='OPEN' and t.ticket_type<>'future'
   and (case when wallet is not null then t.user_wallet_id=wallet else t.team_id=r.team_id and t.user_wallet_id is null end);
 end if;
 if r.kind='monday_watch' and open_count=0 then return jsonb_build_object('allowed',false,'reason','No open personal weekly tickets require a watch.');end if;
 if r.kind='reminder' and choices->>'monday_watch'='true' and open_count>0 and extract(isodow from local_now)=1 and local_now::time>='15:00'::time then merge_watch:=true;end if;
 if r.kind='monday_watch' and choices->>'reminder'='true' then
  if exists(select 1 from sportsbook_private.routine_dispatches d where d.league_id=r.league_id and d.user_id=u and d.period_start=cycle and d.kind='reminder' and d.merged_watch) then return jsonb_build_object('allowed',false,'reason','Ticket watch was included in the closing reminder.');end if;
  c:=public.notification_window(r.league_id,l.nfl_season,period.week,'reminder');
  if c->>'eligible'='true' and (c->>'send_after')::timestamptz<=p_now+interval '2 hours'
   and coalesce((case when wallet is not null then (select balance from public.user_wallets where id=wallet) else (select balance from public.wallets where team_id=r.team_id) end),0)>=(c->>'minimum_stake')::numeric
   and not exists(select 1 from public.outbound_emails e where e.league_id=r.league_id and e.kind='reminder' and e.market_week=period.week and e.recipient=r.recipient and e.payload is not null and coalesce((e.routine_context->>'merge_watch')::boolean,false)=false)
   and ((c->>'send_after')::timestamptz>p_now or exists(select 1 from public.outbound_emails e where e.league_id=r.league_id and e.recipient=r.recipient and e.kind='reminder' and e.market_week=period.week and e.status in('pending','failed','sending') and e.notification_context->>'window_key'=c->>'window_key')
    or not exists(select 1 from public.automation_jobs j where j.event_key='relative-reminder-v1:'||r.league_id||':'||l.nfl_season||':'||period.week||':'||(c->>'window_key') and j.status='done'))
  then return jsonb_build_object('allowed',false,'reason','Ticket watch is covered by the nearby closing reminder.');end if;
 end if;
 context:=jsonb_build_object('contract','routine-composition-v1','league_id',r.league_id,'user_id',u,'nfl_season',l.nfl_season,'period_start',cycle,'kind',r.kind,'merge_watch',merge_watch,'open_ticket_count',least(open_count,10000),'prepared_at',p_now);
 if r.kind='reminder' then
  c:=public.notification_window(r.league_id,l.nfl_season,r.market_week,'reminder');
  if c->>'eligible' is distinct from 'true' or c->>'window_key' is distinct from r.notification_context->>'window_key' or(c->>'send_after')::timestamptz>p_now
   or coalesce((case when wallet is not null then(select balance from public.user_wallets where id=wallet)else(select balance from public.wallets where team_id=r.team_id)end),0)<(c->>'minimum_stake')::numeric
  then return jsonb_build_object('allowed',false,'reason','Reminder opportunity or minimum available funds changed.');end if;
 end if;
 if r.kind='recap' then
  recap:=public.recap_financial_context(r.league_id,r.team_id,r.recipient,l.nfl_season,r.market_week+1);
  if recap->>'ready' is distinct from 'true' then return jsonb_build_object('allowed',false,'reason','Recap waits for the recorded replenishment review.');end if;
  context:=context||jsonb_build_object('recap',jsonb_build_object('state',recap->'state','credited',recap->'credited'));
 end if;
 if r.payload is not null then
  if r.routine_context is null then return jsonb_build_object('allowed',false,'reason','Frozen routine message has no verified composition context.');end if;
  if r.routine_context->>'user_id' is distinct from u::text or r.routine_context->>'nfl_season' is distinct from l.nfl_season::text or r.routine_context->>'period_start' is distinct from cycle::text then return jsonb_build_object('allowed',false,'reason','Frozen routine recipient or useful period changed.');end if;
  if r.routine_context->>'merge_watch'='true' and choices->>'monday_watch' is distinct from 'true' then return jsonb_build_object('allowed',false,'reason','Ticket watch was disabled after composition.');end if;
  if r.kind='recap' and r.routine_context->'recap' is distinct from context->'recap' then return jsonb_build_object('allowed',false,'reason','Recap financial snapshot changed after preparation.');end if;
  context:=r.routine_context;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('routine-budget:'||r.league_id||':'||u||':'||cycle,0));
 select * into prior from sportsbook_private.routine_dispatches where email_id=r.id;
 if found then
  if prior.user_id<>u or prior.period_start<>cycle or prior.nfl_season<>l.nfl_season then return jsonb_build_object('allowed',false,'reason','An earlier delivery attempt belongs to a different recipient or period.');end if;
 else
  select count(*) into used from sportsbook_private.routine_dispatches where league_id=r.league_id and user_id=u and period_start=cycle;
  if used>=3 then return jsonb_build_object('allowed',false,'reason','Three routine messages already admitted for this week.');end if;
  if used=0 and (select count(distinct user_id) from sportsbook_private.routine_dispatches where league_id=r.league_id and period_start=cycle)>=128 then return jsonb_build_object('allowed',false,'reason','Routine recipient capacity reached for this week.');end if;
  if p_commit then
   if r.payload is null or r.routine_context is null then raise exception 'Freeze verified routine composition before dispatch.';end if;
   insert into sportsbook_private.routine_dispatches(email_id,league_id,user_id,nfl_season,period_start,kind,merged_watch)
    values(r.id,r.league_id,u,l.nfl_season,cycle,r.kind,(context->>'merge_watch')::boolean);
  end if;
 end if;
 return jsonb_build_object('allowed',true,'context',context,'weekly_limit',3);
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."routine_delivery_permission_at"(p_email uuid, p_commit boolean, p_now timestamp with time zone) FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.routine_payload_admission()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare total bigint; scoped bigint; n integer;begin
 if tg_op='INSERT' then new.retention_version:=1;
 elsif new.retention_version<>old.retention_version then raise exception 'Retention version is immutable.';end if;
 if tg_table_name='outbound_emails' then
  if tg_op='UPDATE' and old.body_retired_at is not null and
    (new.payload is not null or new.status is distinct from old.status or new.body_retired_at is distinct from old.body_retired_at) then
   raise exception 'Retired email cannot be resent or regenerated.';end if;
  if new.status in ('sent','captured','skipped') then
   if tg_op='INSERT' then new.terminal_at:=coalesce(new.sent_at,clock_timestamp());
   elsif old.status not in ('sent','captured','skipped') then
    new.terminal_at:=case when new.sent_at is distinct from old.sent_at then coalesce(new.sent_at,clock_timestamp()) else clock_timestamp() end;
   elsif new.terminal_at is null then new.terminal_at:=clock_timestamp();end if;
  end if;
  if tg_op='INSERT' or new.payload is distinct from old.payload then
   if new.payload is not null then
    perform pg_advisory_xact_lock(83801201);
    n:=octet_length(new.payload::text);
    select coalesce(sum(payload_bytes),0),coalesce(sum(payload_bytes) filter(where league_id=new.league_id),0)
     into total,scoped from public.outbound_emails where id<>new.id and payload is not null;
    if n>262144 or scoped+n>8388608 or total+n>33554432 then raise exception 'Email body capacity reached; provider delivery was not authorized.';end if;
   end if;
  end if;
 elsif tg_table_name='automation_jobs' then
  if tg_op='INSERT' or new.summary is distinct from old.summary then
   if new.summary is not null then
    perform pg_advisory_xact_lock(83801202);
    n:=octet_length(new.summary::text);
    select coalesce(sum(summary_bytes),0),coalesce(sum(summary_bytes) filter(where league_id=new.league_id),0)
     into total,scoped from public.automation_jobs where id<>new.id and diagnostic_retired_at is null;
    if n>65536 or scoped+n>4194304 or total+n>16777216 then
     new.summary:=jsonb_build_object('detail_unavailable',true,'reason','Routine diagnostic capacity','original_bytes',n,'digest',md5(new.summary::text));
     new.diagnostic_retired_at:=clock_timestamp();
    elsif tg_op='UPDATE' and old.diagnostic_retired_at is not null and new.diagnostic_retired_at is not distinct from old.diagnostic_retired_at then
     new.diagnostic_retired_at:=null;
    end if;
   end if;
  end if;
 elsif tg_table_name='promo_images' then
  if tg_op='INSERT' or new.png is distinct from old.png then
   perform pg_advisory_xact_lock(83801203);
   select coalesce(sum(png_bytes),0),coalesce(sum(png_bytes) filter(where league_id=new.league_id),0),count(*) filter(where league_id=new.league_id)
    into total,scoped,n from public.promo_images where id<>new.id;
   if scoped+octet_length(new.png)>33554432 or total+octet_length(new.png)>67108864 or n>=128 then
    raise exception 'Promotion image capacity reached.';end if;
  end if;
 end if;
 if tg_table_name in ('outbound_emails','automation_jobs') then new.last_error:=left(new.last_error,256);end if;
 return new;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."routine_payload_admission"() FROM PUBLIC,anon,authenticated,service_role;

