CREATE OR REPLACE FUNCTION sportsbook_private.staff_alert_identity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$begin
 if tg_op='UPDATE' and old.staff_user_id is not null and row(new.league_id,new.kind,new.recipient,new.team_id,new.ticket_id,new.staff_user_id) is distinct from row(old.league_id,old.kind,old.recipient,old.team_id,old.ticket_id,old.staff_user_id) then raise exception 'Staff alert identity is immutable.';end if;
 if tg_op='UPDATE' and current_user='boff_routine_retention' and old.body_retired_at is null and new.body_retired_at is not null and new.payload is null then new.staff_context:=null;return new;end if;
 if tg_op='UPDATE' and old.staff_context is not null and new.staff_context is distinct from old.staff_context then raise exception 'Staff alert context is immutable.';end if;
 if new.staff_context is not null and new.staff_user_id is null then raise exception 'Staff context requires a verified user binding.';end if;
 if new.staff_user_id is not null and (new.kind<>'attention' or new.team_id is not null or new.ticket_id is not null or (new.staff_context is null and new.body_retired_at is null)
  or (new.staff_context is not null and(new.staff_context->>'contract' is distinct from 'staff-attention-v1' or new.staff_context->>'league_id' is distinct from new.league_id::text or new.staff_context->>'user_id' is distinct from new.staff_user_id::text))) then raise exception 'Invalid staff alert scope.';end if;
 return new;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."staff_alert_identity_guard"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.staff_grant_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if not sportsbook_private.is_platform_owner() then raise exception 'Platform owner required';end if;
 perform pg_advisory_xact_lock(hashtextextended('staff-grants:'||new.league_id::text,0));
 if tg_op='INSERT' then
  if not exists(select 1 from public.league_staff_grants where league_id=new.league_id and user_id=new.user_id)
   and (select count(*) from public.league_staff_grants where league_id=new.league_id)>=128 then raise exception 'Staff grant admission budget reached';end if;
  new.created_by:=auth.uid();new.created_at:=clock_timestamp();new.revision:=1;
 else
  if new.league_id<>old.league_id or new.user_id<>old.user_id then raise exception 'Staff grant identity is immutable';end if;
  new.created_by:=old.created_by;new.created_at:=old.created_at;new.revision:=old.revision+1;
 end if;
 new.updated_by:=auth.uid();new.updated_at:=clock_timestamp();return new;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."staff_grant_guard"() FROM PUBLIC,anon,authenticated,service_role;

CREATE OR REPLACE FUNCTION sportsbook_private.user_finance_cutover_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if old.enabled and (tg_op='DELETE' or not new.enabled) and (
  exists(select 1 from public.user_wallet_entries where league_id=old.league_id)
  or exists(select 1 from public.user_wallets where league_id=old.league_id and balance is not null))
 then raise exception 'Funded user-finance cutover requires a separately reviewed migration; application rollback cannot revert financial identity.';end if;
 if tg_op='DELETE' then return old;end if;return new;
end $function$
;

REVOKE ALL ON FUNCTION "sportsbook_private"."user_finance_cutover_guard"() FROM PUBLIC,anon,authenticated,service_role;

