CREATE OR REPLACE VIEW "public"."sportsbook_evaluation_runs" WITH (security_invoker=true) AS  SELECT r.id,
    r.league_id,
    r.nfl_season,
    r.market_week,
    r.category,
    r.captured_at,
    r.phase,
    r.provenance,
    r.model_version,
    r.model_config,
    r.sources,
    r.payload,
    NULL::uuid AS sample_id
   FROM model_forecast_runs r
UNION ALL
 SELECT s.run_id AS id,
    s.league_id,
    s.nfl_season,
    s.market_week,
    s.category,
    s.captured_at,
    'pregame'::text AS phase,
    'as_of'::text AS provenance,
    s.model_version,
    c.config AS model_config,
    '{}'::jsonb AS sources,
    s.payload || jsonb_build_object('model_config', c.config, 'scoring_settings', v.scoring_settings) AS payload,
    s.sample_id
   FROM model_evaluation_samples s
     JOIN model_config_versions c ON c.league_id = s.league_id AND c.id = s.model_version
     JOIN model_prediction_contexts v ON v.league_id = s.league_id AND v.id = s.context_version;

;

CREATE OR REPLACE VIEW "public"."sportsbook_live_forecasts" WITH (security_invoker=true) AS  SELECT live_forecast_samples.id,
    live_forecast_samples.league_id,
    live_forecast_samples.nfl_season,
    live_forecast_samples.market_week,
    live_forecast_samples.captured_at,
    live_forecast_samples.status,
    live_forecast_samples.model_version,
    live_forecast_samples.payload
   FROM live_forecast_samples
UNION ALL
 SELECT legacy.id,
    legacy.league_id,
    legacy.nfl_season,
    legacy.market_week,
    legacy.captured_at,
    legacy.status,
    legacy.model_version,
    sportsbook_private.compact_live_payload(legacy.payload) AS payload
   FROM ( SELECT DISTINCT ON (live_forecast_runs.league_id, live_forecast_runs.nfl_season, live_forecast_runs.market_week, (live_forecast_runs.payload ->> 'horizon'::text)) live_forecast_runs.id,
            live_forecast_runs.cycle_id,
            live_forecast_runs.league_id,
            live_forecast_runs.nfl_season,
            live_forecast_runs.market_week,
            live_forecast_runs.captured_at,
            live_forecast_runs.observed_at,
            live_forecast_runs.model_version,
            live_forecast_runs.model_config,
            live_forecast_runs.source_hash,
            live_forecast_runs.status,
            live_forecast_runs.sources,
            live_forecast_runs.payload
           FROM live_forecast_runs
          WHERE live_forecast_runs.status = 'shadow'::text AND ((live_forecast_runs.payload ->> 'horizon'::text) = ANY (ARRAY['0'::text, '1'::text, '2'::text, '3'::text])) AND NOT (EXISTS ( SELECT 1
                   FROM jsonb_array_elements(live_forecast_runs.payload -> 'teams'::text) t(value)
                  WHERE (t.value -> 'reasons'::text) <> '[]'::jsonb))
          ORDER BY live_forecast_runs.league_id, live_forecast_runs.nfl_season, live_forecast_runs.market_week, (live_forecast_runs.payload ->> 'horizon'::text), live_forecast_runs.captured_at DESC, live_forecast_runs.id DESC) legacy
UNION ALL
 SELECT live_forecast_health.league_id AS id,
    live_forecast_health.league_id,
    live_forecast_health.nfl_season,
    live_forecast_health.market_week,
    live_forecast_health.captured_at,
    live_forecast_health.status,
    live_forecast_health.model_version,
    live_forecast_health.payload
   FROM live_forecast_health
  WHERE live_forecast_health.status = 'blocked'::text;

;

CREATE OR REPLACE VIEW "public"."sportsbook_model_future_openings" WITH (security_invoker=true) AS  SELECT id,
    league_id,
    nfl_season,
    market_week,
    captured_at,
    category,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('id', x.q -> 'id'::text, 'market_key', x.q -> 'market_key'::text, 'kind', x.q -> 'kind'::text, 'side', x.q -> 'side'::text, 'line', x.q -> 'line'::text, 'metadata', jsonb_build_object('roster_id', (x.q -> 'metadata'::text) -> 'roster_id'::text, 'fair_probability', (x.q -> 'metadata'::text) -> 'fair_probability'::text, 'expected_wins', (x.q -> 'metadata'::text) -> 'expected_wins'::text, 'win_distribution', (x.q -> 'metadata'::text) -> 'win_distribution'::text)) ORDER BY x.ord) AS jsonb_agg
           FROM jsonb_array_elements(r.payload -> 'quotes'::text) WITH ORDINALITY x(q, ord)), '[]'::jsonb) AS quotes
   FROM ( SELECT DISTINCT ON (sportsbook_evaluation_runs.league_id, sportsbook_evaluation_runs.nfl_season, sportsbook_evaluation_runs.market_week) sportsbook_evaluation_runs.id,
            sportsbook_evaluation_runs.league_id,
            sportsbook_evaluation_runs.nfl_season,
            sportsbook_evaluation_runs.market_week,
            sportsbook_evaluation_runs.captured_at,
            sportsbook_evaluation_runs.category,
            sportsbook_evaluation_runs.payload
           FROM sportsbook_evaluation_runs
          WHERE sportsbook_evaluation_runs.category = 'Season Futures'::text
          ORDER BY sportsbook_evaluation_runs.league_id, sportsbook_evaluation_runs.nfl_season, sportsbook_evaluation_runs.market_week, sportsbook_evaluation_runs.captured_at, sportsbook_evaluation_runs.id) r;

;

CREATE OR REPLACE VIEW "public"."sportsbook_model_latest_reviews" WITH (security_invoker=true) AS  SELECT DISTINCT ON (league_id, nfl_season, market_week) id,
    league_id,
    nfl_season,
    market_week,
    nfl_season * 100 + market_week AS period,
    created_at,
    outcome_id,
    report
   FROM model_weekly_reviews
  ORDER BY league_id, nfl_season, market_week, created_at DESC, id DESC;

;

CREATE OR REPLACE VIEW "public"."sportsbook_model_publications" WITH (security_invoker=true) AS  SELECT id,
    league_id,
    nfl_season,
    market_week,
    captured_at,
    COALESCE(( SELECT jsonb_agg(jsonb_build_object('market_key', x.q -> 'market_key'::text, 'side', x.q -> 'side'::text, 'line', x.q -> 'line'::text, 'metadata', jsonb_build_object('assessment_run_id', (x.q -> 'metadata'::text) -> 'assessment_run_id'::text)) ORDER BY x.ord) AS jsonb_agg
           FROM jsonb_array_elements(f.quotes) WITH ORDINALITY x(q, ord)), '[]'::jsonb) AS quotes
   FROM sportsbook_report_forecasts f;

;

CREATE OR REPLACE VIEW "public"."sportsbook_report_forecast_details" WITH (security_invoker=true) AS  SELECT id,
    league_id,
    nfl_season,
    quotes
   FROM sportsbook_report_forecasts;

;

CREATE OR REPLACE VIEW "public"."sportsbook_report_forecasts" WITH (security_invoker=true) AS  WITH legacy AS (
         SELECT f.id,
            f.league_id,
            f.board_id,
            f.revision,
            f.nfl_season,
            f.market_week,
            f.board_type,
            f.captured_at,
            f.opens_at,
            f.closes_at,
            f.provenance,
            f.quotes,
            row_number() OVER (PARTITION BY f.board_id ORDER BY f.revision) AS first_rank,
            row_number() OVER (PARTITION BY f.board_id ORDER BY f.revision DESC) AS last_rank,
            row_number() OVER (PARTITION BY f.board_id ORDER BY (f.captured_at <= f.opens_at) DESC, (
                CASE
                    WHEN f.captured_at <= f.opens_at THEN f.revision
                    ELSE NULL::integer
                END) DESC, f.revision) AS opening_rank
           FROM forecast_snapshots f
        )
 SELECT legacy.id,
    legacy.league_id,
    legacy.board_id,
    legacy.revision,
    legacy.nfl_season,
    legacy.market_week,
    legacy.board_type,
    legacy.captured_at,
    legacy.opens_at,
    legacy.closes_at,
    legacy.provenance,
        CASE
            WHEN legacy.board_type = 'weekly'::text THEN 'opening'::text
            ELSE
            CASE
                WHEN legacy.first_rank = 1 THEN 'opening'::text
                ELSE 'latest_pregame'::text
            END
        END AS horizon,
    COALESCE(( SELECT jsonb_agg(sportsbook_private.report_quote(x.q) ORDER BY x.ord) AS jsonb_agg
           FROM jsonb_array_elements(legacy.quotes) WITH ORDINALITY x(q, ord)), '[]'::jsonb) AS quotes
   FROM legacy
  WHERE legacy.board_type = 'weekly'::text AND legacy.opening_rank = 1 OR legacy.board_type = 'future'::text AND (legacy.first_rank = 1 OR legacy.last_rank = 1)
UNION ALL
 SELECT published_forecast_samples.id,
    published_forecast_samples.league_id,
    published_forecast_samples.board_id,
    published_forecast_samples.revision,
    published_forecast_samples.nfl_season,
    published_forecast_samples.market_week,
    published_forecast_samples.board_type,
    published_forecast_samples.captured_at,
    published_forecast_samples.opens_at,
    published_forecast_samples.closes_at,
    published_forecast_samples.provenance,
    published_forecast_samples.horizon,
    published_forecast_samples.quotes
   FROM published_forecast_samples;

;

CREATE OR REPLACE VIEW "public"."storage_current_forecasts" WITH (security_invoker=true) AS  SELECT DISTINCT ON (league_id, category) league_id,
    category,
    nfl_season,
    market_week,
    captured_at AS observed_at,
    payload
   FROM ( SELECT model_evaluation_samples.league_id,
            model_evaluation_samples.category,
            model_evaluation_samples.nfl_season,
            model_evaluation_samples.market_week,
            model_evaluation_samples.captured_at,
            model_evaluation_samples.payload
           FROM model_evaluation_samples
        UNION ALL
         SELECT live_forecast_samples.league_id,
            'Live'::text AS text,
            live_forecast_samples.nfl_season,
            live_forecast_samples.market_week,
            live_forecast_samples.captured_at,
            live_forecast_samples.payload
           FROM live_forecast_samples) samples
  ORDER BY league_id, category, nfl_season DESC, market_week DESC, captured_at DESC;

;

CREATE OR REPLACE VIEW "public"."ticket_legs_with_evidence" WITH (security_invoker=true) AS  SELECT id,
    ticket_id,
    leg_number,
    selection,
    market_type,
    matchup,
    accepted_odds,
    accepted_line,
    status,
    actual_value,
    result_evidence,
    market_quote_id,
    accepted_decimal_odds,
    sportsbook_private.expand_receipt_context(settlement_context, context_bundle_id) AS settlement_context
   FROM ticket_legs;

;

