DROP POLICY IF EXISTS "exception_admin_read" ON "public"."admin_exception_reviews";

CREATE POLICY "exception_admin_read" ON "public"."admin_exception_reviews" AS PERMISSIVE FOR SELECT TO "authenticated" USING (sportsbook_private.is_admin(league_id));

DROP POLICY IF EXISTS "automation_admin_read" ON "public"."automation_jobs";

CREATE POLICY "automation_admin_read" ON "public"."automation_jobs" AS PERMISSIVE FOR SELECT TO "authenticated" USING (sportsbook_private.is_admin(league_id));

DROP POLICY IF EXISTS "retention_read" ON "public"."automation_jobs";

CREATE POLICY "retention_read" ON "public"."automation_jobs" AS PERMISSIVE FOR SELECT TO "boff_evaluation_retention" USING (true);

DROP POLICY IF EXISTS "routine_read" ON "public"."automation_jobs";

CREATE POLICY "routine_read" ON "public"."automation_jobs" AS PERMISSIVE FOR SELECT TO "boff_routine_retention" USING (true);

DROP POLICY IF EXISTS "routine_update" ON "public"."automation_jobs";

CREATE POLICY "routine_update" ON "public"."automation_jobs" AS PERMISSIVE FOR UPDATE TO "boff_routine_retention" USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "balance_events_read" ON "public"."balance_events";

CREATE POLICY "balance_events_read" ON "public"."balance_events" AS PERMISSIVE FOR SELECT TO "authenticated" USING (sportsbook_private.can_view_wallet(team_id));

DROP POLICY IF EXISTS "retention_health_admin" ON "public"."evaluation_retention_health";

CREATE POLICY "retention_health_admin" ON "public"."evaluation_retention_health" AS PERMISSIVE FOR SELECT TO "authenticated" USING (sportsbook_private.is_admin(league_id));

DROP POLICY IF EXISTS "retention_internal" ON "public"."evaluation_retention_health";

CREATE POLICY "retention_internal" ON "public"."evaluation_retention_health" AS PERMISSIVE FOR ALL TO "boff_evaluation_retention" USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "forecast_admin_read" ON "public"."forecast_snapshots";

CREATE POLICY "forecast_admin_read" ON "public"."forecast_snapshots" AS PERMISSIVE FOR SELECT TO "authenticated" USING (sportsbook_private.is_admin(league_id));

DROP POLICY IF EXISTS "intake_cleanup_read" ON "public"."league_intake_drafts";

