DROP POLICY IF EXISTS "intake_cleanup_update" ON "public"."league_intake_drafts";

CREATE POLICY "intake_cleanup_update" ON "public"."league_intake_drafts" AS PERMISSIVE FOR UPDATE TO "boff_routine_retention" USING (((state = 'draft'::text) AND (expires_at <= clock_timestamp()))) WITH CHECK (((state = 'expired'::text) AND (source = '{}'::jsonb) AND (capabilities = '{}'::jsonb)));

DROP POLICY IF EXISTS "intake_owner_read" ON "public"."league_intake_drafts";

